[55122] = { ["id"] = 55122, ["name"] = "Murloc Mania", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "I'm glad you made it out in one piece. Judging by the nearby shipwrecks, I think it's safe to say the missing expedition ran aground here, too. We can't move until we've got the remaining survivors back on their feet. Unfortunately, our remaining supplies have been stolen by murlocs! I need you to recover enough first aid supplies for the wounded. Then we can begin searching for the missing expedition.", ["objectivesText"] = "Recover 6 First Aid Kits from Murlocs. Progress: Did you recover the first aid kits ? Don't take the murlocs lightly.", ["rewardGold"] = 120, ["rewardXP"] = 200, ["rewardItems"] = { 170549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55173] = { ["id"] = 55173, ["name"] = "Northbound", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "The quilboar kidnapped the rest of the expedition and took them to the north. I heard mention of needing more sacrifices for some sort of ritual... Please, you must rescue them!", ["objectivesText"] = "Scout northward and find Austin Huxworth .", ["rewardGold"] = 180, ["rewardXP"] = 100, ["rewardItems"] = { 167206 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 9, ["flags"] = 0 } } },
[55174] = { ["id"] = 55174, ["name"] = "Cooking Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Alaria is nearly starved to death. We need to get her something to eat! Slay some of the nearby wildlife for their meat. Bring whatever you find here to cook. If we can help Alaria regain her strength, she might be able to tell us what happened to the others. I'll stay here and help stabilize her wounds.", ["objectivesText"] = "Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire. Progress: Please... I need... some food...", ["rewardGold"] = 565, ["rewardXP"] = 200, ["rewardItems"] = { 117, 172052, 174072, 174074 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55186] = { ["id"] = 55186, ["name"] = "Down with the Quilboar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "From what I can gather, the quilboar are performing a shadow ritual on one of the expedition members. Their chief is Geolord Grek'og . He is the one who seeks to drain the life from our friend. Slay Grek'og and save the captive member of the expedition. He may know where the others were taken.", ["objectivesText"] = "Slay Geolord Grek'og .", ["rewardGold"] = 565, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 11, ["flags"] = 0 } } },
[55193] = { ["id"] = 55193, ["name"] = "The Scout-o-Matic 5000", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "You look like a <race> that needs help finding the scattered members of our alliance expedition! Luckily, you have happened to rescue the one and only Lindie Springstock , inventor extraordinaire! I've got my Scout-o-Matic 5000 all set to go. It'll fly up in the air and let you scout the entire area. I'll give you the honors. Use my Scout-o-Matic 5000 to find the rest of the expedition.", ["objectivesText"] = "Use the Scout-o-Matic 5000 to find Henry Garrick. Progress: Give me a moment to re-size the Scout-o-Matic, then you can ride it!", ["rewardGold"] = 285, ["rewardXP"] = 100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 13, ["flags"] = 0 } } },
[55194] = { ["id"] = 55194, ["name"] = "Stocking Up on Supplies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "Quartermaster Richter was able to scavenge supplies from the wreckages on this island. Why don't you visit her and see if she has anything that you need? You'll want to be well equipped for whatever we encounter next.", ["objectivesText"] = "Purchase any item from Quartermaster Richter and sell any of your items to her. Progress: Quartermaster Richter should have a few supplies that you could use.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["rewardItems"] = { 175239 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1072, ["name"] = "What Lurks Below", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55196] = { ["id"] = 55196, ["name"] = "The Harpy Problem", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "We need to find the remaining survivors of my expedition before the ogres sacrifice them for their dark ritual! I saw one of the survivors being dragged away by some harpies. They have a roost to the north. Kee-La and I will meet you up there with a scouting report.", ["objectivesText"] = "Meet with Henry Garrick near the Harpy Roost.", ["rewardGold"] = 510, ["rewardXP"] = 440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1071, ["name"] = "The Harpy Problem", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55424] = { ["id"] = 55424, ["name"] = "Aspirant Elynna", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 55424 }, ["description"] = "<name>! You've returned to the Maw! Glory be with you! I have news. It seems that one of the aspirants lost in the attack on Honorveil is being held here, in the Jailor's Armory. Her name is Elynna , and she's on the tenth floor. That's all I know for now. We shall speak again when I know more.", ["objectivesText"] = "Find Aspirant Elynna on the tenth floor of the Jailer's Tower.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[55639] = { ["id"] = 55639, ["name"] = "Who Lurks in the Pit", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "The winds whisper of people being trapped in the pit. It seems there may be more members of the expedition within. I fear it will be up to you to make the descent and save the survivors. There should be six in total... though the winds say that one is farther away from the others... With our luck, the last survivor is at the bottom of the pit. Good luck, <name>. And... make sure no spiders follow you back out.", ["objectivesText"] = "Rescue 5 Trapped Expedition Members.", ["rewardGold"] = 3440, ["rewardXP"] = 1095, ["rewardItems"] = { 175203, 175204, 175205, 175206, 175234, 175235, 175236, 175237 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 1072, ["name"] = "What Lurks Below", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 21, ["flags"] = 0 } } },
[55763] = { ["id"] = 55763, ["name"] = "The Rescue of Meredy Huntswell", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "Our expedition's mage, Meredy Huntswell , is being held by the harpies! We've got to stop their ritual and rescue Meredy. You lead the charge. Kee-La and I will back you up if things look dire.", ["objectivesText"] = "Rescue Meredy Huntswell from the harpy's necromantic ritual.", ["rewardGold"] = 1720, ["rewardXP"] = 875, ["rewardItems"] = { 168410 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 1071, ["name"] = "The Harpy Problem", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55764] = { ["id"] = 55764, ["name"] = "Harpy Culling", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "The harpies are preparing for a dreadful assault, <name>. They plan to attack our allies back at camp! Harpies swoop in and snatch their victims before bringing them back to their nests... to feast. We have to stop them. Slay the harpies and their worgs to ensure their forces are too weak to stage an assault.", ["objectivesText"] = "Defeat 10 harpies and their allies. Progress: We must do what we can to fight the harpy menace. Take them down, as well as their worgs.", ["rewardGold"] = 1720, ["rewardXP"] = 875, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 30, ["flags"] = 0 }, { ["id"] = 1071, ["name"] = "The Harpy Problem", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 24, ["flags"] = 0 } } },
[55879] = { ["id"] = 55879, ["name"] = "Ride of the Scientifically Enhanced Boar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "We don't know how long the re-sizing will last, so let's get moving. You're going to ride this giant boar and mow down the army of undead between us and Wrathion . The large ones are pulsing with shadow magic. If you kill them, I bet it they'll take out any enemies near them. Let's hope Wrathion is willing to help us find Kalecgos.", ["objectivesText"] = "Ride the Giant Boar to destroy the undead army. Progress: Please... help! I won't last much longer!", ["rewardGold"] = 1130, ["rewardXP"] = 250, ["rewardItems"] = { 175161, 175162, 175163, 175164, 175165, 175166, 175167, 175168, 175169, 175170, 175171, 175172, 175173, 175174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 }, { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55881] = { ["id"] = 55881, ["name"] = "Purge the Totems", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "The harpies' totems are scattered throughout the area. Harpies are known for using their magic to corrupt those nearby. Even now, I can hear foul whispers in the air... We must destroy these totems before any of us are tainted by their dark magic!", ["objectivesText"] = "Set fire to 5 Harpy Totems . Progress: The totems are not particularly powerful. A simple light and tinder should do.", ["rewardGold"] = 1470, ["rewardXP"] = 875, ["rewardItems"] = { 168445, 175199, 175200, 175201, 175202, 175231, 175232, 175233, 175238 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 1071, ["name"] = "The Harpy Problem", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 25, ["flags"] = 0 } } },
[55882] = { ["id"] = 55882, ["name"] = "Message to Base", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "We did it! We're one step closer to getting off this island. Let's get back to camp and inform the captain of our success.", ["objectivesText"] = "Return to the Alliance Camp and speak with Captain Garrick .", ["rewardGold"] = 735, ["rewardXP"] = 440, ["rewardItems"] = { 175191, 175192, 175193, 175194, 175223, 175224, 175225, 175226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 1071, ["name"] = "The Harpy Problem", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 26, ["flags"] = 0 } } },
[55965] = { ["id"] = 55965, ["name"] = "Westward Bound", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "Captain Garrick wants us tae search west o' camp fer any other members of the expedition. Alaria and I will go on ahead. Meet us tae the west and we'll see what we can find.", ["objectivesText"] = "Meet Bjorn Stouthands west of the Alliance Camp.", ["rewardGold"] = 510, ["rewardXP"] = 440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1072, ["name"] = "What Lurks Below", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 27, ["flags"] = 0 } } },
[55981] = { ["id"] = 55981, ["name"] = "Right Beneath Their Eyes", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "We need to get inside Darkmaul Citadel, rescue the captain of the expedition, and stop the ogre behind all of this. Meredy is going to cast an illusion to make you look like an ogre, and you're going to take us all in as \"prisoners.\" I'll be hiding my efforts to suppress the shadow magic in the meantime. Speak with Meredy when you're ready for her to cast the spell. Her illusion spell should be temporary, as long as she casts it in the proper way.", ["objectivesText"] = "Have Meredy transform you into an ogre, then scout the nearby ogre citadel.", ["rewardGold"] = 2000, ["rewardXP"] = 1010, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 29, ["flags"] = 0 } } },
[55988] = { ["id"] = 55988, ["name"] = "Like Ogres to the Slaughter", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "This is bad, <name>. Captain Kelra is bound by magic, the ogres are preparing to attack our friends, and the ritual is almost complete! I have to stay calm. We can't give up now, right? This may sound risky, but we need to take the fight to the ogres. We're behind enemy lines, so we'll be able to get the jump on them and draw their focus away from the camp. Take down any ogres that you can. That should keep them away from our friends.", ["objectivesText"] = "Slay 8 ogres within Darkmaul Citadel. Progress: You need to slay the ogres so they don't go after our friends back at the camp.", ["rewardGold"] = 1720, ["rewardXP"] = 1010, ["rewardItems"] = { 175184, 175185, 175186, 175187, 175216, 175217, 175218, 175219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 30, ["flags"] = 0 } } },
[55989] = { ["id"] = 55989, ["name"] = "Catapult Destruction", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "Did you notice the catapults on our way up? It appears the ogres plan to attack our allies below. Lindie anticipated something like this and provided several bombs to handle siege weapons. Just don't shake them too hard.", ["objectivesText"] = "Blow up 4 catapults within Darkmaul Citadel. Progress: Don't worry about the bombs. They'll blow up those catapults just fine.", ["rewardGold"] = 1720, ["rewardXP"] = 1010, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 31, ["flags"] = 0 } } },
[55990] = { ["id"] = 55990, ["name"] = "Controlling their Stones", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "Captain Kelra won't last much longer. We need to acquire the ward stones to break the ritual before it kills her. I'll continue weakening the main ritual. Get those ward stones from the ogre lieutenants nearby.", ["objectivesText"] = "Recover the Ward Stones from Jugnug, Wug, and Grunk, then use them to free Captain Kelra . Progress: So, these were the stones used to bind me? The ogres clearly were concerned about you thwarting their plans.", ["rewardGold"] = 2000, ["rewardXP"] = 1010, ["rewardItems"] = { 168599, 168600, 168601 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 32, ["flags"] = 0 } } },
[55991] = { ["id"] = 55991, ["name"] = "An End to Beginnings", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 84, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "You've done fine work within Exile's Reach , recruit. You should continue on to the Dragon Isles. I'm afraid I must change my plans and go back to Stormwind. I need to find out how the ogres found such powerful shadow magic. I'm sure we'll meet again. I can tell you've got many adventures ahead of you.", ["objectivesText"] = "Speak with Kalecgos to travel to the Dragon Isles.", ["rewardGold"] = 2000, ["rewardXP"] = 2020, ["rewardItems"] = { 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211, 248336, 256330 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154169, ["x"] = 0.738, ["y"] = 0.914 }, { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.914 }, ["mapCandidates"] = { ["npc"] = { 84, 2022 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 48, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 34, ["flags"] = 0 } } },
[55992] = { ["id"] = 55992, ["name"] = "Dungeon: Darkmaul Citadel", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "You've slown down Gor'groth's efforts to control Kalecgos atop the citadel, but the ritual itself needs to be thwarted. You must storm the citadel and stop him from completing the ritual. His dark magic is an affront to the Light. We will need all the help we can get. Gor'groth's most elite lieutenants await within the citadel.", ["objectivesText"] = "Complete the dungeon, \"Darkmaul Citadel\". Progress: You must go and slay Gor'groth before it is too late!", ["rewardGold"] = 8000, ["rewardXP"] = 2020, ["rewardItems"] = { 175175, 175188, 175189, 175190, 175207, 175220, 175221, 175222, 178162, 178163, 178164, 178165, 178166, 178167, 178168, 178169, 178171, 178176, 179360, 179362 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 33, ["flags"] = 0 } } },
[56034] = { ["id"] = 56034, ["name"] = "Re-sizing the Situation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "The Re-Sizer v9.0.1 barely works on inanimate objects. I have no idea what it will do to organic matter! But if we do nothing, Wrathion will die! Desperate times call for massively experimental science, <name>. Take the Re-Sizer v9.0.1 . I'll follow you around and calibrate it. We're going to whip up a giant boar!", ["objectivesText"] = "Use the Re-Sizer v9.0.1 on 3 Wandering Boars. Progress: Be careful where you point the Re-Sizer v9.0.1 . Make sure you're only using it on the boars in the immediate area.", ["rewardGold"] = 425, ["rewardXP"] = 150, ["rewardItems"] = { 170557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 14, ["flags"] = 0 } } },
[56070] = { ["id"] = 56070, ["name"] = "Vengeance for the Venthyr", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 56070 }, ["description"] = "Lord Denathrius has fallen under the sway of the Jailer. His betrayal of our people shall not stand. We will show the Jailer that the venthyr are not to be underestimated... nor are you, Maw Walker. Slay his sub-lords. Let him know that he is now being hunted.", ["objectivesText"] = "Defeat the Jailer's lieutenants on floors 5 and 10 of the Jailer's Tower.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56344] = { ["id"] = 56344, ["name"] = "To Darkmaul Citadel", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "We've rescued everyone except for the expedition's captain. Lindie's Scout-o-Matic spotted her just outside Darkmaul Citadel. Meredy has come up with an... interesting plan to rescue the captain. It may be our only chance. Come. We'll convene in the shadow of Darkmaul Citadel, and there we will begin our rescue mission.", ["objectivesText"] = "Meet Lady Jaina Proudmoore outside of Darkmaul Citadel.", ["rewardGold"] = 860, ["rewardXP"] = 505, ["rewardItems"] = { 175175, 175188, 175189, 175190, 175207, 175220, 175221, 175222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 28, ["flags"] = 0 } } },
[56775] = { ["id"] = 56775, ["name"] = "Warming Up", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1156, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Prepare yourself, <name>. We're nearing the island where the previous expedition was lost. Warm up on these combat dummies. We need everyone ready for whatever we find on that island.", ["objectivesText"] = "Warm up by fighting a Combat Dummy . Progress: Don't be shy. Just walk up to the target dummies, select them, and use your main attack.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1954, ["db2PoiUiMapID"] = 1156, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56829] = { ["id"] = 56829, ["name"] = "Bottom Feeders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56942, 56955, 57007, 57025, 57026, 58723, 58724 }, ["description"] = "Oh this is bad. This is really bad. Every time one of the lads makes it down here they don't come back. Things that come down here... they sort of stay down here one way or another. Let's make a deal. You're a Maw Walker. You go find Cudgelface and the Chamberlain while I get this here carriage back in service and then we all get out of here before somethin' tries to eat us and THEN go to work on us.", ["objectivesText"] = "Find Cudgelface and the Lord Chamberlain .", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155668, ["x"] = 0.652, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155668, ["x"] = 0.652, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56839] = { ["id"] = 56839, ["name"] = "Killclaw the Terrible", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "<You see a crude sign made by the ogres. It contains a warning.> BIG bear! Bad! Big bear guard big ogre treasure! Kill after ritual! Get treasure, make more power!", ["objectivesText"] = "Defeat Killclaw the Terrible .", ["rewardGold"] = 6000, ["rewardXP"] = 1515, ["rewardItems"] = { 175195, 175196, 175197, 175198, 175227, 175228, 175229, 175230, 175241 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "group", ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 65, ["flags"] = 0 } } },
