[56955] = { ["id"] = 56955, ["name"] = "Rebels on the Road", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 57007, 57025, 57026, 58723, 58724 }, ["description"] = "This is unacceptable. The stoneborn rebels have ambushed a convoy intended for the Tithelord. He is the local Harvester who rules this ward. We need to get through this mess. The bridge on the far side of this conflict leads to Darkhaven. The Master typically keeps some of his own Stone Legion forces there. Carve us a way through, Maw Walker. Destroy any who would delay us. We must not keep Sire Denathrius waiting.", ["objectivesText"] = "Slay 5 Stoneborn Rebels .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 174102, 175438, 175439, 175440, 175441 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 6, ["flags"] = 0 } } },
[56978] = { ["id"] = 56978, ["name"] = "To Darkhaven", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 58272 }, ["description"] = "Across this bridge is the hamlet of Darkhaven. It is fortified by those loyal to Sire Denathrius. These pitiful rebels would not dare approach it. However, getting to it may prove challenging. Here, I shall carry the anima, you make sure no one throws us back into the Endmire.", ["objectivesText"] = "Escort Lord Chamberlain to Darkhaven.", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57007] = { ["id"] = 57007, ["name"] = "Invitation of the Master", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 56955, 57025, 57026, 58723, 58724 }, ["description"] = "The great Sire Denathrius, Master of Revendreth , and King of the venthyr, has asked me, his loyal Chamberlain, to escort you safely to his personal gardens. This is an honor never before bestowed upon a living mortal. You should feel honored. Come, join me in the carriage and we shall ride to the castle in style.", ["objectivesText"] = "Ride the Darkhaven Carriage .", ["rewardGold"] = 63180, ["rewardXP"] = 355, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155668, ["x"] = 0.652, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57025] = { ["id"] = 57025, ["name"] = "A Plea to Revendreth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 56955, 57007, 57026, 58723, 58724 }, ["description"] = "Revendreth is quite possibly the most... efficient... realm at extracting anima. Perhaps they can lend aid where others cannot. Know that while souls sometimes return from Revendreth , they are never the same when they do. It is a dark realm, where those the Arbiter deems worthy of a chance of redemption are sent. Their path, however, is not an easy one. Kah-Sher will assist you in opening the gateway to Revendreth . Meet him in the Ring of Transference.", ["objectivesText"] = "Journey to Revendreth .", ["rewardGold"] = 25270, ["rewardXP"] = 175, ["rewardItems"] = { 174102 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155537, ["x"] = 0.7, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57026] = { ["id"] = 57026, ["name"] = "The Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 56955, 57007, 57025, 58723, 58724 }, ["description"] = "Well, you ain't like the others. Usually you're supposed to be dead before you come here. Ah well. A sin is a sin and a stone is a stone, as it goes. Let's get you sorted out with your sinstone . This way, if you please.", ["objectivesText"] = "Take the tour.", ["rewardGold"] = 126360, ["rewardXP"] = 710, ["rewardItems"] = { 173793, 173794, 173795, 174102, 181175, 181177, 181178, 181179, 181180, 181183, 181185, 181191, 181195, 181196, 181197, 181199, 181200, 181202, 181211, 181217, 181218, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182724, 184147, 184150, 184777, 185942 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155537, ["x"] = 0.7, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57037] = { ["id"] = 57037, ["name"] = "A Once Sweet Sound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "The bells! That sound! Their song has been twisted! If their dire toll continues, we will all succumb. < Eridia presses her hammer into your hands.> Find the great vespers within the temple and strike them with my hammer. May the mallet's tonal purity restore their true voices! I will listen for their clarion call and meet you near the bridge. Go swiftly!", ["objectivesText"] = "Cleanse the Vesper of Purity and the Vesper of Harmony . Progress: Such a bitter sound!", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 176333, 176335 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57098] = { ["id"] = 57098, ["name"] = "The Grove of Terror", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Ah, yes. You've done me a great favor in delivering the Accuser, Maw Walker. To celebrate, I must insist that you take part in a sacred tradition of Revendreth : The Penitent Hunt. It is a duty we undertake to strike a humbling fear into the hearts of the most... stubborn souls. Fear can be a very powerful motivator for change. Meet the Fearstalker in the Grove of Terror below. There you will prepare.", ["objectivesText"] = "Meet the Fearstalker in the Grove of Terror.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156381, ["x"] = 0.534, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 169087, ["x"] = 0.505, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57099] = { ["id"] = 57099, ["name"] = "A Dreadful Roundup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57099 }, ["description"] = "Welcome to The Banewood, Maw Walker. As Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt. In the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.", ["objectivesText"] = "Collect 6 Condemned Souls .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57100] = { ["id"] = 57100, ["name"] = "Feeding Time is Over", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 57100 }, ["description"] = "A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast. Their fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. Go and collect some from their corpses. Their population is a bit large right now anyhow.", ["objectivesText"] = "Kill Winged Terrorbeasts and collect 6 of their fangs.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 170513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57102] = { ["id"] = 57102, ["name"] = "Pardon Our Dust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 59774 }, ["description"] = "Ah yes, the Greeter. It seems this Mnemis unit has been deactivated. Anima has been so scarce of late, and with no new souls entering our gates... I suppose it was a prudent measure. Anima is our most precious resource, after all. There are some centurions nearby. A portion of their Anima could serve our needs. Ah! One of our most helpful stewards is here to lend her aid. She will guide you in the collection effort. Return when you have sufficient Anima and we will power the Greeter once more.", ["objectivesText"] = "Collect anima from nearby centurions. Progress: <The centurion is unresponsive.>", ["rewardGold"] = 118170, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158281, ["x"] = 0.422, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57113] = { ["id"] = 57113, ["name"] = "On Lysonia's Trail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57114 }, ["description"] = "Our scouts have reported spotting Lysonia and Uther en route to the Temple of Humility. As the de facto leader of the Forsworn, we must not allow her to stand free, twisting the minds of those around her. The disciples of Humility have not answered our beckons. I have sent Kleia ahead to reconnoiter. Meet her outside the temple.", ["objectivesText"] = "Meet Kleia outside the Temple of Humility.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57114] = { ["id"] = 57114, ["name"] = "Aerial Reconnaissance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57113 }, ["description"] = "The temple grounds are crawling with those loyal to the Forsworn. If I were still an aspirant, this task would be monumental. Luckily, that is no longer the case. Let us survey the situation from the sky. We can both take stock of the challenges ahead and find any survivors we can.", ["objectivesText"] = "Fly with Kleia to find the survivors.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.653333, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57115] = { ["id"] = 57115, ["name"] = "Sacred Scrolls of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "The Forsworn are ransacking the library, looking for specific texts amongst our archives. We cannot allow them to uncover the scrolls they are searching for. Find any set aside scrolls and return them to me for safekeeping.", ["objectivesText"] = "Collect 5 Sacred Scrolls . Progress: The scrolls throughout these temples cover many topics, from information on different worlds, to training pillars, to ancient rituals.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57116] = { ["id"] = 57116, ["name"] = "Succumbing to Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "The aspirants that spend the most time at this temple are those who must face their pride. I was one of them, once. During our surveillance, I saw Forsworn forcing these aspirants to fall to their vices then toss them aside as if they meant nothing. You must stop the Forsworn. Free the aspirants from a terrible fate.", ["objectivesText"] = "Free 5 Burdened Aspirants by stopping Forsworn rituals.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.653333, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57117] = { ["id"] = 57117, ["name"] = "Fallen to Their Vices", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia's forces ransack our sacred temple... they are long gone from the Archon's embrace. It pains me to say, but you must defeat them so they can no longer abuse our people. Take Compassion with you. You will find it more than helpful, now that its power has returned.", ["objectivesText"] = "Defeat 15 Forsworn forces in the Terrace of Inner Grace.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550, 181291 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57118] = { ["id"] = 57118, ["name"] = "Distorted by the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia's forces are rerouting the anima collectors to spew Maw energy across the temple. They hamper our forces while strengthening their own. The collectors have been tainted. Take Compassion and destroy them to halt Lysonia's boon.", ["objectivesText"] = "Destroy 3 Anima Collectors in the Terrace of Inner Grace.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57120] = { ["id"] = 57120, ["name"] = "Compassion, Blade of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "<You find a familiar sword impaled into one of the Forsworn corpses. The Paragon of Humility must have left it behind in pursuit of Lysonia. It seems inert, as if all its anima has been used. Perhaps you could restore it to its usual glory.>", ["objectivesText"] = "Charge Compassion, Blade of Humility by killing manifestations. Progress: The Paragon rarely uses his weapon. He prefers debate and reason over the use of force.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57121] = { ["id"] = 57121, ["name"] = "The Power of the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia flees to the Maw to enact her dark rituals. As the Maw Walker, you are the only one who can pursue her. Take Kleia and my blade. She must be stopped.", ["objectivesText"] = "Enter the Maw with Kleia , then meet her outside Perdition Hold.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156474, ["x"] = 0.69, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57122] = { ["id"] = 57122, ["name"] = "A Step Too Far", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "My initial scouting revealed things I did not believe at first. The Mawsworn hold Forsworn captive here, transforming them against their will. Though the Forsworn stand against the Archon, they are still kyrian. It is our duty to free them.", ["objectivesText"] = "Free 5 Captive Forsworn. Progress: I cannot stand idly by while my brothers and sisters are tormented.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57123] = { ["id"] = 57123, ["name"] = "Kyrian No More", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Mawsworn kyrian... I have not seen one since that vision when we first met. I am not intimidated. They are enemies of Bastion , of the Archon, and it is our duty to defeat them.", ["objectivesText"] = "Kill 15 Mawsworn forces.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57124] = { ["id"] = 57124, ["name"] = "Her Will, Inflicted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57125, 62555 }, ["description"] = "I feel myself drawn across the double bridges to the west... Lysonia must be there. Come, <name>. We must confront her before she can escape again. Who knows what she plans.", ["objectivesText"] = "Confront Lysonia in the Altar of Domination.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 170550, 174290, 177051, 178154, 179940 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 169850, ["x"] = 0.253, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.253, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57125] = { ["id"] = 57125, ["name"] = "Time to Reflect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57124, 62555 }, ["description"] = "I knew that Devos had powerful allies. I turned a blind eye. When Lysonia took her place... I was blinded by my loyalty. I have much to reflect on. We may not be allies, but I have one request. Please, escort me from this wretched place. I will leave you be... but do not leave me here in the Maw.", ["objectivesText"] = "Speak to Kleia to exit the Maw, then return to Polemarch Adrestes in Elysian Hold.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 170550, 184312 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 169850, ["x"] = 0.253, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.253, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1533, 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57131] = { ["id"] = 57131, ["name"] = "Let the Hunt Begin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "One step remains until we may begin the Penitent Hunt. You and the other hunters will first siphon a small amount of anima from the souls. It will come with ease. The soul's time in the Grove of Terror causes trace anima to release. This anima helps us venthyr in tracking the prey's fear. I also ask that you do us the honor of signaling the hunt. < The Fearstalker hands you an anima stake and a hollowed dredbat fang .> Use these to complete the task.", ["objectivesText"] = "Complete the hunting ritual at Wanecrypt Hill. Progress: The ceremony must continue.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57136] = { ["id"] = 57136, ["name"] = "The Penitent Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "You will descend upon these poor souls. Remember, you are helping them and Revendreth through the terror you bring. When a soul is filled with fear, their resistances to our methods falter. The Master has requested that you hunt the Accuser yourself. But we must prey upon some of the others first. I will be able to guide you through your first hunt.", ["objectivesText"] = "Speak to the Fearstalker in Wanecrypt Hill and participate in the Penitent Hunt. Progress: The souls must be hunted.", ["rewardGold"] = 255060, ["rewardXP"] = 1415, ["rewardItems"] = { 175715, 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57156] = { ["id"] = 57156, ["name"] = "Blinding the Eye", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57156 }, ["description"] = "You finally arrived <name>. Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you. Dis won't hurt. Much. Tell me when you are ready to begin.", ["objectivesText"] = "Speak with Nailok to cleanse your \"gift\".", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57159] = { ["id"] = 57159, ["name"] = "A Reflection of Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "I sent the Fearstalker far from here with that trap--buying us some time. On the other side of this mirror lies the depths of Castle Nathria, the fortress of Denathrius himself. There, a meeting between Denathrius and one of his lackeys is about to take place. Join me through the mirror, <name>. You shall see the truth of this \"drought\" first hand.", ["objectivesText"] = "Follow the Accuser through the mirror and witness the truth of Revendreth .", ["rewardGold"] = 510120, ["rewardXP"] = 1770, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156554, ["x"] = 0.515, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156554, ["x"] = 0.515, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57161] = { ["id"] = 57161, ["name"] = "I Don't Get My Hands Dirty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "You heard Sire Denathrius. Today, I ascend to the Court of Harvesters. You are fortunate to have the honor of witnessing my rise to power. The traitors have barricaded the bridge ahead. Clear a path for me, so that I might cross it undisturbed. Nothing can stand against me now that I have a Harvester's medallion. But I will not waste my power on this rabble.", ["objectivesText"] = "Clear the bridge for Lord Chamberlain . Progress: Clear the way for Lord Chamberlain !", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175714 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156605, ["x"] = 0.58, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156842, ["x"] = 0.646, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57164] = { ["id"] = 57164, ["name"] = "Devour This", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Though the souls are our primary target, another challenge has arisen. The Banewood has seen an infestation of devourers: disgusting vermin who gorge themselves on the anima we need to survive. A fitting challenge for any true hunter, no? I should only thank the Master that they have remained in a few secluded pockets. I loathe to think that their numbers could multiply. Let us exterminate them before they pose a true threat.", ["objectivesText"] = "Eliminate the devourers in the Banewood. Progress: Are the devourers finished?", ["rewardGold"] = 255060, ["rewardXP"] = 1415, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57173] = { ["id"] = 57173, ["name"] = "The Accuser's Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Lord Chamberlain will cross the bridge when it pleases him. Before he arrives, you will seize the Accuser's sinstone. Wise venthyr like Lord Chamberlain hide their sinstone, so that it can never be used against them. The Accuser is too proud to hide her sinstone. Instead, she puts it on display for all to see. Boasting of the many, many sins she's overcome. Proud. Arrogant. Most importantly, foolish. Her sinstone lies on the altar before us, seemingly unguarded. Retrieve it.", ["objectivesText"] = "Investigate the Accuser's sinstone.", ["rewardGold"] = 126360, ["rewardXP"] = 710, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156842, ["x"] = 0.646, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156823, ["x"] = 0.645, ["y"] = 0.497 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57174] = { ["id"] = 57174, ["name"] = "The Stoneborn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "The Stone Legion is not even here yet? This is an outrage. If we do not do something quickly, the rebels will overrun this filthy hamlet. Here, take the anima and go activate a few of the stoneborn along the periphery of Darkhaven. Take whatever is left over to the Quartermaster and tell her to do her job. I will try to commune with the Master and see if he can send reinforcements.", ["objectivesText"] = "Collect the Anima Cage and then awaken 6 Stoneborn Guardians . Progress: Darkhaven. Such a pitiful hamlet filled with unworthy supplicants.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 176139 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5935, ["y"] = 0.5645 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57175] = { ["id"] = 57175, ["name"] = "Inquisitor Vilhelm's Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Inquisitor Vilhelm has taken exceptional precautions to protect his sinstone. Broken into several pieces and hidden from sight, he believed his sinstone would be safe from us. But his plan had the same weakness as most: he trusted weak-willed underlings. I \"interrogated\" several dredgers to learn where they helped the inquisitor hide the broken fragments of his sinstone. Find all the fragments and bring them to me.", ["objectivesText"] = "Collect the 3 Hidden Sinstone Fragments .", ["rewardGold"] = 262100, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 171103, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57176] = { ["id"] = 57176, ["name"] = "Sinstone Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Lord Chamberlain has held off the Accuser to buy us the time we needed to break the ward on her sinstone. But, thanks to your delays, our reinforcement of his position is overdue. I will collect the Accuser's sinstone and carry us to the battle.", ["objectivesText"] = "Fly with Echelon and deliver the Accuser's Sinstone to Lord Chamberlain .", ["rewardGold"] = 63180, ["rewardXP"] = 355, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157069, ["x"] = 0.656, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57177] = { ["id"] = 57177, ["name"] = "A Fresh Start", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57177 }, ["objectivesText"] = "Halls of Atonement purged Small Enemy Normal Enemy Big Enemy Small Interact Small Interact Normal Interact Accuser Defeated Burden of Pride", ["rewardGold"] = 514800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Halls of Atonement purged", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Small Enemy", ["amount"] = 34, ["type"] = 0, ["objectID"] = 164199, ["orderIndex"] = 1 }, { ["text"] = "Normal Enemy", ["amount"] = 20, ["type"] = 0, ["objectID"] = 164200, ["orderIndex"] = 2 }, { ["text"] = "Big Enemy", ["amount"] = 5, ["type"] = 0, ["objectID"] = 164201, ["orderIndex"] = 3 }, { ["text"] = "Small Interact", ["amount"] = 34, ["type"] = 0, ["objectID"] = 164203, ["orderIndex"] = 4 }, { ["text"] = "Small Interact", ["amount"] = 50, ["type"] = 0, ["objectID"] = 164260, ["orderIndex"] = 5 }, { ["text"] = "Normal Interact", ["amount"] = 34, ["type"] = 0, ["objectID"] = 164204, ["orderIndex"] = 6 }, { ["text"] = "Accuser Defeated", ["amount"] = 4, ["type"] = 0, ["objectID"] = 157065, ["orderIndex"] = 7 }, { ["text"] = "Burden of Pride", ["amount"] = 50, ["type"] = 0, ["objectID"] = 163675, ["orderIndex"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57178] = { ["id"] = 57178, ["name"] = "The Master Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "Maw Walker, I am General Kaal . Those stoneborn who remember their oaths to the Master are under my command. The path between here and Sire Denathrius is no longer secured by my forces. I am pulling my troops from this ward to support the Master's will elsewhere. Sire Denathrius has dispatched me to bring you directly to him. Myskia can carry you.", ["objectivesText"] = "Meet Sire Denathrius. Progress: Mind your manners when speaking to Sire Denathrius. He is a being older than your world.", ["rewardGold"] = 25270, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155541, ["x"] = 0.5885, ["y"] = 0.5765 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5885, ["y"] = 0.5765 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57179] = { ["id"] = 57179, ["name"] = "The Authority of Revendreth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "$p, a proud <race> <class>. I know your name and your deeds. I can taste your regrets and your shame. More importantly, I know what you might become. You can be the beacon for the Shadowlands to rally behind. The symbol my people need to set aside these petty squabbles and help fix the problems that afflict all reality. Before you stands the Court of Harvesters, my most loyal and trusted venthyr. Where once there were seven, only four remain. Introduce yourself to them, for where they go, my power follows", ["objectivesText"] = "Accept the Master's Boon. Progress: My eyes are everywhere.", ["rewardGold"] = 214800, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156644, ["x"] = 0.575, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156644, ["x"] = 0.575, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57180] = { ["id"] = 57180, ["name"] = "The Accuser's Secret", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Now that I possess the Accuser's sinstone, I can finally end her treasonous charade once and for all! Protect me while I study this sinstone, and you will be rewarded as first among my retainers. After I crush her with my incredible power, I will seize control of the Halls of Atonement and receive the Master's reward. This feat heralds my own ascension to the Court of Harvesters!", ["objectivesText"] = "Help Lord Chamberlain defeat the Accuser.", ["rewardGold"] = 137900, ["rewardXP"] = 1770, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175732 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157069, ["x"] = 0.656, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157084, ["x"] = 0.662, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57182] = { ["id"] = 57182, ["name"] = "The Accuser's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "You now stand in the presence of a Harvester, Maw Walker. < Lord Chamberlain breathes in deeply and smiles.> I will use the Accuser's medallion to solidify my foothold over the Halls of Atonement. Meanwhile, the Master has requested that you deliver both the Accuser and the medallion that he loaned to me. Myskia will be along shortly to retrieve you. Do not keep the Master waiting.", ["objectivesText"] = "Ride Myskia and deliver the Accuser to Sire Denathrius . Progress: I trust you have the medallion that I loaned to the Lord Chamberlain ?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175756 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157084, ["x"] = 0.662, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156381, ["x"] = 0.534, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57185] = { ["id"] = 57185, ["name"] = "Dutybound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 57185 }, ["description"] = "Welcome to the fight, <name>. You're with us now. Take a moment and introduce yourself. I will meet you by Draven at the lodge.", ["objectivesText"] = "Introduce yourself to General Draven , Nadjia the Mistblade , and Rendle .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57189] = { ["id"] = 57189, ["name"] = "Breaking the Hopebreakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "The Fearstalker has surely sent her hunters across the entirety of the Banewood in search of us, <name>. Draven informed me that some of her top hunters are scouring Dredhollow as we speak. We can use this to our advantage. Slaying them should get her attention. < The Accuser hands you a collection of bright red vials.> Throw these on her hunters. It should draw the attention of the devourers infesting this place.", ["objectivesText"] = "Use the Concentrated Anima Vial to defeat the hopebreakers in Dredhollow.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 175770, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168468, ["x"] = 0.396, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57190] = { ["id"] = 57190, ["name"] = "They Won't Know What Hit Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Luring the Fearstalker here will prove pointless unless we can tilt the odds. She will surely show up with a small army. Plant these anima containers. When the time comes, we will release their contents into the air, dousing her and her forces in a thick layer of anima. That should get the devourers infesting this place to flock to them like moths to a flame.", ["objectivesText"] = "Plant 8 Rigged Anima Containers.", ["rewardGold"] = 255060, ["rewardXP"] = 1415, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168468, ["x"] = 0.396, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57205] = { ["id"] = 57205, ["name"] = "A Few Bumps Along the Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 57205 }, ["description"] = "This territory is strategic to our defense, we can not allow these abominations to force our retreat! Seize control of two of the locations marked on your map. Defend them from enemy attack till the flag is planted and the location captured.", ["objectivesText"] = "Defend and capture two locations", ["rewardXP"] = 8165, ["rewardItems"] = { 6948, 168583, 171275, 172054, 180273, 180771, 181164, 182163 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Artillery defended", ["amount"] = 2, ["type"] = 0, ["objectID"] = 156797, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57207] = { ["id"] = 57207, ["name"] = "Lysonia's Plan", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia has brought the Paragon to his knees! The Maw powers she wields are far too potent. We must stop her.", ["objectivesText"] = "Confront Lysonia. Progress: <The Paragon of Humility clutches his body in pain.>", ["rewardGold"] = 146000, ["rewardXP"] = 4085, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156474, ["x"] = 0.69, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.653333, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57228] = { ["id"] = 57228, ["name"] = "The Assault on Dredhollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57228 }, ["description"] = "The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us. We have done all we can do to prepare for their assault. Here. <The Accuser gives you an ornate staff.> I fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces . The fight begins.", ["objectivesText"] = "Defeat 12 of the Fearstalker's Forces .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 171146 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57245] = { ["id"] = 57245, ["name"] = "Ani-Matter Animator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57245 }, ["description"] = "This area is rich with the remains of fallen soldiers... some of which still carry a spark of potential. I've created what I call the \" Ani-Matter Orb ,\" with which you can reanimate the skeletal matter littered throughout the foundry. Let us see how many of the new animates would join our cause. As for those who don't... well, they should be quite accustomed to being slain by now.", ["objectivesText"] = "Recruit 15 animates. Progress: Do we have enough animates?", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 175827, 181804 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157076, ["x"] = 0.262, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157076, ["x"] = 0.262, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1176, ["name"] = "Ani-Matter Animator", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57261] = { ["id"] = 57261, ["name"] = "Walk the Path, Aspirant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57584, 60735 }, ["description"] = "If you wish to stand before the Archon, there is a path you must walk. Thankfully, it is well worn and serviceable even in these dire times. Though you are not destined to become kyrian, our ways may be of interest to you. Learn well, learn fast, and perhaps the Archon will take notice and grant you this audience you seek. Aspirant Kleia will show you the way. Archon's eyes upon you.", ["objectivesText"] = "Travel with Kleia .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 124640 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166306, ["x"] = 0.422, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57263] = { ["id"] = 57263, ["name"] = "The Cycle of Anima: Etherwyrms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "Forge is cold, yes? Need LOTS of anima to light. < Sika references her scroll.> Times before now, anima is everywhere, yes? Now it hides. Small bits, weird places. We know that etherwyrms -- flappy scale-things that are blue -- eat anima. They are not dead, so they are finding anima to eat still, yes? Maybe if we take what they have eaten, we can use it to light the forge. This will probably kill them. Sad, yes. But! We will not take too much. Just a little.", ["objectivesText"] = "Slay Etherwyrms to collect 25 Glowing Viscera . Progress: Did you find anima? Small pieces, even?", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57264] = { ["id"] = 57264, ["name"] = "On the Edge of a Revelation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "Ah! Good. You answered the call. As you can see, there are many aspirants who require our aid. Myself and the other disciples are hard pressed to deal with all of them. Some are in greater need than others. Aspirants are most at risk when they are on the precipice of a revelation. It is a critical moment that we cannot allow to pass without intervention. You must push them, one way or another. Find the most vulnerable among your peers and do what you can to help them find the path forward.", ["objectivesText"] = "Inspire 11 Vulnerable Aspirants to action. Progress: My disciples will be grateful for your aid, <name>.", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 }, { ["mapID"] = 1533, ["npcID"] = 160637, ["x"] = 0.6005, ["y"] = 0.7355 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57265] = { ["id"] = 57265, ["name"] = "The Cycle of Anima: Drought Conditions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "In days past, keeping a forge burning was a trivial task. The anima extractors could run constantly without ever running dry. Now, even turning an extractor on is a risk. Etherwyrms, without the anima streams to feed on, are attracted to any source of anima. They are a frequent nuisance. I am going to ask that you risk their attentions. Activate the extractor and guard it until it can accumulate what little anima remains. Bring me the product it collects. Let us hope it is enough.", ["objectivesText"] = "Collect a Condensed Anima Mote from the Anima Extractor . Progress: Is the extractor functional? How much were you able to acquire?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57266] = { ["id"] = 57266, ["name"] = "The First Cleansing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "This situation may feel familiar, <name>. When you found Pelagos, he was undergoing a similar rite. As you saw, it can end in violence. This will be the first time you are asked to draw out the burdens that held you to a mortal life. It may be a painful process. It is for many. For you, this is the path you must walk to attain your goals. To earn the right to stand among us, to be heard. So we may carry your message to the Archon herself. Center yourself. When you are prepared, we will begin.", ["objectivesText"] = "Undergo your first cleansing.", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 173317, 173321, 173322, 173323, 173324, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159583, ["x"] = 0.577, ["y"] = 0.872 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.577, ["y"] = 0.872 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 13, ["flags"] = 0 } } },
[57267] = { ["id"] = 57267, ["name"] = "The Cycle of Anima: Flower Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "For forge to light, need more anima. Always more. Never too much, for forge! < Sika consults her scroll and nods vigorously as she reads.> Out in fields, there is a glowy flower. The round thing inside. Bulb? It glows. So, has anima. From the ground, we think. According to scrolls, it is called Adrima's Lily . We do not know who Adrima is. But the lily is good. Get flowers, too. Not just bulbs. Petals make stewards happy, too. Thank you!", ["objectivesText"] = "Collect 6 Adrima's Lily . Progress: Do you have flower bulb things?", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 172518, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57269] = { ["id"] = 57269, ["name"] = "The Hand of Doubt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57446 }, ["description"] = "Quickly! We have no time to lose. Lysonia has weakened Eridia to the point that she may fall. Our Paragon will do what she can, but we must intervene. We will challenge Lysonia , and perhaps buy Eridia more time. This so-called Hand of Doubt will make no easy foe. Stand ready, <name>.", ["objectivesText"] = "Defeat Lysonia , Hand of Doubt.", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 176330, 176332, 176334, 176336, 176337, 176338, 176339, 176388, 176390 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157687, ["x"] = 0.608, ["y"] = 0.7285 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57270] = { ["id"] = 57270, ["name"] = "The Temple of Purity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57977 }, ["description"] = "Greetings. I am Kosmas, Disciple to the Temple of Purity. The temple is a place of cleansing. Its sole purpose is to free aspirants of the burdens they carry with them from life. It is a place of quiet reflection even for those who have shed their burdens. Of late, those who look to us for purification have grown numerous. My fellow disciples are stretched terribly thin. I have come to ask the aid of all able-minded aspirants. Your help is needed. Please report to the Hand of Purity at once.", ["objectivesText"] = "Meet the Hand of Purity at the Temple of Purity.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57278] = { ["id"] = 57278, ["name"] = "Bring Me Their Heads", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57278 }, ["description"] = "I swore to the grave of Vistara the Fallen that I would bring him the head of the one who betrayed him. Though that was eons ago, it is an oath I must fulfill. Whatever fate ultimately befell the traitor, it is likely that his head can still be found nearby. Slaughter everyone here. Surely one of them must be the traitor... or be in possession of his head.", ["objectivesText"] = "Collect 10 Traitor's Heads . Progress: Do you have the traitor's head ?", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 171204, 175827 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157168, ["x"] = 0.271333, ["y"] = 0.492167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157186, ["x"] = 0.262, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.271333, ["y"] = 0.492167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57284] = { ["id"] = 57284, ["name"] = "Blade of Blades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57284 }, ["description"] = "The finest sword in existence has been lost! Never in your pitiful adventures have you encountered such a blade, mortal. Foe Cleaver was forged to strike down the titans themselves! I have wielded it against countless adversaries. Emissaries of the Light, minions of the Void, meddlers from the Gardens of Life... all have fallen before me! Soon the very planes of reality will kneel to my greatness! Once I find my weapon, that is. I insist you help me reclaim it. I know it's here somewhere!", ["objectivesText"] = "Find Foe Cleaver amongst the forgotten weapons . Progress: Have you found Foe Cleaver ? Well? HAVE YOU?!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 21100, 21746, 27753, 27754, 27756, 31425, 31426, 31427, 31428, 62982, 62983, 62984, 106138, 106148, 106159, 106170, 157547, 171205, 171206, 211279, 220507, 220508, 237812, 242241, 242386, 244846, 244888 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157168, ["x"] = 0.271333, ["y"] = 0.492167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157186, ["x"] = 0.262, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.271333, ["y"] = 0.492167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57288] = { ["id"] = 57288, ["name"] = "Assessing Your Strength", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "The trial to come will test you in ways you can likely only imagine. I can see both from your past and from your demeanor that you are no stranger to combat. I would like to know where your strengths lie so we may address any weaknesses we find before your trial. You will find three praetorian soldiers created for this purpose, each stronger than the last. Defeat them all and I will consider your strength sufficient to continue at this time.", ["objectivesText"] = "Defeat the 3 Praetorian Sparring Assistants. Progress: How fares the combat?", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57291] = { ["id"] = 57291, ["name"] = "The Chamber of First Reflection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "Ah, Athanos. It remains undefeated, as intended. Still, you have exceeded any expectation I might have had. You are stronger than many that have come before you. You have come here for a purpose, and Kleia has illuminated a path that she believes you can walk. I agree. I have opened the way to the Crucible's final rite. Follow the path to the south and east. There you will find the entrance to the Chamber of First Reflection. Kleia will instruct you further. Go in service, <name>.", ["objectivesText"] = "Speak to Kleia in the Chamber of First Reflection.", ["rewardGold"] = 23635, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159583, ["x"] = 0.577, ["y"] = 0.872 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57301] = { ["id"] = 57301, ["name"] = "Callous Concoctions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "I witnessed your success with the Pool of Potions and I think you could be of help. Within this larger pool, we create more dangerous mixtures! There are three different oozing ingredients we mix together in different combinations to create violent creatures. When enough ingredients have been added to the pool, the mixture takes shape and a creature will emerge! Bring any combination of these ingredients, Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities .", ["objectivesText"] = "Deliver any combination of Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities . Progress: Have you completed the mixture?", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 182079 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157313, ["x"] = 0.585, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157313, ["x"] = 0.585, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57316] = { ["id"] = 57316, ["name"] = "The Ladder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Within the Theater of Pain, <brother/sister>, legends rise like cream to the top. Listen to me, <brother/sister>. If you have the courage to step into that sacred arena, you're going to face the greatest threats in all of existence! The cards will be stacked against you, but only those who can work together will emerge as champions. Gather your team and meet this challenge head on! Enter the Theater of Pain and defeat the opponents within! Prove that you can rise to the top!", ["objectivesText"] = "Defeat 3 opponents within the Theater of Pain. Progress: Greetings, brother. Have you faced the madness of the arena?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 176277, 176278, 176279, 176280, 176281, 176282, 176283, 176284, 176285, 176286, 176444, 177835, 177837, 177877, 177957, 181529, 181531, 181534, 181815, 182083 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161733, ["x"] = 0.504667, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161733, ["x"] = 0.504667, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504667, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 13, ["flags"] = 0 } } },
