[57381] = { ["id"] = 57381, ["name"] = "The Greatest Duelist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["description"] = "A mortal in Revendreth . Well, well, well... you are primed to be at the head of high adventure. The name you may call me is Nadjia the Mistblade , and, if I might be so humble as to say, I am the finest duelist that has ever wielded a sword. This trap you found me in was a lesson learned in getting paid in advance. Release me and my blade is yours to command for as long as I find you interesting. Do we have an accord?", ["objectivesText"] = "Release Nadjia the Mistblade . Progress: That consecrated iron really leaves one feeling stiff afterward.", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 174102, 175730 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157550, ["x"] = 0.656, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57386] = { ["id"] = 57386, ["name"] = "If You Want Peace...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 61107 }, ["description"] = "Maldraxxus is a land which revels in strife and conflict. But they should also be bound by honor. If their honor has been tossed aside, then they may move their forces beyond just Bastion. Take care, danger lies beyond that gate. It is a realm of heroes as well as a realm of villains.", ["objectivesText"] = "Enter Maldraxxus .", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 172020, 178496 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57390] = { ["id"] = 57390, ["name"] = "To Die By the Sword", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "What's this? You fly no colors! Where is the pride in your house, gladiator? Bah, this drought has left us with slim pickings indeed, if this is the best Maldraxxus can muster! I remember the old days. The strongest souls arriving, then being divided among the five houses... No matter. The tournament beckons. Enter the arena! Fight for glory! By the look of you, it's likely you won't last long. Try to make a name for yourself in the time you have left.", ["objectivesText"] = "Defeat 30 contenders in the Theater of Pain. Progress: What are you waiting for? Put on a show!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57425] = { ["id"] = 57425, ["name"] = "Land of Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "<The grandmaster's voice rings out over the roaring crowd.> This is it! The final event of the tournament! These two Maldraxxi gladiators have cut down challenger after challenger. Now the only thing left... Is for one to slay the other!", ["objectivesText"] = "Defeat High Champion Meskal .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 172020, 175466, 175467, 175468, 175469, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162069, ["x"] = 0.484, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57443] = { ["id"] = 57443, ["name"] = "Dirty Job: Demolition Detail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57443 }, ["objectivesText"] = "Grab a dredger Rubble Wreckage demolished", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Grab a dredger", ["amount"] = 1, ["type"] = 3, ["objectID"] = 157632, ["orderIndex"] = 0 }, { ["text"] = "Rubble Wreckage demolished", ["amount"] = 3, ["type"] = 0, ["objectID"] = 157649, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57444] = { ["id"] = 57444, ["name"] = "An Inspired Moral Inventory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57444 }, ["description"] = "<name>! You are well! I am glad of it. Many of the ascended who once served this place have betrayed us. To turn so wholly against all that the kyrian stand for is... unimaginable. <The acolyte places a heavy spear in your hands.> This is a tool that has seen little use before today. Its sole purpose is to inspire a moment of reflection in those it touches. It will show them the error of their ways. If they remain unrepentant, then there is no hope for them. They must die.", ["objectivesText"] = "Slay 3 Forsworn ascended . Progress: They betrayed us.", ["rewardGold"] = 265883, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160647, ["x"] = 0.576667, ["y"] = 0.746667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160647, ["x"] = 0.576667, ["y"] = 0.746667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576667, ["y"] = 0.746667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1186, ["name"] = "An Inspired Moral Inventory", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57446] = { ["id"] = 57446, ["name"] = "The Enemy You Know", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57269 }, ["description"] = "My heart is filled with dread. If it truly is Lysonia who leads them now... No. What is important is that we restore the great vespers. So long as their mighty voices are corrupted, all who hear them will suffer as this temple does. It is only a matter of time before all of Bastion succumbs. They will no doubt try to stop you. I will hold their leader's attention as long as I can. If I do not survive... my disciple will see you safely from this place. Go in service.", ["objectivesText"] = "Confront Lysonia and cleanse the great Vespers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630, 237812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57447] = { ["id"] = 57447, ["name"] = "Purity's Prerogative", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "Do you feel it, <name>? That cold hand that grips your throat? That chill settled in the pit of your stomach? That is the touch of the Maw, as certain as the Archon's will. I do not know how Lysonia came to possess this power, but we must act quickly. I will inform the Archon of what transpired here. You will act where my Hand could not. I will explain as we fly. Speak to me when you are prepared to leave the temple.", ["objectivesText"] = "Fly with Vesiphone to Purity's Reflection.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157687, ["x"] = 0.608, ["y"] = 0.7285 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156238, ["x"] = 0.538, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.7285 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57454] = { ["id"] = 57454, ["name"] = "Silence in the Stalks", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["series"] = { 63073 }, ["description"] = "Hmm. Well that's not... great. But no cause for alarm, yet! It has been a long time since our ring withdrew from here, and we probably need to go to its source to get it to return! Unfortunately, I haven't heard from the Chief Mushroomancer, Cortinarius , since the crisis began. Please, find him and help us rejoin the rings! Head west of Dreamsong Fenn to the Stalks. You can't miss them... just follow the mushrooms!", ["objectivesText"] = "Speak to Cortinarius outside the Stalks.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57455] = { ["id"] = 57455, ["name"] = "Mushroom For Improvement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "The mushrooms are under attack! I need your help, or we risk losing it all! Some fae wearing strange masks came in and demanded to gain access to the rings. When I told them they were closed due to the drought, they attacked me! I'm too weak to fight back now, and I'm cut off from the center ring. These fae have destroyed so much, but there is something we can do. Sprinkle some of these spores on their corpses so we can regrow the rings. Even when slain, our enemies can still serve Ardenweald .", ["objectivesText"] = "Use the Pouch of Spores to plant mushrooms on 15 masked fae in the Stalks. Progress: They'd be feeding the mushrooms anyway, so you might as well accelerate the process.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171989 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57457] = { ["id"] = 57457, ["name"] = "Shaking 'Shrooms", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57457 }, ["description"] = "The mushrooms in there need your help, <class>! Some of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there. If you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.", ["objectivesText"] = "Shake 8 Swollen Mushroom Stalks.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57458] = { ["id"] = 57458, ["name"] = "Ring Repairs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "The damage wrought here is severe, but it can be reversed. My master is weakened by all this destruction, but mushrooms are difficult to completely eradicate. By restoring power to the rings throughout the grove, we can strengthen them once again. Take this beacon. Use it near a damaged mushroom in a ring, and watch how quickly nature can heal its wounds.", ["objectivesText"] = "Use the Fungal Beacon to repair 6 Damaged Mushrooms .", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 172084 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57459] = { ["id"] = 57459, ["name"] = "Fighting For Fungus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "Behold, Marasmius ! This is his home, his heart. Every mushroom in Ardenweald , maybe even all of the Shadowlands, stems from here. And the masked fae want to take him for their own purposes. As chief mushroomancer, I cannot abide this. Our foes may look mindless, but they are clever. They will have tracked my position by now. I shall make my final stand here, and hope that Marasmius is strong enough to lend his aid. Will you stand with me, <class>?", ["objectivesText"] = "Help Cortinarius defend Marasmius .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57463] = { ["id"] = 57463, ["name"] = "My Way or the Hyphae", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "<An old, booming voice fills your mind.> Hmph. More are coming. I would rather not lose more of myself, and I don't want you to think I'm not appreciative of the work you and Cort here have done. How about you take a ride on the rings and give those oafs a good thrashing? We'll teach them not to mess with Marasmius and his fae rings!", ["objectivesText"] = "Ride the fae rings with Marasmius and defeat 30 invaders.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57465] = { ["id"] = 57465, ["name"] = "Dirty Job: Wood Work", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57465 }, ["objectivesText"] = "Grab a dredger Infested Horror Sap destroyed", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Grab a dredger", ["amount"] = 1, ["type"] = 3, ["objectID"] = 172929, ["orderIndex"] = 0 }, { ["text"] = "Infested Horror Sap destroyed", ["amount"] = 3, ["type"] = 0, ["objectID"] = 157831, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57470] = { ["id"] = 57470, ["name"] = "An Abominable Discovery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "$p. Come with me. I could explain, but it's easier to understand if you see it for yourself.", ["objectivesText"] = "Follow Draka to Gharmal's Tower.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173308, ["x"] = 0.31, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 16, ["flags"] = 0 } } },
[57471] = { ["id"] = 57471, ["name"] = "It's a Dirty Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["series"] = { 60509 }, ["description"] = "This muck pool is all out of order. The anima shortage has taken its toll here for sure. You see, the pools require filth and fiber to grow dredgers effectively. The problem is every time I try to treat the pool, the dang devourers are on my back! Now the untreated muck is starting to coagulate into these elementals! Can you go and toss some of the filthy rubble into the pool to restore it?", ["objectivesText"] = "Throw Filthy Rubble into the muck pool.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 171966 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57473] = { ["id"] = 57473, ["name"] = "Prized Possession", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 57475, 57636 }, ["description"] = "This chest is different. It's larger than the others... but more importantly, it's locked. <Mograine bashes the lock apart.> Now, let's see what's inside.", ["objectivesText"] = "Open the ornate chest. Progress: How did they acquire that?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 182658 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 18, ["flags"] = 0 } } },
[57474] = { ["id"] = 57474, ["name"] = "Dredger Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["description"] = "You fixed up the muck pool so we can make some dredgers, but them devourers are gonna keep causin' trouble. We're gonna need a Gem of Binding so we can dredge up a biggun to protect the pool. I'll show you how to dredge up some disposable dredgers to work with for now. Get 'em digging in the rubble to find us a Gem of Binding , and then we'll reshape 'em all into a biggun to kick them devourers outta here!", ["objectivesText"] = "Dredge a dredger and bring it to the pile of rubble . Wait for it to dig through the pile and collect the Gem of Binding . Progress: You got the gem?", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 171966 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57475] = { ["id"] = 57475, ["name"] = "The Mantle Returned", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 57473, 57636 }, ["description"] = "The Mantle of the Primus... I can hardly believe it. That Gharmal possessed it. That they did not use it against us. That we reclaimed it. This could prove vital toward our efforts to restore Maldraxxus . We must return it to Baroness Draka at the Seat of the Primus immediately.", ["objectivesText"] = "Return to Draka at the Seat of the Primus.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 19, ["flags"] = 0 } } },
[57477] = { ["id"] = 57477, ["name"] = "We're Gonna Need a Bigger Dredger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["description"] = "Thanks for getting the stone, <name>. While you were out I went ahead and dredged up a few more folks. Now we just need to re-shape these dredgers into a biggun.", ["objectivesText"] = "Witness the ritual. Progress: What do you want?", ["rewardGold"] = 63180, ["rewardXP"] = 355, ["rewardItems"] = { 171966 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158001, ["x"] = 0.728, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57481] = { ["id"] = 57481, ["name"] = "Running a Muck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["description"] = "Bootus ready to smash devourer skulls. Hop on.", ["objectivesText"] = "Board Bootus and quell the devourer incursion. Progress: Enders smashed?", ["rewardGold"] = 524200, ["rewardXP"] = 1770, ["rewardItems"] = { 171966, 177653, 177654, 177655, 177656, 180993 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158001, ["x"] = 0.728, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57506] = { ["id"] = 57506, ["name"] = "Light Lost", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57506 }, ["description"] = "Some of our aspirants foolishly believed they could enter the Maw and make a difference in that dark abyss. Sadly, they are mistaken. To enter the Maw is to invite eternal damnation. But not for you. Please investigate their fate. If you can find them, their souls might once again be free.", ["objectivesText"] = "Find Kyrian Aspirants within the Maw and return with their souls to Elysian Hold.", ["rewardGold"] = 631800, ["rewardXP"] = 14705, ["rewardItems"] = { 263198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57510] = { ["id"] = 57510, ["name"] = "Darklord Taraxis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 57510 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[57511] = { ["id"] = 57511, ["name"] = "Arms for the Poor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "This trench is strewn with the remnants of countless attacks upon the Seat of the Primus by forces which threatened the Shadowlands. Each time, Maldraxxus claimed victory. Now scavengers pick at scraps in hopes of buying their way into one of the three remaining houses. In these desperate times, we must gain every advantage possible over our rivals. If we arm these scavengers and offer them a second chance at glory, we can bolster the ranks of the Chosen.", ["objectivesText"] = "Arm 8 Displaced Scavengers with weaponry scattered around the Iron Trench. Progress: There should be plenty of weapons found on this old battlefield.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162069, ["x"] = 0.484, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57512] = { ["id"] = 57512, ["name"] = "Walk Among Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "This trench echoes with necromantic energies unleashed in the countless battles waged here. That power has coalesced into chaotic entities we call deathwalkers. In simpler times, we would have sent troops out to subdue them to serve the House of the Chosen. But with war brewing, there is no time for that. Eliminate this potential threat, before our enemies turn them against us.", ["objectivesText"] = "Kill 8 Unbound Deathwalkers .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57513] = { ["id"] = 57513, ["name"] = "Enemy of My Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57513 }, ["description"] = "I have no doubt you have questions. Know that we share enemies in this land. For now, we must move. I will get you to a safer location and then we can speak.", ["objectivesText"] = "Escape from the Theater of Pain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 38134, 38135, 38176, 38177, 38178, 38732, 38759, 39030, 39058, 39096, 44987, 45724, 46114, 52879, 52884, 52887, 52902, 52931, 52948, 60260, 65290, 65309, 65328, 65341, 119139, 131828, 131840, 158666, 159123, 159147, 159148, 159149, 159150, 160083, 160084, 160085, 160086, 160093, 160094, 160095, 160096, 182077, 198611, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630, 211279, 237812, 249699, 253178 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57514] = { ["id"] = 57514, ["name"] = "The First Act of War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["series"] = { 57515 }, ["description"] = "Look around you, $p. This army is all that remains to defy the treachery of the other two houses. I must regroup with the margrave and discuss strategy. War will soon be upon us. I would ask that you prepare for the coming battle alongside the rest of our forces. We cannot afford for a single soldier to falter. Seek out Baron Vyraz . He has earned countless victories for Maldraxxus . I fear his blades must soon be turned upon our former allies.", ["objectivesText"] = "Report to Baron Vyraz . Progress: What are you waiting for?", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57515] = { ["id"] = 57515, ["name"] = "The House of the Chosen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 57514 }, ["description"] = "<Draka gestures to the sky.> Look there, mortal. That is the necropolis of Margrave Krexus, who leads the House of the Chosen. It is my honor to serve as his baroness. Let us ride to our fortress. There we can gather our strength and make ready for the battle to come.", ["objectivesText"] = "Head to the House of the Chosen with Draka. Progress: Yes?", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 172020, 178496 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57516] = { ["id"] = 57516, ["name"] = "Through the Fire and Flames", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Margrave Krexus was pleased to hear of your service to our house. He senses great potential within you. Potential that must be tested. A stone stands at the center of our citadel, surrounded by magma. Reaching the stone is a challenge of endurance and fortitude. This trial is usually attempted only by our most renowned soldiers, but Margrave Krexus commands you to attempt the rite at once. Go on, then. Prove your worth.", ["objectivesText"] = "Reach the Standing Stone. Progress: What happened?", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 59529, 59530, 131310, 172061, 174499, 175470, 175471, 175472, 175473, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57529] = { ["id"] = 57529, ["name"] = "Garden in Turmoil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57529 }, ["description"] = "Please excuse me for not standing. I would rather not disturb these creatures. If you have a desire to help the creatures of Bastion , Zosime needs aid to regain control of our garden. You will find her just down this path. Go in service.", ["objectivesText"] = "Speak with Zosime downhill in the Garden of Respite.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158005, ["x"] = 0.522, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57530] = { ["id"] = 57530, ["name"] = "Gharmal's Tower", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "Gharmal collected anything they believed to be an item of power. We'll need to search the tower. There is almost certainly something here of value to us.", ["objectivesText"] = "Search Gharmal's Tower.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 17, ["flags"] = 0 } } },
[57531] = { ["id"] = 57531, ["name"] = "An Unfortunate Situation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["series"] = { 60051, 63056 }, ["description"] = "Laurent , mirror maker to the Master. Pleasure to meet you. Excuse my disheveled appearance. It appears I've found myself in a most unfortunate situation. I was attempting to travel on royal business when my mirror sent me to this wasteland instead. Not a moment after I arrived, a band of exiles ripped the clothes right from my back, making it impossible for me to traverse this unforgiving terrain. Assist me and I will endeavor to create a mirror which will allow us to escape this wretched place.", ["objectivesText"] = "Defeat Costel and recover Laurent's belongings . Progress: Have you recovered my belongings?", ["rewardGold"] = 382590, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220, 175503, 175504, 175505, 175506 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57532] = { ["id"] = 57532, ["name"] = "Foraging for Fragments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Forgive me. I don't mean to appear ungrateful, but my mirror fragments are missing. I shouldn't be surprised, really. They're quite powerful and I'm sure the miscreants out here would be happy to get their hands on them. Nonetheless, I will not let this deter me. The Master sends his stone servants to smash any mirrors erected in this ward, so we should have no trouble finding fragments nearby.", ["objectivesText"] = "Follow Laurent and collect Mirror Fragments . Progress: Simone shouldn't be here!", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172086, 172087, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57533] = { ["id"] = 57533, ["name"] = "Light Punishment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "The reasons we were banished here differ, but our goal once we arrive is always the same--to avoid becoming ash. The Shrouded control the areas shaded from Light. Those that trespass within their stronghold are made to suffer. Our flesh blisters and burns, yet we do not die. Instead, our minds descend into madness from the pain. I do not claim to know the crimes of those trapped within the Light, but I know this is not the Maw. It is not our role to punish. Free the others as you have freed me.", ["objectivesText"] = "Free 5 Blistering Outcasts . Progress: Penance, not punishment. It seems the Master has forgotten the difference.", ["rewardGold"] = 382590, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57534] = { ["id"] = 57534, ["name"] = "When Only Ash Remains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Is this really what becomes of the exiled? Are they left here to burn to ash? How could the Master allow such a thing? It is cruel. Heartless, even. No venthyr would want to continue on like this. You must end their suffering.", ["objectivesText"] = "Kill 10 Ashen Ravagers .", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220, 175507, 175508, 175509, 175510, 175716 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57535] = { ["id"] = 57535, ["name"] = "Escaping the Master", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Now more than ever I wish to escape this place, but I cannot go back to serve the Master. Not after seeing what goes on here. Simone and I are in agreement. With your assistance, I will craft a mirror that connects to a sanctuary controlled by the prince. We will leave this place and pledge our support to Renathal. But first, I'll need fragments of glass. The Shrouded seem to have plenty, and the fewer they have to make traps, the better.", ["objectivesText"] = "Collect 10 Mirror Fragments . Progress: Have you collected the fragments?", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57536] = { ["id"] = 57536, ["name"] = "Mirror Making, Not Breaking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Denathrius does not allow mirrors to be erected within the ember ward. His stone servants shatter anything that so much as glints. I need you to remain vigilant as I make this mirror. I have no doubt that the Master's minions will try to stop us. Are you ready?", ["objectivesText"] = "Defend Laurent and Simone from Stone Legion attackers.", ["rewardGold"] = 929400, ["rewardXP"] = 1770, ["rewardItems"] = { 172074, 172085, 172220, 175733, 177657 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158505, ["x"] = 0.248, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57537] = { ["id"] = 57537, ["name"] = "Covering our Tracks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["storyline"] = { 57537 }, ["description"] = "I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there. We'll fly the rest of the way. Approach my flayedwing when you are prepared.", ["objectivesText"] = "Ride with Draka to the House of the Chosen.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57538] = { ["id"] = 57538, ["name"] = "Disturbing the Peace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "This anima drought isn't hard on just the kyrian. The wildlife of Bastion are suffering too! Many creatures are becoming aggressive and menacing, wyrms and cloudfeathers especially. They are hurting the other wildlife and long beyond saving. If someone doesn't clear this garden of these starved creatures, we can no longer meditate here. And if we can no longer meditate, that will make the anima shortage even worse!", ["objectivesText"] = "Kill 10 Anima-Starved creatures. Progress: We must deal with the anima-starved creatures so this place can return to a state of tranquility.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 172036, 172037, 172039, 172141 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57545] = { ["id"] = 57545, ["name"] = "Distractions for Kala", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "When the animals became aggravated, we left in a hurry. However, all of Kala's toys are still inside the garden. Since you are going to be there, would you please collect them? Kala may be very large, but she is still young. She can be a bit of a troublemaker as well. Hopefully the return of her toys will help keep her distracted.", ["objectivesText"] = "Collect Kala's playthings. Progress: Do you have her playthings? She's becoming quite the handful!", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 172036, 172037, 172039, 172141 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57547] = { ["id"] = 57547, ["name"] = "A Test of Courage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "I'm still new and haven't passed all of my Aspirant tests. But, I have an idea. There is an artifact called Korinna's Allaying Crook. Korinna was a powerful Ascended who tamed the creatures of Bastion eons ago. Her staff has the power to prevent more creatures from succumbing to a savage, anima-starved state. However, the artifact is protected and only one with great courage can retrieve it. I bet you could, <name>. Go on ahead. The staff is in the reliquary to the north. I'll join you there shortly.", ["objectivesText"] = "Help Zosime retrieve Korinna's Allaying Crook. Progress: Were you able to retrieve the crook?", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 172036, 172037, 172039, 172141, 174655, 183045 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57549] = { ["id"] = 57549, ["name"] = "In Agthia's Memory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["series"] = { 57551 }, ["description"] = "Greetings, mortal! Are you here to learn about the legacy of Agthia, Paragon of Courage? I welcome you to walk the grounds of this ancient battleground to learn of the battle that occurred here, and the heroic Paragon who saved all of Bastion and the Shadowlands.", ["objectivesText"] = "Read the Scrolls of Remembrance around Agthia's Repose. Progress: Agthia did not only live a life of courage, but one of service to all of the Shadowlands.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57551] = { ["id"] = 57551, ["name"] = "Agthia's Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["series"] = { 57549 }, ["description"] = "Now that you have familiarized yourself with the events leading to the battle that took place here eons ago, it is time to experience it for yourself. Ring the bell, take a deep breath, and walk in Agthia 's steps.", ["objectivesText"] = "Ring the Vesper of History.", ["rewardGold"] = 105338, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57552] = { ["id"] = 57552, ["name"] = "Warriors of the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "These Void invaders are wiping our forces from existence! My disciples fall, returning their anima to the lands. If we fail to drive them from our lands, more than kyrian will be lost. First Bastion , then the Shadowlands as a whole.", ["objectivesText"] = "Kill 15 Void forces.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57553] = { ["id"] = 57553, ["name"] = "On Wounded Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "I see my peers fall in pain, their wounds from the Void overtaking them. We cannot allow ourselves, or each other, to give up hope. Share your anima with our wounded brothers and sisters. Help them stand tall for another fight!", ["objectivesText"] = "Heal 5 Wounded Defenders .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158178, ["x"] = 0.461429, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461429, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57554] = { ["id"] = 57554, ["name"] = "Wicked Gateways", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "The forces of the Void are infinite. They travel through the Great Beyond by creating portals, twisting gateways between our planes. Quickly, move to close these portals. Cripple the swell of their forces for as long as we can hold.", ["objectivesText"] = "Destroy 3 Void Portals . Progress: New portals shall open, but we can prevent the swell for a time.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57555] = { ["id"] = 57555, ["name"] = "Shadow's Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "Despite our efforts, the Void stands strong. All of the forces of Bastion fight, and fall one by one... The Void cannot destroy us! They are led by Tezulat the Annihilator , scourge of a thousand realms. This day, his reign of terror will end!", ["objectivesText"] = "Kill Tezulat the Annihilator . Progress: We shall sing the songs of Agthia , hero of Bastion , for eternities to come.", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 175719 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57568] = { ["id"] = 57568, ["name"] = "Tough Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "Heavens! Kala has flown off with Korinna's Allaying Crook ! I saw her fly into her den to the west. I must warn you, she can become very protective when she's in there. Please be careful, but do not be afraid to give her some tough love. She is exceptionally resilient. Here, take her slobber ball. It's her favorite and may help to distract her.", ["objectivesText"] = "Retrieve Korinna's Allaying Crook from Kala inside her den. Progress: Do you have the crook?", ["rewardGold"] = 716040, ["rewardXP"] = 1770, ["rewardItems"] = { 172036, 172037, 172039, 172141, 175616, 175617, 175618, 175619, 183045 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57571] = { ["id"] = 57571, ["name"] = "Moving Mirrors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "What sort of horrific trap is this? The Light is being reflected directly on her! Simone 's a dear friend of mine! Free her from that thing, please!", ["objectivesText"] = "Redirect the mirror fragments to free Simone .", ["rewardGold"] = 382590, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57583] = { ["id"] = 57583, ["name"] = "Through the Veil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving. Here, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you? Come back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.", ["objectivesText"] = "Find somewhere to plant Marasmius in the Heart of the Forest.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 178033 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57584] = { ["id"] = 57584, ["name"] = "A Fate Most Noble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57261, 60735 }, ["description"] = "Welcome, Worthy One! I am Greeter Mnemis . It is my duty and pleasure to assist you on this, your first day among the kyrian. Allow me to congratulate you. Your fate is reserved for the most noble of souls. Only those who lived a life of service may call Bastion home. I am certain you have many questions- all new aspirants do! Please allow me the honor of introducing you to the next chapter of your existence. We will begin when you are ready.", ["objectivesText"] = "Learn more about the kyrian. Progress: Please alert me to your needs and concerns, Worthy One.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158281, ["x"] = 0.422, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57634] = { ["id"] = 57634, ["name"] = "Bring Your Own", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57634 }, ["description"] = "Scunner , a roiling mass of flesh and slime, has crawled out of the ruins of the House of Plagues. He emits a toxic vapor that impairs the functions of those who attempt to fight him. You can try it, Maw Walker, but it's doubtful you could hurt him on your own. Constructs are built to fight creatures like Scunner . So gather a force of them and eliminate the threat.", ["objectivesText"] = "Defeat Scunner .", ["rewardXP"] = 8165, ["rewardItems"] = { 178658, 181806, 182382, 182959, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159199, ["x"] = 0.554, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57636] = { ["id"] = 57636, ["name"] = "Pride of Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 57473, 57475 }, ["description"] = "The Mantle of the Primus. It belongs on his statue. You were the one to recover it, so you will have the honor of returning it to its proper place.", ["objectivesText"] = "Place the Mantle of the Primus. Progress: Each answer leads to another question. Each enemy defeated reveals another secret.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 182258, 182267, 182276, 182285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 20, ["flags"] = 0 } } },
[57644] = { ["id"] = 57644, ["name"] = "No Friend Left Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "I would care for nothing more than to serve as navigator again, but my dearest friend suffers. I cannot stand to abandon him. I can feel Twigin now. He struggles against the binding web of the spiders who once served us. More victims of this senseless conflict... Though it pains me to say it, you must slay our spiders and gather their caustic venom. You can then use it to free Twigin . If not out of empathy, rescue him for the sake of your plans. My skills will be useless without his direction.", ["objectivesText"] = "Rescue Twigin . Progress: Please spare him this pain.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181237, 183118 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158604, ["x"] = 0.509333, ["y"] = 0.166667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 158604, ["x"] = 0.509333, ["y"] = 0.166667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.509333, ["y"] = 0.166667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57646] = { ["id"] = 57646, ["name"] = "The Tithelord", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "With his army defeated, the Tithelord is vulnerable. Now, he has but a small contingent to protect him. Let us strike him down decisively. He draws power from these anima wells, keeping it all for himself. If you can hold his attention, I can not only empower you to defeat him but also disable the wells. Speak to me when you are ready to begin. When the time is right, the baroness will lead our new recruits into battle.", ["objectivesText"] = "Slay The Tithelord and collect the Medallion of Envy . Progress: An Archlich? This complicates things.", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 173976, 180920, 180921, 180922, 180923 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167689, ["x"] = 0.6864, ["y"] = 0.6896 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6864, ["y"] = 0.6896 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57648] = { ["id"] = 57648, ["name"] = "The Impossible Plan", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["series"] = { 62169 }, ["description"] = "Everything is in place for us to seize a necropolis. I will coordinate our efforts and meet you at the Seat of the Primus. Draka will undoubtedly commend you on your success. I, however, will do so once our mission is complete.", ["objectivesText"] = "Report back to Draka at the Seat of the Primus.", ["rewardGold"] = 842700, ["rewardXP"] = 12250, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57649] = { ["id"] = 57649, ["name"] = "Whisper of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "Akarek's demise has cast a dark shadow upon our house... but it is in the shadows where we thrive. I know that not all the Eyes have perished. They could lie in wait, hidden for eternity, if such was demanded of them. But it is time to reclaim our destiny. Take my sigil through the wreckage and awaken any Eyes who remain. We will seize our victory.", ["objectivesText"] = "Use Vashj's Sigil to rally survivors of the House of Eyes.", ["rewardGold"] = 221280, ["rewardXP"] = 8165, ["rewardItems"] = { 172371 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2005 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57650] = { ["id"] = 57650, ["name"] = "Better Off Dead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57650 }, ["description"] = "Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.", ["objectivesText"] = "Eliminate Enemy forces and positions.", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Enemy Troops slain", ["amount"] = 15, ["type"] = 0, ["objectID"] = 161376, ["orderIndex"] = 0 }, { ["text"] = "Siege Artillery destroyed", ["amount"] = 5, ["type"] = 0, ["objectID"] = 165828, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57651] = { ["id"] = 57651, ["name"] = "Trouble in the Banks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "Ah, be welcome in my glade, Maw Walker. You are safe here. While it is regrettable that Sorcha must wait for her weapons, it is of paramount importance that I keep my charges safe. I will do anything to prevent them from suffering as the rest of Ardenweald . Perhaps I could ask a small favor of you. I have not heard from the gatherers at the Banks of Life in some time. Would you mind checking on them to make sure they are well? I would go myself, but I must deal with Sorcha. Seek out Foreman Thorodir .", ["objectivesText"] = "Find Foreman Thorodir near the Banks of Life.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57652] = { ["id"] = 57652, ["name"] = "Supplies Needed: Amber Grease", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57652, 57655, 59623 }, ["description"] = "Foreman, Our supply of gris is running low. You know as well as I do that there is no end to Glitterfall Basin's need of it. I've overheard from some of the other workers that you have a bit of a gorm problem. But the bigger the gorm, the bigger the gris, right? If you happen to harvest some more, we can certainly put it to good use. <The work order is signed: \"Cavina.\">", ["objectivesText"] = "Collect 6 Giant Gorm Gris . Progress: Do you have something for me?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 172221 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1167, ["name"] = "Supplies Needed", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57653] = { ["id"] = 57653, ["name"] = "Unsafe Workplace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "You've returned just in time! Fae are in danger! It seems our actions have enraged the gorm. They are even more aggressive than they were before! While some fae were able to evacuate, there are still many who are trapped down there. Take this jar and slather anyone you find with a generous helping. That should heal their wounds and give them a chance to escape.", ["objectivesText"] = "Heal 10 wounded sylvar in the Banks of Life.", ["rewardGold"] = 18450, ["rewardXP"] = 1415, ["rewardItems"] = { 172950, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57655] = { ["id"] = 57655, ["name"] = "Supplies Needed: More Husks!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57652, 57655, 59623 }, ["description"] = "I need more husks, Thorodir! The Lady herself wants to make sure we are outfitted with the finest armor. They've been soaking in the waters long enough to be workable. Find some time to retrieve them before our hunters find themselves without adequate protection. <The work order is signed: \"Cavina.\">", ["objectivesText"] = "Collect 6 Treated Gorm Husks . Progress: What's that you have there?", ["rewardGold"] = 433950, ["rewardXP"] = 1415, ["rewardItems"] = { 172218 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1167, ["name"] = "Supplies Needed", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57656] = { ["id"] = 57656, ["name"] = "Gifts of the Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "These gorm have gone out of control! We need to stop them. I have a plan, but I cannot do it on my own. We lure the gormlings to the Banks of Life by using special totems that are drained of their anima. If you can retrieve the wood required for the totem, I can prepare the ritual. Take these pipes. Find the Culex trees growing on the banks and play a song for them. You will recognize them by their pale green leaves. The wood must be given freely for the ritual to work.", ["objectivesText"] = "Collect 3 Culexwood Branches. Progress: We need that lure for my clever plan. It's very clever, you're going to love it.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172512, 172517, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57657] = { ["id"] = 57657, ["name"] = "Tied Totem Toter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "Hope you've caught your breath. The totem is now a big, tasty beacon to all the nearby gorm. They're going to want to eat it and you're going to be carrying it! We need to rehome the smaller ones. If they stay here they're just going to get big and angry again. If you can drop off a few groups of them outside the Banks of Life we can make sure they find their way to more balanced feeding grounds. Let Thorodir know when you're done. I will let him know the plan.", ["objectivesText"] = "Lure 30 gormlings to the wrangler in the Banks of Life.", ["rewardGold"] = 372060, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57658] = { ["id"] = 57658, ["name"] = "The Final Leg", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 57658 }, ["description"] = "Please, I must get to Glitterfall Basin. I thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest. I am too close to fall here. The Lady herself invited me to come join her. She said I would be safe. Can you take me to her?", ["objectivesText"] = "Deliver Windchaser to Glitterfall Basin.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57660] = { ["id"] = 57660, ["name"] = "The Grove of Creation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57660 }, ["description"] = "I probably would have been digested if not for you. And while that sounds like a fascinating phenomenon, I am glad I did not experience it... firsthand. You have a knack for solving problems and you're not afraid to get your hands dirty with our tools. Might I suggest paying a visit to Glitterfall Basin, to the west? It is home to our finest minds and workshops, and I am sure they could use your help in this drought. The Lady of the Falls is droman there. She will know where you can best help!", ["objectivesText"] = "Speak with the Lady of the Falls in Glitterfall Basin.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160121, ["x"] = 0.628, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[57661] = { ["id"] = 57661, ["name"] = "Silk Shortage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57661 }, ["series"] = { 60061 }, ["description"] = "We are running short on silk! We use it for so many things, like instruments, weapons, and tools. But our supply has dried up! We are in desperate need for fresh silk. Our main hub of silk production is in the Gossamer Cliffs. If you could, seek out Caretaker Lillythistle , and see what the holdup is!", ["objectivesText"] = "Find Lillythistle in the Gossamer Cliffs.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 178138, 178143, 178144 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158556, ["x"] = 0.484, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159270, ["x"] = 0.39, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[57676] = { ["id"] = 57676, ["name"] = "The Things That Haunt Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["description"] = "As you will soon learn, a ritual cleansing can be a... painful process. In most cases, the upwelling of emotion is harmless. It can even generate anima under the right circumstances. However... sometimes the result is far less pleasant. Negative memories can take a form of their own and manifest in a violent fashion. I fear Pelagos' attempt at cleansing has brought forth such monsters. You must destroy them, and quickly.", ["objectivesText"] = "Slay 12 memories. Progress: Is it done?", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57689] = { ["id"] = 57689, ["name"] = "Prince Renathal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1960, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57690, 57691, 57693, 57694, 59327, 60568 }, ["description"] = "You! They say you are a Maw Walker. Well, time to put that to the test. My master, Prince Renathal, was the one who started the rebellion. He knew Denathrius was working towards something truly nefarious, and attempted to stop him. The rebellion failed, and Renathal was flung into the Maw . I propose you and I venture into the Maw . There is an old device here that only you will be able to use. Together, we can recover my Prince. You need him, if you are to have any hope of success.", ["objectivesText"] = "Enter the Maw to find Prince Renathal. Progress: Your fighting style lacks... finesse.", ["rewardGold"] = 127530, ["rewardXP"] = 710, ["rewardItems"] = { 172446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57690] = { ["id"] = 57690, ["name"] = "Cages For All Occasions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57691, 57693, 57694, 59327, 60568 }, ["description"] = "Okay, do not lose focus. I can feel Renathal's presence. It is faint but I can sense he is outside of the tower, at least. Come, let's find him and get out of here.", ["objectivesText"] = "Find Prince Renathal .", ["rewardGold"] = 157900, ["rewardXP"] = 710, ["rewardItems"] = { 172446 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57691] = { ["id"] = 57691, ["name"] = "A Royal Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57690, 57693, 57694, 59327, 60568 }, ["description"] = "I am not about to question whatever twist of fate led you to me. Your timing could not be better. This cage was custom built to contain me. There is one key, and of course it is on the armor of that large brute over there. Vanquish him and take the key. Be swift, the Jailer's eyes are always on this area.", ["objectivesText"] = "Recover Renathal's Cage Key . Progress: There was an age when I knew how to pick a lock even this elaborate. Sadly that was so long ago I seem to have fallen out of practice.", ["rewardGold"] = 631800, ["rewardXP"] = 1770, ["rewardItems"] = { 172446 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57693] = { ["id"] = 57693, ["name"] = "Torghast, Tower of the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57690, 57691, 57694, 59327, 60568 }, ["description"] = "My allies were taken into the Tower of the Damned, and so we must follow. I do not think we must venture deep into those halls, which is good as I do not believe either of us is in shape for a fight like that. Come, let us find our way to one of the most dangerous towers in all of existence.", ["objectivesText"] = "Recover Renathal's Allies from Torghast, Tower of the Damned.", ["rewardGold"] = 510120, ["rewardXP"] = 1770, ["rewardItems"] = { 172446, 175731 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57694] = { ["id"] = 57694, ["name"] = "Refuge of Revendreth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57690, 57691, 57693, 59327, 60568 }, ["description"] = "Sinfall is more than a ruin. It was once a place of dark magic and experimentation. When the Light retaliated and scorched the Ember Ward, the walls of this place stood. It is fortified, supplied, and filled with secrets. A perfect staging ground for our upcoming conflict. But first, take me to meet these allies who led you to Vorpalia. We must take stock of what resources we have to work with.", ["objectivesText"] = "Gather your allies.", ["rewardGold"] = 147500, ["rewardXP"] = 710, ["rewardItems"] = { 172446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57709] = { ["id"] = 57709, ["name"] = "The Aspirant's Crucible", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57710, 57711 }, ["description"] = "I have given Kalisthene's words some thought. If you are to learn our ways, we should proceed as if you were an aspirant yourself. The next step is to journey through the Aspirant's Crucible. It is a place of reflection, training, and cleansing. For an aspirant, it is where they prepare for the long journey ahead. For you... I hope you will learn how you might help us in this time of crisis. Word of your arrival has likely spread. We will not keep them waiting. Take my steed, and go in service.", ["objectivesText"] = "Ride Theonara to Aspirant's Crucible.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57710] = { ["id"] = 57710, ["name"] = "A Life of Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57709, 57711 }, ["description"] = "Curious. You are unlike any aspirant that has come before, that much is certain. You will notice that we have an audience. It has been a long time indeed since we welcomed another to the path. We are all eager to see what deeds brought you to us. Simply approach the dais before you and gaze into the flame. The Watcher will pull forth your memories of those you served in life, and you will be transported back to those moments to aid them once more.", ["objectivesText"] = "Witness memories of your past life. Progress: Such a display is certain to raise our spirits.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 173344, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57711] = { ["id"] = 57711, ["name"] = "A Forge Gone Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57709, 57710 }, ["description"] = "I have seen firsthand that you are a most capable soul. Kleia has told me of your purpose here. She has spoken of the hopes she places in you. I am not yet certain if I am ready to do the same. There is one small task that I would set before you, however. My forge has grown cold without anima to keep it burning bright. I long to practice my craft again. My helper, whom you have met before, can elaborate on our needs. You will find Sika near the forge. I will follow shortly.", ["objectivesText"] = "Speak to Sika .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57712] = { ["id"] = 57712, ["name"] = "Suggested Reading", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57712 }, ["description"] = "Greetings. You must be the new aspirant everyone is talking about. I thought you might like to learn more about us. There are three tomes that would serve you well as a starting point, but they are not currently in the library. Aspirant Leda was the last to hold \" Worlds Beyond Counting .\" Aspirant Ikaran has yet to return \" The Infinite Treatises .\" It seems \" Bear Witness: The Watcher's Code \" went missing some time ago. I would search the village. Once returned, you can read them at your leisure.", ["objectivesText"] = "Retrieve \" The Infinite Treatises \", \" Worlds Beyond Counting \", and \" Bear Witness: The Watcher's Code .\" Progress: Did you find the scrolls I suggested?", ["rewardGold"] = 265883, ["rewardXP"] = 1060, ["rewardItems"] = { 173023, 173024, 173025, 173973 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157138, ["x"] = 0.554, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157138, ["x"] = 0.554, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1195, ["name"] = "Suggested Reading", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57713] = { ["id"] = 57713, ["name"] = "The Work of One's Hands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57908, 59920 }, ["description"] = "Too long have my hands been idle! < Forgelite Sophone smiles warmly at you.> You cannot know what this means to me, but I might be able to show you. For your aid in restoring my forge, please allow me to craft you a piece of armor. It will not be an extravagant affair, but through good works we grow to know ourselves better. I will need your aid once more. Sika and I will guide you on the specifics. All you need to do is listen and do as instructed. What do you say?", ["objectivesText"] = "Assist Forgelite Sophone in crafting a piece of armor. Progress: There is no greater pleasure than creating something from nothing.", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 90899, 172516, 173317, 173318, 173319, 173320, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57714] = { ["id"] = 57714, ["name"] = "Assessing Your Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "It is clear to all that you are indeed a skilled combatant. There is one challenge here that continues to test even the strongest among us. I would have you attempt to best a well-known centurion, beloved by all aspirants. It is called Athanos . Consider this a test of your spirit. If you can withstand this trial, then I will deem you ready for what lies ahead.", ["objectivesText"] = "Challenge Athanos . Progress: < Kleia watches you impassively.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 173325, 173326, 173327, 173328, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57715] = { ["id"] = 57715, ["name"] = "The Archon's Answer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920 }, ["description"] = "Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", ["objectivesText"] = "Speak to Kalisthene .", ["rewardGold"] = 472680, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156217, ["x"] = 0.535, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 14, ["flags"] = 0 } } },
[57716] = { ["id"] = 57716, ["name"] = "A Wayward Disciple?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57717 }, ["description"] = "While you are here and as yet unaffected by this--rash of doubt, we shall call it--there is one other errand I would ask of you. I sent one of the disciples to investigate reports of the fallen fleeing our temple. For their own safety, they must be taken to the Temple of Loyalty. Disciple Nikolon has yet to return. If he is to be found nearby, it will be near the border of our temple to the north. Please, seek him out and ensure that he is not injured or in peril.", ["objectivesText"] = "Locate Disciple Nikolon . Progress: Have you located Disciple Nikolon ?", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 173340, 173341, 173342, 173343 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57717] = { ["id"] = 57717, ["name"] = "Step Back From That Ledge, My Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57716 }, ["description"] = "This disciple... such emotion... < Eridia stares at Nikolon for a long moment.> Rarely do ascended require such rigorous cleansing, but I cannot deny what is readily apparent. This disciple will fall if I do not intervene. There is no time to lose. Come. I will instruct you. ... I only hope we are not too late.", ["objectivesText"] = "Assist Eridia in cleansing Disciple Nikolon.", ["rewardGold"] = 472680, ["rewardXP"] = 1770, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57719] = { ["id"] = 57719, ["name"] = "Dangerous Discourse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "<The scroll's runes shift and change as you attempt to read it. At first glance, it appears illegible. Similar scrolls have appeared all over the Temple of Purity. Eridia will be interested in these.>", ["objectivesText"] = "Collect 6 Dark Sermons . Progress: We must defend the temple, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57727] = { ["id"] = 57727, ["name"] = "Stonevigil Unrest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "Greetings, <name>. I'm sure you've met my associate, Baroness Draka. I have recruited her to help us with the growing threat of the Tithelord. His involvement with the Maldraxxi renegades is troubling. One conspiracy begets another. So I recruited Draka to help us end it. We must not treat this situation lightly. We first need to put an end to his oppression of Stonevigil Overlook. That way we can we win over the hearts and minds of his subjects.", ["objectivesText"] = "Meet Prince Renathal and Baroness Draka at Stonevigil Overlook.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57729] = { ["id"] = 57729, ["name"] = "To the Estate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "A window of opportunity has presented itself to us, <name>. With his supply line cut off, Vartox dead, and people turned against him, the Tithelord should be no match for us. However, I must admit I do fear what tools he may have acquired from his Maldraxxi cohorts. His base of operations is just down the road: the Caretaker's Manor, named for the Harvester whom he replaced. We will meet you there.", ["objectivesText"] = "Meet Prince Renathal at The Caretaker's Manor.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 140247, 237812 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167620, ["x"] = 0.615333, ["y"] = 0.695333 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167689, ["x"] = 0.6864, ["y"] = 0.6896 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.615333, ["y"] = 0.695333 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57766] = { ["id"] = 57766, ["name"] = "War with the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57766 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 58983, 59641, 60362 }, ["description"] = "Good to see you've received proper training as a <class>. We'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers. King Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job. Before you meet him, let me get get you caught up on what has been happening so far.", ["objectivesText"] = "Speak with Captain Garrick to find out what is happening between the Horde and Alliance.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57771] = { ["id"] = 57771, ["name"] = "An Unwelcome Incursion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "The Tithelord sent his stoneborn to further reap the anima from these citizens. How long has this been going on? These acts reek of unfathomable greed. There is but one answer to this dilemma: to send a message. Crush these oppressors. Drain their anima and return it to Stonevigil's anima well. The incursion will be dealt with and the downtrodden's spirits lifted. Two birds, one stone. <Draka hands you an anima container.> Take this. I stole it from one of the guards earlier.", ["objectivesText"] = "Drain anima from 12 Stonevigil stoneborn. Then, refuel the anima well in the town center.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180947 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57772] = { ["id"] = 57772, ["name"] = "Fangs and Minds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "The denizens of Stonevigil have been wrung dry by the Tithelord's greed. While some have taken up arms against these injustices, most are too downtrodden to act. We need them on our side to take him down. < Prince Renathal hands you a heavy scroll dripping with anima.> Go, show them the hypocrisy of their oppressor! Send them to me with the promise of sanctuary.", ["objectivesText"] = "Use Renathal's Decree to inspire 8 Stonevigil Citizens .", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 178213 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57778] = { ["id"] = 57778, ["name"] = "The Maldraxxian Job", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 61485 }, ["description"] = "We cannot hope to hold the Seat without a necropolis. Khaliiq reports that Vashj is ready to set her plan in motion. Meet with her and the other Eyes at Nurakkir. Do what must be done.", ["objectivesText"] = "Meet with Whisperer Vyn at Nurakkir.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57787] = { ["id"] = 57787, ["name"] = "Keep to the Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60859 }, ["description"] = "That's everything on the list for this part of the forest. Lady Moonberry said to meet her in Tirna Vaal. It's just down the road; I'm going to fly ahead so everyone knows to expect you. Just stay on the path and you won't be eaten. Probably. See you soon!", ["objectivesText"] = "Continue down the road toward Tirna Vaal. Progress: Hey! You survived!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170533, ["x"] = 0.667, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169031, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.667, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57816] = { ["id"] = 57816, ["name"] = "Dreamweaver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Troubled winds sweep across Tirna Vaal. The boughs tremble in concern over the Queen's arrival. All must be as it should be. Dreamweaver 's wings droop with the weight of worry. Chaos swirls around the wildseeds under his care. Calm the churning waters of the grove. Bring harmony to discord and let Dreamweaver flutter once more.", ["objectivesText"] = "Speak with Dreamweaver in the Tranquil Pools.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 152103, 157822, 176445, 179921, 179922, 179978, 237812, 246813, 246815, 248247, 249786, 254267 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169116, ["x"] = 0.642, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57818] = { ["id"] = 57818, ["name"] = "Nothing Goes to Waste", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57824, 57825, 57952, 61051 }, ["description"] = "The gormlings are industrious creatures. Naturally, they are our source of gorm gris. Gormlings are cute, small, and hungry, like Gloober here! Except he is not hungry right now, because I just fed him. Look at that little belly... <Ahem>. I digress. Gormlings will be drawn to consume anything that is not brimming with anima. They find it simply delicious. Take that wildseed there, and bring it into their pen. Then, see if you can get the gormlings to feast upon it!", ["objectivesText"] = "Collect the Depleted Wildseed , place it in the gormling pen, and coax gormlings to eat it. Progress: Have you fed the gormlings?", ["rewardGold"] = 96525, ["rewardXP"] = 355, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57824] = { ["id"] = 57824, ["name"] = "Collection Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57818, 57825, 57952, 61051 }, ["description"] = "Now, we can collect the gorm gris for Guardian Kota! Once the gormlings have eaten something, we can 'encourage' them to give it back up. What they produce, we call gorm gris! My Gormherd Branch should encourage them to do this safely. Go on, give it a try on good ol' Gloober first. What has me worried is how the other gormlings might behave. They have been acting so strangely lately!", ["objectivesText"] = "Use the Gormherd Branch on Gloober , then collect gorm gris from the Gorged Gormlings . Progress: I wonder what would happen if I overcharged the Gormherd Branch ... would that be more efficient? Or would it make things explode? ... probably explode.", ["rewardGold"] = 93015, ["rewardXP"] = 355, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57825] = { ["id"] = 57825, ["name"] = "Delivery for Guardian Kota", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57818, 57824, 57952, 61051 }, ["description"] = "This is most disturbing, indeed. The gorm are just too... wild, now! I wonder if the drought is making everything delicious to them, and that is why. This isn't enough gorm gris, either. And I do not want to disappoint Kota.. But, I also don't want to put you through more trouble collecting it. I will go myself into the burrows nearby, to see if I can find any more for her. Would you take this gorm gris to her for me, please?", ["objectivesText"] = "Deliver the gorm gris to Guardian Kota in Tirna Vaal. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 175741, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57860] = { ["id"] = 57860, ["name"] = "How to Become Forsworn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57860 }, ["description"] = "The Forsworn have taken control of Kalliope's Rest and are looting its antiquities. They must be looking for the Spear of Kalliope, a relic of great power. Their numbers are far too great and we are no match. Perhaps there is another way? A small group of aspirants is removing artifacts from the shrine. If you gather uniform pieces and an insignia from them, we can get you inside the shrine unnoticed.", ["objectivesText"] = "Collect 3 Forsworn Uniform Pieces and a Quartermaster's Insignia from within Kalliope's Rest. Progress: Do you have everything we need to make a disguise?", ["rewardGold"] = 386100, ["rewardXP"] = 8165, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57861] = { ["id"] = 57861, ["name"] = "Just Act Natural", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57861 }, ["description"] = "With this disguise you will blend right in. I... know a Forsworn artificer on the inside who should prove useful. You need to remain convincing, however. The most important thing is to get to Kalliope's spear before the Forsworn manage to do so. The shrine has many defenses, but it's only a matter of time before they find it. I am somewhat ashamed. Many of the aspirants here used to be friends. So much has been lost.", ["objectivesText"] = "Find Artificer Ligiea farther into Kalliope's Rest.", ["rewardGold"] = 105338, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57865] = { ["id"] = 57865, ["name"] = "Ages-Echoing Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Hmph. Even if I wanted to give her weapons, I cannot. My glade is under attack! Most of my people were driven out during the attack on the growthworks but a few of the elders stayed behind. Whether to delay the enemy or see the friends to safety, they are not here where it is safe. Each elder can perform extraordinary works and could make the weapons in no time at all. Rescue the elders and then we'll talk about using their talents for the good of Ardenweald .", ["objectivesText"] = "Locate Elder Gwenna, Elder Finnan, and Groonoomcrooek.", ["rewardGold"] = 372060, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57866] = { ["id"] = 57866, ["name"] = "Idle Hands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "If you want my help then you are going to need to help me first. There is a group of spriggans that have assaulted the growthworks to the northeast. They are causing all manner of havoc and I simply will not abide this trespass into my lands. Go there and teach them a lesson. If they will not flee, then slay them on the spot!", ["objectivesText"] = "Slay 12 Brittlebark invaders in the Growthworks.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57867] = { ["id"] = 57867, ["name"] = "The Sweat of Our Brow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Ah, an outsider! You are perfect for this task. The spriggans are known for their mischief. They have been cursing our tools and supplies and trapping unsuspecting workers! Like our curses, they must obey the rules. You'll need shimmerdust for baskets, thread made of gossamer for harps, and minty fresh breath for the soulwebs. How odd. Good luck and let the Lady of the Falls know when you're done. She'll be delighted to hear it!", ["objectivesText"] = "Disarm 6 trapped tools.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 177161, 177162, 177163, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160045, ["x"] = 0.547, ["y"] = 0.2705 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.547, ["y"] = 0.2705 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57868] = { ["id"] = 57868, ["name"] = "Craftsman Needs No Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Oh, I am quite all right! There's just one little thing.... One of these fiends made off with my lucky mallet! I simply cannot leave my mallet behind. I do not even use it much any more, but it is quite lucky and I always keep it with me. Please, I cannot even think about building anything without it. Do keep an eye out for it, will you?", ["objectivesText"] = "Find Finnan's Lucky Mallet . Progress: It is small, and quite lucky. I am sure you will know it when you see it.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173150, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159427, ["x"] = 0.558, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159427, ["x"] = 0.558, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57869] = { ["id"] = 57869, ["name"] = "Spirit-Gathering Labor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "You are not like the others. The waters here carry deep power. Power most have forgotten. But the tirnenn forget very little. Power flows through the earth just as water flows with power. Flows can be trapped for a time, dripping. Drop by drop they drip into vessels. Search for the vessels beneath the falls. Collect the power.", ["objectivesText"] = "Collect 6 River Sediment . Progress: Drip, drip, go the falls. Drop, drop, goes the power. Power of the earth.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173187, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159428, ["x"] = 0.564, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159428, ["x"] = 0.564, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57870] = { ["id"] = 57870, ["name"] = "The Games We Play", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Do not worry about me. We have a bigger problem. I heard their leader around here somewhere during the attack. I have been keeping watch from here but I have not been able to see them. They must be using some sort of glamour to hide themselves. I have yet to meet a spriggan who can resist a game. If you find one eager to play and can win, then perhaps you can learn something about their leader.", ["objectivesText"] = "Win the game of wits by using emotes to correctly answer the Playful Trickster's riddles.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159465, ["x"] = 0.59, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159465, ["x"] = 0.59, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57871] = { ["id"] = 57871, ["name"] = "Outplayed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Now we can strike down their leader, friend. It just so happens that I have a large pouch of puffpetal powder right here. Why don't you take it and toss a few handfuls around the workshop floor at the top of the falls? If they are still there, I imagine they will have an... unfortunate reaction. While you do that I will gather the other elders and make our way to Glitterfall Basin. Speak with the Lady when your task is done.", ["objectivesText"] = "Defeat Wicked Wort .", ["rewardGold"] = 929400, ["rewardXP"] = 1770, ["rewardItems"] = { 173355, 180728, 183849, 183850 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159465, ["x"] = 0.59, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57872] = { ["id"] = 57872, ["name"] = "Bring More Friends!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57872 }, ["description"] = "This is only the beginning, friend. I must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here. I have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place. She was last seen near Tirna Fein to the west. Please let her know the way is clear.", ["objectivesText"] = "Locate Roriel.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57875] = { ["id"] = 57875, ["name"] = "Mark of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57875 }, ["series"] = { 57914, 57966 }, ["description"] = "Quartermaster, you've arrived. Those fools over there still haven't gotten past the first barrier. We need to get into that cave to have any chance at recovering the Spear of Kalliope. Our research discovered the phrase, \"Only the humble find their way. Even heroes kneel before virtue.\" But those fools have been working on that clue for ages. Go figure out the problem and get inside that cave. We need its mark to open the final vault.", ["objectivesText"] = "Obtain the Mark of Humility from within the First Chamber of Kalliope. Progress: Have you acquired the mark?", ["rewardGold"] = 96525, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57876] = { ["id"] = 57876, ["name"] = "The End of the Beginning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57876, 57877, 57878 }, ["series"] = { 57877, 57878, 58086, 59644 }, ["description"] = "<Renathal struggles to speak, his wounds evident.> I knew Denathrius had hoarded anima, but this... this is beyond imagining. The Jailer will surely use this power to shatter his bonds. Should he break free of the Maw, all the realms of Death will fall. We must continue to press the fight against Denathrius. Alas, we cannot hope to succeed alone. Return to Oribos with Draven and speak to the Honored Voice, Tal-Inara . Tell her what you have seen this day and implore her to action.", ["objectivesText"] = "Speak with the Voice of the Arbiter, Tal-Inara , in Oribos .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393, 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211, 237812 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165557, ["x"] = 0.502, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 126, ["title"] = "The Looming Dark", ["questLineID"] = 1137, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1257, ["questLineOrder"] = 32 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1010, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1137, ["name"] = "Choosing Your Covenant", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1257, ["name"] = "Time Skip", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57877] = { ["id"] = 57877, ["name"] = "The Looming Dark", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 57876, 57877, 57878 }, ["series"] = { 57876, 57878, 58086, 59644 }, ["description"] = "It is good you have returned safely from Revendreth, <name>. We sensed a betrayal that has shifted the infinite threads of fate. The Maw surges with power. We must know the cause.", ["objectivesText"] = "Reveal the Jailer's plan. Progress: As the bearer of this news, you must bear this burden as well.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184378, 184381, 184382, 184383, 184384, 184519 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 126, ["title"] = "The Looming Dark", ["questLineID"] = 1137, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1257, ["questLineOrder"] = 32 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1010, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1137, ["name"] = "Choosing Your Covenant", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1257, ["name"] = "Time Skip", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57878] = { ["id"] = 57878, ["name"] = "Choosing Your Purpose", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 57876, 57877, 57878 }, ["series"] = { 57876, 57877, 58086, 59644 }, ["description"] = "Each covenant is vital to the Shadowlands. Though they often seem at odds with one another, this too is part of the Purpose. All the covenants need to grow strong to face the threat of the Jailer. But your efforts cannot be divided. They must be focused upon a single path. Other mortals may make a different choice. The time has come for you to take a side. Speak to your allies. Then make your choice at the map of the Shadowlands before me.", ["objectivesText"] = "Speak to the Covenants. Decide how your path is entwined with the Purpose. Progress: Have you made your decision yet?", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 126, ["title"] = "The Looming Dark", ["questLineID"] = 1137, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1010, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1137, ["name"] = "Choosing Your Covenant", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57880] = { ["id"] = 57880, ["name"] = "An Estate Within the Old Gate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["series"] = { 60904 }, ["description"] = "I believe I know how we can obtain the Countess's medallion and avoid making any new enemies. Before being cast out into the Light, I held a prominent position within the Countess's court. She bestowed upon me an estate with direct access to her private chambers. If the estate still stands, you can use it to sneak into the Countess's manor and steal the medallion without ever drawing your weapon. Take this note to my trusted butler, Bogdan . He will provide whatever assistance you need.", ["objectivesText"] = "Deliver Theotar's Note to Bogdan within the Old Gate. Progress: What is this? A note from the Duke?", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 173158 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 1, ["flags"] = 1 } } },
[57881] = { ["id"] = 57881, ["name"] = "The Key to Rebuilding", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "If we plan to revive the estate, we'll first need the keys! When Theotar was exiled to the Ember Ward, he lost all titles and property, meaning that the estate fell into the hands of another aristocrat. The new owner is a mystery to me, but household staff almost always carry keys on them as they do their business within the Old Gate. Recover the key and we'll be on our way to rebuilding the manor.", ["objectivesText"] = "Recover an Ornate Key from Redelav house staff within the Old Gate. Progress: Have you recovered the key?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 173180 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57882] = { ["id"] = 57882, ["name"] = "Reestablishing the Household", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "Unfortunately, when ownership of the estate changed hands, the staff were all displaced and forced to find new work. Some of us found suitable roles within favorable households. After all, everyone needs a sommelier! Others were not so lucky. They're still here in the Old Gate, taking odd jobs to survive. I'm sure they'll be eager to work for the Duke again once they learn we're reestablishing the household. Seek them out and present this offer of employment .", ["objectivesText"] = "Deliver offers of employment to Dumitra , Elena , and Florin .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174839 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57884] = { ["id"] = 57884, ["name"] = "Reclaiming Thornhill Manor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I've done some digging and discovered that Viscount Nicolae is the new inhabitant of Thornhill Manor. A vile thing, he is. It'll take us weeks to rid the estate of his stench! Hopefully, you can rid us of him in a much timelier fashion. I'll gather the rest of the staff and together we can reclaim Thornhill Manor.", ["objectivesText"] = "Kill Viscount Nicolae and reclaim Thornhill Manor. Progress: I cannot stand the thought of someone else occupying Thornhill Manor.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57885] = { ["id"] = 57885, ["name"] = "A Discreet Entrance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I can assure you--this is not how we left the place. Never would we ever let the manor fall into such a state. At least the mirror is still intact, that's what's important. You can use it to enter the Countess 's private chambers discreetly and recover the medallion. Go, quickly, before word spreads of what we've done. We'll do our best to restore the manor while you're gone.", ["objectivesText"] = "Enter the Countess 's chambers by using the ornate mirror.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57886] = { ["id"] = 57886, ["name"] = "A Meal and A Deal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "Even though you arrived here uninvited, you weren't unexpected. I know all that goes on within my district. As such, let us share a meal and speak of the matters at hand. I believe there's a way in which we can both get what we want.", ["objectivesText"] = "Enjoy The Countess 's hospitality while listening to her proposal. Progress: Please, enjoy my hospitality.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57887] = { ["id"] = 57887, ["name"] = "Killing the Messenger", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I make it my business to know what is going on within my district. Traditionally we use stone fiends to relay messages, but my informants have alerted me to some suspicious communications going on within the Old Gate. A venthyr has been hired to run missives between two undisclosed parties. When someone puts that much effort into concealing their identity, it can never be good. Find this courier and recover whatever missives they might be carrying.", ["objectivesText"] = "Recover a Treasonous Missive from a Redelav Courier. Progress: Has it been done?", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 173285 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57888] = { ["id"] = 57888, ["name"] = "An Invitation to Treachery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "While the missive made it clear that Andrei is displeased with my position, nothing in the letter identifies his co-conspirator. All we really know is that they are trying to gain access to my soiree this evening so they can carry out their plans. Let's make it easy for them, shall we? Head into the Redelav District and deliver an invite to the prominent houses. This way, we'll be sure the traitors show up.", ["objectivesText"] = "Deliver invitations to each of the noble houses within the Redelav District.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173358 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57889] = { ["id"] = 57889, ["name"] = "\"Accidental\" Arson", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "It's no use trying to get Andrei to tell us who he's working with. He won't talk, and we can't risk alerting his accomplice. We need to get rid of him, and it needs to look like an accident. Once Andrei's been dealt with, set fire to his rug and let the whole estate burn down. Andrei isn't someone you want coming into power. He's as ruthless as he is cruel.", ["objectivesText"] = "Kill Lord Andrei and set fire to his estate.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 180916, 180917, 180918, 180919 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57890] = { ["id"] = 57890, ["name"] = "Beautiful, But Deadly", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "The Redelav District is home to the most affluent venthyr in all of Revendreth. Its denizens spare no expense on the upkeep of their extravagant gardens. Well worth the effort, I must say. For the Redelav District is the only place where Duskmire mushrooms can grow. They are as beautiful as they are deadly. Would you mind collecting a few? Their uses are varied, and it's always a good idea to have some on hand.", ["objectivesText"] = "Collect 50 Duskmire Mushrooms from gardens within the Redelav District. Progress: Do you have the mushrooms?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 173286 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57891] = { ["id"] = 57891, ["name"] = "Mix, Mingle, and Meddle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "Once the party begins, I will be occupied with a plethora of nobles that wish to cling to my side. This is why I need you to mingle. Speak with the attendees and see if you can determine which house is conspiring against me. Be warned, invited guest or not, these aristocrats can smell an outsider. You won't receive a warm welcome from everyone.", ["objectivesText"] = "Attend the Countess 's soiree and speak with guests to uncover the traitorous house. Progress: One among my guests is the traitor. I need you to find out who.", ["rewardGold"] = 241020, ["rewardXP"] = 8165, ["rewardItems"] = { 174923 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57892] = { ["id"] = 57892, ["name"] = "Enacting Immediate Justice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "There are likely many in attendance who wish me harm. I trust you have done your job in determining which house has been working with Andrei? Once they are named, I trust you will enact immediate justice.", ["objectivesText"] = "Name the traitorous house and enact justice. Progress: The traitorous house will be uncovered and swiftly dealt with.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57893] = { ["id"] = 57893, ["name"] = "Neither Enemy nor Ally", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I hope you now see the importance of the role I play. My parties serve a greater purpose. Keeping the influential and elite entertained helps quell uprisings. If their minds are consumed by trivial things, they don't have time to plot or plan. Sometimes, battles are best fought before they begin. Giving you my medallion is an example of that. We may not be allies, but we are not enemies, either.", ["objectivesText"] = "Deliver the medallion to Prince Renathal in Sinfall. Progress: Have you secured the medallion?", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 173287 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 13, ["flags"] = 0 } } },
[57895] = { ["id"] = 57895, ["name"] = "Elysian Hold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57905, 62692, 62698, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "One more step yet remains before your initiation is complete. You must now enter Elysian Hold, entryway to the rest of the Spires of Ascension and the vantage point from which the ascended safeguard Bastion and our aspirants in training. Once there, we shall ensure you are fully acquainted with the hold's offerings. Since you lack wings, I shall escort you there.", ["objectivesText"] = "Travel with Polemarch Adrestes to Elysian Hold.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168906, ["x"] = 0.584, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57897] = { ["id"] = 57897, ["name"] = "Dangerous to Go Alone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "There is one last thing you must do before we can act to clean up Denathrius's chaos. You must have a soulbind. All kyrian undergo this sacred ritual--albeit typically many aeons before they stand before the Archon herself. Soulguide Daelia will guide you in this process. Seek her out in the chamber below.", ["objectivesText"] = "Speak with Soulguide Daelia in the Sanctum of Binding.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57898] = { ["id"] = 57898, ["name"] = "Soul Meets Body", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.", ["objectivesText"] = "Complete the soulbinding ritual. Progress: Take your time. This is a significant step in your journey to ascension.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57899] = { ["id"] = 57899, ["name"] = "More Work?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57899, 57900 }, ["series"] = { 57897, 57898, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Your world has a saying that \"you cannot be in two places at once.\" Without a soulbind, that is true. Thankfully we have resolved that matter. Such physical limitations are a mortal construct. Christen our newest addition to the Hold in the ramparts above, then seek out Koros and you will see.", ["objectivesText"] = "Activate the Command Table.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1207, ["name"] = "Adventures", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57900] = { ["id"] = 57900, ["name"] = "Across the Shadowlands", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57899, 57900 }, ["series"] = { 57897, 57898, 57899, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "As kyrian we are responsible for ensuring that every last soul that enters the Shadowlands is sent to their appropriate eternity. However, our eternal charge does not end in Oribos. There are countless matters in the Shadowlands that need attention--far more than any one of us can handle. That, my friend, is where I come in. Consider me your eyes in the field. Allow me to demonstrate with a simple task, so that you may both reap the benefits of my services.", ["objectivesText"] = "Use the Command Table to start an adventure. Progress: Good things are worth waiting for.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1207, ["name"] = "Adventures", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57901] = { ["id"] = 57901, ["name"] = "All That Remains", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57901, 57903 }, ["description"] = "Just as you must work with your soulbind in an eternal partnership to ensure peace in our realm, so must you work to restore the flow of anima in the sky above. Capheus , one of the great Mikanikos's students, has specialized in the craft of directing what anima we have to the temples that need it most. Given the great drought of anima that plagues us if anyone could use assistance, it would be her.", ["objectivesText"] = "Activate the Anima Conductor. Progress: Yes, yes, you! You can help!", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1208, ["name"] = "Anima Conductor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57903] = { ["id"] = 57903, ["name"] = "Power in the Sky", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57901, 57903 }, ["description"] = "This device you see here can be used to send anima to our temples and aid our people. As each temple regains its flow of anima, it will begin to function once more. You may find these functions useful in your journeys, or you may even find new challenges that await you. Once you have brought some anima to our sanctum, use the device to direct it to a temple, and see the results for yourself.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Bastion. Progress: Does the anima flow?", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1208, ["name"] = "Anima Conductor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57904] = { ["id"] = 57904, ["name"] = "Our Eternal Charge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "You have been fully inducted into our sacred covenant, Maw Walker, and may stand tall forevermore as a kyrian. There will be many challenges ahead of us--we shall face them together. For now, return to Polemarch Adrestes and inform him that your training is complete. We are few in number as of late and I am sure he will have need of you. Go in service, <name>.", ["objectivesText"] = "Return to Polemarch Adrestes .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 174292, 177053, 178156, 179942 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57905] = { ["id"] = 57905, ["name"] = "A Unique Opportunity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57895, 62692, 62698, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "All the anima in the Shadowlands will not restore Elysian Hold to its full glory without willing souls to ensure its many capabilities function properly. Soulguide Daelia is one of our most veteran watchers. She has been tasked with bringing souls to these halls once more. You should pay her a visit within the Sanctum of Binding to see if you might be of aid.", ["objectivesText"] = "Speak to Soulguide Daelia in the Sanctum of Binding.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57908] = { ["id"] = 57908, ["name"] = "The True Crucible Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57713, 59920 }, ["description"] = "I confess, <name>. I had little hope when you first arrived. Kleia is convinced that your presence here is a sign of things finally improving in Bastion . I was... skeptical. <The Forgelite gestures to her forge.> What you have done for me will not soon be forgotten. There is a path beyond the Crucible. To walk it, you must overcome a trial. It will be difficult. Such a thing takes eons for most. You are not most. Kleia and Pelagos will tell you more. They await you near the sparring grounds.", ["objectivesText"] = "Speak to Kleia and Pelagos in Aspirant's Crucible.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57909] = { ["id"] = 57909, ["name"] = "Assessing Your Stamina", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "The trial ahead will test you on many levels. I, like Kleia, wish to assess your willingness to endure. Look around you. All the aspirants here train for the very trial you are to attempt. Some have been here, honing their skills, for centuries. Ages. Some grow quickly, some do not. Your task is to engage them in friendly, armed combat. Among the kyrian this is known as a combat meditation. Help them find focus, and they shall help you do the same. Return to me when you feel ready to continue.", ["objectivesText"] = "Participate in 8 combat meditations. Progress: Trust in the process, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158861, ["x"] = 0.5355, ["y"] = 0.831 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158861, ["x"] = 0.5355, ["y"] = 0.831 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5355, ["y"] = 0.831 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57912] = { ["id"] = 57912, ["name"] = "Baron of the Chosen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Our forces at the Spearhead are under siege from Margrave Gharmal's vanguard. If Vyraz himself is leading the defense, then the situation must be dire. The House of Constructs shapes flesh to forge bodies for its forces. They were once an indispensable ally, but have become a fearsome enemy. Margrave Krexus trusts your might. No doubt you will have need of it.", ["objectivesText"] = "Meet with Baron Vyraz at the Spearhead.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159894, ["x"] = 0.392, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57914] = { ["id"] = 57914, ["name"] = "Mark of Knowledge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57914 }, ["series"] = { 57875, 57966 }, ["description"] = "There is another matter for which I need your assistance. My researchers and interrogators have been tirelessly working on the second chamber. So far they don't have any leads. I need you to speak to them and see if they've made any progress. Tell them, if they have nothing to show, then they will soon find themselves at the end of my sword. Get me that mark, quartermaster!", ["objectivesText"] = "Obtain the Mark of Knowledge . Progress: Did you bring the mark? If not, then why are we speaking?", ["rewardGold"] = 105338, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57918] = { ["id"] = 57918, ["name"] = "The Absolution of Souls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57918 }, ["series"] = { 57919, 58093 }, ["description"] = "Do you not yet understand the purpose of Revendreth , Maw Walker? The souls under our care teeter on the brink of permanent damnation. Even with perfect attention and careful processing, not every soul can escape the Maw and be elevated to a higher destiny. That is true under the best of circumstances. Currently, due to your installation of the Chamberlain at the Halls of Atonement, we're instead witnessing the worst of circumstances. We must return to the Halls of Atonement and enforce order.", ["objectivesText"] = "Meet the Accuser at Absolution Crypt.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57919] = { ["id"] = 57919, ["name"] = "An Abuse of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["series"] = { 57918, 58093 }, ["description"] = "The souls have suffered tremendously under the Lord Chamberlain. We venthyr subjugate souls to our will so that we may lead each to the absolution it requires--willing or not. The Lord Chamberlain, however, has been using our relics and rituals to abuse the souls under his authority. He binds the souls to their sinstones, perverting their very essence! Use these ritual chains on the abused soul and subjugate it to your will. We must attempt to absolve it.", ["objectivesText"] = "Subjugate the Abused Soul. Progress: Every lost soul is a tragedy.", ["rewardGold"] = 505440, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57920] = { ["id"] = 57920, ["name"] = "The Proper Souls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "We must save as many souls as we can from the fate we have just witnessed. Search the halls for souls who have escaped the Lord Chamberlain's perverse rituals. Subjugate them and bring them to me inside the Halls of Atonement. Together, we will make certain that each soul is appropriately processed and cared for.", ["objectivesText"] = "Subjugate 4 Fugitive Souls and deliver them to the Accuser . Progress: If even one soul can be saved, it is worth it.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57921] = { ["id"] = 57921, ["name"] = "The Proper Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "There are very specific procedures that we must follow to best tend to the souls under our care. You and I will follow them exactly. I can mask your garish appearance, but you must acquire the necessary ritual tools on your own. Requisition them from the depraved venthyr serving the Lord Chamberlain nearby.", ["objectivesText"] = "Collect Venthyr Ritual Robes , Dagger, and Tome. Progress: We will do this the proper way.", ["rewardGold"] = 505440, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57922] = { ["id"] = 57922, ["name"] = "The Proper Punishment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Thankfully, I am not the only one who remembers the high calling of the Halls of Atonement and its servants. These avowed ritualists have been working covertly to preserve the integrity of the halls. They report that the Lord Chamberlain relies on a particularly gifted soulflayer to teach other ritualists how to corrupt the souls. Give him the reward he deserves.", ["objectivesText"] = "Kill Fata the Soulflayer .", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57923] = { ["id"] = 57923, ["name"] = "Ritual of Absolution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "The ritual of absolution is a sacred rite that forces souls to discard the burdens of their mortal lives. The soul must be a willing participant if the ritual's effect will be meaningful and long-lasting. We often spend ages preparing a soul for a single absolution ritual. The Lord Chamberlain has neglected his duty. These souls are overdue for absolution, practically bursting with anima. We will perform the ritual ourselves, and hurry these souls along their journey.", ["objectivesText"] = "Help the Accuser complete the ritual of absolution. Progress: Absolution is where mercy meets justice.", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160163, ["x"] = 0.713, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57924] = { ["id"] = 57924, ["name"] = "Ritual of Judgment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "After all rituals of absolution are complete, each soul must face its final judgment in Revendreth . There are three potential verdicts: If proven unworthy, it is condemned to the Maw for eternity. If fully absolved of its sins, it is either elevated to a venthyr or returned to the Arbiter to be assigned its new destination. Our most sacred ritual, the judgment, determines this fate. One such ritual is happening now. I will disguise you and we will participate to ensure a just verdict.", ["objectivesText"] = "Participate in the ritual of judgment.", ["rewardGold"] = 189540, ["rewardXP"] = 1060, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160163, ["x"] = 0.713, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160294, ["x"] = 0.742, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.713, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57925] = { ["id"] = 57925, ["name"] = "Archivist Fane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Well, our disguises are superfluous now. We will not be welcome after disrupting their depraved ritual. Despite what we've observed here, some steadfast venthyr do still remain within these halls. Those who have not forsaken our vocation, and carry on with our calling. Archivist Fane is one such as these. Aid his endeavors however you can. We will need his insight to loosen the Lord Chamberlain's grip over these halls. I must tend to Gresit. He has much to learn.", ["objectivesText"] = "Introduce yourself to Archivist Fane .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160294, ["x"] = 0.742, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57926] = { ["id"] = 57926, ["name"] = "The Sinstone Archive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "You said Inquisitor Traian oversaw the ritual? < Archivist Fane searches the massive archives in this chamber.> We archivists maintain strict records of every soul that passes through these halls. Or at least we're supposed to. The sinstones of powerful venthyr tend to go \"missing.\" < Archivist Fane rolls his eyes.> I don't see his sinstone here. He might've stolen it, or someone could be hoarding it as blackmail. Help me complete my archives, and I'll get you any sinstone you need.", ["objectivesText"] = "Collect 100 Sinstone Records . Progress: Sinstones are the most powerful weapon in Revendreth .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57927] = { ["id"] = 57927, ["name"] = "Rebuilding Temel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Revendreth demands penance from all, and it would appear that even you are not exempt. < Cryptkeeper Kassir grins.> Do not fear, I have no intention of exacting revenge for the violence you inflicted upon me. But I cannot offer you Temel either. The Lord Chamberlain--who you so wisely chose to install as master of these halls--deemed Temel a threat to his control. His thugs bashed Temel to bits and scattered the pieces among these crypts. It's not the first time I've had to rebuild him.", ["objectivesText"] = "Collect Temel's Head , Body, and Wings. Progress: No matter how broken Temel is, I can rebuild him.", ["rewardGold"] = 505440, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57928] = { ["id"] = 57928, ["name"] = "Atonement Crypt Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "<This key is marked with a sigil that matches the crypts in the Halls of Atonement. What is the Lord Chamberlain hiding away in there?>", ["objectivesText"] = "Open an Atonement Crypt.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 9, ["flags"] = 0 } }, ["startItems"] = { 173735 } },
[57929] = { ["id"] = 57929, ["name"] = "Hunting an Inquisitor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "You may have noticed that inquisitors are protected by the Lord Chamberlain's magic. A potent consequence of wielding the Master's medallion. But now that we have access to Inquisitor Traian 's sinstone from the archives, we have the power needed to break through those defenses. Locate the inquisitor, and order Temel to read out from his sinstone. Declaring the true name and sins of the inquisitor will shatter his defenses and make him vulnerable for a short window of time. Be ready to strike.", ["objectivesText"] = "Kill Inquisitor Traian . Progress: Truth, wielded properly, is a potent weapon.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57931] = { ["id"] = 57931, ["name"] = "Phalynx Malfunction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 58185 }, ["description"] = "As part of their training, I order my phalynx units to march the fields, keeping an eye on the wildlife and any goings-on. Unfortunately, last time they returned they were one fewer in number. Please search the Golden Pasture and search for the missing unit, then return it here.", ["objectivesText"] = "Find Gatamatos in the Golden Pasture and return him to his pedestal in Forgefire Outpost. Progress: My phalynx units require occasional repairs to keep them operational. If one is overlooked, it may malfunction.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57932] = { ["id"] = 57932, ["name"] = "Resource Drain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Usually repairs easy. Anima everywhere! Except drought means we can't just pull it from air. Other sources needed! Take this. Drain anima from cloudstriders. Not ideal, but desperate times.", ["objectivesText"] = "Drain anima from Gilded Cloudstriders 5 times. Progress: Drought has big effects. Feel bad for cloudstriders.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.547, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57933] = { ["id"] = 57933, ["name"] = "We Can Rebuild Him", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Gatamatos needs numerous repairs to meet functional standards. Upkeeping phalynx is part of the role. Lend a hand so we may finish the repairs thoroughly and quickly.", ["objectivesText"] = "Aid Pelodis in repairing Gatamatos . Progress: As long as you keep your phalynx in working condition, they will obey without hesitation.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57934] = { ["id"] = 57934, ["name"] = "Combat Drills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Our phalynx units excel in combat. They are thoroughly trained in taking foes down by the legs, as well as hunting down beasts gone awry. I need you to take stock of Gatamatos's fighting routines. Take him into the cavern below and practice his combat against the wyrms there.", ["objectivesText"] = "Kill 8 Agitated Etherwyrms in the Hall of Beasts with Gatamatos.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57935] = { ["id"] = 57935, ["name"] = "Laser Location", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Phalynx have precise detection mechanisms that allow for excellent scouting. In the cave below we have scattered gems that our units are trained to locate. Escort Gatamatos to run some drills and recalibrate his training.", ["objectivesText"] = "Bring Gatamatos to the Hall of Beasts, then direct him to locate 6 Training Gems . Progress: The technical process behind phalynx tracking and locating their targets is quite fascinating. However... you do not seem the type who is interested in the details.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57936] = { ["id"] = 57936, ["name"] = "Superior Programming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Phalynx listen to their orders. Never disobey! Larions are wild beasts. Can attack. Could eat a steward, probably! Untamed larion lives close. Has chased many stewards, very scary! Please take care of it.", ["objectivesText"] = "Kill Leonid in the Hall of Beasts. Progress: Wild beasts. Terrifying! No thank you! I work with very safe phalynx.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702, 175612, 175613, 175614, 175615, 175635, 175636, 175637, 175638 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.547, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57937] = { ["id"] = 57937, ["name"] = "Tactical Formation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "The principal step of our training regiment for our phalynx is formational drills. They must recall standard kyrian battle formations, and how to flow from one to the next. Formational training is the final piece of information that Gatamatos is still missing. Please aid in retraining him.", ["objectivesText"] = "Aid Gatamatos in taking the correct position in three formations. Progress: A good soldier marches in order.", ["rewardGold"] = 473850, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57947] = { ["id"] = 57947, ["name"] = "Spirits of the Glen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Animals of the forest, mortal souls given form, frolic in the glen. Their anima, a boon to the weald, given freely as rain on the leaves. But danger lurks in the shadows. A dark storm of malice and enmity tears at the trees. Creatures seeking shelter find only peril. Rescue them.", ["objectivesText"] = "Find Choofa in the Spirit Glen.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57948] = { ["id"] = 57948, ["name"] = "Nothing Left to Give", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Oh no, oh no! My friends, they gave so much. So much of their anima, they lost their forms! We all take a form when we come here, you see. Something that suits us! But we give our anima, we give! To help the groves. And we give so much... sometimes too much. I still have some anima. I still have my form! Get me to my friends! We can get THEIR forms back!", ["objectivesText"] = "Restore soul shapes to Slanknen , Rury , and Awool in the Spirit Glen. Progress: Oh dear, oh dear. My friends are in trouble!", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57949] = { ["id"] = 57949, ["name"] = "They Need to Calm Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Spriggans! Nasty spriggans. They came to the grove. They messed it all up! They took the anima from the soul webs! We were collecting it, yes. Collecting it for the Tall Tree and their grove. The spriggans have to pay! Beat them up! Then use this soulweb to take back the anima. We need it! They don't!", ["objectivesText"] = "Defeat Spriggans and use the Soulweb to drain them of stolen anima in Spirit Glen. Progress: Did you destroy them? Did you make them pay?", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 }, { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57950] = { ["id"] = 57950, ["name"] = "Mizik the Haughty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["series"] = { 57951 }, ["description"] = "Bad spriggans! Bad! They take our anima. We lose our forms! And one is worst of all. Mizik! He tells the others what to do. And he rides a gorm! Big, nasty gorm! Get him. Get him!", ["objectivesText"] = "Defeat Mizik the Haughty .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 64482, 176445, 176730, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6844, ["y"] = 0.3508 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57951] = { ["id"] = 57951, ["name"] = "Souls Come Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["series"] = { 57950 }, ["description"] = "To the tree, to the tree! It is time for us to return to the grove. We have our anima. We have our forms. The Tall Tree needs the anima. The Tall Tree will be happy! I will see you there!", ["objectivesText"] = "Report your success to Droman Tashmur in Tirna Vaal.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 173292, 175656, 175657, 175658, 175659, 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57952] = { ["id"] = 57952, ["name"] = "In Need of Gorm Gris", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57818, 57824, 57825, 61051 }, ["description"] = "Our neighboring grove at Glitterfall Basin has sent out a desperate plea for gorm gris. It may have humble origins, but it is an important ingredient for our artisans and crafters. As this drought goes on, it has become increasingly difficult to collect. I would like to help them out, with the resources that we are able to spare. Please, find Master Sha'lor out by the Tranquil Pools, where he keeps our little gormling population. Ask him for more gorm gris.", ["objectivesText"] = "Seek out Master Sha'lor by the Tranquil Pools.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57964] = { ["id"] = 57964, ["name"] = "Revenge Is Easy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57964 }, ["description"] = "There's still a lot of us here, trying to survive in these ruins. These constructs have been encroaching on us constantly. They steal what they can, and haul off any of us they capture to be recycled in their labs. The solution here requires an extensive use of violence, by you!", ["objectivesText"] = "Kill 15 bonefused forces. Progress: I still see a lot of abominations walking around.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181501, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181652, 181653, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181679, 181680, 181681, 181682, 184195, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160523, ["x"] = 0.514, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160523, ["x"] = 0.514, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57967] = { ["id"] = 57967, ["name"] = "Rightful Resting Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57967 }, ["description"] = "You have truly proven yourself a hero in the eyes of those who are its absolute judge. I thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place. Let us meet at Elysian Hold where you can do the honors.", ["objectivesText"] = "Enshrine the Spear of Kalliope in its rightful place at Elysian Hold. Progress: <The resting place of the spear lies before you.>", ["rewardGold"] = 116100, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57976] = { ["id"] = 57976, ["name"] = "Lead By Example", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Margrave Krexus expects much of you, mortal. Show these soldiers how a true champion of the arena vanquishes their foes and claims victory! Meet these traitorous constructs head on. Leave none standing!", ["objectivesText"] = "Kill 12 Steelskin Vanguard or Steelskin Brutalizers . Progress: What?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120, 237812 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159894, ["x"] = 0.392, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 }, { ["mapID"] = 1536, ["npcID"] = 169359, ["x"] = 0.394, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57977] = { ["id"] = 57977, ["name"] = "A Temple in Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57270 }, ["description"] = "< Eridia peers down at you.> Your face is new to me. < Eridia frowns.> I regret that this shall be your introduction to our temple. As my disciple has informed you, we seek the aid of all available aspirants to tend to those in our care. Do not trouble yourself over the specifics of the work that is needed. Those devoted to this temple will guide you. Seek out the disciples within. You may find me within the temple when you have given your aid.", ["objectivesText"] = "Aid the disciples within the Temple of Purity. Progress: Have you lent my disciples your aid?", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57979] = { ["id"] = 57979, ["name"] = "Offensive Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Fine work, $p. We've advanced with minimal casualties. From this new forward position, we can strike directly at the enemy commander. The troops you rallied will join the attack. Together, we will bring this battle to a decisive end. Locate General Alver and sound the horn.", ["objectivesText"] = "Kill General Alver .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 175763, 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57982] = { ["id"] = 57982, ["name"] = "Breaking Down Barriers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "As I suspected, Stitchflesh's assistants are carrying on his work. Whatever they're building, we need to destroy it. They've secured the chamber with a soul barrier and several bile spewers. We must find a way through! Thales said he may have a suggestion.", ["objectivesText"] = "Find a way past the Soul Barrier. Progress: Is the barrier down?", ["rewardGold"] = 121680, ["rewardXP"] = 710, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57983] = { ["id"] = 57983, ["name"] = "Archon Save Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Most of the aspirants were slaughtered and dismembered on arrival. They were the lucky ones. The lead surgeon decided that the only things worth taking from me... were my eyes. I was discarded afterward and left to my rot. Archon save me, the screaming... I think there are other survivors being held nearby. Can you aid me in freeing them?", ["objectivesText"] = "Save the souls in the Holding Pens. Progress: Yes?", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.344667, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57984] = { ["id"] = 57984, ["name"] = "The Ones in Charge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "They have been collecting kyrian... and our corpses... for some dark purpose. Whatever they are planning, we must put a stop to it. I have overheard mention of three individuals who seem to be in charge. We need to find them and eliminate them.", ["objectivesText"] = "Slay Doctor Hivvil , Tabulator Hymeris , and Leacher Cvan .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175474, 175475, 175476, 175477, 176456, 179923, 180120 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57985] = { ["id"] = 57985, ["name"] = "Give Them a Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The corpses are brought to this pit for processing. Their flesh is liquified and congealed before being shaped into new constructs. We can hinder their production by extracting the animates from the pool prematurely. Use this hook to do so. Do not let Baron Halis catch you. He has a reputation for cruelty, even within his own house.", ["objectivesText"] = "Destroy 10 Vestigial Animates . Progress: The weak make way for the strong, such is the way of Maldraxxus .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57986] = { ["id"] = 57986, ["name"] = "A Burden Worth Bearing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Mevix may be here for blood, but what I want is to spare my fallen kin from a terrible fate. Most of my fellow kyrian were either slain in combat or shortly after arriving here. If their corpses were bound for this pit, then perhaps we can recover them before they are thrown into it. Take the stewards with you and gather the bodies of my brethren. I will not allow them to be made into monsters.", ["objectivesText"] = "Help Kou and Koa retrieve 6 Lost Kyrian. Progress: Were there any left?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169949, ["x"] = 0.3, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.344667, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57987] = { ["id"] = 57987, ["name"] = "A Deadly Distraction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Vyraz's assault on the House of Constructs may have failed, but we can still make them bleed now that we're inside. Slaughter as many as you can. I will hunt down the masterminds behind these new production efforts.", ["objectivesText"] = "15 Warstitched forces slain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120, 180127 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57989] = { ["id"] = 57989, ["name"] = "The Spear of Kalliope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57989 }, ["description"] = "The Spear of Kalliope is finally in my grasp! With it, I will lay waste to all the Forsworn's enemies. Now behold while I take my prize!", ["objectivesText"] = "Defeat Artificer Ligiea and earn the Spear of Kalliope . Progress: Did you find the spear?", ["rewardGold"] = 386100, ["rewardXP"] = 8165, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57993] = { ["id"] = 57993, ["name"] = "Two of Them, Two of Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "A construct made entirely of kyrian flesh... This betrays everything Maldraxxus stands for! We are meant to defend the Shadowlands and all within it, not slaughter and exploit them! Come, $p! We end this now!", ["objectivesText"] = "Defeat Sharrex the Fleshcrafter and First Apprentice Malkrex .", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 175447, 175448, 175449, 175450, 176456, 179923, 180120, 180127 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165575, ["x"] = 0.288, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57994] = { ["id"] = 57994, ["name"] = "In The Flesh", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The souls of the fallen kyrian... I can sense their pain and confusion. They yet exist within the construct! Please, we must not destroy it. Doing so would consign the souls within it--the souls of my brethren--to oblivion. Perhaps... perhaps they can aid us in escaping to freedom. I will soothe the souls within the construct while you direct its actions.", ["objectivesText"] = "Take control of the Soulfused Construct and escape the House of Constructs. Progress: My fallen kin...", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 30341, 30342, 30352, 30519, 44378, 44379, 44380, 44381, 171354, 176456, 179923, 180120, 182257, 182266, 182275, 182284, 204714, 204728, 204797, 204805, 204810, 204811, 237812 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165575, ["x"] = 0.288, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 13, ["flags"] = 0 } } },
[58007] = { ["id"] = 58007, ["name"] = "Eyes on the Problem", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "Our enemies rally at our gates. We cannot rely on daring air strikes to hold them at bay. Vashj has a plan to permanently bolster our defenses. With your help, it might actually succeed. Do what you can to assist her. She seems more... agreeable toward you than she is with me.", ["objectivesText"] = "Speak with Vashj and put her plan into action.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2005 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58011] = { ["id"] = 58011, ["name"] = "Bug Bites", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58016, 58027 }, ["description"] = "Margrave Stradama eagerly awaits the completion of our latest potion! However, I seem to have misplaced my stockpile of venom sacs. How embarrassing! I have felt a touch out of sorts lately... Would you please do me a favor and fetch some more? We cannot continue our work without them!", ["objectivesText"] = "Collect 6 Bloated Venom Sacs . Progress: Now where did I put my venom sacs...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58016] = { ["id"] = 58016, ["name"] = "Spores Galore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58011, 58027 }, ["description"] = "My brightest apprentice, you return to me at last! You worried me--you see, I heard the loudest clatter while working on one of my experiments... Before I knew it, I was here, and you'd disappeared! Wherever you went is no matter. You're back now, and we have much to do! Come, my apprentice--we must fetch our ingredients first. Can you smell the spores germinating around us? We should pull some up to use in our endeavors!", ["objectivesText"] = "Harvest 8 Stringy Spores.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58022] = { ["id"] = 58022, ["name"] = "Finish What He Started", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "Finding Sha'lor is our main priority. But there is another opportunity. Take the Gormherd Branch that he dropped. I know he was tinkering with it so that it would work on wild gorm. Use it on the gorm in the burrows, and see if you can collect any of their gorm gris. Don't bother with the little ones; get the really potent stuff from the bigger gorm. Perhaps if we can collect enough, and find that silly sylvar, he will not rush horns-first into the burrows again.", ["objectivesText"] = "Use the Gormherd Branch to collect Wild Gorm Gris from gorm in the Dusty Burrows. Progress: Have you had any luck?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171099, ["x"] = 0.628, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 }, { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58023] = { ["id"] = 58023, ["name"] = "One Big Problem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "We must go after Master Sha'lor. Tirna Vaal needs him! And I... I... I will report to the droman. They must know that Sha'lor is in danger. Then, I will enter the burrows myself from the south and help you defeat it. For now, see what you can find. I refuse to believe that he is gone. That monster will know the fury of a vorkai.", ["objectivesText"] = "Hunt down the Gorm Matriarch . Progress: What's gotten into these gorm?", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171099, ["x"] = 0.628, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58024] = { ["id"] = 58024, ["name"] = "Burrows Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "<The ground has been freshly dug, and there are signs of more tunnels all over the place. Collapsing a few burrows would go a long way toward keeping Tirna Vaal safe from gorm infestation.>", ["objectivesText"] = "Collapse Gorm Burrows in the Dusty Burrows.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171195, ["x"] = 0.622, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 }, { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58025] = { ["id"] = 58025, ["name"] = "Queen of the Underground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "You tracked the massive gorm here to her den, and we've found Master Sha'lor. Perhaps not entirely unscathed, but he lives. That is enough. One last task remains. Let us end this.", ["objectivesText"] = "Slay the Gorm Matriarch . Progress: Tirna Vaal will not be safe with that monstrosity about.", ["rewardGold"] = 929400, ["rewardXP"] = 1770, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.331333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58026] = { ["id"] = 58026, ["name"] = "When a Gorm Eats a God", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "There is nothing more we can do here. I will get Master Sha'lor safely back to Tirna Vaal. When you get there, report to the droman what we found here. If the gorm have started to eat the dead wildseeds, and are absorbing the power of the spirits within, we are all in serious danger.", ["objectivesText"] = "Report back to Droman Tashmur in Tirna Vaal.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 175663, 175664, 175665, 175666, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.331333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58027] = { ["id"] = 58027, ["name"] = "Slime, Anyone?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58011, 58016 }, ["description"] = "While I know we're both eager to complete our potion, I believe the best lesson I can share with you is patience. Patience and slimes, of course! With the help of slimes, we'll have our laboratory back in working condition. It's just as I taught you: combine your ingredients in the cauldron. Mix until the viscosity is just right... Oh, listen to me--acting as if you've never concocted your own sentient being! Go on, my apprentice! The slimes are calling!", ["objectivesText"] = "Craft a Plagueborn Slime in Marileth's cauldron. Progress: Go on, now! You can do it!", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58031] = { ["id"] = 58031, ["name"] = "Applied Science", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58036, 58045, 59223, 59231, 60831 }, ["description"] = "<What appears to be an old journal sits on Marileth's table, now mangled and missing pages. The entries that are legible seem to have been written by Marileth when he was still sane, before the fall of his house. Perhaps if you find the journal's missing pages, you will gain more insight into what befell the House of Plagues.>", ["objectivesText"] = "Collect the lost pages of Marileth's journal from Plague-doused Remnants.", ["rewardGold"] = 331700, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 4, ["flags"] = 0 } }, ["startItems"] = { 174643 } },
[58036] = { ["id"] = 58036, ["name"] = "Hazardous Waste Collection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58045, 59223, 59231, 60831 }, ["description"] = "Ah, slimes: the dearest of friends and infinitely useful! They will help us craft our potion. But it seems our tools have been scattered around, doused in toxic refuse. Margrave Stradama would be so disappointed at my lack of respect for lab safety! Your slime can comb through the refuse, diluting the plague's harmful agents. Simply pull the cleaned equipment from the body of your slime! Slimes... what would we do without them?", ["objectivesText"] = "Collect 6 pieces of Laboratory Equipment . Progress: Has your slime been useful? I'm sure it has!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58037] = { ["id"] = 58037, ["name"] = "Part of the Pride", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 58184 }, ["description"] = "Pelodis insists that phalynx are superior to all autonomous beings, taking orders without fail. But where is the nuance? Where is the reward for your effort? Larions make fantastic companions, but you must build a relationship with them. Introduce yourself to my pride. You will see that each has a personality of their own.", ["objectivesText"] = "Introduce yourself to 5 Tamed Larions . Progress: Larions are free-thinking beings. They will decide whether you are accepted within the pride.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58038] = { ["id"] = 58038, ["name"] = "All Natural Chews", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "A huge part of larion care is providing for them and keeping them happy. Larions need to keep their teeth sharp and healthy, and for that they need to chew. If you do not give them proper things to chew on, they can get destructive. One of their favorite chew toys are the antlers from the cloudstriders in the nearby field. Please, collect some antlers for the pride to enjoy.", ["objectivesText"] = "Collect 5 Cloudstrider Antlers from Gilded Cloudstriders in the Golden Pasture. Progress: Antlers are great for keeping my pack's teeth sharp and clean.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58039] = { ["id"] = 58039, ["name"] = "Larion at Large", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Some larions are more particular about the people they bond with than others. Lentios is my companion, the larion I trust most with my life. I love the others as well, but he is a part of my soul. One of my pride, Andira , has posed a struggle for me to bond with. She ran off into the pastures once again, and I fear she's gotten into something she shouldn't have. Would you mind finding her and bringing her home?", ["objectivesText"] = "Find Andira in the Golden Pasture and return her to Nemea 's Retreat. Progress: Andira and I do not see eye to eye. I know she will be a loyal companion... but perhaps to somebody else.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702, 182653 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 10, ["flags"] = 0 } } },
[58040] = { ["id"] = 58040, ["name"] = "With Lance and Larion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Say what you want about phalynx, but Larion will always have one major advantage. Wings! A bonded larion will hunt alongside you whether you are on the ground or in the air. Take my javelin and Andira then go out into the fields to hunt the cloudfeathers there. You'll feel the boon of larion companionship firsthand!", ["objectivesText"] = "Kill 5 Cloudfeather Greatwing in Greatwing Roost.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58041] = { ["id"] = 58041, ["name"] = "Providing for the Pack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Even beings of the Shadowlands need to eat. They may not do so quite like your world, but it is similar enough. The pride's favorite prey is the juvenile cloudfeathers found nearby. Prove to Andira that you are a contributing member of the pride by taking her out to hunt for their next meal.", ["objectivesText"] = "Collect 10 Cloudfeather Essence . Progress: Larions bond through hunting. Working together with Andira to collect food is vital to your relationship.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 12, ["flags"] = 0 } } },
[58042] = { ["id"] = 58042, ["name"] = "On Larion Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "As a flightless being, you will unfortunately never feel the joy of flying alongside your companion. However... you could still fly with Andira . It seems you have earned Andira 's trust more than I've seen her with anybody else. Would you like to try a flight course? Take wing with Andira , then fly through the rings. Don't stray off course or take too much time to get between rings or she will leave you behind!", ["objectivesText"] = "Mount Andira , then complete the flight course. Progress: I set up the flight course to train the larions to listen to aerial commands. They know where to go!", ["rewardGold"] = 455700, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173332, 173333, 173334, 173335, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 13, ["flags"] = 0 } } },
[58045] = { ["id"] = 58045, ["name"] = "Plague is Thicker Than Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58036, 59223, 59231, 60831 }, ["description"] = "Come closer, my apprentice... I have a mission of dire import! A necromancer came to our house recently, sent by the lich Margrave Sin'dane! He seemed so polite, always eager to lend a hand in my lady's most volatile creations. But I grew wise, my apprentice. The way he skulked around, prodding for our most sensitive experiments... He was trying to steal our slimes! I know it! You should admonish him quite harshly. Show that no harm will come to our friends!", ["objectivesText"] = "Kill Korrim the Cunning . Progress: Have you chided the defiler?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 175455, 175456, 175457, 175458, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58060] = { ["id"] = 58060, ["name"] = "The Night Market", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58060, 58062 }, ["description"] = "<Dracho motions to keep your voice down.> I need some assistance, I promise you will be paid handsomely. At the edge of The Banewood lies some ruins. These ruins are home to a marketplace run by some brokers. They won't let me back there. Let's just say that my goods were deemed to not be up to their authenticity metrics. But you... you're a Maw Walker! Bring them this package and exchange it for some Surberries from Ardenweald. Just don't say I sent you.", ["objectivesText"] = "Bring the Hastily Wrapped Package to Ta'ruca at The Night Market in Revendreth . Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 173689 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160100, ["x"] = 0.526, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160091, ["x"] = 0.51, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1185, ["name"] = "The Night Market", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58062] = { ["id"] = 58062, ["name"] = "A Very Special Guest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58060, 58062 }, ["description"] = "Listen. It is obvious you are doing this deal on Dracho's behalf. I believe Ta'xera , the boss around here, would be very interested in striking a deal with someone of your talents. She resides in the manor at the top of the hill. I recommend you don't keep her waiting.", ["objectivesText"] = "Speak to Ta'xera at The Night Market.", ["rewardGold"] = 70225, ["rewardXP"] = 2040, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160091, ["x"] = 0.51, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160081, ["x"] = 0.524, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1185, ["name"] = "The Night Market", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58068] = { ["id"] = 58068, ["name"] = "...Even The Most Ridiculous Request!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "A fan of the competition, are you? Perhaps you would like to be more than a mere spectator? I will give you a small task... one that not only benefits me, but that also gives you a chance to meet some of the storied competitors here. As you can see, our three remaining houses have sent champions to attend the Contest of Conquest. Talk with them and attend to what needs they might have.", ["objectivesText"] = "See to the needs of the Promenade Champions. Progress: What now?", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 2, ["flags"] = 0 } } },
