[58086] = { ["id"] = 58086, ["name"] = "The Master of Lies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58086, 59644 }, ["series"] = { 57876, 57877, 57878, 59644 }, ["description"] = "Once more unto the fangs of death himself, sword drawn, peace with oblivion made. Let us meet death together and bring him low. Be sure you are prepared for a sustained assault. For once we reveal ourselves, there will be no stopping. When you are ready, direct the Focal Mirror at the gates of Castle Nathria. Let us descend upon our burning enemies with ferocity and swiftness of action.", ["objectivesText"] = "Defeat Sire Denathrius .", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 175479, 175480, 175481, 175482, 175483, 175492, 175493, 175494 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172673, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165557, ["x"] = 0.502, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1038, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1038, ["questLineOrder"] = 31 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1038, ["questLineOrder"] = 31 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1038, ["name"] = "The Master of Lies", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58088] = { ["id"] = 58088, ["name"] = "Juicing Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "I've conceived a task befitting of your \"talents\". Have you heard of the House of Plague? Crafters of toxins and potions. They suffered a tragic accident--a true, true shame. Herein lies the problem: I have long used the work of the plague devisers to bolster my arena performance. Without a potion of their creation, I'd find the fight unnecessarily taxing. The brokers do have such potions, but they \"do not like my face.\" Could you obtain such a potion for me?", ["objectivesText"] = "Find someone at the Challenger's Promenade who has enhancement potions.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957, 229365 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159827, ["x"] = 0.538, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159833, ["x"] = 0.536, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58090] = { ["id"] = 58090, ["name"] = "Side Effects", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["series"] = { 58095 }, ["description"] = "Scrapper Minoire's use of enhancers creates unpredictable betting implications. It is quite unhealthy... for our profits! For a nominal fee, Au'larrynar can provide you with a \"special\" enhancer that Minoire will not be able to resist: a potion that turns the one who imbibes it into the ultimate combatant... and teaches them a lesson in restraint, as well. I cannot wait to see Minoire's next match in the arena!", ["objectivesText"] = "Deliver the potion to Scrapper Minoire. Progress: This is an unexpected turn of events.", ["rewardGold"] = 24335, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957, 237812 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159833, ["x"] = 0.536, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58092] = { ["id"] = 58092, ["name"] = "Halls of Atonement: Your Absolution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "The depravity outside of these halls is only a whisper of the true horrors being committed under the Lord Chamberlain 's guidance inside the Halls of Atonement. If you truly wish to curb this corruption, you must dethrone the imposter that you installed here. Atone for your own mistake. Kill the Lord Chamberlain , so that we may begin to restore permanent order to this place.", ["objectivesText"] = "Kill the Lord Chamberlain inside the Halls of Atonement.", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002, 184717 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58093] = { ["id"] = 58093, ["name"] = "Our Forgotten Purpose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58093 }, ["series"] = { 57918, 57919 }, ["description"] = "I have no quarrel with you, Maw Walker. The Lord Chamberlain and his abhorrent followers have debased these halls with their perversions of the rituals. Abusing souls and destroying their potential for pathetic mockeries of power. The Accuser would never have allowed this. I have heard rumors that you may still be in contact with her. If so, please inform her of the situation here. She will bring these depraved dogs to heel.", ["objectivesText"] = "Meet the Accuser at Absolution Crypt.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[58095] = { ["id"] = 58095, ["name"] = "Theater of Pain: Help Wanted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12841, ["mapID"] = 1536, ["storyline"] = { 58095 }, ["series"] = { 58090 }, ["description"] = "Oh, bother--the Lich champion has withdrawn from the contest. Well, then... It appears we have an opening! Would anyone like to enter in her stead? Perhaps to increase the odds for their house? Anyone? Oh, <name>! So kind of you to volunteer. No better way to get experience than to just jump right in unprepared! Remember, we can't all be winners.", ["objectivesText"] = "Enter the Theater of Pain dungeon, and defeat the champions within.", ["rewardGold"] = 1158300, ["rewardXP"] = 12250, ["rewardItems"] = { 181646 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12841 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1169, ["name"] = "Theater of Pain: Help Wanted", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58103] = { ["id"] = 58103, ["name"] = "Pride or Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "I hope that working with my phalynx has swayed you, <name>. Let us meet with Nemea . There you can decide whose way of life is superior, and which you would prefer to pursue.", ["objectivesText"] = "Meet with Pelodis and Nemea , then pick a side. Progress: Surely you must agree that the ease of phalynx companionship suits you.", ["rewardGold"] = 30300, ["rewardXP"] = 175, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702, 174281, 177040, 182652, 182653 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 15, ["flags"] = 0 } } },
[58104] = { ["id"] = 58104, ["name"] = "Show, Don't Tell", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58157, 58158, 58159, 61554 }, ["description"] = "As a new champion of the Court, you'll need to be properly introduced to the rest of the Night Fae. And that calls for something big. Bold. Memorable. A demonstration of who you are and where you've come from. Something with... flair. Normally, we spend ages crafting a masterpiece presentation. But we don't have time for that! We'll just have to improvise. <Moonberry winks.> Commune with me so I can pick up the highlights! I'll make sure it's a show to remember!", ["objectivesText"] = "Commune with Lady Moonberry .", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58127] = { ["id"] = 58127, ["name"] = "Inquisitor Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58127 }, ["objectivesText"] = "Progress: With my archives, it shouldn't be too challenging to identify and recreate the sinstone of an inquisitor.", ["rewardGold"] = 262100, ["rewardXP"] = 1415, ["rewardItems"] = { 173793, 173794, 173795 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[58128] = { ["id"] = 58128, ["name"] = "High Inquisitor Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58128 }, ["objectivesText"] = "Progress: Even with my archives, it could be difficult to identify and recreate the sinstone of a high inquisitor.", ["rewardItems"] = { 173794, 173795, 180451 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[58129] = { ["id"] = 58129, ["name"] = "Grand Inquisitor Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58129 }, ["objectivesText"] = "Progress: The Grand Inquisitors are incredibly protective of their secrets. We will need to expend exceptional resources to identify and recreate one of their sinstones.", ["rewardItems"] = { 173794, 173795, 180451 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[58144] = { ["id"] = 58144, ["name"] = "Battered and Bruised", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58144 }, ["objectivesText"] = "Chains collected Neglected Soul retrieved Ash Ghouls slain", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Chains collected", ["amount"] = 1, ["type"] = 0, ["objectID"] = 160473, ["orderIndex"] = 0 }, { ["text"] = "Neglected Soul retrieved", ["amount"] = 8, ["type"] = 0, ["objectID"] = 160400, ["orderIndex"] = 1 }, { ["text"] = "Ash Ghouls slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 160375, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58157] = { ["id"] = 58157, ["name"] = "Break a Leg", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58104, 58158, 58159, 61554 }, ["description"] = "The show is about to begin! You... that's what you're going to wear? Well, I suppose it works. For your grand introduction, we will re-enact recent victories and events that took place on Azzinoth. Er, Azeroth. That's where you're from, right? The Starlight Company has graciously volunteered to assist us in this production. We've recruited some special guests as well! Don't worry about the script. This is your story, after all! Just try not to get too much blood on stage. It's hard to clean.", ["objectivesText"] = "Reenact the Third Invasion of the Legion on Azeroth. Progress: Well, that wasn't... terrible.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58158] = { ["id"] = 58158, ["name"] = "The Fourth Wall, er, War", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58104, 58157, 58159, 61554 }, ["description"] = "It's time for the next act of your theatrical introduction: the Grand Drama Of Azereth! Azeroth. Right. All these worlds are hard to tell apart. Help set the stage, then come back here. You'll need to play a few other characters before you appear as yourself again. Get a move on! We have a lot to cover!", ["objectivesText"] = "Set the Stage then help the reenactment of events after the Legion's fall. Progress: Come on, come on! We have a crowd to please!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58159] = { ["id"] = 58159, ["name"] = "What's My Motivation?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58104, 58157, 58158, 61554 }, ["description"] = "Now for our finale! A thrilling performance of the most recent trials on Azathoth! < Featherlight checks his notes.> Azeroth. Whatever. It features an artificial god, a powerful magic ice princess, an infamous queen, and an eldritch abomination of unspeakable terror! Who doesn't love a good drama with a dash of existential horror? You're back to playing yourself, so just... do whatever heroes are supposed to do!", ["objectivesText"] = "Perform the final acts! Progress: Well! That was exciting.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180263 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160467, ["x"] = 0.41, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58161] = { ["id"] = 58161, ["name"] = "Forest Disappearances", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "A moment of your time, friend? A short while ago a sylvar named Partik came seeking the aid of our grove. He said his village was under attack by the gorm and was in danger of crumbling away altogether. I told him we could not spare any soldiers, but their people were welcome to take refuge with us. However, it has been some time since he left and I have not seen or heard anyone from that region since. Can you go investigate? He came from the northeast.", ["objectivesText"] = "Find Partik .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160440, ["x"] = 0.644, ["y"] = 0.352 }, { ["mapID"] = 1565, ["npcID"] = 169153, ["x"] = 0.644, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58162] = { ["id"] = 58162, ["name"] = "Mysterious Masks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "The village, my friends, gone. They are no more. I came back from the nearby grove to find them... like this. Even Lavrash, my best friend! He came at me with only violence in his heart. They are all wearing these masks now, and they are not themselves anymore. Please, deliver them from this fate. Bring me their masks and perhaps we can decipher this mystery.", ["objectivesText"] = "Collect 15 Featureless Masks . Progress: For so many to fall, I did not think I was gone that long....", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58163] = { ["id"] = 58163, ["name"] = "A Desperate Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "<A well-made, if well-worn, journal catches your eye. Thumbing through the pages, it is clear that this journal once belonged to someone prominent from this group of night fae. The last few pages are torn out of the book. Perhaps if the rest of the pages were located then Partik could help decipher what happened here.>", ["objectivesText"] = "Find the missing journal pages. Progress: What's that you've got there?", ["rewardGold"] = 372060, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173798, 173800, 173872, 173873, 177878, 183851 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58164] = { ["id"] = 58164, ["name"] = "Cult of Personality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "Some of my people are still alive! We must rescue them! The prisoners are kept in cages throughout the ridge, waiting for this horrible fate to befall them. Please, set them free. We cannot let what happened to Lavrash happen to them!", ["objectivesText"] = "Rescue 8 trapped night fae.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58165] = { ["id"] = 58165, ["name"] = "Cut the Roots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "It's just as I feared, friend. The entire village is turned, just like Lavrash. Lewor would have transformed the other elders as soon as possible. They are all strong in their own right. Brave Fiona, clever Bitterfly .... It pains me to say this, but they must be destroyed. For the good of Ardenweald and the forest, slay our former leaders before they can infect the rest of the land!", ["objectivesText"] = "Slay Bitterfly , Fiona Bleakthorn , and Wildtwister Lewor. Progress: If they fell, then what hope do we have?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173732, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58166] = { ["id"] = 58166, ["name"] = "Unknown Assailants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "This must be the stone he found. I do not recognize the mark. You should bring this to the nearby droman. They are wise and retain much of the knowledge of the forests and the realms beyond. They will know what to do.", ["objectivesText"] = "Bring the Strange Runestone to Droman Tashmur in Tirna Vaal. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 155876, 173732, 173800, 173872, 173873, 175675, 175676, 175677, 175678, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58174] = { ["id"] = 58174, ["name"] = "All An Aspirant Can Do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "I think we can agree that such a reply feels... somewhat hollow. I choose to take faith that we have done all we can. All of us. I do not know what comes next, but perhaps the path will reveal itself. In the meantime, Pelagos and I will return to Aspirant's Rest for a moment of respite. We will meet you there, though there is no need to hurry.", ["objectivesText"] = "Return to Aspirant's Rest.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158471, ["x"] = 0.482, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 26, ["flags"] = 0 } } },
[58175] = { ["id"] = 58175, ["name"] = "The Eternal Forge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "The Forgelite Prime has taken up the mantle of building our new Crest of Ascension. No ordinary tools or materials will do. He will require Phaestus, Genesis of Aeons, Hammer of the First Forgelite. It sits at the shrine to the First Forgelite in the Eternal Forge. The Forsworn have taken over this forge to create their own endless centurion army. You must meet Mikanikos at the forge, push back the Forsworn, and retrieve Phaestus for our own uses.", ["objectivesText"] = "Meet Mikanikos at the Eternal Forge.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 109076, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58176] = { ["id"] = 58176, ["name"] = "Stewards of a Feather", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "You! Maw Walker! The forge was bustling. Many forgehands, on task! Then Forsworn came. Some followed their demands, turned to their side. But not all! Yes, rescue forgehands so they can aid us. Work to be done!", ["objectivesText"] = "Free 5 Captured Forgehands . Progress: I tried to save, but am no hero. Can only try to organize chaos.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160648, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160648, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58177] = { ["id"] = 58177, ["name"] = "Refining Ego", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "I will locate Phaestus. In the meantime, task for you! The Forsworn use my forge to make their centurion army. Their vile intentions warp the metals we use! Destroy their centurions, take their parts. Smelt them down in the forge to purify the metals, then return to me. I need much metal for my plan.", ["objectivesText"] = "Collect 8 Purified Metal by collecting Tainted Centurion Components from centurion units and smelting them down at the Eternal Forge. Progress: I keep my resources here. The Forsworn stole from me! I cannot let this stand.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 173879, 173880, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58178] = { ["id"] = 58178, ["name"] = "A Partner for Eternity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58180, 58182, 58183 }, ["description"] = "Before returning to the Hold, one more thing to do. Defeat the Forsworn and their centurion army! This goliath here can help with just that. My finest creation yet! I need an extra pair of hands. Yours will do.", ["objectivesText"] = "Help Mikanikos finish his finest creation. Progress: Trust he is no ordinary goliath. An extension of my hand itself!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58179] = { ["id"] = 58179, ["name"] = "Instruments of Perfection", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "Mikanikos is no ordinary steward. He is wise! Talented! The smartest of us all! Also very particular! He cannot work without his tools. The Forsworn scattered them around the forge! You need to rebuild Crest? Retrieve his tools!", ["objectivesText"] = "Collect Mikanikos 's Soulsteel Clamps , Sparkling Driftglobe Core , and Gracepetal Incense Burner . Progress: I cannot work in these conditions.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173882, 173909, 173910, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160648, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58180] = { ["id"] = 58180, ["name"] = "Phaestus, Genesis of Aeons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58178, 58182, 58183 }, ["description"] = "Sika reports the Forsworn are widespread. They not only took over production, but the rise as well! They organize their armies from the cliffs, send word back to their leaders. They've ransacked our shrine to the First Forgelite and took her hammer. My hammer! Defeat their commander, retrieve Phaestus. You must go now!", ["objectivesText"] = "Collect Phaestus, Genesis of Aeons from Overseer Atticus. Progress: Without Phaestus, we cannot work on the Crest.", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 174061, 174296, 177057, 178160, 179947, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58181] = { ["id"] = 58181, ["name"] = "Building the Base", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "The Crest is almost complete. I give you the honor of the final touch. You have done much. Please, take Phaestus and give the final blow!", ["objectivesText"] = "Complete the Crest of Ascension. Progress: Please care. Phaestus is older than you could dream!", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58182] = { ["id"] = 58182, ["name"] = "Dismantling the Opposition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58178, 58180, 58183 }, ["description"] = "The Forsworn mobilize! We cannot allow them to march. Attune to Bron, share your power with him. Between the three of us, we shall destroy this new centurion army!", ["objectivesText"] = "Ride Bron, then defeat 30 Forsworn forces and dismantle 2 Colossus in the Eternal Forge. Progress: Bron was not meant as a tool of destruction, but will excel at it with you!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58183] = { ["id"] = 58183, ["name"] = "Friend to the Forgelite", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58178, 58180, 58182 }, ["description"] = "With Phaestus in hand, we can start building Crest. Let us return to Elysian Hold. Triumphant!", ["objectivesText"] = "Return to Polemarch Adrestes in Elysian Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58184] = { ["id"] = 58184, ["name"] = "Antiquated Methodology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 58037 }, ["description"] = "You possess the correct mindset for retraining a phalynx. I believe you could find great success here. Before you commit, I implore you to go across the hill and introduce yourself to my rival, Nemea . She believes that her unreasonable, free-willed larions are better partners than my perfect phalynx. Experience her lifestyle so that you may know how much greater my work is.", ["objectivesText"] = "Talk to Nemea at Nemea 's Retreat.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58185] = { ["id"] = 58185, ["name"] = "Success Without Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 57931 }, ["description"] = "The larions seem to truly enjoy your company, Andira most of all. I hope you've come to understand and appreciate the nuance of working with a beast with free will. Now you must spend time with Pelodis , down the hill. His phalynx may be effective, but working with them only brings hollow satisfaction. I am sure working with the phalynx will only strengthen your appreciation of larions.", ["objectivesText"] = "Talk to Pelodis at Forgefire Outpost.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 14, ["flags"] = 0 } } },
