[58208] = { ["id"] = 58208, ["name"] = "Brace for Impact", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1156, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "That's it for warming up. You and the other new recruits are a promising bunch, I'll tell you that much. Hold on... what's that sound? I think something big is headed our way!", ["objectivesText"] = "Find Lady Jaina Proudmoore inside the ship.", ["rewardGold"] = 30, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1954, ["db2PoiUiMapID"] = 1156, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58209] = { ["id"] = 58209, ["name"] = "Stand Your Ground", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1156, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "I hope this rain isn't a bad omen... this is supposed to be a simple rescue mission. You'll be sparring with me today. We have to make sure you can handle yourself once we make landfall. Let's see what you've got!", ["objectivesText"] = "Spar with Private Cole . Progress: Having trouble? Happens to the best of us. Just stay calm, select your target, and use one of your abilities on it. Make sure your target is in front of you. We don't want another incident like when Bjorn tried to throw an axe over his shoulder.", ["rewardGold"] = 120, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1954, ["db2PoiUiMapID"] = 1156, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58211] = { ["id"] = 58211, ["name"] = "Pumped Up", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58211 }, ["description"] = "When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up! Take this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there! Just be careful with whatever you pull up! You could face some resistance.", ["objectivesText"] = "Collect 15 Salvaged Gear by using the Sludge Pump near bubbling sludge. Progress: Have you recovered anything useful?", ["rewardGold"] = 257400, ["rewardItems"] = { 173881, 173892, 181501, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181652, 181653, 181654, 181656, 181657, 181659, 181675, 181676, 181677, 181681, 181689, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
