[58260] = { ["id"] = 58260, ["name"] = "Queens And Future Kings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58260 }, ["description"] = "A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage. With Twigin's help, eliminate the queens and recover larvae from the eggs. I have a plan for the larvae that may allow us to use the marrowbore to our advantage.", ["objectivesText"] = "Slay 1 marrowbore queens , and collect 5 marrowbore larvae. Progress: It's dirty work, but we need those larvae.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173942, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58264] = { ["id"] = 58264, ["name"] = "Wake Up, Get Up, Get Out There", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "They need your help! Not all of the faeries have been turned yet. Some remain prisoner, but they have these masks on their faces.... You've got to help them! I'm not strong enough to pry off the masks, but you could! You could stop the guards from getting us too!", ["objectivesText"] = "Aid 8 subdued faeries.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 174078 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160749, ["x"] = 0.535, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58265] = { ["id"] = 58265, ["name"] = "Blooming Villains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "Something stinks, traveler. The air to the west is rotten with malice. Shimmerbough has long been a peaceful way station along the Path of Rebirth. The faeries there delight in revelry and celebration. But now their glade has fallen silent. Scouts bring reports of the strange masked night fae. I know little other than that they are a threat. For the sake of Ardenweald , they must be eliminated. Slay any you encounter.", ["objectivesText"] = "Slay 15 masked night fae in Shimmerbough.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 174078 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160929, ["x"] = 0.603, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160929, ["x"] = 0.603, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.603, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58266] = { ["id"] = 58266, ["name"] = "Break It Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "I've seen the ritual. It's... terrifying. But the altars seem to be the key. If only I had my pyrotechnic powder, I could blast them to bits! < Primrose is silent for a moment, then takes a deep breath.> If you could get the powder and guard me, we could blow up those altars. I stashed as much as I could in our dwellings. They don't seem to care any more. You don't have wings, but a pinch of faerie dust should work for a short time. Let's do this before I change my mind!", ["objectivesText"] = "Use Primrose's Pyrotechnic Powder to destroy 5 Ritual Altars.", ["rewardGold"] = 375570, ["rewardXP"] = 1415, ["rewardItems"] = { 31312, 31313, 31314, 31315, 33226, 142054, 174042, 174078, 237812 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160749, ["x"] = 0.535, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58267] = { ["id"] = 58267, ["name"] = "Beneath the Mask", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "It's time to end this. When I first hid, I saw a dark shape on the northeast platform. I think that's their leader. Now that they can't perform any more rituals, we should be able to scare them off. <Primrose pauses for a moment.> I... I just wanted to say thank you. I never could have done this without your help. Now, let's drive out this enemy and retake the village!", ["objectivesText"] = "Confront the leader of the possessed fae in Shimmerbough.", ["rewardGold"] = 375570, ["rewardXP"] = 1415, ["rewardItems"] = { 174078, 175712 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160929, ["x"] = 0.603, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.603, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58268] = { ["id"] = 58268, ["name"] = "Take the High Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath. His forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed. We will take the ridge from him before that can happen.", ["objectivesText"] = "Destroy the three enemy positions.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 169359, ["x"] = 0.394, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58272] = { ["id"] = 58272, ["name"] = "Words Have Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58272 }, ["series"] = { 56978 }, ["description"] = "The Stoneborn Rebels have left behind recruitment pamphlets. Recovering these for the venthyr may earn some much needed favor.", ["objectivesText"] = "Collect 9 Rebellion Pamphlets. Progress: Uncouth and vile documents, but written in a rather elegant hand. The Prince always had better penmanship than sense.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173945, 177665, 183874, 183875 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 }, { ["mapID"] = 1525, ["npcID"] = 156291, ["x"] = 0.632, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1177, ["name"] = "Words Have Power", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58325] = { ["id"] = 58325, ["name"] = "Watcher Emil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Watcher Emil is my trusted overseer of the catacombs. Before I was thrown into the Maw, half of the mirror was entrusted to him. I had him stationed at the Catacombs of Regret. But I do not know where in the sprawl he is. There is a guard station near the entrance to the catacombs. Start the search there. There is an officer who can help us, I--I can't remember who. That is, provided they survived this whole mess. You must find Emil at once. We may not have much time.", ["objectivesText"] = "Search for Watcher Emil in the Catacombs of Regret. Progress: A friend of the Curator ?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58326] = { ["id"] = 58326, ["name"] = "Combing the Catacombs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "When the anima drought began, our defenses began to fail. Our guards, weakened by the lack of anima, became overrun as the sinstones this land is built upon rose up around us. Not to mention the manifestations of the souls who can no longer be tended to are running wild. You may be able to help us, mortal. Please, we can barely hold this position... and I don't know for how much longer.", ["objectivesText"] = "Kill 12 Manifestations and 3 Sinstone Rampagers in the Catacombs of Regret.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58327] = { ["id"] = 58327, ["name"] = "Snacks for Stonehead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58327 }, ["description"] = "< Stonehead has amassed a wide variety of half-eaten oddities. He'd certainly appreciate you bringing some new, creative snacks for him to try.>", ["objectivesText"] = "Collect a sampling of snacks from across the Ember Ward for Stonehead . Progress: Tummy rumbly...", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 175826, 175828, 175829, 175840 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
