[58337] = { ["id"] = 58337, ["name"] = "Break Out", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Our reinforcements never came, leaving us unable to tend to the souls here. They have begun to break out of their cells. Many of them are not ready for the next step in the process. Take these iron chains. They can be used to rein them under your control. Once you have a soul bound, you can return them to any intact cage you can find.", ["objectivesText"] = "Use the Chains of Regret on Escaped Captives and bring them to any intact Catacombs Cage.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 31312, 31313, 31314, 31315, 33226, 37959, 38001, 38044, 38105, 38230, 38231, 38232, 38665, 55004, 65277, 65297, 65316, 65335, 65683, 65703, 65721, 112591, 112592, 112593, 112594, 131699, 142054, 143498, 174040, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 202283, 203330, 211279, 237812, 248563, 248564, 248565, 248566 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58351] = { ["id"] = 58351, ["name"] = "The Hills Have Eyes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "The other houses have yet to launch a full scale assault, but do not mistake their cowardice for incompetence. Any tactician worth their weight in maldracite knows the value of espionage. I suspect that the agents of our foes skulk within our own ranks as we speak. Take one of my hounds. It will know our enemies by their scent. Once the pests have been discovered, exterminate them.", ["objectivesText"] = "Uncover hidden spies with the Chosen Corpsehound. Progress: Get moving!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58372] = { ["id"] = 58372, ["name"] = "Lead the Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "We must move now. That won't be the last assassin we face. I can provide some cover of darkness, but mind that the spell is not infallible. Enough talking. The Curator needs us and my mirror shard to get to her as soon as possible.", ["objectivesText"] = "Escort Watcher Emil out of the Catacombs of Regret.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180924, 180925, 180926, 180927 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 5, ["flags"] = 0 } } },
