[58382] = { ["id"] = 58382, ["name"] = "Someone Worth Saving", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["series"] = { 61077 }, ["description"] = "Are you familiar with Kael'thas Sunstrider? He was a powerful leader on your world for a time. The immense anima of that lingering power attracted the Master's attention, to the eternal detriment of Kael'thas's soul. < The Accuser 's lip curls in disgust.> Every soul deserves a chance at redemption, $p. If you do not believe that, believe me when I say that this soul is immensely powerful and still at risk of self-destruction. Release him so that we may walk his path of redemption together.", ["objectivesText"] = "Release Kael'thas Sunstrider in Sinfall.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58383] = { ["id"] = 58383, ["name"] = "The Many Sins of Kael'thas Sunstrider", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Kael'thas Sunstrider was on the verge of destruction when we rescued him from Castle Nathria. Denathrius had infused Kael'thas with unimaginable amounts of anima, each bit carrying with it the sins of others. It made his soul strong, but unstable--confused and pushed to the edge of its own existence. Trust me when I tell you that Kael'thas Sunstrider has enough sins of his own. Assist me in identifying which of the many sins heaped on his soul are truly his burden to bear.", ["objectivesText"] = "Help the Accuser identify the sins of Kael'thas Sunstrider. Progress: The ritual of absolution allows me to peer directly into a soul to see every sin weighing it down.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174211 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58384] = { ["id"] = 58384, ["name"] = "Dredgers Left Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "When Prince Renathal fled Darkwall Tower, he was forced to leave many people and belongings behind. The powerful relics and weapons were long ago carted off to the Master's lair. But the Prince's dredgers were forced to stay and serve the Master's traitorous lackeys here instead. You will be a welcome sight to them--a sign that the Prince has not forgotten them. If they are willing to fight, help them escape and I will ensure they are brought safely to Sinfall.", ["objectivesText"] = "Help 10 dredgers escape Darkwall Tower.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161208, ["x"] = 0.422, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58385] = { ["id"] = 58385, ["name"] = "Learning to Sacrifice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Kael'thas remains unstable in his current state, bursting at the seams with anima. He is also an arrogant, selfish moron. Thankfully, I have a lesson that can address both concerns. True leaders sacrifice of themselves to empower those under their care. Many stoneborn and gargon, including the Prince's own pet, were left dormant in Darkwall by the Master's forces. Order Kael'thas to forfeit portions of the anima trapped inside of him to reanimate those dormant stoneborn to aid us.", ["objectivesText"] = "Help Kael'thas reanimate the Prince's pet, Vrednic, and other dormant stoneborn in Darkwall Tower.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161208, ["x"] = 0.422, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58386] = { ["id"] = 58386, ["name"] = "Use My Strengths", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "<Kael'thas looks around to make sure the Accuser is out of earshot.> the Accuser is so obsessed with my negative traits that she has failed to see my strengths! Even in death, I am incredibly powerful. the Accuser herself said that Denathrius infused me with anima to make me strong. Let us use that strength for good while I have it! This tower once belonged to the Prince of this realm, correct? Let us find his usurper and gain vengeance! Vengeance is a virtue I have always appreciated.", ["objectivesText"] = "Help Kael'thas confront Usurper Simona. Progress: Yes?", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 137663, 174211 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.4235, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58387] = { ["id"] = 58387, ["name"] = "We Each Must Carry Our Own Sins", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "The Master chained Kael'thas's sinstone to his soul via a dark, corruptive process that left Kael'thas scarred and overburdened. He bears the weight of not only his own sins, but the sins of countless other souls on his back. That would be a crushing burden for even the most noble of souls--which Kael'thas is not. Let us hope your time with Kael'thas has prepared his soul for my ritual. I must break that cursed burden by removing the foreign sins from his soul, or else we'll lose him forever.", ["objectivesText"] = "Complete the ritual of extraction on Kael'thas Sunstrider. Progress: This must work.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174211, 180941 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.4235, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58388] = { ["id"] = 58388, ["name"] = "Blackbale Betrayers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "When the Prince made his final stand at Darkwall Tower, he called for aid from the many noble houses here in the Chalice District. None came. Most simply avoided the conflict, out of self-preservation. A shameful, but understandable choice. However, one house took action. Lord Blackbale replied with cruel mockery and sent his stoneborn to aid the Master's armies instead. Prince Renathal has not forgotten that betrayal. Kael'thas seeks vengeance? Let him have some. Start with the stoneborn.", ["objectivesText"] = "Kill 4 Blackbale Overseers . Progress: The Blackbale seem to have grown more influential since the Prince's fall.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.5145 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58389] = { ["id"] = 58389, ["name"] = "Maldraxxian Weapons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "<The weapon you find seems unlike those wielded by most venthyr, yet the marks it bears are unmistakably familiar... It would be wise to seek out more such weapons and bring them to the Accuser .>", ["objectivesText"] = "Collect 8 Maldraxxian Weapons . Progress: What are you carrying? Those do not belong here...", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 174211, 174212 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.5145 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 10, ["flags"] = 0 } }, ["startItems"] = { 174212 } },
[58391] = { ["id"] = 58391, ["name"] = "Reconnaissance... for my, uh, Recovery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "It appears I am at your mercy once more, $p. Far be it from me to tell you the best way to absolve my sins as the Accuser insists we do. However... In that note, the Tithelord arranged a meeting with his contact in Darkhaven. Do you know where that is? If you do, we could investigate, gather more information, and present that information to the Accuser and Prince Renathal. I imagine that would be quite useful to them. And a very selfless act of assistance on my part, do you not agree?", ["objectivesText"] = "Spy on the Tithelord's meeting with his Maldraxxian contact.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 109076, 174211 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 12, ["flags"] = 0 } } },
[58392] = { ["id"] = 58392, ["name"] = "Death's End Destruction", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "It appears we have discovered a common enemy to pursue, $p. Wherever that necromancer ran off to is no doubt filled with traitors, undead armies from another realm, and at least one lich... It cannot be a sin to kill such as these. To demolish the camp of these invaders and betrayers must be a virtue. A virtue I crave. Let us pursue it with haste.", ["objectivesText"] = "Destroy the Maldraxxian camp in Death's End. Progress: I hope they put up a fight.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 13, ["flags"] = 0 } } },
[58393] = { ["id"] = 58393, ["name"] = "Strategic Executions", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "I confess that I do not comprehend the full array of potential consequences wrought by the Tithelord's anima-sharing arrangement. But I am very aware of the dangers posed by a lich with access to power. I am also very aware that resolving this situation is important to the Accuser, which, given my current situation, makes it important to me. We should eliminate the muscle behind the anima transfer logistics. Without that, the shipments will halt.", ["objectivesText"] = "Kill the dredger giants in Death's End. Progress: They really do grow their monsters big here, do they not?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 14, ["flags"] = 0 } } },
[58394] = { ["id"] = 58394, ["name"] = "Lady Ouix'Ara", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Can you feel it? The chill in your bones... the energy... power... She's here. The lich. Take me to her. I must speak with her, in my own way.", ["objectivesText"] = "Kill Lady Ouix'Ara . Progress: No good has ever come from a lich, <name>.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 174211 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 15, ["flags"] = 0 } } },
[58395] = { ["id"] = 58395, ["name"] = "Enough Vengeance For One Day", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "After the Sunwell's destruction and the near extermination of my people, I vowed to claim vengeance upon Arthas and Kel'Thuzad. But I needed power to see that happen, and to seize that power I... <Kael'thas grows quiet.> I... am ready to return to Sinfall. I must recover my strength for what lies ahead. As the Accuser is so fond of reminding me, I have... much to ponder. Let us inform our allies of the enemy we have revealed.", ["objectivesText"] = "Deliver Kael'thas to Sinfall and report to Prince Renathal .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 174211, 180901, 180902, 180903, 180904 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 16, ["flags"] = 0 } } },
[58406] = { ["id"] = 58406, ["name"] = "Mirror to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58406, 58407 }, ["description"] = "I've received word that Laurent 's made substantial progress with his repairs. Once the mirror has been restored, we can realize our efforts to recover the final medallion. Head to the ramparts and see if his work is near completion.", ["objectivesText"] = "Find Laurent on the Sinfall ramparts.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170532, ["x"] = 0.272, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1018, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1018, ["name"] = "Dominion", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58407] = { ["id"] = 58407, ["name"] = "The Medallion of Dominion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58406, 58407 }, ["description"] = "Laurent speaks the truth. We must not delay. This mirror is our entryway into the heart of Maldraxxus. Together with Kael'thas, we will find Kel'Thuzad and rip the Medallion of Dominion from his undeserving grasp.", ["objectivesText"] = "Use Laurent's mirror to enter Maldraxxus and recover the Medallion of Dominion from Kel'Thuzad.", ["rewardGold"] = 842700, ["rewardXP"] = 12250, ["rewardItems"] = { 180948, 183888, 183889, 183890, 183891, 183892, 183893 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170543, ["x"] = 0.274, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.274, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1018, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1018, ["name"] = "Dominion", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58421] = { ["id"] = 58421, ["name"] = "Special Access", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Mateo will have the other mirror shard we need to access the medallion. He is likely in my former manor in Archivam. It is guarded by Nourman , a loyal dredger. Nourman is ever committed to his duties, regardless of the situation. Mateo likely maintained the same rule to access the manor--possess the fangs of those granted access. If you collect the fangs of the commanders of his operation, Nourman will let you pass.", ["objectivesText"] = "Collect the fangs of Examiner Daciana, Examiner Boian, and Examiner Ionata. Progress: Oi, you want to access the manor? Let me see your fangs.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174093, 174094, 174095 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161298, ["x"] = 0.775, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58424] = { ["id"] = 58424, ["name"] = "An Eye for an Amulet", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Archivam has been overrun by Denathrius's lackeys. We must eliminate these intruders. From the look of things, they have resorted to tearing Archivam down to the core for any evidence of the Curator's medallion. Go, <name>. Stop them before it is too late.", ["objectivesText"] = "Kill 12 Archivam Intruders and 5 Excavation Enforcers in Archivam. Progress: Are they dead?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58426] = { ["id"] = 58426, ["name"] = "In the Shadow of our Failures", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "I will personally tend to the absolution of Kael'thas Sunstrider. His current state and trauma requires nothing short of perfect intervention and instruction to correct. I would welcome your assistance in this. I sense a bond between Kael'thas and yourself. I think your presence may help inspire him down a better path. If you're willing, meet us at Darkwall Tower. Prince Renathal suffered a great defeat there once. Perhaps a better fate will be found this time.", ["objectivesText"] = "Meet the Accuser and Kael'thas at Darkwall Tower.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 174211 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161208, ["x"] = 0.422, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58428] = { ["id"] = 58428, ["name"] = "Crypt Crashers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "There's one more thing I forgot to mention. Apologies, <name>. The mirror, once complete, is inherently cursed by design. You need to locate my Death Lotus Powder . It was in one of the crypts in Archivam... I cannot recall which one. I'm afraid you may have to brute force this one, <name>.", ["objectivesText"] = "Collect Stonebreaker Mallets to destroy crypt doors in search of Death Lotus Powder . Progress: Do you have the powder?", ["rewardGold"] = 292100, ["rewardXP"] = 8165, ["rewardItems"] = { 174098, 174100 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58431] = { ["id"] = 58431, ["name"] = "Pool of Potions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "I shall teach you about the Pool of Potions . The potions we create here have a variety of beneficial effects. Kill the slimes in the surrounding ruins and collect the Oozing Ingredient: Viscous Oil they may drop. Each slime can produce a great quantity of oil, so you'll only be able to carry one slime's worth at a time. Deliver this oil to the Pool of Potions and toss it in.", ["objectivesText"] = "Deliver three Oozing Ingredient: Viscous Oil to the Pool of Potions . Progress: Have you brought enough oil?", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 171267, 171268 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58432] = { ["id"] = 58432, ["name"] = "Something Old, Something Used", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58432 }, ["description"] = "Want new luckydos? Chordy is best at finding luckydos! Want to go look around with Chordy ? < Chordy looks at you pleadingly with his large eye.>", ["objectivesText"] = "Use Chordy to locate and collect 10 valuable salvage in Maldraxxus. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 158149, 174101, 178554, 182489, 182498, 182507, 182516, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 161270, ["x"] = 0.55, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58433] = { ["id"] = 58433, ["name"] = "Anima Attrition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["description"] = "This is not some simple raid or protest. These stoneborn mean to steal the anima this convoy was carrying. That anima was destined to be tithed to the Master. There is a drought on and we cannot let these vagabonds and miscreants steal our hard-earned anima. Recover the tithe if you can and I will see to your notoriety.", ["objectivesText"] = "Recover the Anima Canister . Progress: What have you found?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58437] = { ["id"] = 58437, ["name"] = "Parts to a Whole", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 58437 }, ["description"] = "Damien has some great dreams, but without more abominations, this training facility will not succeed! I have a plan though! If we can't recruit more abominations, then we shall make them ourselves! I need you to make some corpses, then mark them for harvesting with a flag. I will do the rest.", ["objectivesText"] = "Mark 15 corpses for harvesting", ["rewardXP"] = 8165, ["rewardItems"] = { 174110 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Corpses marked for harvest", ["amount"] = 15, ["type"] = 0, ["objectID"] = 161288, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58440] = { ["id"] = 58440, ["name"] = "Mirror, Mirror...", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "We have what we need to get you through, <name>. My medallion lies on the other side of the mirror. Once through, my medallion will be there... somewhere. Please be careful. My mind may be weakened, but I do remember working with the Accuser to protect the crypt's interior. I should be able to tell you everything about this place, but I am afraid that just is not the case anymore.", ["objectivesText"] = "Enter the Curator 's mirror. Then, collect the Medallion of Avarice . Progress: My medallion? Do you have it?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 79868, 87399, 174111, 174179, 175733, 176127, 177657, 180945, 184373, 184374 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 10, ["flags"] = 0 } } },
[58443] = { ["id"] = 58443, ["name"] = "Continued Care of Kael'thas", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Kael'thas is free from the twisted corruption of the Master, but he is not truly \"free\" yet. He carries more than enough burdens from his own sins to condemn him to the Maw. We must be vigilant in encouraging and forcing him to atone for his mistakes. If he cannot right the many wrongs of his mortal life, he will be doomed forever. You are having a positive effect on him. Please, accompany us down to the Chalice District for his next lesson.", ["objectivesText"] = "Meet the Accuser and Kael'thas in the Chalice District.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.4235, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58444] = { ["id"] = 58444, ["name"] = "Return to Sinfall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "<name>, we must get the medallion back to Sinfall as soon as possible. We saw how fierce Mateo's forces were, just imagine what destruction Denathrius will bring if we linger around. I will return to Absolution Crypt in a moment. With all the work you've done, I can begin to resume my duties. My first order of business will be to recruit a new sinkeeper. Oh how I dread interviews...", ["objectivesText"] = "Bring the medallion to Prince Renathal at Sinfall. Progress: Did you retrieve the Medallion of Avarice ?", ["rewardGold"] = 842700, ["rewardXP"] = 12250, ["rewardItems"] = { 174111 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58445] = { ["id"] = 58445, ["name"] = "Containing the Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "It is fortunate you are here, <name>. Thiernax believes he may know how to save Tyrande from the fate he himself suffered as the Night Warrior. Let us hear what he has to say.", ["objectivesText"] = "Listen to Thiernax's plan. Progress: It cannot be easy for Thiernax to share his memories of becoming the Night Warrior... or the pain that followed.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58446] = { ["id"] = 58446, ["name"] = "Tracker Tracking", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "We will require the aid of an expert tracker if we are to find the other Night Warriors. The Wild Hunt possesses legendary skills in such matters. No quarry can elude them. Speak with Lord Herne. With one of his hunters at your side, your search will surely be successful.", ["objectivesText"] = "Speak with Lord Herne and locate the Wild Hunt tracker.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58447] = { ["id"] = 58447, ["name"] = "Monster Hunting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "Make ready, <class>. We hunt a worldeater. They are the largest of devourers, massive beings who can drain anima from an entire region within a matter of moments. With Ardenweald suffering from the drought, a worldeater's presence could prove disastrous. Still, we must not rush into battle without first understanding our prey. Tread the Elder Stand with me. Even creatures such as these leave spoor. Knowing our quarry will be what allows us to slay it.", ["objectivesText"] = "Search for clues and tracks to learn more about the worldeater.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165841, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58449] = { ["id"] = 58449, ["name"] = "Acid Reflux", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "We will need to be properly prepared before we can face Voras. The digestive juices of Ardenweald 's gorm dissipate the anima in their food. Ingesting them causes devourers no small discomfort. For a beast of that size, we will need a lot of it to have any effect. There should be plenty of gorm in the hive to the east. Long ago, an artisan gave me a tool that he said would be useful against the gorm, should I ever need it. You may borrow it.", ["objectivesText"] = "Use the Gormherd Branch on gorm in Gormhive to retrieve 50 Bulging Digestive Sacs . Progress: We will need those digestive sacs if we are to disrupt the worldeater enough to slay it, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 173534, 174467, 174645 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165841, ["x"] = 0.352, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58450] = { ["id"] = 58450, ["name"] = "Anima Instincts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "Voras is clearly content to roam the Elder Stand. We will need a way to lure it to us once we are ready to fight. Did you notice the wildseeds in the clearing where we spotted it? Voras must be feasting on the concentrated anima contained within them. There should still be some expended wildseeds from before the drought in the Gormhive. Let us create bait too tempting for Voras to ignore.", ["objectivesText"] = "Collect 8 Life-Hardened Anima . Progress: It may take several wildseeds, but with enough concentrated anima, we should be able to lure out Voras.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 175753 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165841, ["x"] = 0.352, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58451] = { ["id"] = 58451, ["name"] = "Voras, The Realm Eater", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "We have everything we need, <name>. Now only the kill remains. We set the lure, weaken the beast, and land the final blow. Hunting is a battle of wills. Life or death hangs in the balance for all of us. It has always been this way, on Azeroth as in Ardenweald . Let the hunt begin.", ["objectivesText"] = "Slay Voras . Progress: Voras cannot continue to leech anima from Ardenweald . We must stop it now.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161354, ["x"] = 0.243333, ["y"] = 0.490667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58452] = { ["id"] = 58452, ["name"] = "Tracking the Shadows", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "The quarry has been slain, and my duties fulfilled. The tirnenn are more than capable of defending their home from the lesser devourers. Nature will take its course. I will report back to Lord Herne and meet you at the Heart of the Forest. There we shall see what I will be hunting next.", ["objectivesText"] = "Speak with Ysera in the Heart of the Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 175592, 179769, 179891, 181913 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58454] = { ["id"] = 58454, ["name"] = "Spoiling For A Fight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58454 }, ["description"] = "Your contribution of anima has aided our operation here greatly. Several of our more famous competitors have come here lured by the flow of new anima. Would you like to test yourself versus the famous Sabriel? There could be much profit for everyone, if you were to defeat her. I can add her to the schedule, she will appear soon if you defeat the other challengers.", ["objectivesText"] = "Defeat Sabriel the Bonecleaver in the Theater of Pain.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 181815, 182083 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group" },
[58472] = { ["id"] = 58472, ["name"] = "A Farewell to Arms", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58599, 58608, 58624, 62388 }, ["description"] = "The Maldraxxi toil away just behind us. I care not if you consider them allies or traitors, so long as you remove them from Revendreth. Destroy their encampment. Purge it from our soil, and ensure such an affront never occurs again. The means are not important. All that matters is that these heretics remember the consequences of trifling with true power.", ["objectivesText"] = "Destroy the Maldraxxi encampment at Death's End. Progress: Well?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161694, ["x"] = 0.739, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.739, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58473] = { ["id"] = 58473, ["name"] = "Echoes of Tirna Noch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "It is clear that we need more anima than this grove can provide. I may know of a way we can acquire some. Many of the masked fae have been collecting anima for some unknown purpose. I propose we take it back from them. The Wild Hunt has tracked them to Tirna Noch... my former grove. Long has it been since I walked beneath its boughs. Not since it was left to wither so that other groves might survive. I remember it well...", ["objectivesText"] = "Meet Ara'lon in Tirna Noch.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160963, ["x"] = 0.6, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58480] = { ["id"] = 58480, ["name"] = "Read the Roots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "When my grove withered, I answered the Queen's call and joined the Wild Hunt. Nothing can be done for Tirna Noch. But it wounds me to see it crawling with foes of the forest. We need a great deal of anima. The masked fae must be keeping a stockpile somewhere within the grove--we just need to find it. They likely used soulwebs to collect and move the anima. If I examine them, I should be able to pick up the trail.", ["objectivesText"] = "Investigate the Depleted Soulwebs in Tirna Noch, to find the greatest concentration of anima in the grove. Progress: I sometimes mourn what was lost. And then I remember what work there is still left to do.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58483] = { ["id"] = 58483, ["name"] = "Mementos", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "At Heartwood Grove, I heard tales about the fall of Tirna Noch. I never thought that I would see it with my own eyes. It brings me great sadness. And I wonder... if this is the fate that awaits my old grove as well. I can't believe that everything that was once here is truly gone. Perhaps there are still some mementos that can be recovered. Something to remember the fallen.", ["objectivesText"] = "Collect Stolen Mementos from slain enemies in Tirna Noch. Progress: Is this what lies in store for Heartwood Grove? For my old home?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161379, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58484] = { ["id"] = 58484, ["name"] = "Take What You Can", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "We know that these invaders have taken over the remains of the grove. But why? Why are they gathering anima and bringing it all to one place? And how did they enter Ardenweald ? We should stay alert and take as much anima as we can find. Perhaps some good can come out of all this loss.", ["objectivesText"] = "Take Plundered Anima from stores in Tirna Noch. Progress: I sometimes mourn what was lost. And then I remember what work there is still left to do.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58486] = { ["id"] = 58486, ["name"] = "He's Drust in the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["series"] = { 58488 }, ["description"] = "Only the heart of a grove can hold the sheer massive quantity of anima I'm sensing. When my grove was sacrificed, the anima within its heart was reclaimed. Now it brims with anima once again. Anima that was stolen from other groves. We must secure the heart not just for our own sake, but for the entire forest. I suspect that we will not be allowed to simply trot our way in there. Be prepared for anything.", ["objectivesText"] = "Slay Vroth , Bulwark of Thros, and make your way to the Heart of the Fallen Tree.", ["rewardGold"] = 250380, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161492, ["x"] = 0.714, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58488] = { ["id"] = 58488, ["name"] = "Go for the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["series"] = { 58486 }, ["description"] = "I was right! A great deal of anima has been stored inside the heart of the grove. The Drust must have collected it from all over Ardenweald . And now, we will take it back. Quickly, destroy that barrier and grab the heart. Niya and I will protect you.", ["objectivesText"] = "Destroy the barrier and collect the Heart of Tirna Noch . Progress: We will reclaim this anima. The Drust will not use it for their own ends.", ["rewardGold"] = 125190, ["rewardXP"] = 710, ["rewardItems"] = { 6948, 25712, 25713, 25714, 36739, 50375, 50376, 50377, 50378, 50384, 50386, 50387, 50388, 50397, 50398, 50399, 50400, 50401, 50402, 50403, 50404, 52569, 52570, 52571, 52572, 54921, 54922, 57320, 57321, 57322, 58991, 58992, 58993, 60709, 60710, 64507, 64508, 64509, 64510, 64511, 64512, 64513, 64514, 112603, 112604, 112605, 112606, 129250, 129251, 129252, 129253, 129254, 129255, 129256, 129257, 131300, 131417, 131557, 147442, 156932, 159901, 159902, 159903, 159904, 159905, 159906, 159907, 159908, 160906, 160907, 160908, 160909, 160910, 160911, 160912, 160913, 160914, 160915, 160916, 160917, 160918, 160919, 160920, 160921, 174219, 174269, 175648, 175649, 175650, 175651, 175713, 175740, 176832, 176921, 176922, 179500, 179508, 179517, 179537, 179547, 179562, 179584, 179604, 180287, 180944, 181368, 181377, 181407, 181409, 181410, 181418, 181422, 181423, 181424, 181425, 181430, 181457, 181458, 181459, 181477, 181479, 181506, 181541, 181569, 181577, 181587, 181591, 181603, 181605, 181627, 181632, 181633, 181635, 181636, 181637, 181702, 181704, 181738, 181745, 182128, 182203, 182385, 182480, 182649, 182675, 182736, 182743, 183167, 183402, 183468, 183469, 183473, 183481, 183482, 183486, 183489, 184294, 184362, 184373, 184374, 184381, 184382, 184383, 184384, 184587, 184765, 184766, 184767, 184768, 189865, 198002, 198003, 198004, 198006, 198009, 198034, 198105, 198612, 200597, 204581, 204589, 204597, 204605, 211279, 219764, 219765, 237812, 251547, 253021 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161492, ["x"] = 0.714, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161492, ["x"] = 0.714, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58490] = { ["id"] = 58490, ["name"] = "Deadly Reminder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58490 }, ["description"] = "Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.", ["objectivesText"] = "Eliminate Enemy forces and positions.", ["rewardXP"] = 8165, ["rewardItems"] = { 181811 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Lich Forces Eliminated", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58504] = { ["id"] = 58504, ["name"] = "Accusatory Missive", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["description"] = "We have received word from Revendreth. It seems that Maldraxxi conspirators have been found skulking within their realm. An emissary from Sinfall wishes to discuss the anima reserves we discovered. Join me. We depart immediately.", ["objectivesText"] = "Meet with the Accuser in the Halls of Atonement in Revendreth.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161461, ["x"] = 0.72, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58505] = { ["id"] = 58505, ["name"] = "Planned Demise", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 58505 }, ["description"] = "Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.", ["objectivesText"] = "Eliminate Enemy forces and positions.", ["rewardXP"] = 8165, ["rewardItems"] = { 174231, 174232, 174233 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58515] = { ["id"] = 58515, ["name"] = "Scrounging for Scrolls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58515 }, ["description"] = "The kyrian are known for their collection of scrolls and writings. I'm particularly interested in their texts regarding those who have joined their ranks. Why is it that some of the greatest fighters are sent to Bastion and not to Maldraxxus? Perhaps research can divine the answer.", ["objectivesText"] = "Collect information on the kyrian from the Temple of Humility. Progress: Let's see, where did that paper go?", ["rewardXP"] = 8165, ["rewardItems"] = { 175275, 182486, 182495, 182504, 182513, 183142, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159198, ["x"] = 0.552, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58518] = { ["id"] = 58518, ["name"] = "There's Always a Paper Trail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "I noticed that you were surprised to find those strange weapons here. I sense the essence of their power as well. It is strangely familiar... We must discover where the weapons came from and who imbued them with such power. <Kael'thas smiles.> If you and I present the proof to the Accuser together, perhaps she shall allow us to hunt down whoever is behind all of this!", ["objectivesText"] = "Discover proof of who's supplying the venthyr with Maldraxxian weapons. Progress: You found something?", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 174211, 174278 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.5145 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58523] = { ["id"] = 58523, ["name"] = "You're Dead To Me", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["description"] = "Your cooperation is expected, but I await results. Our reconnaissance has revealed a Maldraxxi encampment in the Endmire. We speculate that your kind have been siphoning the Master's stockpiles of anima. I have called for a carriage to take us there. Let us make haste.", ["objectivesText"] = "Follow the Accuser to the Maldraxxi encampment.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 13444, 13446, 21316, 21317, 34119, 56875, 56876, 56877, 56878, 56879, 56880, 56881, 56882, 60924, 60925, 60926, 60927, 61497, 61499, 61501, 65666, 65689, 66067, 79731, 108972, 108975, 108976, 130219, 131587, 131894, 138819, 138820, 138821, 138822, 138823, 138824, 138837, 142273, 143488, 157003, 160000, 160001, 160002, 160003, 161168, 161169, 161170, 161171, 181501, 181502, 181507, 181645, 181647, 181649, 181653, 181659, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 181802, 182610, 182753, 183744, 184305, 184772, 184773, 184774, 184775, 184776, 184843, 197892, 197895, 197900, 211279, 237812, 237861, 237873, 237878, 237892 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161461, ["x"] = 0.72, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161694, ["x"] = 0.739, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58524] = { ["id"] = 58524, ["name"] = "Sparkles Rain from Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["series"] = { 58589 }, ["description"] = "You found the heart of the grove! And it's full of anima! The Drust don't seem to like the idea of you taking it from them. They're massing in great numbers all over the forest! We need to get you and the others out of here safely. I can help. How do you feel about dishing out a little sparkly mayhem?", ["objectivesText"] = "Speak with Lady Moonberry and escape Tirna Noch.", ["rewardGold"] = 250380, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 175767, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161494, ["x"] = 0.714, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58525] = { ["id"] = 58525, ["name"] = "The Two Sides of History", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58525 }, ["description"] = "You mortals always say that history is written by the victors. But in the Shadowlands, I have found that to be untrue. Everyone has their own version of events. I would like to know them all. There was an author of history books who made her abode in Revendreth's Darkfall Tower. She wrote from the venthyr's perspective of various incursions and battles alongside the Primus. If we could find copies of her works...", ["objectivesText"] = "Find copies of \" On Bone and Stone \" and \" The Malice of Maldraxxus .\"", ["rewardXP"] = 8165, ["rewardItems"] = { 182486, 182495, 182504, 182513, 183142, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159198, ["x"] = 0.552, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58530] = { ["id"] = 58530, ["name"] = "Hidden Mirror", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["series"] = { 61050 }, ["description"] = "If Renathal is going to put the Harvesters' medallions to use, he's going to need a conduit to focus that power. Denathrius's corruption taints the forges of Revendreth. Our best option is in Bastion. As denizens of Revendreth, Bastion will not allow us to enter through Oribos. We will need you to activate a mirror hidden away there long ago. Take this. We concealed it at a rarely used site, the Veiled Enclave. There should be no one there, especially with the drought.", ["objectivesText"] = "Use Laurent's Compact Looking Glass to reveal the Hidden Mirror in Bastion.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 180356 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 162213, ["x"] = 0.501333, ["y"] = 0.306667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.501333, ["y"] = 0.306667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58555] = { ["id"] = 58555, ["name"] = "A Tense Reunion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "We are looking for the forgelite prime, Mikanikos. Only he will be able to craft the device we need. I've seen some of his creations. Truly impressive constructs and weaponry that rival even the mightiest of us stoneborn. When last I encountered him, it was at his workshop. A place of wonders known as the Eternal Forge. We will meet you there. Traveling as a group may draw too much attention.", ["objectivesText"] = "Meet General Draven and Theotar at the Eternal Forge.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 162213, ["x"] = 0.501333, ["y"] = 0.306667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.501333, ["y"] = 0.306667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58557] = { ["id"] = 58557, ["name"] = "Assistance from Sinfall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "In order to defeat the Forsworn, the Crest needs an artifact that embodies repentance, atoning for past mistakes and moving forward. I have an artifact in mind. Long ago, many souls from Revendreth arrived in Bastion . Purer souls than we have ever received from Revendreth. They bore the mark of the Seal of Contrition, a focus that expedited their cleansing. Go to Revendreth and find this seal so that we may harness its power.", ["objectivesText"] = "Meet with The Curator in Darkhaven in Revendreth.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1525, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58558] = { ["id"] = 58558, ["name"] = "Overhead Intelligence", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The Countess knows the fates and goings-on of every noble in Revendreth. It is the best way to keep them in her debt. However, she has a dark secret. Despite what she may say... she was once mortal. We will need to find where she keeps her sinstone. No easy feat, of course. We will need to gather some intel. The venthyr of the Chalice District are constantly gossiping. Collect their letters from the couriers until you learn something of interest.", ["objectivesText"] = "Collect the Rumors of Favor from Chalice Couriers in the Chalice District.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58559] = { ["id"] = 58559, ["name"] = "Eyes of the Master", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "I worry about entering the city. I'm sure you have noticed how well we... stand out here. Denathrius's loyalists have eyes everywhere, and no more dedicated soldiers than the stoneborn. Their eyes and ears watch over the Chalice District. Take out their leaders so none can report our presence here before we acquire the seal.", ["objectivesText"] = "Kill Evaala the All-Seeing , Guardian Mastrus , and Keraal the Ripper in the Chalice District. Progress: The stoneborn forces can never be truly defeated, but they can be quelled for a time.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 130222, 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58560] = { ["id"] = 58560, ["name"] = "Gothic Fashion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "Making my way into the city unseen was not as simple as I thought. I trekked through some mud, where I came across these... small men. Perhaps Kleia is right. I draw far too much attention here to be of much use. Perhaps I can disguise myself? Please, help me by gathering some venthyr clothing as a disguise.", ["objectivesText"] = "Collect 5 articles of venthyr clothing from Chalice Residents and Garment Trunks in the Chalice District.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161543, ["x"] = 0.599333, ["y"] = 0.438667 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.438667 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58561] = { ["id"] = 58561, ["name"] = "Shards of the Countess", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The venthyr travel long distances through enchanted mirrors. The keys we look for are not as we have in Bastion , but rather shards of a mirror that will lead to the sinstone's location. Based on the intel you found, we know which three houses hold these shards. Primrose, Darkvein, and Sinfang. Go to their manors and retrieve the shards. We will find the frame to piece them into.", ["objectivesText"] = "Collect the 3 Shards of the Countess .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174374, 174375, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58562] = { ["id"] = 58562, ["name"] = "Collecting Dust", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "If I know the Countess, which I do, her sinstone will have stronger protection than mere keys. She is quite fond of curses to protect her gateways. I am capable of creating a residue that should protect us, but it requires the petals of a specific flower you can find in Redelav gardens. Collect the petals of these flowers so that I may protect us from the dangers to come.", ["objectivesText"] = "Collect 30 Death Lotus Petals from Death Lotuses in the Redelav District. Progress: I will need many petals to protect the four of us.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58563] = { ["id"] = 58563, ["name"] = "Through Glass", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The mirror frame rests at the bottom of Redelav Hall. Kleia and Pelagos wait there. With these shards, I can piece it together. We will go through, grab the sinstone, and go face the Countess. Let nothing stand in our way.", ["objectivesText"] = "Go through the mirror, then collect the Countess's Sinstone . Progress: Venthyr carry their pasts as a burden, a weight upon them. The kyrian stand free of ours.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174382, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084, 181286 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58564] = { ["id"] = 58564, ["name"] = "Sins of the Past", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The Countess built her reputation on being a native venthyr, never a soul. Revealing her sinstone to the world would be catastrophic. This is the leverage we need for the information we seek. She will tell us where Alwin is. Where the seal is. This mirror leads to her estate. I will follow behind you as backup, but the kyrian shall wait here. Don't let her threaten you. You hold the power.", ["objectivesText"] = "Go through the mirror and face the Countess . Progress: You are lucky that the Curator is by your side, Maw Walker. If you dared this stunt on your own, you would never see your precious Bastion again.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161996, ["x"] = 0.58, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58565] = { ["id"] = 58565, ["name"] = "Land of Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The Ember Ward is filled with outcasts from Revendreth society, whether they rebelled, crossed a noble, or simply looked at Denathrius wrong. It is a Light-scorched land that drives venthyr mad, unless they manage to stay within the shadows. If Alwin is there, it may be too late. Let us visit Theotar at the Sanctuary of the Mad. I'm sure he will be pleased to see you.", ["objectivesText"] = "Meet Theotar at the Sanctuary of the Mad in the Ember Ward.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161515, ["x"] = 0.32, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58566] = { ["id"] = 58566, ["name"] = "Actions Speak Louder than Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "<The ash ghoul inspects you, checking your weapons and armor closely. He shifts his eyes from you to your kyrian companions before checking back in with Theotar, who nods to him. Alwin motions for you to follow him.>", ["objectivesText"] = "Follow Mindscorched Alwin through the Ashen Traverse.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161553, ["x"] = 0.345333, ["y"] = 0.513333 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161553, ["x"] = 0.345333, ["y"] = 0.513333 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.345333, ["y"] = 0.513333 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58567] = { ["id"] = 58567, ["name"] = "Skulking in the Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "I had only heard tales of the Ember Ward before now. It's breathtaking... yet terrible. The Light burns the venthyr here, scorching their flesh and driving them mad. The only reprieve is darkness, but thugs have taken over every inch of shelter outside of this sanctuary. There is no redemption for them. Only justice.", ["objectivesText"] = "Kill 8 outcast venthyr in the Ashen Traverse.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 10, ["flags"] = 0 } } },
[58568] = { ["id"] = 58568, ["name"] = "Light Respite", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "We passed many ash ghouls on the way here, screaming in pain from their Light-dispensed burns. And after meeting Alwin and the others here, my heart aches for them. They have lost much of who they once were, and suffer daily for it. Please, collect some berries from the Ashen Traverse. I believe I could impart anima into them to create a healing salve to soothe their wounds. It is the least I can do.", ["objectivesText"] = "Collect 25 Brushberries from the Ashen Traverse. Progress: The denizens of the Ember Ward have suffered enough for their mistakes. The Light goes too far in its punishment.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58569] = { ["id"] = 58569, ["name"] = "The Folly of Envy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["series"] = { 58570, 58571 }, ["description"] = "<Alwin points at a venthyr on the ledge above. He lets out a slight, low rumble.>", ["objectivesText"] = "Kill Duke Vielle and retrieve the Seal of Contrition . Progress: Alwin has brought us far. We must retrieve the Seal!", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161553, ["x"] = 0.345333, ["y"] = 0.513333 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.345333, ["y"] = 0.513333 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 12, ["flags"] = 0 } } },
[58570] = { ["id"] = 58570, ["name"] = "Parting Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["series"] = { 58569, 58571 }, ["description"] = "With the seal in hand, we must return to Bastion . Alwin has received his justice. He has bequeathed the seal to our care. Let us say our goodbyes at the Sanctuary of the Mad, then head home. I look forward to returning to the blue skies and open fields of Bastion .", ["objectivesText"] = "Speak to the Curator at Sanctuary of the Mad, then return to Elysian Hold. Progress: You return! With good news, I hope?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084, 184353 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 13, ["flags"] = 0 } } },
[58571] = { ["id"] = 58571, ["name"] = "The Seal of Contrition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["series"] = { 58569, 58570 }, ["description"] = "Preparations for the Seal are complete. Go, insert it into the Crest. Be delicate, yet firm! Move with purpose, but a steady hand.", ["objectivesText"] = "Place the Seal of Contrition in the Crest of Ascension. Progress: <The orb hangs in front of you. The Seal in your hand pulses quickly.>", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174289, 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084, 177050, 178153, 179943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 14, ["flags"] = 0 } } },
[58575] = { ["id"] = 58575, ["name"] = "Stuff We All Get", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "A lot of competitors meet their end in the Theater of Pain. But their weapons are still good as new! It can get expensive to equip a fresh recruit, especially if you're not sure they'll survive their first bout. That's why we outfit them with \"slightly used\" armaments. Gather them up for me, would you? Can't let a good weapon go to waste!", ["objectivesText"] = "Collect 12 Weapons of the Fallen . Progress: The weapons you collect could be wielded by a future champion!", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58584] = { ["id"] = 58584, ["name"] = "Right our Wrongs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "General Kaal was sent here on a mission for Denathrius long ago. On that mission, they concealed anima siphons , making their presence impossible to detect, to limit the amount of anima this workshop could use. That destabilized this area. The Forsworn must have noticed this and exploited the weakness. These previous actions are in opposition to our goal. Take Theotar and destroy those siphons.", ["objectivesText"] = "Speak to Theotar at the Eternal Forge. Then, reveal and destroy 5 Concealed Anima Siphons .", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 180934, 180936, 180937, 180938 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58585] = { ["id"] = 58585, ["name"] = "No Friend of Mine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Tools. I cannot work without my tools! Famos, my former apprentice, stole them all when she went to the Forsworn. It breaks my heart. She had so much promise. She must be stopped.", ["objectivesText"] = "Kill Famos in the Eternal Forge and collect Mikanikos 's Toolchest. Progress: I need my tools. My work cannot be done without them.", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 174466 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58586] = { ["id"] = 58586, ["name"] = "The Right Stuff", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Building something that can help in your mission will require some metal. The constructs of the Forsworn have metal parts, suitable for what we need. Tainted by the Forsworn, they will need some additional work. Collect their metal and smelt them in the flames of the Eternal Forge to purge the corruption.", ["objectivesText"] = "Kill Forsworn constructs and collect and smelt 5 Tainted Centurion Components . Progress: Do you have the metal?", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 173880, 174465 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58589] = { ["id"] = 58589, ["name"] = "The Restless Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58524 }, ["description"] = "Now that we have the anima we need, we must attune the heart of Tirna Noch to the shrines of Hibernal Hollow. Then we can bring the wildseed's nightmares into the light and dispel them. Take the heart to the shrines just outside of Hibernal Hollow, in the Dreamshrine basin. Then bring the heart back to the wildseed to complete the preparations for the ritual. But be careful. Minions of the Drust seem to be amassing near the grove.", ["objectivesText"] = "Attune the filled heart of the tree at the shrines in the Dreamshrine Basin. Progress: The spirit dreams.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58590] = { ["id"] = 58590, ["name"] = "Visions of the Dreamer: Origins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58593, 60578 }, ["description"] = "The spirit within the wildseed dreams of her birth and youth, in the primordial days of her world. Go to the first Dreamshrine outside of Hibernal Hollow. Meditate at the shrine, and soothe this vision of how her life began.", ["objectivesText"] = "Grapple with the spirit's vision of their origin. If you leave the Vision, interact with a Dreamer's Vision portal in Dreamshrine Basin to enter again.", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58591] = { ["id"] = 58591, ["name"] = "Despoilers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["description"] = "Your efforts at Tirna Noch have enraged the Drust. Those creatures of decay and destruction swell at our borders, and already they pierce our defenses. Now we see their real faces, and know the true nature of our foe. Strike at them. It will buy us time for you to conduct Dreamweaver's ritual.", ["objectivesText"] = "Slay Witherscorn Drust and Blighted, and vanquish Skell the Despoiler .", ["rewardGold"] = 505440, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58592] = { ["id"] = 58592, ["name"] = "Caring for the Caretakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["description"] = "The Drust attacked so quickly, they captured some of the spirit tenders of this grove! It's not an easy job to do, between the drought and monsters and everything. I should know. Please, see if you can get them out of whatever terrible magic those invaders have cast on them.", ["objectivesText"] = "Free Spirit Tenders in the Dreamshrine Basin.", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 162577 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58593] = { ["id"] = 58593, ["name"] = "End of the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58590, 60578 }, ["description"] = "The time has come. The ritual will be complete when you have fully entered into the spirit's dreams. It will be as if you are her, in every aspect. She relives the moment of her death over and over again. It torments her. Something about how she ended... she had no control over her actions. She hurt the ones she loved. Speak to me when you are ready to immerse yourself in her nightmare of the end.", ["objectivesText"] = "Witness the end of the spirit's life. Progress: Have you entered into the spirit's final dream and witnessed her fate?", ["rewardGold"] = 505440, ["rewardXP"] = 1770, ["rewardItems"] = { 175647, 175660, 175661, 175662 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58596] = { ["id"] = 58596, ["name"] = "Specter Of War: Visectus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 58596 }, ["rewardItems"] = { 173202, 178594, 183619 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58599] = { ["id"] = 58599, ["name"] = "Drive A Dredge Between Them", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58472, 58608, 58624, 62388 }, ["description"] = "First, we ruin their operation. Questions can come later. I scouted from the overlook as we rode in. Necromancers charge crystals full of siphoned anima. Three dredgers stack them onto carts. Kill those dredgers and everything will grind to a halt.", ["objectivesText"] = "Kill the 3 large dredgers. Progress: Are you ready?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58600] = { ["id"] = 58600, ["name"] = "A Perfect Circle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "I've come up with the perfect design to fit your needs--a crown capable of channeling the powers of the Harvesters. I need one more tool to put it together, a mold. Circular objects difficult to get right. Go up to my old storage. A perfect mold exists there. I'm sure of it. Perhaps in one of my old trunks. Go rummage around for it, will you?", ["objectivesText"] = "Search for the Perfected Circlet Mold . Progress: Crown must be perfect!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174330, 180448, 180449, 180450 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 6, ["flags"] = 0 } } },
