[58603] = { ["id"] = 58603, ["name"] = "Phaestus, Genesis of Aeons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Missing something sacred. Forsworn ransacked our shrine to the First Forgelite and took her hammer. My hammer! Defeat their commander, retrieve Phaestus. You must go now!", ["objectivesText"] = "Collect Phaestus, Genesis of Aeons from Overseer Atticus. Progress: Without Phaestus, we cannot forge your crown!", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 174061, 174296, 177057, 178160, 179947 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58605] = { ["id"] = 58605, ["name"] = "Amateur Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 58605 }, ["objectivesText"] = "Arena opponent slain", ["rewardXP"] = 8165, ["rewardItems"] = { 184062 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Arena opponent slain", ["amount"] = 2, ["type"] = 0, ["objectID"] = 163226, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[58608] = { ["id"] = 58608, ["name"] = "It's Treason, Then", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58472, 58599, 58624, 62388 }, ["description"] = "We've halted their efforts, but we still have more to do. Sin'dane must have sent someone to oversee the encampment. Find and slay whoever is in charge. Only then can we be sure their work has ended.", ["objectivesText"] = "Kill Lady Ouix'ara . Progress: Still more schemes...", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 182386 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161865, ["x"] = 0.78, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58609] = { ["id"] = 58609, ["name"] = "Taking The Seat", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 63212 }, ["description"] = "A wise choice, <name>. Under your command, we will restore honor and glory to Maldraxxus. Your strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential. For now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.", ["objectivesText"] = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58610] = { ["id"] = 58610, ["name"] = "The Speaker of Elune", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "Fortune smiles upon us, <name>. We have found a soul in Ardenweald who was once a Night Warrior in life, as Tyrande is now. His name is Thiernax . I am told he assists in tending to the spirits resting in the Garden of Night. Seek him out and petition him for aid. I pray he will have wisdom to share.", ["objectivesText"] = "Find Thiernax near the Queen's Garden. Progress: Oh, dear.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58616] = { ["id"] = 58616, ["name"] = "Forging a Champion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Of all the souls who have reached that stone, only you discovered its true purpose. I am no zealot, but clearly there is a deeper meaning in this. We would be wise to investigate further. Find Bonesmith Heirmir at her forge. She is the most renowned smith in Maldraxxus , and the last remaining apprentice of the Primus himself. She will know what course to take.", ["objectivesText"] = "Speak with Bonesmith Heirmir about your runeblade. Progress: Something else?", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58617] = { ["id"] = 58617, ["name"] = "Maintaining Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Communication is the key to victory. The greatest strategists are rendered useless if their orders go unheard. Deliver my orders to Summoner Perex, Drill Sergeant Telice , and Secutor Mevix . And do it quickly. Every moment we waste is one our enemy will have to their advantage!", ["objectivesText"] = "Deliver orders to Summoner Perex, Drill Sergeant Telice , and Secutor Mevix .", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58618] = { ["id"] = 58618, ["name"] = "Ossein Enchantment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "A potent blade requires potent components. I know of something that would suit our needs. Recently a monstrosity trained by the constructs was snared by our soldiers at the eastern side of our stronghold. Vyraz insists we can siphon \"intelligence\" from the beast's mind. Hmph. The will of the Primus trumps the desires of an ambitious baron! The bones of that beast would forge the perfect hilt for this blade. I say you lay claim to them.", ["objectivesText"] = "Slay Marrowjaw and collect an Empowered Bone from its corpse. Progress: Brave enough to manage this?", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58619] = { ["id"] = 58619, ["name"] = "Read Between the Lines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["series"] = { 62605 }, ["description"] = "Ah, mortal, how fortunate that I, humble Ta'eran , happen to be standing here just as you, the outsider everyone is talking about, happens to wander by! In the spirit of cooperation and mutual interests, there is a matter I wish to discuss. A nearby structure called the Sepulcher of Knowledge was built as a repository for military strategy. I fear the knowledge contained within may soon be lost. If you would do me the honor of escorting me to the Sepulcher, I can share what else I know.", ["objectivesText"] = "Follow Ta'eran to the Sepulcher of Knowledge and hear his proposal.", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166657, ["x"] = 0.406, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58620] = { ["id"] = 58620, ["name"] = "Slaylines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "Gaining entrance to the Sepulcher is no easy feat, <name>! Not only were guardians put in place, but an elaborate magical lock was created to seal the door. To open the way, the two obelisks which control the lock must be fed anima. Fortunately, there are some empowered crystals in the area we can use for this purpose. Locate the focus crystals and redirect their anima flow into the obelisks. Then the secrets of the Sepulcher will soon be ours!", ["objectivesText"] = "Connect the anima flow to the Unlocking Obelisks. Progress: Have you activated the two obelisks?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58621] = { ["id"] = 58621, ["name"] = "Repeat After Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "The Primus placed guardians in the area around the Sepulcher to protect the knowledge within. Each embodied the virtues of one of the five houses. To gain entrance, you must prove yourself worthy by besting these protectors. Seek out the rune stones that represent the houses of Maldraxxus . Pay attention to the words inscribed on each stone, then pay deference each house's values. If you honor the stone, its protector will come forth. Defeat each of them.", ["objectivesText"] = "Read the rune stones of the five houses, then honor them by performing the correct /emote at each stone. Progress: The Primus was clever indeed.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 175707, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58622] = { ["id"] = 58622, ["name"] = "Secrets Among the Shelves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "Now that the door to the Sepulcher is unlocked, we can venture inside. And by \"we\", I mean \"you\". Until it's safe, at least. The volumes within contain the collected wisdom of the greatest military minds of Maldraxxus . For the good of the Necrolords, do whatever is needed to gather these precious volumes. It is safe to assume that the books will be protected by traps. The Primus wouldn't want just anyone laying their hands on this knowledge. Once you clear a path, I'll join you.", ["objectivesText"] = "Recover volumes of the tomes kept within the Sepulcher. Progress: Were you successful?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 170667, ["x"] = 0.418, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58623] = { ["id"] = 58623, ["name"] = "A Complete Set", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "This is only volume one? We can't just take the first volume. A rare item like this is only useful if it's in a complete set! Grab as many of the other volumes as you can, I will have to prepare a larger expedition to remove all of these volumes.", ["objectivesText"] = "Collect Volumes of Victory. Progress: Did we get all the volumes?", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178019, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166806, ["x"] = 0.452, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166806, ["x"] = 0.452, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58624] = { ["id"] = 58624, ["name"] = "Pauldrons of Imperium", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58472, 58599, 58608, 62388 }, ["description"] = "Now we know who is responsible for the unrest in Maldraxxus. If Kel'Thuzad has allied with the Banished One, then he wields greater power than anyone realizes. We must lay siege to the House of Rituals, but we need time to prepare. Attacking without a flawless strategy will only ensure our defeat. For now, return the pauldrons to the Seat of the Primus. I will meet you there.", ["objectivesText"] = "Return to the Seat of the Primus with the Pauldrons of Imperium .", ["rewardGold"] = 842700, ["rewardXP"] = 12250, ["rewardItems"] = { 182255, 182264, 182273, 182282 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161865, ["x"] = 0.78, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58625] = { ["id"] = 58625, ["name"] = "Connecting the Dots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 58625 }, ["description"] = "The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting. He went off to meet with some member of the House of Rituals. There were a few of his guards with him. While it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.", ["objectivesText"] = "Search the Forgotten Wounds for the previous baron.", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58630] = { ["id"] = 58630, ["name"] = "Crown of the Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Power you seek to focus is volatile. Need the Eternal Forge's flames to get it done. Without the blessing of the flames, I fear it will overwhelm the wearer. Bring venthyr friend. His magic will prove useful. Need you to absorb impurities. < Mikanikos hands you an elegant container.> Use this to capture imperfections that burn off during the process.", ["objectivesText"] = "Meet Mikanikos at the Eternal Forge. Then, assist him with forging the Crown of the Harvesters. Progress: It is done then?", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 174587, ["x"] = 0.51, ["y"] = 0.191333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58647] = { ["id"] = 58647, ["name"] = "Broken Webs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "My husband once served our people as the Speaker of Elune--until he became the Night Warrior. His feelings on the matter are... complicated, to say the least. Spriggans have been ripping the garden's soulwebs. Would you please help me repair them? I will recount our story as we work.", ["objectivesText"] = "Help repair soul webs. Progress: Just one more.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58654] = { ["id"] = 58654, ["name"] = "A Plea to the Harvesters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "You come during strange times. Every day the tithes we must pay to the Tithelord increase, and our ability to get anima dwindles. What souls we have to work with here are near their final judgment and we lack the resources to harvest them without endangering the hamlet. If you have the ear of Lord Chamberlain , then you might be able to pass a message to the Master himself. Here, take this letter. Please see that it makes it to the hands of the Chamberlain.", ["objectivesText"] = "Deliver Mihaela's Note to the Lord Chamberlain . Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 174482 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58656] = { ["id"] = 58656, ["name"] = "Heavy is the Head...", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Crown is unstable due to Sire's lingering influence from the medallions. A test run should solve. Socketed one of your medallions. Witness its power focused into a weapon of destruction. Perfect opportunity. Forsworn finished colossi construction. Destroy them. Bring the Forsworn the end they crave. Careful. Theotar informed me how powerful magic this is. The crown will hunger, must control it.", ["objectivesText"] = "Test the Crown of the Harvesters and defeat the Operational Colossi. Progress: Bring the Forsworn the destruction they crave.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 174587, ["x"] = 0.51, ["y"] = 0.191333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.191333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58664] = { ["id"] = 58664, ["name"] = "Ultimate Makeover", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["storyline"] = { 58664 }, ["description"] = "We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls. Emeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard. You will assist me in rebuilding Emeni's construct.", ["objectivesText"] = "Help Rathan rebuild Emeni's Construct.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58665] = { ["id"] = 58665, ["name"] = "Rebellious Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "Please hear us out, Maw Walker. When Margrave Gharmal launched his attack on Bastion, there were many, such as Emeni and myself, that opposed his actions. Fearing dissent, Gharmal removed many souls from their constructed bodies and imprisoned them. Emeni escaped the prison, but most did not. Help us free the other souls, and we can build you an army of constructs far greater than any that serve Gharmal.", ["objectivesText"] = "Meet Rathan and Emeni at Sixfold Recluse.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162108, ["x"] = 0.26, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58668] = { ["id"] = 58668, ["name"] = "Find The Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "I apprenticed at the Stitchyard for many eons. I even worked in the Body Banks with surgeon Stitchflesh to design Emeni's last construct. If we gain control of the Body Banks, we will have the parts necessary to rebuild Emeni and create new bodies for other souls we rescue. Lead us to there and we'll see if we can get it operational.", ["objectivesText"] = "Lead Rathan and Emeni to the Body Banks.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 2411, 25470, 25474, 25948, 25949, 25951, 31725, 247234, 254878 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162108, ["x"] = 0.26, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58669] = { ["id"] = 58669, ["name"] = "A Little Pruning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "Spriggans sometimes invade the garden to spread mischief and mayhem. There is no end to the trouble they bring with them. Usually, the Wild Hunt keeps them in check... but their huntsmen and huntresses have had far more pressing concerns as of late. Thiernax and I have been helping to keep the garden clear, but he's run off somewhere to brood. < Qadarin shakes his head.> You would be doing me a favor if you helped me clear the Queen's garden of these vermin.", ["objectivesText"] = "Slay 15 Sicklethorn spriggan. Progress: At least here we only have to worry about spriggans. Other parts of the forest are not so fortunate.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58670] = { ["id"] = 58670, ["name"] = "The Slaughter Daughter", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "When I was locked up, I made a list of all the constructs that betrayed me... it is a lengthy list! Help me teach these constructs the mistake they made. I want to destroy everyone on my list, along with Yardmaster Pralak , who is number one on the list!", ["objectivesText"] = "Help Emeni slaughter everyone on her list.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58671] = { ["id"] = 58671, ["name"] = "Bottled Up Inside", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "There were many souls that opposed Margrave Gharmal's attack on Bastion. Those of us that spoke out, were stripped our bodies, imprisoned in the Etheric Vault, till our souls faded away, starved of anima. My friends are still imprisoned in the vaults. We will free them, and build an army of constructs to fight for you!", ["objectivesText"] = "Rescue 10 Imprisoned Souls in the Etheric Vault.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58677] = { ["id"] = 58677, ["name"] = "Skin in the Game", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "This task is probably above your capabilities, but listen anyway. As a construct I was feared throughout the Shadowlands. The magnificent skin of my construct was impervious to mortal weapons, it was a work of art that took years to perfect. When I was removed from my construct, it was Faldo Iscar who took great delight in stealing that skin. He keeps it on himself as a souvenir. Kill Faldo Iscar, and get my skin back!", ["objectivesText"] = "Emini's Magnificent Skin obtained Progress: When I was alive, you might have been my friend... or maybe my dinner.", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 174520 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161285, ["x"] = 0.251, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161285, ["x"] = 0.251, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.251, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58680] = { ["id"] = 58680, ["name"] = "Loose Threads", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "We're missing a few tools and parts for sewing a construct. We need these items if we're to rebuild my construct! Search the surrounding area. See if you can find us what we need. Search tables for the Skewering Needles , you can find haulers that carry Razorthread Spools , and look for Clotting Patches on constructs you kill.", ["objectivesText"] = "Locate Skewering Needles , Razorthread Spools and Clotting Patches . Progress: You are good at this.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174524, 174526, 174534 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58686] = { ["id"] = 58686, ["name"] = "Weapon of Mass Construction", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "We are in luck! Surgeon Stitchflesh and his assistant have not returned from Bastion. The entire Stitchyard is lightly guarded. We must work fast. See if you can get the equipment operational. Once it is active, we can begin the construction process.", ["objectivesText"] = "Get the assembly lab operational. Progress: We will control the means of production!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58704] = { ["id"] = 58704, ["name"] = "The Garden of Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "That should take care of things out here. Now we must tend to the inner garden. Once we're done, I'll sort out my recalcitrant husband. Hopefully, any remaining spriggans will have cleared out on their own after hearing us dispatch the others.", ["objectivesText"] = "Slay spriggans in the central garden. Progress: This is my fault... just like before...", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 175581, 179766, 179889, 181910 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161785, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58706] = { ["id"] = 58706, ["name"] = "Dressing the Kill", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "<Huln listens to your explanation, then pauses thoughtfully.> I believe I understand, <name>. But I cannot help you right now. Allow me to explain. In the meantime, will you carve up this carcass with me? Your prey always has something to teach you.", ["objectivesText"] = "Help Huln Highmountain carve up the devourer. Progress: The more quickly you carve, the more quickly I can help you.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58714] = { ["id"] = 58714, ["name"] = "The Forest Has Eyes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["description"] = "That dream! With the teeth and the claws and the heart... heart-wrenching sacrifice? <Moonberry chokes up for a moment then collects herself.> Sorry! While we were in dreamland, possessed spies have snuck into Hibernal Hollow! They must be hunted down and slain before they can report back on the grove's defenses. Here, borrow a bit of my magic. Seek out the ones hidden in the shadows and smite them!", ["objectivesText"] = "Slay hidden Possessed Spies throughout Hibernal Hollow. Progress: Have you uncovered all those pesky spies yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 174864, 187591 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161847, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58717] = { ["id"] = 58717, ["name"] = "Bell of Remembrance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58717, 58725 }, ["description"] = "<The bell is scratched and damaged. You remember the Curator being very interested in this item. Maybe someone at the Crypt of the Forgotten will know more.>", ["objectivesText"] = "Find someone who knows more about the bell at the Crypt of the Forgotten.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 174674 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161418, ["x"] = 0.732, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1193, ["name"] = "Bell of Remembrance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 174674 } },
[58719] = { ["id"] = 58719, ["name"] = "The Droman's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58720, 58869, 60621 }, ["description"] = "Our enemies close in swiftly, <name>. We must sound the call to defend the grove! Use this horn to call upon our protectors. Summon the Wild Hunt to slay those who would attack us.", ["objectivesText"] = "Use the Droman's Horn to summon the Wild Hunt at the entrances to the grove. Progress: The Hunt will hear our call and ride to defend the grove!", ["rewardGold"] = 126360, ["rewardXP"] = 710, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58720] = { ["id"] = 58720, ["name"] = "Missing!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58719, 58869, 60621 }, ["description"] = "The Wild Hunt has answered the call to defend us... except for Hunt-Captain Korayn and her forces. She had led her hunting party to the west, on the trail of a powerful foe. They may have encountered trouble. Find her and provide whatever aid she requires. We need her hunters and her leadership if our defenses are to hold.", ["objectivesText"] = "Find Hunt-Captain Korayn on the Path of Rebirth.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 25631, 25632, 25633, 31666, 73223, 73241, 74583, 74584, 74585, 131912, 158464, 161083, 174864, 199115, 207002, 211279, 237812, 248051, 248052 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162541, ["x"] = 0.570667, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58721] = { ["id"] = 58721, ["name"] = "Awaken the Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 60661 }, ["description"] = "Much of the Queen's focus has centered on the Grove of Awakening, where rejuvenated spirits emerge from their wildseeds and return to their worlds. Perhaps it is fitting you carry a wounded spirit with you. < Lord Herne studies Ysera's wildseed for a moment before a slow grin spreads across his face.> This one fights with all of her being. Even now she clings to existence. Come, stranger, let us see what fate the Queen will decree for this one.", ["objectivesText"] = "Travel to the Grove of Awakening.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169869, ["x"] = 0.466, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58723] = { ["id"] = 58723, ["name"] = "The Court of Winter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 56829, 56942, 56955, 57007, 57025, 57026, 58724 }, ["description"] = "My Court informs me that you bear an important message. You may now deliver it.", ["objectivesText"] = "Give the Primus's message to the Winter Queen . Progress: The ancient enemy has not been idle...", ["rewardGold"] = 126360, ["rewardXP"] = 710, ["rewardItems"] = { 174864, 175710 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58724] = { ["id"] = 58724, ["name"] = "The Queen's Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 56829, 56942, 56955, 57007, 57025, 57026, 58723 }, ["description"] = "Dire portents indeed. I have used what little anima we possess to save our groves and the spirits they nurture. So many were lost... all as the Heart of the Forest grew ever weaker. Keeping the Banished One bound within the Maw will require more anima than Ardenweald can spare. <The Queen considers for a moment.> Sire Denathrius is a master of anima extraction. Journey to Revendreth and inform him of our plight. I know he will lend us his aid. Your allies in Oribos can open the way.", ["objectivesText"] = "Return to Tal-Inara in Oribos.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58725] = { ["id"] = 58725, ["name"] = "Sinkeeper", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58717, 58725 }, ["description"] = "This is a Bell of Remembrance . Before the recent... \"events\" we used them to beckon souls from the Crypt of the Forgotten to deem their fate. If they are less arrogant than they were before, they may continue in the process. If not, they must spend additional time in the crypt. Let's put this one to use, shall we? It's pretty beat up, let's hope we can get at least one use out of it.", ["objectivesText"] = "Use the Bell of Remembrance to beckon a soul from the Crypt of the Forgotten. Then, deem the soul's fate.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 174652, 174674, 174741 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161418, ["x"] = 0.732, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161418, ["x"] = 0.732, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1193, ["name"] = "Bell of Remembrance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58726] = { ["id"] = 58726, ["name"] = "Thick Skin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "The Primus forged a fine blade, but it will do you no good in its current state. Fortunately for you, I possess the skill to finish his work! That being said, I will require materials. The other Chosen have been too preoccupied with their combat drills to assist me at the forge, even as they demand more weapons and armor. That's where you come in. You want a new blade? You'll have to earn it.", ["objectivesText"] = "Collect 40 Pulsating Hide Scraps from Overgrown Masses. Progress: Can't be that difficult, can it?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 172089, 174499, 175462, 175463, 175464, 175465, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58727] = { ["id"] = 58727, ["name"] = "A Place To Call Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "You didn't end up on my list... so, I guess we're friends... for the moment. Rathan took the soul you freed to Butchers Block near the Seat of the Primus. Let us meet him there and plan our next step together.", ["objectivesText"] = "Meet up with Rathan and Emeni at Butchers Block.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58750] = { ["id"] = 58750, ["name"] = "Take the Bull by the Horns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58750, 58785, 58794 }, ["description"] = "I've carved out quite the reputation as a tauralus wrangler. Everyone needs a tauralus! You do some work for me, and people will know who you are as well. Take this bone splinter and poke a few juicy nibblers . Use them to lure a tauralus to you, then ride it back to me.", ["objectivesText"] = "Ride 5 Bloodskin Tauraluses back to Dundae . Progress: You want to be famous? Get the tauraluses I wanted?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174749, 174751 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1159, ["name"] = "Wasteland Work", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58751] = { ["id"] = 58751, ["name"] = "A Common Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["description"] = "Each house in Maldraxxus has two barons. Before the fall of my first house--the House of Eyes--our margrave sent my fellow baroness to investigate suspicious behavior in the House of Rituals. I have not heard from her since. Either she has found something... or has become another casualty of their treachery. Her orders took her to the Decay in the east. If you can find the baroness, give her this summons. We were not friends, she and I, but she is a formidable combatant. We could use her might.", ["objectivesText"] = "Locate the lost baroness in the Renounced Bastille. Progress: Someone new...but someone familiar.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 132516, 174755, 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58769] = { ["id"] = 58769, ["name"] = "REUSE ME", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 58769 }, ["description"] = "Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband. But I will get them back. If you are our new champion then you will help me for the good of Ardenweald . <Thiernas snorts.> Death did not part us. I will not be torn from him now.", ["objectivesText"] = "Ride with Thiernax after the Drust.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58771] = { ["id"] = 58771, ["name"] = "Directions Not Included", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["description"] = "Look at this place! What a mess. The Locus is inactive and these \"Forsworn\" have taken over. We need to restore the Locus, but I do not know how. This place is not of my design, built long, long ago. Luckily, the previous Forgelite Prime was prolific. Recorded everything! If we can find her designs, I can certainly work it out. Even without Mnemis's help. Look around. Plenty of scrolls strewn about. Meet me near the Locus when you find what I need.", ["objectivesText"] = "Find the Locus Manual among discarded scrolls in the Mnemonic Locus. Progress: You find correct scroll?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178047, 178048, 178049, 178050, 178062, 178063, 178064, 178092, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58773] = { ["id"] = 58773, ["name"] = "The Thornspeaker Captive", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "Good to know the old bear hasn't forgotten me. Unfortunately, neither have the Drust. I was enjoying a peaceful afterlife before they showed up. Do not bother trying to force open this cage. You can only unlock it with three separate keys, and each one is held by a different Drust commander. They should be somewhere nearby. Find them.", ["objectivesText"] = "Rescue Kivarr from Eventide Grove in Ardenweald . Progress: I would love to help you, but as you can see... I am not exactly free to leave.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180777, 182639, 182641 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173612, ["x"] = 0.465, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.6912 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58775] = { ["id"] = 58775, ["name"] = "Meet the Queen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "<name>, we need only one more piece to complete the Crest of Ascension. Eons ago, our Crest was originally crafted with the assistance of the fae. Deep within Ardenweald lies a portal they maintain to ferry souls back to their worlds. It is a source of great power and the final key to rebuilding the Crest. Seek out the Winter Queen in Ardenweald and plead our case. We've already sent Pelagos ahead as our envoy to arrange for your meeting.", ["objectivesText"] = "Gain an audience with the Winter Queen at the Heart of the Forest in Ardenweald.", ["rewardGold"] = 84900, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58785] = { ["id"] = 58785, ["name"] = "Smack and Grab", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58750, 58785, 58794 }, ["description"] = "Bonetooths are the backbone of Maldraxxus 's armed forces. Those that have been trained well are in demand amongst all of the houses. I always need new bonetooths to train, but they can be rather difficult to collect. Bring me some of the younger ones, and I will reward you greatly. Be advised that you may need to weaken them before you are able to capture them.", ["objectivesText"] = "Capture 10 Neonate Bonetooths. Progress: Bring me back some bonetooths!", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 119083, 174749, 174751 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162615, ["x"] = 0.47, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162615, ["x"] = 0.47, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1159, ["name"] = "Wasteland Work", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58787] = { ["id"] = 58787, ["name"] = "Trial of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58788 }, ["description"] = "The Forsworn threat is ever looming, and our forces are dwindling. Now, more than ever, we need more Ascended. Our generous Archon has blessed us with a portion of our anima stores to ascend our top aspirants to join our forces. Kleia is amongst the chosen, and thus must complete her final trial. As Pelagos is not yet prepared to ascend, I request you be Kleia 's partner for this process. It is arduous and should not be embarked on alone. She must bear her first soul.", ["objectivesText"] = "Meet Kleia at the Court of Elation.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 183741, 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 49, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58788] = { ["id"] = 58788, ["name"] = "Censers of Guidance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58787 }, ["description"] = "The Forsworn are going to great lengths to prevent us from ascension. They mobilize to stand in our way, to dismantle our chances to partake in our rituals. They have stolen the resources we need to start our trial. Defeat them and retrieve the incense they carry so that we may continue on this path.", ["objectivesText"] = "Collect 10 Incense of Guidance from Forsworn forces. Progress: Each censer will require considerable incense. We must make sure we gather enough.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 174821 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58789] = { ["id"] = 58789, ["name"] = "Misguiding Mentors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "These aspirants... we trained together. Learned together. The Forsworn have swayed them from the path, now leading them to their demise. They betray the path. Take out the Ascended that lead these forces against us.", ["objectivesText"] = "Kill Strategist Palladia and Instructor Herus . Progress: For an Ascended to use the trust their aspirants have in them... They do not deserve their wings.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 174297, 177058, 178161, 179948 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 162544, ["x"] = 0.326, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 162544, ["x"] = 0.326, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58790] = { ["id"] = 58790, ["name"] = "To Cross the Veil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58791 }, ["description"] = "Pallessa found a scroll detailing the ritual. We will need to take our positions and speak a chant, surrendering some of our anima with every word. Your presence is vital. I ask you to use the censers to burn the incense as we meditate. The rest should unfold on its own.", ["objectivesText"] = "Aid Kleia in the Rite of Guidance.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162558, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58791] = { ["id"] = 58791, ["name"] = "A Day in the Life", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58790 }, ["description"] = "A Bearer's duty is to carry souls through the veil to Oribos, where they shall be judged and passed along to one of the realms of the Shadowlands. This soul is ready to move on. During this trial, you will experience his final moments before his death. When you are prepared, you shall see how this soul passed.", ["objectivesText"] = "Witness Ben Howell 's final moments.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 20576 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162558, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58792] = { ["id"] = 58792, ["name"] = "Where a Soul Belongs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58793, 58795, 58796, 58797, 58798 }, ["description"] = "This soul is no longer tethered to his world of Azeroth. Kleia must perform her duty and bear him to Oribos to be judged by the Arbiter. Take this vesper. When you are ready, it will call Ascended to ferry you back across the Veil to Oribos. Go in service.", ["objectivesText"] = "Use the Vesper of Veilflight to travel to Oribos, then witness Ben Howell's judgment. Progress: It is the duty of all kyrian to ferry souls to Oribos.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 175011 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162558, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58793] = { ["id"] = 58793, ["name"] = "Faith Through the Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58795, 58796, 58797, 58798 }, ["description"] = "This drought is... so much larger than I imagined. Why did nobody tell us? The burden of this knowledge weighs heavy... do we bear souls to their eternal torture? We must return home.", ["objectivesText"] = "Return to Adrestes in Elysian Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 10, ["flags"] = 0 } } },
[58794] = { ["id"] = 58794, ["name"] = "Stabbing Wasteward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58750, 58785, 58794 }, ["description"] = "I've been finding a lot of tauralus corpses lately, and I know it's all because those bonetooths Caleesy loves so much! I spotted the one that's responsible for the slaughter just west of here. Get rid of it! And don't mention this to Caleesy!", ["objectivesText"] = "Slay the Satiated Sawtooth . Progress: I hope you put an end to that creature.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174749, 174751 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1159, ["name"] = "Wasteland Work", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58795] = { ["id"] = 58795, ["name"] = "Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58796, 58797, 58798 }, ["description"] = "With success over their trials, our aspirants shall now start the next chapter of their afterlives. They have proven themselves through eons of training and cleansing, and will now earn ascendance. As each aspirant is called, I ask you and Pelagos to please assist by ushering them up. It is a tradition we have practiced for eons, reinforcing the bonds that we share.", ["objectivesText"] = "Assist Pelagos with the ascension ceremony.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174293, 177054, 178157, 179944, 180647 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58796] = { ["id"] = 58796, ["name"] = "The Forsworn Onslaught", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58795, 58797, 58798 }, ["description"] = "Loyalty's betrayal shall not go unnoticed. But while the Paragons defend the city proper, it is up to us to defend Elysian Hold. I am very wounded... but I will hold strong. Pelagos and I will protect the survivors. You must aid in pushing back this assault!", ["objectivesText"] = "Repel the Forsworn invasion. Progress: Devos... she goes too far.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 12, ["flags"] = 0 } } },
[58797] = { ["id"] = 58797, ["name"] = "Forged by Trial", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58795, 58796, 58798 }, ["description"] = "<name>, my friend. I have thought of you as an ally for some time now. The thrill I felt when you decided to join us in Bastion ... I knew you would be a boon unto our ranks. Our bond has been forged by the trials we face. Without you, I could have fallen to my newfound knowledge as Achillon did. I wish to cement our bond. I would be honored to soulbind with you.", ["objectivesText"] = "Complete the soulbinding ritual with Kleia . Progress: You are an important part in my journey. I respect you greatly, and hope you feel the same.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 13, ["flags"] = 0 } } },
[58798] = { ["id"] = 58798, ["name"] = "The Spires of Ascension", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58795, 58796, 58797 }, ["description"] = "Our task is not complete yet. We may have pushed back the Forsworn here in Elysian Hold, but it was only a distraction to split our forces. The Archon and the Paragons fight to retake the Spires themselves. We cannot hesitate to aid them in this time of need!", ["objectivesText"] = "Kill Devos, Paragon of Doubt in the Spires of Ascension.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 1804, 1805, 1806, 1807, 181743, 184374 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160390, ["x"] = 0.642, ["y"] = 0.166 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.166 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 14, ["flags"] = 0 } } },
[58799] = { ["id"] = 58799, ["name"] = "The Prime's Directive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["description"] = "All centurion are made to serve the kyrian. That they now work against ME, the Forgelite PRIME, is an insult to all centurions in Bastion . Look at them! Praetors! Goliaths! All... PURPLE! I hereby give you permission and expressly order you to extract their cores. I will repurpose them in a fitting manner. I will reclaim their anima to power the Locus. I can build more. Do not pity.", ["objectivesText"] = "Collect 12 Centurion Cores . Progress: You have the cores?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58800] = { ["id"] = 58800, ["name"] = "The Mnemonic Locus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58977, 58978 }, ["description"] = "< Mikanikos examines the scroll you retrieved for him.> Right, right. Soul mirrors and Locus are tied together. If we restore anima to mirrors, it should repair the Locus back to full functionality. Thankfully, the cores you brought should be sufficient. All I need to do is enable conduits. Simple! Well? Go on. You know how to use these, yes?", ["objectivesText"] = "Use the Anima Conduits to restore the Mnemonic Locus. Progress: I wait to hear the hum of anima, yes.", ["rewardGold"] = 119340, ["rewardXP"] = 710, ["rewardItems"] = { 175704, 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58816] = { ["id"] = 58816, ["name"] = "Getting Backstage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "The next thing we need to prepare the vessel is a set of Night's Veil Flowers. We use these flowers in our ceremonies, but since the drought we've just used them as props in our plays. There are certainly some backstage at the Star Lake Amphitheater. I bet Moonberry is there for the rehearsal of their next play. As a bonus, this will work out quite nicely for me to get revenge on her. < Willowblossom flashes a wicked grin.>", ["objectivesText"] = "Retrieve a Wreath of Night's Veil Flowers from backstage at the Star Lake Amphitheater. Progress: Do you have the flowers?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58820] = { ["id"] = 58820, ["name"] = "Bindings of Fleshcrafting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["description"] = "These are the Bindings of Fleshcrafting ! They empowered the Primus to shape the very flesh and bone of Maldraxxus. We must return them to their rightful place, so their power can bolster us all.", ["objectivesText"] = "Place the Bindings of Fleshcrafting upon the Statue of the Primus.", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 182257, 182266, 182275, 182284 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58821] = { ["id"] = 58821, ["name"] = "Glorious Pursuits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59171, 59172 }, ["description"] = "Perhaps Draka has forgotten her loyalties, but I will fulfill my mission. My enemy--the lich Mor'Bitan--hides within the House of Rituals. For some reason, his underlings skulk in this marsh. We have not learned why they are here, but my devoted have spotted Mor'Bitan's second-in-command, Mephiles the Loyal. He will have our answers. Collect him for me. Once you capture him, slay his kin. Weaken his resolve. I will prime my base for his interrogation.", ["objectivesText"] = "Kidnap Mephiles the Loyal, then kill 6 Morbid Disciples to intimidate him. Progress: Any luck?", ["rewardGold"] = 243360, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58832] = { ["id"] = 58832, ["name"] = "Trinkle Trinkle Little Twerp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "<On the note are the scribblings for a plan to steal silkstrider larvae and cook them. It is signed by someone named Trinkle.>", ["objectivesText"] = "Kill Trinkle the Silk Eater . Progress: Have you taken care of that nasty Trinkle?", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 175982 } },
[58833] = { ["id"] = 58833, ["name"] = "Calling in All Favors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1536, ["storyline"] = { 58833, 59020, 62391, 62406 }, ["series"] = { 61761, 62391 }, ["description"] = "$p, the time has come. We cannot allow Kel'Thuzad to wield the Ritualists' sorcery as a weapon. He must be destroyed. Rally our forces. We march on the House of Rituals!", ["objectivesText"] = "Meet Draka and allies at the House of Rituals.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 174179, ["x"] = 0.62, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1118, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1118, ["name"] = "Assault on the House of Rituals", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58842] = { ["id"] = 58842, ["name"] = "The Curator", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["series"] = { 60935 }, ["description"] = "I tasked the Curator with reacquiring the Medallion of Avarice. However, since her return from the Maw, her mind has become... a bit chaotic. Do be kind, will you? I ask that you lend her assistance in her search. She is at the Crypt of the Forgotten.", ["objectivesText"] = "Meet the Curator at the Crypt of the Forgotten. Progress: I require your assistance, Maw Walker.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 37378, 37436, 37515, 37521 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58843] = { ["id"] = 58843, ["name"] = "The Vault of the Archon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58980, 59196, 60013, 60180 }, ["description"] = "Behind me is the entrance to the Vault of the Archon. As you can see, it is warded against all unauthorized intrusion. To make yourself an authorized entrant, place the offerings you collected before the guardians. You may then browse the contents of the vault at your leisure. Do consider that such access is coveted among the Forsworn and is the sole focus of their efforts here. I advise preparing for combat.", ["objectivesText"] = "Gain entrance into the Vault of the Archon. Progress: Please place the offerings, and you may enter.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167035, ["x"] = 0.578, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167504, ["x"] = 0.563333, ["y"] = 0.673333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58844] = { ["id"] = 58844, ["name"] = "Before the Dawn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58846, 58847, 58854, 59919 }, ["description"] = "We shall need all we can muster if this day is to be ours. Gather them all. The Watchers, Bearers, Centurions, and Collectors. Tell them that their Archon calls for them. Our Paragons will clear a staging ground at the Court of Elation for the final assault.", ["objectivesText"] = "Gather the Watchers, Bearers, Centurions, and Collectors.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164473, ["x"] = 0.314, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58846] = { ["id"] = 58846, ["name"] = "The Greater Good", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58847, 58854, 59919 }, ["description"] = "The Forsworn are our former brothers and sisters in arms...our former kin. But we must see this through. We will hit them from all sides. Fight well, but do not forget that Lysonia is our ultimate objective. If she does not fall, then she will recruit more to their cause in time. Follow the path, <name>.", ["objectivesText"] = "Defeat Lysonia.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164473, ["x"] = 0.314, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166693, ["x"] = 0.674, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58847] = { ["id"] = 58847, ["name"] = "Kyrestia's Grace", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58846, 58854, 59919 }, ["description"] = "I remember this particular soul...Uther. Devos brought him before us some time ago. She pleaded her case about his soul having a connection to the Maw. She then took him under wing, ascending him before he was ready. He became her other hand alongside Lysonia, as it were. He may proclaim a change of heart, but we shall see. Place him under guard. He may stay by the Archon's grace, but I will not take any chances with one so...broken.", ["objectivesText"] = "Escort Uther.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 175254, 178973, 183888, 183889, 183890, 183891, 183892, 183893, 184273 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166693, ["x"] = 0.674, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58854] = { ["id"] = 58854, ["name"] = "Convene the Paragons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58846, 58847, 59919 }, ["description"] = "We have defeated the Forsworn at every turn. Saved those not too far gone. Routed them from our blessed Archon's temples. Now only one remains. The Temple of Loyalty. Lysonia has grown desperate in defeat. Abandoned all we strive to uphold by embracing the Maw. She has rallied her most fervent loyalists to the temple, knowing we will come for her. We shall need the Paragons to finish this. Summon them.", ["objectivesText"] = "Summon the Paragons to call them to action. Progress: Without the Paragons we cannot prevail against Lysonia.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58856] = { ["id"] = 58856, ["name"] = "Who Are You Fooling?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "We cannot conduct the ritual without a very special guest. He's a silkstrider larva named Grubby and he's my best friend. Unfortunately, the nasty spriggans took him! What's worse is they cast illusions on what they steal, so no one can take it back! The spriggans often carry trickster powder. If you can take some of that stuff, I can reverse their illusions and rescue Grubby .", ["objectivesText"] = "Loot Sicklethorn Trickster Powder from Sicklethorn spriggans to dispel illusions on Conspicuous Objects and find Grubby . Progress: We need to find Grubby !", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58857] = { ["id"] = 58857, ["name"] = "Seeds Away!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "I think we have a problem. Plucking the seed from this root must have shaken some burrowed gorm awake. This isn't good! Grab on to me. I will fly us out of here, but we must stop the gorm before they overrun the local Vorkai defenses!", ["objectivesText"] = "Stop the gorm from overrunning the Gormhive Defense Wall and then pouring into the rest of Ardenweald! Progress: I can't believe this. Blue seeds, red seeds, flying faeries!", ["rewardGold"] = 331700, ["rewardXP"] = 8165, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58869] = { ["id"] = 58869, ["name"] = "Battle for Hibernal Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58719, 58720, 60621 }, ["description"] = "This is where we make our stand. The Drust and their minions have us nearly overrun. But we will not let them destroy Hibernal Hollow. Nor will they take our anima or our wildseeds. Fight with us. Let us drive them out.", ["objectivesText"] = "Win the Battle for Hibernal Hollow.", ["rewardGold"] = 758160, ["rewardXP"] = 2125, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169541, ["x"] = 0.598, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58871] = { ["id"] = 58871, ["name"] = "Broken Harts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "The curse on Qadarin is a powerful one. But I will break it. < Thiernax snorts.> Death did not part us. I will not be torn from him now. < Thiernax studies both you and Shandris with a serious look in his eyes.> Lend me your aid, and in turn I will help you with your world's Night Warrior. I do not promise I can save her... but I will share all that I know. Return to the Heart of the Forest and tell Lord Herne what has happened. We will meet there.", ["objectivesText"] = "Report to Lord Herne at the Heart of the Forest, then speak with Moonberry. Progress: This is even worse than I had thought.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161785, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58900] = { ["id"] = 58900, ["name"] = "A Sure Bet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "You've made a name for yourself and earned the respect of everyone here, including Au'narim. You are ready, $p! Anzio is expecting us at the entrance to the Theater of Pain. You're going to be a champion!", ["objectivesText"] = "Meet Anzio at the entrance to the Theater of Pain.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161733, ["x"] = 0.504667, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 12, ["flags"] = 0 } } },
[58905] = { ["id"] = 58905, ["name"] = "Picking Up Pelagos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "Pelagos should have the seed by now! Can't start the ritual without the seed. He's likely still at Claw's Edge. We'll see you there!", ["objectivesText"] = "Meet up with Pelagos , Willowblossom , and Grubby at Claw's Edge.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58908] = { ["id"] = 58908, ["name"] = "Finding Your Way", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["series"] = { 59583 }, ["description"] = "Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around. She said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there. Have no worries, <name>! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master in Old Town!", ["objectivesText"] = "Speak with Curly at the stables in Old Town. Progress: Welcome to the stables, <class>. I've been expecting you.", ["rewardXP"] = 505, ["rewardItems"] = { 2411, 25470, 25474 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163095, ["x"] = 0.713818, ["y"] = 0.739636 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163007, ["x"] = 0.774, ["y"] = 0.671 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.713818, ["y"] = 0.739636 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 49, ["flags"] = 0 } } },
[58910] = { ["id"] = 58910, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 4, 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 59254, 59350, 59583, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Hey, <name>! Have you decided on a combat specialization yet? Since you're a <class>, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Mithlos Falconbriar to learn more about specializations!", ["objectivesText"] = "Speak with Mithlos Falconbriar to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?", ["rewardXP"] = 505, ["rewardItems"] = { 25470, 25474, 175165, 175166, 246462 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 164962, ["x"] = 0.792, ["y"] = 0.697 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.697 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 52, ["flags"] = 0 } } },
[58911] = { ["id"] = 58911, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "I don't know about you, but all this running around has got me thirsty! Why don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice? While we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a gryphon, but you'll save a few copper in the process!", ["objectivesText"] = "Speak with Meagan Tillman to make the Pig and Whistle Tavern your home. Progress: How can I help you today, <class>? Are you looking for a place to stay?", ["rewardGold"] = 200, ["rewardXP"] = 505, ["rewardItems"] = { 6948 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 44237, ["x"] = 0.755333, ["y"] = 0.540667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.755333, ["y"] = 0.540667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 53, ["flags"] = 0 } } },
[58912] = { ["id"] = 58912, ["name"] = "An Urgent Meeting", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58912 }, ["description"] = "I've been looking for you all over Stormwind, <name>. The captain has delivered her report to the king. It appears that Stormwind requires your service yet again. The leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay. It has been an honor serving with you, <name>. May the Light bless you on your journey.", ["objectivesText"] = "Speak with Captain Garrick at Stormwind Keep.", ["rewardXP"] = 125, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163211, ["x"] = 0.754, ["y"] = 0.543333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163219, ["x"] = 0.85, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.754, ["y"] = 0.543333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[58914] = { ["id"] = 58914, ["name"] = "A Warrior's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 85678 }, ["description"] = "Hey, <name>! You're a <class>, right? Maybe you can deal with this... situation. I was scouting the area with Lindie's device and saw a ghost who was offering power to any \"true\" warriors. I know you're still new at this, but why don't you try going over there? We could use every advantage against these ogres.", ["objectivesText"] = "Speak with the strange ghost at the Darkmaul Bridge.", ["rewardGold"] = 1600, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1073, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58915] = { ["id"] = 58915, ["name"] = "Hjalmar's Final Execution", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 85678 }, ["description"] = "You now wield my most powerful skill, young warrior. Now use it to finish me! These ogres trapped my spirit here long ago for daring to defy them. Only through a glorious death will I finally be allowed to rest. It is the only way I will see my brothers and sisters in the afterlife.", ["objectivesText"] = "Slay Hjalmar the Undying . You must use Execute in order to truly kill him.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 1073, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58916] = { ["id"] = 58916, ["name"] = "Dread Priming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Sire Denathrius has requested I help you prepare for the hunt. Every hunter must help prepare a soul here in the Grove of Terror. I have a stubborn soul here who's been quite uncooperative, Houndmaster Loksey . His time has come to be hunted. < The Fearstalker hands you a set of Hopebreaker Soul Chains .> Demoralize him. We can't let him leave here with any hope. The hunt is meant to break the souls so they become less... resistant to the processes of Revendreth .", ["objectivesText"] = "Prepare Houndmaster Loksey for the Penitent Hunt in the Grove of Terror.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 175770, 178873, 178994, 179388 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 169087, ["x"] = 0.505, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58917] = { ["id"] = 58917, ["name"] = "A Rogue's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58917, 58933, 85678 }, ["description"] = "A rogue from the lost expedition, Coulston Nereus , tried scouting the island for any threats after they made landfall. The last time Henry saw him, he was headed for a cave not far from here. Can you make contact with Coulston? He may be able to help with our rescue mission. Oh, and be careful when heading north. Alaria spotted a vicious bear roaming the area.", ["objectivesText"] = "Use Stealth to sneak around and find the first expedition's rogue. Progress: Did you get the roots? Make sure that bear is far away when you pick them.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 174916 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1074, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58918] = { ["id"] = 58918, ["name"] = "Huwerath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58918 }, ["objectivesText"] = "Free the Half-Digested Soul", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Free the Half-Digested Soul", ["amount"] = 1, ["type"] = 0, ["objectID"] = 163156, ["orderIndex"] = 0 } }, ["db2VignetteID"] = 4379, ["db2VignetteName"] = "Huwerath" },
[58923] = { ["id"] = 58923, ["name"] = "A Paladin's Service", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58923, 58946, 85678 }, ["description"] = "I found something strange while using Lindie's Scout-o-Matic that you should probably know about. The ghost of a paladin appeared on the hill nearby. She looked straight at the Scout-o-Matic and asked for you. I don't understand a whole lot about paladins and the Light, but I think you may not want to ignore her.", ["objectivesText"] = "Speak with the paladin's ghost. Progress: Greetings, <name>. It is good to finally see you.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 1077, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58931] = { ["id"] = 58931, ["name"] = "Inquisitor Stelia's Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "You never truly escape your past, Maw Walker. Every venthyr once entered Revendreth as a soul, burdened by the immoralities of their mortal lives. Like all souls, they carved their true names and most shameful transgressions into sinstones. Knowledge that intimate can be a potent weapon, if wielded properly. Locate the sinstones of the inquisitors aiding the Accuser so that you may kill them. Start with Stelia. After they're dead, bring me the Accuser's sinstone. I will deal with her myself.", ["objectivesText"] = "Collect Avowed Crypt Keys and open crypts until you locate Inquisitor Stelia's Sinstone . Progress: Inquisitors hide their sinstones to protect themselves.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156823, ["x"] = 0.645, ["y"] = 0.497 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.497 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58932] = { ["id"] = 58932, ["name"] = "Temel, the Sin Herald", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "<Before flying away, Echelon shouted an additional command.> Expropriate Temel as well. He will know how to exploit the sinstone properly.", ["objectivesText"] = "Defeat Cryptkeeper Kassir to earn Temel's obedience. Progress: Temel will not come willingly.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58933] = { ["id"] = 58933, ["name"] = "The Deadliest of Poisons", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58917, 58933, 85678 }, ["description"] = "You've got the poison. Now it's time to take out that ogre. Gutgruk the Tough. He usually patrols around their citadel. Probably looking for your expedition as we speak! Poison your blades, then take that monster down.", ["objectivesText"] = "Kill Gutgruk the Tough.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 35, ["flags"] = 0 }, { ["id"] = 1074, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58936] = { ["id"] = 58936, ["name"] = "Beast Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58936 }, ["description"] = "The Grove of Terror's dredbats have become aggressive due to the lack of anima caused by the drought. This is a formal request to cull their numbers. We must re-establish dominance over our creations. - Flockmaster Sergio", ["objectivesText"] = "Kill 6 Dredbats in the Grove of Terror.", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 179719 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1192, ["name"] = "Beast Control", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58937] = { ["id"] = 58937, ["name"] = "Evil Grubbies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "Oh no! This place is littered with mites! They are cute like Grubby, but they grow into horrible gorm! If we cleared some of them out, then the Sylvari will have less to fight against later. They can burrow away, so it's best to burn them up with Pelagos' red seeds. They'll be good for something after all.", ["objectivesText"] = "Burn 20 Evolving Mites with Pelagos' Flamelash Seeds. Progress: How many more are there?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 174291, 174843, 174845, 174938, 175153, 175982, 176446, 177052, 178155, 179941, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58938] = { ["id"] = 58938, ["name"] = "Gorm Ruin Everything", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "These red seeds will still prove useful. They come from a very dangerous plant and are quite unstable. If we are going to recover the blue seed we really need, then these might help. Let's clear out some of these gorm and search for the real seed.", ["objectivesText"] = "Kill 10 mature gorm. Progress: We need to clear a path.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58939] = { ["id"] = 58939, ["name"] = "The Blue Seed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "I remember seeing a blue seed with red leaves nearby, but it was in a cave behind a wall of brambles. I didn't think of it at the time, but maybe you could use the red seeds to get us in? I wish I didn't mix up the instructions or we wouldn't be in this mess. But maybe it's all going to work out anyway. Let's go!", ["objectivesText"] = "Find the cave entrance , get through the blockage of brambles, and obtain the Ripened Anima Seed . Progress: This has been quite the fun adventure. Wouldn't you say?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58941] = { ["id"] = 58941, ["name"] = "Alpha Bat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Dredbats are quite useful to us. We make them just like stoneborn, but they lack their same... intelligence. With very little direction, they strike fear into stubborn souls' hearts. With the anima drought, our dominion over them has waned. One, Duskterror , has wreaked the most havoc. This presents us with an opportunity. Take this soul and draw her in. When she's weak, we can capture her for our own purposes.", ["objectivesText"] = "Hitch Houndmaster Loksey to the stake in the Grove of Terror. Then, weaken Duskterror to capture her. Progress: Is Duskterror captured?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 175765, 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58946] = { ["id"] = 58946, ["name"] = "The Divine's Shield", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 3, 4, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58923, 58946, 85678 }, ["description"] = "This island has been cursed by necrotic magic. The Light can only just reach this place. Call upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar. Show the darkness on this island that you are protected by the Light's embrace.", ["objectivesText"] = "Cross the necrotic barrier with Divine Shield and destroy the Necrotic Altar. You can speak with Yorah if you need to reduce Divine Shield's cooldown. Progress: Do you require aid? Use Divine Shield to safely pass through the necrotic barrier.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 1077, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 10, ["flags"] = 0 } } },
[58947] = { ["id"] = 58947, ["name"] = "Test Your Mettle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Many of the greatest Maldraxxi legends earned their fame fighting in the Theater of Pain. If you want to follow in their footsteps, you need to prove you have what it takes to survive in there. Defeat Valuator Malus and Tester Sahaari in combat. Let's see what you can do!", ["objectivesText"] = "Valuator Malus and Tester Sahaari defeated. Progress: Earn the right to proceed!", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58948] = { ["id"] = 58948, ["name"] = "Food on the Table", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "I'm making a stew for dinner tonight, but it seems we're missing rabbit meat . Would you be able to go out back and collect some for me? Oh and do be careful, I heard howling earlier. The wolves aren't normally out during the day.", ["objectivesText"] = "Collect 4 Rabbit Meat . Progress: Shh shh, Gwendolyn. It's okay, baby girl.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 174935 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58949] = { ["id"] = 58949, ["name"] = "Millie's Garden", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "Alma came by earlier and gave Millie some flower seeds to plant out in the garden. I love that our daughter is taking an interest in gardening, but I don't have time to wash her dress when she gets it covered in mud again! Would you help her with the digging so that she doesn't get too dirty?", ["objectivesText"] = "Use your shovel to till 3 Untilled Soil. Progress: <Millie giggles.> Hi daddy!", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162962, ["x"] = 0.21, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58950] = { ["id"] = 58950, ["name"] = "Lumber for Lakeshire", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "Magistrate Solomon requested a bundle of wood for his hearth. However, he's been too busy to come by and retrieve it. If you wouldn't mind running it down to him at the town hall, I'm sure he'd appreciate it.", ["objectivesText"] = "Bring the Bundle of Lumber to Magistrate Solomon at the Lakeshire Town Hall. Progress: The folks are on edge, Ben. It's my job to keep them at ease.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 174997 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 163111, ["x"] = 0.288, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58953] = { ["id"] = 58953, ["name"] = "A Priest's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58953, 58960, 85678 }, ["description"] = "You're a trained priest, right <name>? This might be up your alley. We've spotted the bodies of other recruits from our expedition. I'm guessing they washed up on a different part of the island. They didn't make it very far. When you have a moment, could you say a few prayers over them? Just to help put their spirits at ease. We'll give them a proper burial once we deal with the ogres.", ["objectivesText"] = "Find the corpses of the first expedition recruits.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 37, ["flags"] = 0 }, { ["id"] = 1082, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58960] = { ["id"] = 58960, ["name"] = "Resurrecting the Recruits", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58953, 58960, 85678 }, ["description"] = "The souls of these recruits aren't strong enough tae resist the dark magic bein' practiced on this island. Use Resurrect on the remains of these recruits. Beseech the Light tae give 'em another chance while their souls still linger. I've been stranded on this island for years, watchin' these ogres get away with all of this. It's time tae make a stand.", ["objectivesText"] = "Resurrect the Expedition recruits. Progress: Get goin' and save those recruits with resurrect!", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 1082, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 12, ["flags"] = 0 } } },
[58962] = { ["id"] = 58962, ["name"] = "A Warlock's Bargain", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58962, 85678 }, ["description"] = "While you were mowing down hordes of undead, I was scouting more of the area with Lindie's device. I saw what looked like a portal out near the bridge, along with the corpse of a warlock we thought was lost in the shipwreck. Think you can go investigate the area and try to close that portal? We have enough problems on this island as it is.", ["objectivesText"] = "Investigate the first expedition warlock's corpse. Progress: I see you have the grimoire that enacted the binding ritual.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 174947 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 39, ["flags"] = 0 }, { ["id"] = 1078, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 13, ["flags"] = 0 } } },
[58975] = { ["id"] = 58975, ["name"] = "Pest Removal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58975 }, ["objectivesText"] = "Burrowing Mite extracted Mature Gorm slain", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Burrowing Mite extracted", ["amount"] = 6, ["type"] = 0, ["objectID"] = 163212, ["orderIndex"] = 0 }, { ["text"] = "Mature Gorm slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 170182, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58976] = { ["id"] = 58976, ["name"] = "Chasing a Memory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["description"] = "The attack on the Temple of Purity is unprecedented in Bastion . At least, to my knowledge. We need to know more. The fragment that the Paragon captured may contain the answers we seek. There is a place nearby called the Mnemonic Locus. There, aspirants and ascended alike can call forth their memories and store them away. If we can look through this fragment's memories, perhaps we can learn more about the so-called Forsworn and, with luck, uncover their plan. I will meet you there. Go in service.", ["objectivesText"] = "Travel to the Mnemonic Locus.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156238, ["x"] = 0.538, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58977] = { ["id"] = 58977, ["name"] = "What's In a Memory?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58800, 58978 }, ["description"] = "It may be possible to extract memories from fragment, but I worry they will not be useful. This is not whole kyrian, but a tiny piece! A weird, broken piece. It cannot even speak! We will apply extractor and see what comes out. Extractor might explode. It might not. For this? Worth the risk, I think. Do not know what will emerge. Could be memories. Could be nothing. Could be something else. May try to fight you! Stay on your guard, yes? Collect all that look Forsworn. Speak when ready.", ["objectivesText"] = "Collect memories of the Forsworn from the Fragment of Lysonia . Progress: Do you think we will get the information we need, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58978] = { ["id"] = 58978, ["name"] = "Lysonia's Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58800, 58977 }, ["description"] = "If I had not seen it with my own eyes, I do not know that I would believe such a thing is possible. You carry a significant piece of Lysonia within you, now. Go to the Soul Mirrors and open yourself to them. With luck, they will draw from her essence to draw forth a memory of the Forsworn. If this works, we may know what they are planning within minutes!", ["objectivesText"] = "Stand before a Soul Mirror and witness memories from Lysonia's past.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.6295 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58980] = { ["id"] = 58980, ["name"] = "Mnemis, At Your Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58843, 59196, 60013, 60180 }, ["description"] = "Greetings, I am Locus-Keeper Mnemis and I would be delighted to assist you. I recall that you are trying to access a particular memory. Due to the contents, that memory can only be viewed within the Vault of the Archon. In order to gain access to the Vault, you must collect offerings for the two guardians who watch over it. I have hidden these offerings from the Forsworn, as they are not authorized to enter. The Forgelite Prime is the only one among you who can grant authorization. How convenient!", ["objectivesText"] = "Locate two offerings within the Walk of Recollection, then proceed to the Vault of the Archon. Progress: Did you find the offerings of which I spoke?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167035, ["x"] = 0.578, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167035, ["x"] = 0.578, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58983] = { ["id"] = 58983, ["name"] = "Battle for Azeroth: Tides of War", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58983 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 57766, 59641, 60362 }, ["description"] = "King Wrynn has called us together for an urgent war council. It seems that there was some trouble with the Horde while we were away. The king was impressed with the valor and bravery that you demonstrated during our mission to Exile's Reach. Now that you've arrived, the meeting will begin without delay.", ["objectivesText"] = "Attend the War Council in Stormwind Keep. Progress: Thank you for coming.", ["rewardGold"] = 200, ["rewardXP"] = 125, ["rewardItems"] = { 178941, 178942 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163219, ["x"] = 0.85, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 165395, ["x"] = 0.856, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[58992] = { ["id"] = 58992, ["name"] = "Pie Not?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58992 }, ["description"] = "I want to cook something warm, savory, and gooey! That's right! I want to make a lovely bone marrow pie! When it's done, you'll be as full as a tick. I guarantee it! Now, just any old marrow won't do. I need the very best and rarest marrow. And that's where you come in! I need you to help Mama out and dig that marrow up. Yes... dig. Oh and be ready to knock some heads. Maldraxxus doesn't take kindly to being carved up.", ["objectivesText"] = "Collect 4 Maldraxxi Bone Marrow . Progress: Is there any kind of pie that's not just the best? Blood pie, bone marrow pie, bone marrow jelly...", ["rewardGold"] = 619600, ["rewardXP"] = 8165, ["rewardItems"] = { 177879, 181809, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
