[58995] = { ["id"] = 58995, ["name"] = "I Dreamed A Dream", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "This is quite a ceremony, everyone is here. This ritual is essential to the recreation of the Crest of Ascension and the preservation of Bastion . We owe the Winter Queen and Willowblossom a great debt. Someday, I hope we can repay them.", ["objectivesText"] = "Witness the ceremony. Progress: Do you have the vessel?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58996] = { ["id"] = 58996, ["name"] = "Abel's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58996 }, ["description"] = "Maw Walker, I have another task for you. Some time ago, I sent Soulwatcher Abel and a few others to slay some troublesome bonemaulers. They have yet to return. Go find them, will you?", ["objectivesText"] = "Investigate Soulwatcher Abel's fate. Progress: What became of Abel?", ["rewardGold"] = 421350, ["rewardXP"] = 1415, ["rewardItems"] = { 174957 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156384, ["x"] = 0.485, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156384, ["x"] = 0.485, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1189, ["name"] = "Abel's Fate", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58997] = { ["id"] = 58997, ["name"] = "A Bittersweet Prize", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["series"] = { 61135 }, ["description"] = "I... I don't know what to say. All that is left is to return Willo... the vessel... to Polemarch Adrestes in Bastion . This sacrifice must not be in vain.", ["objectivesText"] = "Deliver the Vessel of Ardenweald to Polemarch Adrestes at Elysian Hold in Bastion .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59004] = { ["id"] = 59004, ["name"] = "Splash Damage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59004 }, ["description"] = "The Jailer's troops use anima charged runes to empower their armor. Without those runes, the troops will be significantly weaker! I developed this special formula to remove tough laundry stains, but it should be capable of removing magical runes as well! Splash my Putrification Potion on Rune-hardened troops, the bigger the better! Then collect the runes that fall off, so I can extract their anima.", ["objectivesText"] = "50 Anima Charged Runes collected off Rune-hardened Troops. Progress: Have you cleaned things up?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181625, 181638, 181645, 181647, 181649, 181651, 181662, 181675, 181676, 181677, 181678, 181689, 181693, 181695, 181982, 182657, 182684, 182772, 183202, 183487, 183490, 184305, 184772, 184773, 184774, 184775, 184776, 185485, 185729 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 163295, ["x"] = 0.328, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[59007] = { ["id"] = 59007, ["name"] = "Soul Well", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59007 }, ["objectivesText"] = "Catch the Stygia erupting from the Soul Well", ["rewardGold"] = 619600, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Catch the Stygia erupting from the Soul Well", ["amount"] = 30, ["type"] = 0, ["objectID"] = 163367, ["orderIndex"] = 0 } }, ["db2VignetteID"] = 4380, ["db2VignetteName"] = "Soul Well" },
[59008] = { ["id"] = 59008, ["name"] = "Spriggan Snares", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "I'm so glad you and Qadarin were passing by! These spriggans are crazy! Get me out of here! I was gathering some herbs from the garden when they nabbed me. I'm sure they've captured other souls, too!", ["objectivesText"] = "Free Cirrik and rescue 8 Captives. Progress: This behavior is unexpectedly bold for the spriggans.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163385, ["x"] = 0.39, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59009] = { ["id"] = 59009, ["name"] = "Her Rightful Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59025, 59185, 59190, 59210 }, ["description"] = "Mor'Bitan has met his end... and a painful one at that. Your fortitude contributed in no small part to my success. You have earned my allegiance... for the time being. There is much left to do, should you truly desire ownership of this realm. Let us regroup at the Seat.", ["objectivesText"] = "Return to the Seat of the Primus with your runeblade. Progress: Were you successful?", ["rewardGold"] = 121680, ["rewardXP"] = 710, ["rewardItems"] = { 174934, 175409, 175451, 175452, 175453, 175454, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59011] = { ["id"] = 59011, ["name"] = "In Death We Are Truly Tested", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["description"] = "Vyraz is the one who trapped me within the Maw. He has long been in league with the House of Rituals and the House of Constructs. No doubt he intended to trap you within that hellish place as well. It is time he be brought to justice for his treason. Stand with me, and we will face him as one.", ["objectivesText"] = "Confront Vyraz about the death of Margrave Krexus.", ["rewardGold"] = 491400, ["rewardXP"] = 1770, ["rewardItems"] = { 180663, 180664, 180665, 180666, 180667, 180668, 180669, 180670, 180671, 180672, 180673, 180790, 180791, 180792 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162801, ["x"] = 0.412, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 170309, ["x"] = 0.504, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59014] = { ["id"] = 59014, ["name"] = "King of the Hill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Loksey is ready. It is finally time to begin the hunt. Take him to Wanecrypt. The Fearstalker and the other hunters will be there already. Hurry now. She does not like to be kept waiting.", ["objectivesText"] = "Bring Houndmaster Loksey to the Fearstalker in Wanecrypt Hill. Progress: Where's the soul?", ["rewardGold"] = 71600, ["rewardXP"] = 355, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59015] = { ["id"] = 59015, ["name"] = "Hostile Recollection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59015 }, ["objectivesText"] = "Repel the Forsworn threat", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178149, 178150 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Repel the Forsworn threat", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59020] = { ["id"] = 59020, ["name"] = "The Third Fall of Kel'Thuzad", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58833, 59020, 62391, 62406 }, ["description"] = "The time has come to purge Maldraxxus of treachery. Our armies are rallied. Our allies stand ready. The machine of war is in motion. We must win this battle, or all of the Shadowlands will be lost.", ["objectivesText"] = "Remove Kel'Thuzad from Maldraxxus .", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 181822 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 174179, ["x"] = 0.62, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1118, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1118, ["name"] = "Assault on the House of Rituals", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59021] = { ["id"] = 59021, ["name"] = "Herald Their Demise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Since the dawn of Revendreth , Temel has been charged with proclaiming the sins of souls for all to hear. Every soul here, including venthyr, has been forced to endure his wrathful pronouncements on at least one occasion. He will know how to wield Inquisitor Stelia 's sinstone to break through her defenses. Simply command him to do so after you locate the inquisitor, and eliminate her.", ["objectivesText"] = "Order Temel to read from Inquisitor Stelia 's sinstone, then kill her. Progress: Is the inquisitor dead?", ["rewardGold"] = 252720, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175430, 175431, 175432, 175433 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59023] = { ["id"] = 59023, ["name"] = "Ending the Inquisitor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Inquisitor Vilhelm hides smugly in the back of the courtyard, flanked by several gargons and loyal venthyr. We must kill him to break the ward on the Accuser's sinstone, so that Lord Chamberlain can use it in his battle. Temel will once again help you penetrate the inquisitor's defenses. Do not tarry.", ["objectivesText"] = "Order Temel to read from Inquisitor Vilhelm 's sinstone, then kill him. Progress: Once the inquisitor is dead, the warding spell will be broken.", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175442, 175443, 175444, 175445 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59025] = { ["id"] = 59025, ["name"] = "Straight to the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59185, 59190, 59210 }, ["description"] = "The success of Mor'Bitan 's treachery has made him complacent. Let him enjoy the feeling, for it ends here. We will lure him out with this ritual... and we will avenge my margrave. Stand with me now, <name>. Together, we will make an example of this traitor.", ["objectivesText"] = "Kill Mor'Bitan . Progress: He will regret crossing me.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59042] = { ["id"] = 59042, ["name"] = "A Good Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "Despite the beliefs of most people, Emeni has a kind heart. Err...at least she will have one, once you give it to her! I can think of no one better than you, Maw Walker, to give Emeni a new heart. Perhaps this will warm her blood towards you. You might become friends or even soulbinds! Please select and place a heart in Emeni's construct.", ["objectivesText"] = "Place a heart in Emenis' construct. Progress: I hope you chose well!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59043] = { ["id"] = 59043, ["name"] = "Baker's Dozen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59043 }, ["description"] = "Under this very tent, I've prepared delicacies that would make demigods cry tears of joy. I'm always in need of more baking supplies! The brokers usually sell me eggs from parts near and far, but maybe this time you could help me out instead. You familiar with gorm? Big insect-like creatures native to Ardenweald. Well, if you find me some eggs of theirs, I'll bake you up something nice in return! Mama will even send Starchy to help you out.", ["objectivesText"] = "Travel to Ardenweald and collect 13 Hatchready Gorm Eggs .", ["rewardXP"] = 8165, ["rewardItems"] = { 181809, 183744, 184040, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[59063] = { ["id"] = 59063, ["name"] = "Curses!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "Oh, dear me, this is terrible! Just terrible! I know precisely which awful curse afflicts that poor soul! But these damnable spriggans keep stealing my scrolls, scattering them all over and ripping them apart! Now the falls are overrun with all manner of dangerous magic! The spriggans have the pieces of the scroll you need. Gather them along with a binding from one of the major hexes, and you can put it all back together.", ["objectivesText"] = "Retrieve 5 pieces of Shredded Scroll from Rotbriar spriggans and a Tattered Binding from a Major Hex to create a Sealed Scroll of Soul Rot . Progress: Hmm... Yes, this looks like it could be the one.", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 175137, 175138, 177280 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59068] = { ["id"] = 59068, ["name"] = "A Secret Never Spoken", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "The first reagent listed in the scroll is a secret never spoken . Well, that's easy. I know who has tons of secrets! Watcher Vesperbloom , our resident snoop. She keeps the Wild Hunt informed of any nefarious behavior that takes place in the forest. I know she'd be willing to give us a secret to save Qadarin's soul from dissolving in excruciating pain. I'll have Thiernax meet you wherever she's hidden them. It'll keep his mind off what's happening to his husband.", ["objectivesText"] = "Obtain a Secret Never Spoken from Watcher Vesperbloom 's records. Progress: Whew! This page... It's seen sights no one should ever see.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 175152, 175154 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59069] = { ["id"] = 59069, ["name"] = "A Token of Lost Love", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "My sister, Alexstrasza, lost her prime consort, Korialstrasz, towards the end of our war with Deathwing. She has loved many in her long life, but none as deeply as he. I know in my heart she loves him still. Find Alexstrasza in the Vermillion Redoubt and ask for a token of her lost love. It will surely prove a powerful reagent for the counter-curse.", ["objectivesText"] = "Speak with Alexstrasza at the Vermillion Redoubt in Twilight Highlands. Progress: My sister loves with all of her heart...", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 6948, 63378, 63379, 175149, 187897 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59070] = { ["id"] = 59070, ["name"] = "A Sacrifice of Anima", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "The last thing we need for this counter-curse is some attuned anima. Of course, we don't have much to spare. That means this is more of a sacrifice than it normally would be. But you know what? The spriggans made this mess, so they should help clean it up. Some really nasty ones have been causing mischief in Tirna Scithe. They should have the anima we need. Thiernax looks like he could use some nice, vengeful, therapeutic spriggan stomping. I'll have him meet you there.", ["objectivesText"] = "Slay Spriggans in Tirna Scithe to collect Mischief-touched Anima . Progress: Have you handled those spriggans yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175139 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59071] = { ["id"] = 59071, ["name"] = "Mending a Broken Hart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "We have all the reagents for the counter-curse! Hurry up and cast it before Qadarin 's soul is lost, and Thiernax refuses to help you, and Tyrande is doomed to die horribly in the Maw, and everyone is sad! But no pressure.", ["objectivesText"] = "Perform the counter curse. Progress: I... I cannot thank you enough.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181301, 182172 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 11, ["flags"] = 0 } } },
[59076] = { ["id"] = 59076, ["name"] = "The Minions of Mayhem", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59076 }, ["description"] = "To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves! Come to our secret meeting at the Ledge of Destiny. To all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. Don't tell the fuzz.", ["objectivesText"] = "Attend the publicly posted \"Secret Meeting.\"", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59087] = { ["id"] = 59087, ["name"] = "That Darn Fox!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59087 }, ["description"] = "You! You there! I, Clarion Song , need your assistance. Yes, yes, give yourself a moment to bask in my glory. < Clarion Song gives you a moment.> Done? Good. I need you to catch a troublesome vulpin kit. He is positively barbaric! Running amok, causing havoc, ruining my beauty rest! He's using a concealing charm to make himself invisible, but I know it's him! Make yourself useful and catch that kit!", ["objectivesText"] = "Find and Catch Renny the Vulpin kit. Progress: Well? Did you catch it?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175114, 184396 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163774, ["x"] = 0.508, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163774, ["x"] = 0.508, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[59120] = { ["id"] = 59120, ["name"] = "Renny the Vulpin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59120 }, ["description"] = "<The small vulpin kit runs up to you with a cheerful bounce and an air of mischief. You, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you. What could possibly go wrong?>", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 175114, 180644, 180645, 180814, 180857, 180859, 180860, 180861 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59130] = { ["id"] = 59130, ["name"] = "The House of Plagues", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["description"] = "The House of Plagues was the first to fall in this conflict. We believed its demise was the result of a careless accident. If only we had known the truth sooner... But perhaps not all their knowledge was lost. Before you arrived, our scouts reported signs of movement near the wreckage of their necropolis. If any survivors remain, we'd be wise to add them to our ranks. But approach with caution. The toxic fallout may have left them mad... or worse.", ["objectivesText"] = "Search for survivors near the House of Plagues.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59147] = { ["id"] = 59147, ["name"] = "The Hand of Purification", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "Nikolon was not alone. < Eridia stares grimly out over the temple grounds.> Long have I toiled over the aspirants in my care. Long have I tended to this temple under my Paragon. To know that so many have fallen, alone, is a blow. But this... wanton destruction! It will not stand. You will be my hand, <name>. Go forth. End them. All of them. My duty demands that I tend to those that remain. I will find you near the bridge when the way is clear.", ["objectivesText"] = "\"Cleanse\" the Temple of Purity by slaying enemies.", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59171] = { ["id"] = 59171, ["name"] = "Prey Upon Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 58821, 59172 }, ["description"] = "My mission cannot progress without a supply of anima. Fortunately, the necromancers nearby have been kind enough to gather some into their maldracite crystals. You will relieve them of those crystals. They may be reluctant to part with them, but I trust you can be... persuasive.", ["objectivesText"] = "Collect 3 Anima-charged Maldracite . Progress: Do not fail me.", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59172] = { ["id"] = 59172, ["name"] = "War is Deception", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 58821, 59171 }, ["description"] = "You have proven a useful ally, <name>. Mephiles undoubtedly possesses a wealth of information for us. However, the House of Rituals is unforgiving when it comes to betrayal. He will not talk. Not that it matters. The House of Eyes has ways to... extract a prisoner's knowledge without the use of words. Place the charged crystals around me. They will facilitate the interrogation.", ["objectivesText"] = "Prepare to interrogate Mephiles the Loyal. Progress: Let us reveal the truth.", ["rewardGold"] = 24335, ["rewardXP"] = 175, ["rewardItems"] = { 174934, 175409, 175706, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59175] = { ["id"] = 59175, ["name"] = "The Eternal Revenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59175 }, ["description"] = "<On the shelves there are hundreds of other phylacteries of varying shapes and sizes. Many bear names - this one specifically has a etching with the name Mor'Bitan. Lady Vashj would be interested in this phylactery.>", ["objectivesText"] = "Take the phylactery of Mor'Bitan back to Lady Vashj.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59179] = { ["id"] = 59179, ["name"] = "Daughter of the Night Warrior", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 59179, 59181, 59189, 59242, 60508, 60530 }, ["description"] = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance. And... Ardenweald 's destruction. These visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm. Shandris Feathermoon , Tyrande's daughter, is touched by dreams as well. Even now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", ["objectivesText"] = "Find Shandris Feathermoon within Oribos.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59181] = { ["id"] = 59181, ["name"] = "Into the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "I have not seen Tyrande since she departed for Icecrown... but I see her in my dreams. She stalks a nightmarish landscape, brimming with the might of the Night Warrior. Such power is too much for any mortal to bear for long. I shudder to think of the toll it has taken on my minn'do. Highlord Fordragon has told me of the Maw. If you truly have braved its horrors before, then I ask that you guide me through them as well. We must find Tyrande and convince her to let go of the Night Warrior's rage.", ["objectivesText"] = "Take Shandris Feathermoon into the Maw.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 55049, 55050 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 174833, ["x"] = 0.445, ["y"] = 0.411 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.411 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 2, ["flags"] = 0 } } },
