[59184] = { ["id"] = 59184, ["name"] = "Borr-Geth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 59184 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[59185] = { ["id"] = 59185, ["name"] = "Entangling Web", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59025, 59190, 59210 }, ["description"] = "It would seem we have a means of luring Mor'Bitan to us. But what good is a web if the prey can run free? For these rituals to work, the liches require a magical conduit. They draw runes with finely ground maldracite to channel anima. I have no doubt Mor'Bitan's necromancers have ground maldracite in the area. If we gather enough, we can draw a rune of binding to trap our target. Work with haste, $p.", ["objectivesText"] = "Collect 8 jars of Maldracite Dust . Progress: I'm waiting.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59188] = { ["id"] = 59188, ["name"] = "Vaunted Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["description"] = "So you are from my baroness's home world? It must be a special one to breed such powerful individuals. The necromancers here have already begun preparation for Mor'Bitan's ritual. We should capitalize on their progress. Three necromancers act as the ritual's architects. Should we acquire their drafts, we could modify them to suit our purposes. Collect the plans... and feel free to savor your victims' torment.", ["objectivesText"] = "Collect Ritual Drafts from the three Architects. Progress: We are hopeful for your success.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 175446, 175459, 175460, 175461, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164297, ["x"] = 0.714667, ["y"] = 0.448667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164297, ["x"] = 0.714667, ["y"] = 0.448667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.714667, ["y"] = 0.448667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59189] = { ["id"] = 59189, ["name"] = "The Recovery of Tyrande Whisperwind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "The Night Warrior's power is tearing Tyrande apart. Such rage... it is consuming her. <Shandris is silent a moment.> And yet, my mother speaks true. We cannot leave the souls of my people to suffer. We shall follow Tyrande into Torghast. We must find a way to save the spirits of the kaldorei. And in the process, pray that we can save my minn'do as well.", ["objectivesText"] = "Enter Torghast to recover Tyrande Whisperwind.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 174834, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 174834, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59190] = { ["id"] = 59190, ["name"] = "Seek Your Mark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59025, 59185, 59210 }, ["description"] = "I see why Draka sent you in her stead--you accomplish what she could not. We have all the pieces. Now, we must simply put them together. The steps to the ritual are simple: place our fractured crystals in formation around the obelisk. Then comes the sigil--*our* sigil. Use the maldracite powder to draw a binding glyph at the obelisk's base. When you are through, return to me.", ["objectivesText"] = "Prepare the ritual. Progress: Work swiftly.", ["rewardGold"] = 121680, ["rewardXP"] = 710, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59196] = { ["id"] = 59196, ["name"] = "Go in Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 58843, 58980, 60013, 60180 }, ["description"] = "We cannot waste any more time. We must get an audience with the Archon, before this next attack happens! We need to find a way to get you to Elysian Hold... and quickly! Hero's Rest is a place of respite for the aspirants of Bastion . You can see it floating above from across the fields. Meet me there when you can. I have a plan.", ["objectivesText"] = "Meet Kleia at Hero's Rest. Progress: We must get moving.", ["rewardGold"] = 23870, ["rewardXP"] = 175, ["rewardItems"] = { 35884, 35885, 35886, 35887, 62892, 62893, 62894, 198606, 198607, 198609, 198611, 198612, 198613, 228773, 228774, 228775, 228776, 228777, 228778, 228779, 237578, 237812, 245345, 263454, 263455, 263456, 263457, 263458, 263459, 263460 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165042, ["x"] = 0.528, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.6295 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59197] = { ["id"] = 59197, ["name"] = "Steward at Work", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59198, 59199, 59200, 59426, 60005, 60006 }, ["description"] = "Stewards are useful for many reasons. They keep Bastion tidy, fix anything broken, and offer unrivaled companionship and support. Your new steward assistant should be able to repair the beacon. Then you can summon the Polemarch to Hero's Rest.", ["objectivesText"] = "Use Summon Steward to fix the Beacon of Invocation, then use it to summon Polemarch Adrestes .", ["rewardGold"] = 119340, ["rewardXP"] = 710, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165045, ["x"] = 0.528, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165048, ["x"] = 0.53, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59198] = { ["id"] = 59198, ["name"] = "On Swift Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59199, 59200, 59426, 60005, 60006 }, ["description"] = "Our revered Archon has decided to grace you with an audience. It is your duty to present your discoveries to her, then follow her wise judgment. She holds audience in Elysian Hold, part of the sprawling Spires of Ascension, the home of the Ascended. We shall carry you there, for it is a place for those who can fly.", ["objectivesText"] = "Fly with Adrestes to Elysian Hold.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 173316, 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165048, ["x"] = 0.53, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59199] = { ["id"] = 59199, ["name"] = "Kyrestia, the Firstborne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59198, 59200, 59426, 60005, 60006 }, ["description"] = "I will escort you to hold audience with the Archon. I beseech you to present your information succinctly and directly. Our wise Archon will hear you and make a decision on the best course of action.", ["objectivesText"] = "Speak with Adrestes to address the Archon. Progress: None shall doubt the Archon, in her infinite wisdom.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59200] = { ["id"] = 59200, ["name"] = "The Wards of Bastion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59198, 59199, 59426, 60005, 60006 }, ["description"] = "Each temple of Bastion is protected by a ward here in Elysian Hold. As long as the wards hold, no malevolent force can launch an assault. It is concerning that the Forsworn were able to attack Purity in such force... Your orders are to examine the wards. As long as they hold, Bastion stands strong.", ["objectivesText"] = "Investigate the temple wards in Elysian Hold. Progress: The wards each protect one of the temples of Bastion . If a ward is not active, that temple stands vulnerable.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59202] = { ["id"] = 59202, ["name"] = "Among the Chosen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "Only one rune remains... We should return to the House of the Chosen and report to Margrave Krexus. He will want to know of our progress.", ["objectivesText"] = "Return to the House of the Chosen.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164843, ["x"] = 0.389333, ["y"] = 0.650667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59203] = { ["id"] = 59203, ["name"] = "Leave Me a Loan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "I run a myriad of businesses here. Betting rings, performance enhancers... whatever the customer is willing to purchase. However, a few of those customers are late with their payments. And a customer who does not pay is a customer without value. Please ask them to surrender what they owe. I trust you know what to do if they refuse.", ["objectivesText"] = "Collect 6 Anima Vials from the arena spectators. Progress: Do not try to cheat me out of anything I am owed. I will know.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59206] = { ["id"] = 59206, ["name"] = "Words of the Primus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["series"] = { 61715, 61716 }, ["description"] = "Even in his absence, the wisdom of the Primus rings true. This message must have been put here to await one who proved worthy of hearing it. <Draka peers at you.> You came to Maldraxxus to learn why Bastion was invaded. Now you know that there is treachery in our ranks. And that there are noble souls here who will set things right. Tell your allies in Oribos all you have witnessed. See that the warning of the Primus reaches the Eternal Ones. It would be an honor to fight by your side again, <name>.", ["objectivesText"] = "Return to Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59207] = { ["id"] = 59207, ["name"] = "Unshackled Knowledge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59207 }, ["description"] = "These Forsworn are looting the artifacts contained in Kalliope's Rest. What is worse is they have captured many of the shrine's scholars. I fear they will interrogate these aspirants for knowledge about the artifacts held within the inner chamber of the shrine. Most escaped with me, but Lano, Eratus, and Tyrana have not returned yet.", ["objectivesText"] = "Free Curator Lano , Librarian Eratus , and Historian Tyrana .", ["rewardGold"] = 289575, ["rewardXP"] = 6125, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59209] = { ["id"] = 59209, ["name"] = "Rebel Reinforcements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "< General Draven looks around.> We require additional reinforcements. I know of two here that are fiercely loyal to the true purpose of Revendreth . The Fearstalker left them here to be consumed by the anima drought due to their allegiance. They are both fully capable of assisting us in our mission. Take this anima stake and infuse them. Direct them to me, I will explain the situation.", ["objectivesText"] = "Recruit Watchmaster Boromod and Tactician Sakaa . Progress: Are our allies infused?", ["rewardGold"] = 255060, ["rewardXP"] = 1415, ["rewardItems"] = { 175414, 175427, 175428, 175429, 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164394, ["x"] = 0.432, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168471, ["x"] = 0.398, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 11, ["flags"] = 0 } } },
[59210] = { ["id"] = 59210, ["name"] = "Tainted Cores", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59025, 59185, 59190 }, ["description"] = "This lich seeks a reward for his assault on the House of Eyes. But the power he craves will be his downfall. We will use our knowledge of his secret ritual to lure him out of the House of Rituals. Take these crystals, <name>. Charge them with anima reclaimed from Mor'Bitan's slain minions. But fracture them first, so that they shatter as the ritual nears completion... but not before Mor'Bitan believes that it has begun. That is when we will strike.", ["objectivesText"] = "Fracture the three Depleted Anima Crystals, then charge the Fractured Anima Crystals with deceased Morbid Ritualists. Progress: Is it done?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 31088, 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 4, ["flags"] = 0 } } },
