[59223] = { ["id"] = 59223, ["name"] = "By Any Other Name", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58036, 58045, 59231, 60831 }, ["description"] = "Excellent work, my apprentice! Our laboratory is back in working order! Now, there is one final ingredient we require to complete our potion for Margrave Stradama. You will need to run along to the greenhouse. I've cultivated a sprig of dreadshade that should be ready to harvest. I will prepare the other reagents while you're away. Be safe, apprentice!", ["objectivesText"] = "Collect Dreadshade Extract for Marileth's potion. Progress: Have you found it?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 7, ["flags"] = 0 } } },
