[59231] = { ["id"] = 59231, ["name"] = "Fathomless Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58036, 58045, 59223, 60831 }, ["description"] = "Forgive me, apprentice... I felt a bit woozy for a moment! But you've done it! You've crafted the potion! I'm so proud of you. What joy your work brought to our margrave! What manner of teacher would I be were I to ask for your help and not offer my own in return? If you have research you must conduct, you have my full support! Let us venture to your laboratory, then. I wait with bated breath to behold your future achievements!", ["objectivesText"] = "Meet Marileth at the Seat of the Primus.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59232] = { ["id"] = 59232, ["name"] = "A Lesson in Humility", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Thank you for your service in deposing the Accuser and elevating Lord Chamberlain in her place. The Accuser's unprompted betrayal has rendered her both undeserving and unfit to serve on the Court of Harvesters. Now, please, observe what happens to traitors in Revendreth .", ["objectivesText"] = "Witness the Accuser's judgment. Progress: Please observe silently, Maw Walker.", ["rewardGold"] = 126360, ["rewardXP"] = 710, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175434, 175435, 175436, 175437 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156381, ["x"] = 0.534, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156381, ["x"] = 0.534, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59233] = { ["id"] = 59233, ["name"] = "The Prince's New Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "The crown is ready. I will entrust you to deliver it to Renathal. Make haste, <name>. This power will surely attract assailants if word gets out. You may use the mirror to return. Know that I will be dispatching others to destroy it after your arrival. Safe travels, Maw Walker.", ["objectivesText"] = "Deliver the Crown of the Harvesters to Prince Renathal in Sinfall.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 180604, 180905, 180906, 180907, 180908 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171175, ["x"] = 0.232, ["y"] = 0.256333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.232, ["y"] = 0.256333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 14, ["flags"] = 0 } } },
