[59242] = { ["id"] = 59242, ["name"] = "Their New Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "It pains me to leave my mother behind... but the souls of my people must be brought to safety. I heard the attendants in Oribos speaking of a place called Ardenweald . A realm of ancient forests where the spirits of nature slumber. This is a land you know well, is it not? I would see its wonders with my own eyes. Perhaps the spirits there will know how to save my minn'do from the Night Warrior's power.", ["objectivesText"] = "Take Shandris Feathermoon and the rescued night elf souls to Ysera at the Heart of the Forest in Ardenweald . Progress: You've returned. But what of the others?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 175576, 179657, 179765, 179774, 179888, 181909, 181979 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 174834, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59246] = { ["id"] = 59246, ["name"] = "Daughter of the Night Warrior", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance. And... Ardenweald 's destruction. These visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm. Shandris Feathermoon , Tyrande's daughter, is touched by dreams as well. Even now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", ["objectivesText"] = "Find Shandris Feathermoon within Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59254] = { ["id"] = 59254, ["name"] = "Enhanced Combat Tactics", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Alaria says that the quilboar kidnapped other members of her expedition. Chances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier. I need to make sure I'm not sending you to your death. We're going to have one last sparring session.", ["objectivesText"] = "Spar with Captain Garrick .", ["rewardGold"] = 565, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59256] = { ["id"] = 59256, ["name"] = "The Fearstalker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "The trap has been set and the Fearstalker has walked right in. Just as I expected, her pride has blinded her to the obvious. Have that vial I gave you earlier ready. It may prove useful in the fight ahead. When you are ready, we can spring the trap.", ["objectivesText"] = "Speak to the Accuser to trigger the trap, then kill the Fearstalker and collect the Medallion of Dread . Progress: The Fearstalker must be defeated.", ["rewardGold"] = 510120, ["rewardXP"] = 1770, ["rewardItems"] = { 175484, 175485, 175486, 175487, 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168468, ["x"] = 0.396, ["y"] = 0.812 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 13, ["flags"] = 0 } } },
[59258] = { ["id"] = 59258, ["name"] = "Home of the Tirnenn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "The Horned Hunter is no longer here. But I do know where he went. He tracked his prey to the west of here, in the Elder Stand. These woods in particular have grown dangerous as of late, and we are currently beset by invading devourers. They have overrun the roads between here and the Stand. I shall accompany you across the bridge, and see that you are delivered to the Horned Hunter.", ["objectivesText"] = "Fight your way into Tirna Scithe and find the Horned Hunter.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59259] = { ["id"] = 59259, ["name"] = "The Eternal Tormentor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59259 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[59262] = { ["id"] = 59262, ["name"] = "Broken Wings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59262 }, ["series"] = { 59263, 59311, 59348, 59351, 59865, 60660 }, ["description"] = "You help me? Really? Wow! Look at me. What am I? I have beak. Feathers. Scaly toes. I am bird, yes? But birds have wings. And I have arms. Why I not have wings? I broken. I can not fly. Larion nearby, flies so gracefully. I must study her wings up close! You help me?", ["objectivesText"] = "Bring Kowalskos Ariella's Wing . Progress: If I can study a larion wing, surely I can learn!", ["rewardGold"] = 316013, ["rewardXP"] = 6125, ["rewardItems"] = { 175791, 175792, 175967, 175968, 176812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59263] = { ["id"] = 59263, ["name"] = "Feathers of Flight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59263 }, ["series"] = { 59262, 59311, 59348, 59351, 59865, 60660 }, ["description"] = "Now, let us see this next to my arm... Look! There many long feathers along the edges of the Larion's wing! And none on mine. This is why I can not fly! Hmm. It will take lots of flight feathers to give me wings. You help?", ["objectivesText"] = "Bring Kowalskos 100 Larion Flight Feathers . Progress: Feathers... So many feathers...", ["rewardGold"] = 289575, ["rewardXP"] = 6125, ["rewardItems"] = { 172089, 175791, 175792, 175967, 175968, 176812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59265] = { ["id"] = 59265, ["name"] = "Prying Eyes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "The Constructs would repurpose the carcass of our necropolis. But we will need its parts for our own ends. Let us deliver a warning to these scavengers. Slay the Constructs amid our wreckage. Pluck the eyes from their skulls. Such is our signature. They will know to fear the darkness once more.", ["objectivesText"] = "Collect 20 Betrayer's Eyes from constructs in Akarek's Tears. Progress: You offer gifts?", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 175795, 237812 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 158529, ["x"] = 0.498, ["y"] = 0.178 }, { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2005 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59293] = { ["id"] = 59293, ["name"] = "Special Formula", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59293 }, ["description"] = "You may think I'm naturally gassy, but it actually takes a lot of work to build it all up. This is all the result of a nice coating of Pox Nodules . Help me refresh my coating. Just get me near the absorbing pox and I'll pull the nodules right off his slimy skin.", ["objectivesText"] = "Help Gas Bag collect Pox nodules . Progress: Did you get what he needed?", ["rewardXP"] = 8165, ["rewardItems"] = { 175843, 182481, 182490, 182499, 182508, 183133, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159240, ["x"] = 0.542, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[59311] = { ["id"] = 59311, ["name"] = "How to Catch a Glimmerfly", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59311 }, ["series"] = { 59262, 59263, 59348, 59351, 59865, 60660 }, ["description"] = "Yes! Proper tools collected. Now to catch glimmerflies! Anima drought more severe in northern pools. Many Starving Glimmerflies, most eager to drink from our animyllis blooms . Place blooms, then while glimmerflies are drinking attach to filaments! Then return to me.", ["objectivesText"] = "Capture 5 Starving Glimmerflies in the Shimmering Pools, then return to Kowalskos . Progress: Glimmerflies will surely help me fly!", ["rewardGold"] = 464700, ["rewardXP"] = 8165, ["rewardItems"] = { 175791, 175792, 175967, 175968, 176812, 180839 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59314] = { ["id"] = 59314, ["name"] = "Sinfall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59315, 63215 }, ["description"] = "I knew you could be counted on. Revendreth's revival relies on forging pacts with those outside of our realm. The Prince never had any doubt that you would agree to join our cause. He summoned the Court of Harvesters in anticipation of your arrival. Renathal awaits you within Sinfall, where you will be presented to the court.", ["objectivesText"] = "Report to Prince Renathal in Sinfall.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 177635, 177636, 177637, 177638, 177639, 177641, 177642, 177643, 177644, 180909, 180910, 180911, 180912, 184320, 184326 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59315] = { ["id"] = 59315, ["name"] = "The Court of Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59314, 63215 }, ["description"] = "Partnerships such as ours will be key to Revendreth's revival. As Harvesters, we have the ability to extend our powers to mortals, though the decision must be unanimous. To that extent, the court has gathered and is awaiting your arrival. Let's not keep them waiting.", ["objectivesText"] = "Stand before the Court of Harvesters and pledge your loyalty. Progress: You will be welcomed by the court, I have no doubt, but first, you must swear an oath before the Harvesters.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 180648 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59316] = { ["id"] = 59316, ["name"] = "Binding Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59316 }, ["description"] = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.", ["objectivesText"] = "Complete the soulbinding ritual.", ["rewardGold"] = 262100, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59317] = { ["id"] = 59317, ["name"] = "Strengthening the Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59317 }, ["description"] = "Do you feel it, too? Our connection is stronger than I imagined could be possible. I have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. Sinfall needs our strength. Perhaps it is best we engage in this method now.", ["objectivesText"] = "Strengthen your bond with Nadjia.", ["rewardGold"] = 262100, ["rewardXP"] = 8165, ["rewardItems"] = { 180847, 181373, 181467, 181469, 181512, 181539, 181639, 181707, 181774, 181775, 181840, 181962, 182106, 182108, 182113, 182129, 182130, 182133, 182288, 182317, 182324, 182331, 182335, 182336, 182347, 182348, 182448, 182460, 182463, 182466, 182469, 182584, 182651, 182685, 182767, 182777, 182962, 182964, 183199, 183463, 183466, 183467, 183473, 183474, 183494, 183495, 183496, 183500, 199456, 199459, 199460 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59319] = { ["id"] = 59319, ["name"] = "Advancing Our Efforts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 59319 }, ["series"] = { 63064 }, ["description"] = "A venthyr's primary responsibility is ensuring that souls are unburdened of their pride, but they must see to other matters as well. We must act beyond the bounds of Revendreth to ensure that the souls of the Shadowlands keep to their fate. Allow me to demonstrate with a simple task for your companion here. This will be the first of many strikes.", ["objectivesText"] = "Inspect the Command Table and start an adventure. Progress: These calculated strikes will further our cause.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[59321] = { ["id"] = 59321, ["name"] = "Sacred Covenant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["description"] = "Our covenant is more than just pacts and promises. We have immense power, too. And that power we shall bestow upon you in a sacred ritual. Once complete, you will be able to call upon our gifts with ease.", ["objectivesText"] = "Meet Prince Renathal in the ritual hall on the lower level of the sanctum.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59322] = { ["id"] = 59322, ["name"] = "Shared Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59322 }, ["description"] = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. Doing so has no known drawbacks, but offers many advantages for both parties involved. The Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", ["objectivesText"] = "Meet The Accuser at the Forge of Bonds.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59323] = { ["id"] = 59323, ["name"] = "Anima Awakening", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62691, 62695, 62856, 62857 }, ["description"] = "This ritual will bestow upon you our gift. We will stir the anima within your soul, awakening a power that has only been known to Harvesters. It has never been performed on a mortal before, but I have been assured that it won't hurt a bit.", ["objectivesText"] = "Participate in the Harvesters's ritual. Progress: Take your place when you are ready to begin.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59325] = { ["id"] = 59325, ["name"] = "A Stalwart Ally", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 59325 }, ["description"] = "We have our work cut out for us, Maw Walker. The Harvesters will not relinquish their power without a fight. You will need stalwart allies at your side. Ones that know how battles are fought within the Shadowlands. Let me be your guide. Together, we will see Revendreth return to its true purpose.", ["objectivesText"] = "Complete the soulbind process with General Draven .", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[59339] = { ["id"] = 59339, ["name"] = "Enhanced Combat Tactics", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 59339, 59347, 59349 }, ["description"] = "Alaria says that the quilboar kidnapped the rest of the expedition... including my son. Chances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier. I need to make sure I'm not sending you to your death. We're going to have one last sparring session.", ["objectivesText"] = "Spar with Captain Garrick .", ["rewardGold"] = 565, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1080, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59342] = { ["id"] = 59342, ["name"] = "Taming the Wilds", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 59342, 59355, 59356, 60168 }, ["description"] = "As a hunter, you need a trustworthy beast at your side... or else these quilboar will slaughter you. When you're ready, I'll teach you how to tame such a beast. Then you must find one to be your loyal companion.", ["objectivesText"] = "Learn Tame Beast from Austin Huxworth , then use Tame Beast on any nearby wildlife. Progress: I'll teach you how to tame beasts. Then you'll need to choose any animals nearby to tame.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1076, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59343] = { ["id"] = 59343, ["name"] = "Kindred Spirits", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["description"] = "I have come to the realization that you and I are meant to be the most kindred of spirits. Your enduring nature has enraptured me, and I'm afraid I cannot bear to imagine an afterlife without your beguiling presence. Let us bind our souls, and forever carry each other in both heart and mind.", ["objectivesText"] = "Complete the soulbinding ritual.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59347] = { ["id"] = 59347, ["name"] = "A Monk's Focus", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59347, 59349, 85678 }, ["description"] = "You fought well against the harpies, but we all need to become stronger to face what lies ahead. The first step is to find a nice place to meditate and focus yourself. A monk is only as strong as they are focused. Come. I know of such a place.", ["objectivesText"] = "Follow Kee-La and meditate with her. Progress: Let us meditate. I find meditation always helps clear my mind.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 41, ["flags"] = 0 }, { ["id"] = 1080, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 14, ["flags"] = 0 } } },
[59348] = { ["id"] = 59348, ["name"] = "More Wings!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59348 }, ["series"] = { 59262, 59263, 59311, 59351, 59865, 60660 }, ["description"] = "Idea! Maybe I am too heavy. Maybe need more wings! Glimmerflies have lovely wings. With correct bait and strong rope, perhaps we can catch. Please bring Animyllis Blooms . Their nectar is delicious for glimmerflies, and makes them drowsy!", ["objectivesText"] = "Collect 10 Animyllis Blooms . Progress: Animyllis Bloom nectar is a glimmerfly's favorite sleepytime treat!", ["rewardGold"] = 348450, ["rewardXP"] = 6125, ["rewardItems"] = { 124640, 175791, 175792, 175967, 175968, 176812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59349] = { ["id"] = 59349, ["name"] = "One Last Spar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59347, 59349, 85678 }, ["description"] = "Let us have a quick sparring session before we return to camp, <name>. I want to see how this island has pushed you to grow.", ["objectivesText"] = "Spar with Kee-La .", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 42, ["flags"] = 0 }, { ["id"] = 1080, ["name"] = "Classical Learning", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 15, ["flags"] = 0 } } },
[59350] = { ["id"] = 59350, ["name"] = "A Druid's Form", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 4, 22 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59350, 85678 }, ["description"] = "Thank you for rescuing me, <name>. Allow me to aid you in your druidic studies. To escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same. Come with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", ["objectivesText"] = "Commune with the nearby druid stone. Progress: Come. The spirits of nature await us.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 43, ["flags"] = 0 }, { ["id"] = 1075, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 16, ["flags"] = 0 } } },
[59351] = { ["id"] = 59351, ["name"] = "Strings and Things", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59351 }, ["series"] = { 59262, 59263, 59311, 59348, 59865, 60660 }, ["description"] = "Glimmerflies are creatures of anima. Though they look delicate, they are quite strong! Filaments from etherwym tails are sturdy. They should help hold onto glimmerflies. Collect for me!", ["objectivesText"] = "Collect 10 Etherwyrm Filaments . Progress: Etherwyrm Filaments are almost pure anima. Very hard to break!", ["rewardGold"] = 348450, ["rewardXP"] = 6125, ["rewardItems"] = { 175791, 175792, 175967, 175968, 176812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59352] = { ["id"] = 59352, ["name"] = "A Mage's Knowledge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59352, 59354, 85678 }, ["description"] = "Ye got some good spells fer a novice mage. Ye might even be as good as I am one day! But ye don't know Polymorph ! How could ye not know that? Polymorph 's one of a mage's most useful spells. I can teach it tae ye, if ye can find me spellbook. Last I saw, the ogres threw me book in the lake. The LAKE! Go get me book, and I'll show ye how tae cast Polymorph .", ["objectivesText"] = "Recover Meredy Huntswell 's book at the bottom of the nearby lake. Progress: I hope me book isn't too damaged after sittin' at the bottom o' the lake.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 175975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 44, ["flags"] = 0 }, { ["id"] = 1081, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 17, ["flags"] = 0 } } },
[59354] = { ["id"] = 59354, ["name"] = "The Best Way to Use Sheep", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59352, 59354, 85678 }, ["description"] = "I'm not gonna send ye off without showin' ye how tae properly use this spell. Ye wanna cast Polymorph if ye get yerself into a situation when two foes are fightin' ye at once. Cole and I will spar with ye a bit tae make sure ye know what tae do.", ["objectivesText"] = "Practice using Polymorph against Meredy and Private Cole . Progress: And don't ye worry, recruit. Ye won't be turnin' anyone into a sheep permanently!", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 45, ["flags"] = 0 }, { ["id"] = 1081, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 20, ["flags"] = 0 } } },
[59355] = { ["id"] = 59355, ["name"] = "A Hunter's Trap", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59355, 59356, 60168, 85678 }, ["description"] = "By now, most hunters would have been trained in the art of trapping. Allow me to get you up to speed. We'll start with a freezing trap . In order to make one, you'll have to forage materials from your surroundings. Meredy can provide you with a mote of ice. Scavenge the area for the rest of what is required. And don't delay. You will need that freezing trap to deal with a problem that has cropped up within the camp.", ["objectivesText"] = "Scavenge parts in the area to create a Freezing Trap . Progress: Did you get the supplies needed? Meredy should have the ice mote , while the other two should be nearby.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 175979, 175980, 175981 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 46, ["flags"] = 0 }, { ["id"] = 1076, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 19, ["flags"] = 0 } } },
[59356] = { ["id"] = 59356, ["name"] = "Hunting the Stalker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59355, 59356, 60168, 85678 }, ["description"] = "Now that you have your trap, there's a problem we need to deal with. A wild beast has been stalking our camp. It's already stolen some of our food. We have little enough as it is. You and I will work together. Set your freezing trap and lure out whatever this creature is. Once it is caught, I will determine if the beast can be tamed... or if it needs to be put down.", ["objectivesText"] = "Use your Freezing Trap within the Ogre Ruins to lure out the beast stalking the camp. Progress: Use the Freezing Trap anywhere within the Ogre Ruins. Just don't do it right within the camp.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 47, ["flags"] = 0 }, { ["id"] = 1076, ["name"] = "Classical Learning", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 22, ["flags"] = 0 } } },
[59426] = { ["id"] = 59426, ["name"] = "Your Personal Assistant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59198, 59199, 59200, 60005, 60006 }, ["description"] = "Here in Hero's Rest, we have a beacon that is the fastest way to draw the Polemarch's attention. It has been quite some time since we have used it, and I am afraid that it has fallen into disrepair. I authorize you to receive a steward companion during your stay here in Bastion . I will call for some to convene here. You may select one to aid you.", ["objectivesText"] = "Select a steward to aid you, then return to Kalisthene . Progress: Stewards are the force that keep Bastion running.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 177278 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165045, ["x"] = 0.528, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165045, ["x"] = 0.528, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59427] = { ["id"] = 59427, ["name"] = "We Need More Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Laurent's plan is a bit ambitious. Mirrors are most reliable when used to traverse short distances. Traveling to the sanctuary will require a great deal of power, more than he or I have. The shrouded have stores of anima in their compound. With enough of it, the mirror should be stable enough to get us where we need to go.", ["objectivesText"] = "Collect anima from around The Shrouded Asylum. Progress: Long distance travel requires a great deal of power.", ["rewardGold"] = 382590, ["rewardXP"] = 1415, ["rewardItems"] = { 129759, 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59430] = { ["id"] = 59430, ["name"] = "A Plague on Your House", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "Though the physical House of Plagues is lost, the knowledge contained within was not. There are survivors here that continue to research and develop new horrifying weapons. In time we will restore the house and rise to even greater power, unleashing creations and plagues never before seen upon our enemies! Perhaps you can help? Speak with survivors and see if any of them can use your aid.", ["objectivesText"] = "Speak with House of Plagues survivors. Progress: Have you spoken to anyone?", ["rewardGold"] = 393150, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165049, ["x"] = 0.58, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59441] = { ["id"] = 59441, ["name"] = "Soulsmith Yol-Mattar", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 59441 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2VignetteID"] = 4132, ["db2VignetteName"] = "Soulsmith Yol-Mattar" },
[59520] = { ["id"] = 59520, ["name"] = "Plaguefall: Knee Deep In It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "There are many in the House of Plagues who survived its destruction only to later fall victim to the plagues released in the explosion. Margrave Stradama herself was driven mad from a mixture of twelve different airborne poxes! These dangers still remain and spread out from the ruins, infecting new victims daily. I need you to travel into the ruins and recover samples from the victims there.", ["objectivesText"] = "Enter Plaguefall and recover 12 Poxedskin Samples and Margrave Stradama's Plasm . Progress: Have you brought me the Poxedskin Samples ?", ["rewardGold"] = 1158300, ["rewardXP"] = 2125, ["rewardItems"] = { 175531, 175532, 175533, 175534, 176057, 183724 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165052, ["x"] = 0.594, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165052, ["x"] = 0.594, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59554] = { ["id"] = 59554, ["name"] = "A Fine Journey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59554 }, ["description"] = "Aspirants new and ancient, take note! The heralded Agthia's Repose calls. Make the ceremonial journey and learn about the ancient fallen Paragon who saved this very realm! Find the Repose just a short ride southwest of Hero's Rest.", ["objectivesText"] = "Speak to Keeper Mnemis in Agthia's Repose.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59555] = { ["id"] = 59555, ["name"] = "Enemy at the Door", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "The remaining houses of Maldraxxus have joined forces against us. Their armies besiege the Seat of the Primus, and our defenses cannot hold forever. Our reserves have met the enemy in battle. I need you to break the siege. Report to Heirmir and Marileth. They will give you the means to rain destruction on our foes.", ["objectivesText"] = "Ride Ragewing and destroy the enemy forces.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182077 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59556] = { ["id"] = 59556, ["name"] = "Welcome To Our House", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["description"] = "Your ties to the other covenants had me doubting you would return. I see now that was foolish of me. Outsider or not, you have stood bravely beside the armies of Maldraxxus. I am confident the Primus would have welcomed you into our ranks with pride. One day, he might return as well. But we cannot afford to wait. In the Primus's absence, I will name you a Necrolord of Maldraxxus.", ["objectivesText"] = "Speak with Baroness Draka to be inducted as a Necrolord in the Maldraxxus covenant hall. Progress: There is no greater honor than to defend the Shadowlands as a Necrolord of Maldraxxus.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } } },
