[59583] = { ["id"] = 59583, ["name"] = "Welcome to Stormwind", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["series"] = { 58908 }, ["description"] = "Now that we are back in Stormwind, I need to deliver my mission report to King Wrynn. In the meantime, I've asked Lindie to accompany you around the city. There's a lot to see and do in Stormwind, so feel free to explore at your leisure. I'll send for you once I've delivered my report to the king.", ["objectivesText"] = "Meet with Lindie Springstock at the city gate.", ["rewardGold"] = 510, ["rewardXP"] = 505, ["rewardItems"] = { 168100, 178120, 248336, 256330 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154169, ["x"] = 0.738, ["y"] = 0.914 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163095, ["x"] = 0.713818, ["y"] = 0.739636 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.914 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 54, ["flags"] = 0 } } },
