[59609] = { ["id"] = 59609, ["name"] = "No Rest For the Dead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Excellent work, my apprentice! You have completed your training and are now a true Necrolord. That also means you've taken on additional responsibilities. Such is the burden of genius! I believe Baroness Draka wanted to have a word with you.", ["objectivesText"] = "Report to Baroness Draka .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 43832, 43833, 43834, 43835, 182254, 182263, 182272, 182281 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59615] = { ["id"] = 59615, ["name"] = "Every Dog Has Its Day", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59615 }, ["description"] = "Maw Walker, when I heard you were building constructs and a home for souls still loyal to Maldraxxus, I began my search for you! I am loyal and have always wanted a construct form, but the Margrave was unwilling to build one that suited my natural inclinations. I lived my whole life with the curse, it's all I know, and it's all I still want. Would you build a construct for me?", ["objectivesText"] = "Take specifications for Neena 's construct. Progress: Are you willing to do this?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 178061, 182075, 184354 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162151, ["x"] = 0.694, ["y"] = 0.406667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.406667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[59616] = { ["id"] = 59616, ["name"] = "Army of One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Mevix will lead the attack, but you will finish it. There are no reinforcements, no cavalry. Only you and your runeblade. Show me the might you wield, outsider. Lay siege to the House of Constructs and bring them to ruin!", ["objectivesText"] = "Meet Secutor Mevix near the House of Constructs.", ["rewardGold"] = 121680, ["rewardXP"] = 710, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 169462, ["x"] = 0.396, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59617] = { ["id"] = 59617, ["name"] = "Stone Fiend Saboteurs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1525, ["storyline"] = { 59617 }, ["objectivesText"] = "Stolen Missives delivered House Redelav House Sourwine House Darkvein House Duskmire House Primrose House Sinfang House Iremoore", ["rewardXP"] = 8165, ["rewardItems"] = { 176582 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Stolen Missives delivered", ["amount"] = 7, ["type"] = 0, ["objectID"] = 165372, ["orderIndex"] = 0 }, { ["text"] = "House Redelav", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165377, ["orderIndex"] = 1 }, { ["text"] = "House Sourwine", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165386, ["orderIndex"] = 2 }, { ["text"] = "House Darkvein", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165387, ["orderIndex"] = 3 }, { ["text"] = "House Duskmire", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165389, ["orderIndex"] = 4 }, { ["text"] = "House Primrose", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165390, ["orderIndex"] = 5 }, { ["text"] = "House Sinfang", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165391, ["orderIndex"] = 6 }, { ["text"] = "House Iremoore", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165392, ["orderIndex"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59621] = { ["id"] = 59621, ["name"] = "Breaking a Few Eggs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "As you can see, we have a gorm problem. I'm not sure what has them so riled up. They've been getting bigger, more hostile. It must be due to the anima drought. If nothing stops them, they'll eat everything! Their egg production is out of control. We can't let their population grow any larger. Please, go in to their nests and destroy as many of their eggs as you can find.", ["objectivesText"] = "Destroy 10 Gorm Eggs in the Banks of Life.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59622] = { ["id"] = 59622, ["name"] = "Tending to the Tenders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "The eggs are a problem, but so are the gorm that take care of them. The egg-tenders are the leaders of the hive when no matriarch is present. If left unchecked, they will simply produce more eggs and we will be right back where we started. Or worse, one of them could turn into a queen. They are simply too large and hostile for us to properly contain. I see no other recourse than to put them down.", ["objectivesText"] = "Slay Egg-Tenders Tiom, Bloome and Erys.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59623] = { ["id"] = 59623, ["name"] = "What a Buzzkill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57652, 57655, 59623 }, ["description"] = "What do you say? Fancy one more hunt? One of those little flying pests has grown into a very large flying pest. Large, pristine gorm parts are hard to find in the best of times, and a smith always appreciates a challenge. <Cavina's voice drops as he leans in towards you.> Besides, I'm worried about the safety of my family and the rest of us in the grove. Bring me the stinger from that big fella and I'll make it worth your while. Do we have a deal?", ["objectivesText"] = "Deliver Buzzkill's Stinger to Gormsmith Cavina . Progress: I must say, I am looking forward to the opportunity to working with such a fine specimen.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 176760, 178021, 178022, 178023, 178024, 178025, 178027, 178030, 180473, 180474 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1167, ["name"] = "Supplies Needed", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59625] = { ["id"] = 59625, ["name"] = "The Only Cure", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "Maldraxxus is on the path to reclaiming its rightful role as defender of the Shadowlands. But the treasonous attack on Bastion remains a stain on our honor. We had thought Gharmal's forces routed, but we've received word from the Paragon of Courage that reinforcements have begun arriving at her temple. This threat must be eliminated. I have volunteered to spearhead this operation. Your support would be an asset, $p.", ["objectivesText"] = "Meet with the Paragon of Courage in Bastion.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59641] = { ["id"] = 59641, ["name"] = "The Nation of Kul Tiras", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47181, 47186, 47189, 47485, 47486, 47487, 47488, 47489, 47960, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49401, 49404, 49405, 49736, 49737, 49738, 49740, 49741, 49869, 50110, 50531, 50573, 50787, 50788, 50789, 50790, 50795, 50972, 51341, 52128, 52431, 52750, 52787, 53041, 59641 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 57766, 58983, 60362 }, ["description"] = "Kul Tiras is the greatest naval power on Azeroth, and a former member of the Alliance. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was killed at Theramore. Many have said that Jaina believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father on that day. Perhaps she feels it is time to put the past to rest. Loathe as I am to put Jaina at risk... Kul Tiras must rejoin the Alliance. Light be with you.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", ["rewardGold"] = 128700, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 165395, ["x"] = 0.856, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 120922, ["x"] = 0.655, ["y"] = 0.507 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 46, ["flags"] = 0 } } },
[59642] = { ["id"] = 59642, ["name"] = "Pulling Hairs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 59642 }, ["description"] = "The abominations are well organized and well supplied. We've not been able to gain any ground. A little disorganization in their supplies and reinforcements might give us an edge. I need you to work you way behind their lines and eliminate three abominations handling their supplies.", ["objectivesText"] = "Eliminate Strategist Orco, Lobber Jalrax, and Munitioner Vizic", ["rewardXP"] = 8165, ["rewardItems"] = { 176846, 176847 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Stringy Growth plucked", ["amount"] = 8, ["type"] = 0, ["objectID"] = 175434, ["orderIndex"] = 0 }, { ["text"] = "Corpselouse Bristles collected", ["amount"] = 8, ["type"] = 1, ["objectID"] = 176846, ["orderIndex"] = 1 }, { ["text"] = "Sour Suckle's Antenna collected", ["amount"] = 1, ["type"] = 1, ["objectID"] = 176847, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59643] = { ["id"] = 59643, ["name"] = "It's Race Day in the Ramparts!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59643 }, ["objectivesText"] = "Speak to Grand Marshal Mudrag Win the Wheelbarrow Race", ["rewardXP"] = 8165, ["rewardItems"] = { 177239, 181222, 183989, 208825 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Speak to Grand Marshal Mudrag", ["amount"] = 1, ["type"] = 3, ["objectID"] = 165419, ["orderIndex"] = 0 }, { ["text"] = "Win the Wheelbarrow Race", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165475, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59644] = { ["id"] = 59644, ["name"] = "Blinded By The Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58086, 59644 }, ["series"] = { 57876, 57877, 57878, 58086 }, ["description"] = "$p, Sire Denathrius must be stopped. The anima he is stealing from the Shadowlands is weakening the bonds that seal the Jailer within the Maw. That must not happen. Time is short so we must strike quickly. I would like for you to head up to the surface, into that accursed Light, and align as many mirrors as you can find to the focusing mirror atop the portcullis. We will shine a light on Castle Nathria so bright no venthyr will wish to step forth from that fortress to challenge us.", ["objectivesText"] = "Use the mirrors atop Sinfall to seal the gates of Castle Nathria. Progress: Hopefully you did not get too scorched out there.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172673, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1038, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1038, ["questLineOrder"] = 31 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1038, ["questLineOrder"] = 31 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1038, ["name"] = "The Master of Lies", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59645] = { ["id"] = 59645, ["name"] = "Death Rains", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "With its repeated invasions here, the House of Constructs continues to sully the honor of Maldraxxus . We cannot salvage that honor until justice is done. May we mete it so thoroughly that none will ever attempt this desecration again. Eliminate these traitors with me, $p. Leave none standing.", ["objectivesText"] = "Slay 30 enemy forces. Progress: See justice done.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59648] = { ["id"] = 59648, ["name"] = "Peace by Piece", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "These Maldraxxi fiends have reoccupied my temple. They have entrenched this resurgence with shields powered by necromancy. My disciples--the ones who were not captured and executed by your treacherous compatriots--report the core of a necrotic bulwark to the south. We cannot counter their forces until the shield is brought down. See it done. I will not tolerate your presence otherwise.", ["objectivesText"] = "Disable the Necrotic Bulwark in the South. Progress: Do not keep me waiting.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59650] = { ["id"] = 59650, ["name"] = "No Hesitation, No Surrender", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "I cannot fathom where the constructs acquired these reinforcements, but we are once again outnumbered. I seethe at the thought of my fallen disciples. You will make this right. The renegades have established a foothold in the northern region of the temple. Their necrotic magic has granted them a shield, defending them from ranged assault. Disable it. Let nothing impede you. This is the way of Courage.", ["objectivesText"] = "Disable the Northern Bulwark.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59653] = { ["id"] = 59653, ["name"] = "Don't Cross Courage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "We have rendered the enemy holdouts defenseless. My disciples will begin preparations to purge the corruption that your errant kind have left on our home. But more still remain in the inner sanctum of the temple. Their defenses prevent us from flying in en masse, but I can secure a foothold myself. We will cross the breach and annihilate them.", ["objectivesText"] = "Cross the breach with Xandria . Progress: We shall not waste time.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59656] = { ["id"] = 59656, ["name"] = "Well, Tell the Lady", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "<Thorodir breathes a deep sigh of relief.> That's that, I'd say. The Banks are largely safe now, thanks to you. We can handle the rest of the cleanup on our own now. The Lady of the Falls will want to hear of your success here. Why not go tell her the good news?", ["objectivesText"] = "Report to the Lady of the Falls in Glitterfall Basin.", ["rewardGold"] = 28600, ["rewardXP"] = 175, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59658] = { ["id"] = 59658, ["name"] = "Express Dominance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59658 }, ["objectivesText"] = "Conquer Beasts or Slay Enemies", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "pvp", ["db2Objectives"] = { { ["text"] = "Conquer Beasts or Slay Enemies", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[59659] = { ["id"] = 59659, ["name"] = "Aerial Absolution", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "My kyrian would have attempted to retaliate by now, but these vile interlopers are a devious sort. Their necromancers pollute the air, tainting it with foul power that corrodes our very wings. I cannot advance an assault until they are eradicated. Deal with these befoulers, and I will deliver retribution to the rest.", ["objectivesText"] = "Slay the three befoulers.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59660] = { ["id"] = 59660, ["name"] = "A New Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59660, 59661, 61616, 61704, 61705, 61706, 61880, 61882, 61884 }, ["series"] = { 63065 }, ["description"] = "My dear $p, I have heard a delightful rumor that you are considering hosting a new court in Sinfall. If that is true, you simply must permit me to recommend staff to help you host a perfect court. < Theotar pulls long parchments out of his pockets.> I have been developing ranked lists for every court staff position since the moment I stepped foot in Sinfall. I do not wish to be a braggart, but courts are kind of my specialty.", ["objectivesText"] = "Recruit the personnel needed to open the Ember Court.", ["rewardGold"] = 84900, ["rewardXP"] = 4085, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1196, ["name"] = "The Ember Court", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59661] = { ["id"] = 59661, ["name"] = "Ember Court Rehearsal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59660, 59661, 61616, 61704, 61705, 61706, 61880, 61882, 61884 }, ["description"] = "Look, $p. Venthyr have been throwing fancy courts for themselves ever since they were created. It won't always be easy to impress them with our own court. Don't worry, I've got a plan. I've scheduled a rehearsal court for us to learn the ropes during a practice run. You, me, Renathal, and a few socialites from the covenant who are eager to help us succeed. Relax. It'll be fun!", ["objectivesText"] = "Help Temel host the rehearsal for the Ember Court.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1196, ["name"] = "The Ember Court", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59674] = { ["id"] = 59674, ["name"] = "A Friendly Rivalry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59674 }, ["description"] = "Ah, a fresh soul! Your perspective may prove useful to us. Nemea and I have opposing viewpoints. She lauds her larion, creatures native to Bastion whom she raises and trains as her companions. However, I find that phalynx are the superior beings. They are efficient, obedient, and easy to work with. Please, come learn both of our ways. Perhaps you can decide which of our ways of life is superior.", ["objectivesText"] = "Meet with Pelodis at Forgefire Outpost or Nemea at Nemea 's Retreat.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 }, { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59676] = { ["id"] = 59676, ["name"] = "Harvester of Desire", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59706 }, ["description"] = "So, here's the sketch: we muck you up to look like one of the servants. This stuff is protected by anti-theft so if 'em clothes think they are being stolen they teleport back here, you an' all. You \"should\" be able to reach the Countess with your message. Just smile, nod, do as you're told, don't talk to anyone, and don't make eye contact with anything that's got wings. They'll know you shouldn't be there.", ["objectivesText"] = "Infiltrate the Eternal Terrace and deliver Prince Renathal 's message to the Countess . Progress: Still got your head at least. They often try to take that first if they are mad at ya.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 109076 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165658, ["x"] = 0.525, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59678] = { ["id"] = 59678, ["name"] = "Sustain, In Vain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "These turncoats have kept busy. They've opened more portals around the area, allowing themselves to replenish their numbers with little trouble. Even with her might, the Paragon cannot eliminate an endless army. Let us destroy these portals. Without reinforcements to sustain this contingent, it will surely fall.", ["objectivesText"] = "Disable 6 Necrotic Portals . Progress: The time for mercy is behind us.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59680] = { ["id"] = 59680, ["name"] = "Vesiphone's Vicious Vesper", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59680 }, ["objectivesText"] = "Empower the Purity Chime Coalesced Fury in Purity's Pinnacle slain", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Empower the Purity Chime", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Coalesced Fury in Purity's Pinnacle slain", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165720, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59698] = { ["id"] = 59698, ["name"] = "Wipe the Slate Clean", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["series"] = { 59700, 59709 }, ["description"] = "At last, the skies belong to us once more... and in those skies, the storm of our vengeance brews. Come, you who claim to be true Maldraxxi. You wish to right the wrongs of those you once called allies? Rain your justice upon them! Show no quarter!", ["objectivesText"] = "Fly with Xandria and slay Maldraxxi.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59700] = { ["id"] = 59700, ["name"] = "The Last Labor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["series"] = { 59698, 59709 }, ["description"] = "The evil that threatens Bastion crumbles beneath us. But if we allow this cruel baroness to evade justice, we have not won this day. She cowers in the necropolis above, casting her shadow on this once sacred temple. We will pull the dagger from our backs. This wound will heal.", ["objectivesText"] = "Slay Baroness Antolyte . Progress: This is all that remains.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 182253, 182262, 182271, 182280 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165752, ["x"] = 0.296, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59701] = { ["id"] = 59701, ["name"] = "Common Ground", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["description"] = "Now that we have a stronghold from which to operate, we need to begin the next stage of my plan to wrest control of Revendreth from the Master. We must convince the Court of Harvesters to convene. We must not have them come here, though. It would be suicide. Go to my old fortress, Darkwall Tower, and place these banners at the four most distant points of the tower. This will ensure the power of the Harvesters and the Master will not be able to interfere with a neutral meeting.", ["objectivesText"] = "Place four of Renathal's Banners at Darkwall Tower.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59703] = { ["id"] = 59703, ["name"] = "Abombing Run", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59703 }, ["objectivesText"] = "Speak with Kynthia House of Construct forces slain Anima Conduit destroyed", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Speak with Kynthia", ["amount"] = 1, ["type"] = 0, ["objectID"] = 160952, ["orderIndex"] = 0 }, { ["text"] = "House of Construct forces slain", ["amount"] = 50, ["type"] = 0, ["objectID"] = 160927, ["orderIndex"] = 1 }, { ["text"] = "Anima Conduit destroyed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 165684, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
