[59719] = { ["id"] = 59719, ["name"] = "The Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59707, 59708, 59711, 59720 }, ["description"] = "Well, we have quorum. You have done all you can do for us at this stage, Maw Walker. It falls to me, now, to convince these ancient fools to forsake the greatest patron in all of their reality and throw their lot in with me, a failed rebel with a \"new\" plan. Let us see if I can still sway a crowd, as it were. Wish me luck.", ["objectivesText"] = "Witness the Court of Harvesters gathering.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 53283, 53294, 53297, 57492, 57493, 123890, 131386, 133671, 133672, 133673, 133674, 140421, 140500, 152102, 157825, 166518, 172089, 176126, 176127, 176128, 176130, 176131, 176132, 176134, 176135, 176136, 176138, 176139, 176140, 176850, 179584, 180648, 180928, 180929, 180930, 180931, 181521, 181524, 181536, 181537, 182342, 182343, 184379, 211279, 226357, 232768, 232773, 232782, 232786, 237812, 238987, 246813, 246815, 246936, 248247, 249400, 249787, 251821, 254267, 254579, 263433, 266429, 266430, 266431, 266432 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59720] = { ["id"] = 59720, ["name"] = "Harvester of Wrath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59707, 59708, 59711, 59719 }, ["description"] = "We walk in the winged shadows of my brothers and sisters in arms, Stoneborn I have trained since they were first carved from stone. This is an ancient rite. If we cross this bridge on foot, defeating any who would dare stop us, we may have an audience with the mother of the stoneborn. However, know that our safe return is not guaranteed, so try not to offend her. I do not look forward to this.", ["objectivesText"] = "Cross the Bridge of Defiance on foot.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165865, ["x"] = 0.402, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59721] = { ["id"] = 59721, ["name"] = "Becoming the Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "< Reldorn grins at you.> He knew you'd be back! The Horned Hunter went on ahead to prepare the hunting ground. He said you should join him as soon as you can. Now that you have the materials for the trap, you just need to reach him... It's dangerous territory to traverse, but I've been devising a glamour that should help you avoid the attention of the roaming beasts. Maybe if it's useful, you could put in a good word for... Ahem. Anyway, we should focus on your quarry. Good hunting, friend.", ["objectivesText"] = "Find Huln Highmountain within the Elder Stand.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59722] = { ["id"] = 59722, ["name"] = "Grand Theft Necropolis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["description"] = "The necropolis is safe and secure, but we can only maintain a portal to the Seat of the Primus for a short time. Khaliiq will return with you and work on establishing a permanent portal connection.", ["objectivesText"] = "Use the portal to meet Khaliiq in the Seat of the Primus.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164679, ["x"] = 0.463161, ["y"] = 0.443177 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.463161, ["y"] = 0.443177 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59724] = { ["id"] = 59724, ["name"] = "The Field of Honor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "Thanks to you, <name>, I am free of Matyas's control for the first time in ... well, a very long time. Now, together, we will seek my vengeance. I've laid a solemn duty upon you by naming you as my second for this duel. I know not the code in your homelands but in mine, it is your task to secure the field. Matyas and his followers are garrisoned at Witherfall Ruin nearby. Unless I miss my guess, that's where he will have run. I will prepare for the battle and join you soon.", ["objectivesText"] = "Clear Taskmaster Matyas's followers from Witherfall Ruins.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 166616, ["x"] = 0.601, ["y"] = 0.791 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59725] = { ["id"] = 59725, ["name"] = "Archivist on the Edge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "If the curse isn't removed, Qadarin will waste away until nothing is left! We used to bind and seal curses just like this all the time, but we haven't had to deal with one in ages. Go to Archivist Dreyden at the Grove of Memory. He will know which curse this is and can give you its scroll. Bring it back so we can figure out what we need in order to cast a counter-curse. Hurry, <name>!", ["objectivesText"] = "Speak with Archivist Dreyden at the Grove of Memory.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59726] = { ["id"] = 59726, ["name"] = "It's a Trap", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "At last, I will have my vengeance! I am certain Matyas will flee again if he sees me first so you will need to confront him on my behalf, friend. Then, while he's distracted, I will engage him. At that point, your obligation as my second is a formality. You must assure Matyas does not dishonor the duel and cheat. When he inevitably does, I expect you'll help me defeat him. He's just through the portcullis there.", ["objectivesText"] = "Approach Matyas to start the duel. Assist Nadjia when Matyas cheats. Progress: Matyas will apologize, or he will die.", ["rewardGold"] = 567720, ["rewardXP"] = 1770, ["rewardItems"] = { 177640, 177713, 177714, 177765, 177881, 178053, 178054, 178055, 178056, 178057, 178058, 178059, 178060, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 166616, ["x"] = 0.601, ["y"] = 0.791 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 166616, ["x"] = 0.601, ["y"] = 0.791 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.601, ["y"] = 0.791 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59731] = { ["id"] = 59731, ["name"] = "An Expected Guest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "While we await word from Huln, another matter of importance has arisen. Bwonsamdi has returned to Ardenweald. Lord Herne believes he is here to request an audience with the Winter Queen. The loa of death, however, pursues a different purpose. One that I have glimpsed in my dreams. Meet with Bwonsamdi . Discover what fate has in store for the both of you.", ["objectivesText"] = "Meet Bwonsamdi in the Heart of the Forest within Ardenweald.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165951, ["x"] = 0.482, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59732] = { ["id"] = 59732, ["name"] = "Something Extra for the Winter Queen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Ya did good wit' how ya handled Mueh'zala. Me be wantin' ta return da favor. We be friends, after all... riiiight? Dat nasty loa be at me mercy now. Him been mutterin' about some tings he stole from ya Winter Queen. Come along ta me Necropolis. Ya can see what Ol' Bwonsamdi be talkin' about for yaself. Ya gonna come back with someting nice for her majesty... reeeeeal nice.", ["objectivesText"] = "Travel with Bwonsamdi to the Necropolis in Nazmir.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165951, ["x"] = 0.482, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 863, 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59739] = { ["id"] = 59739, ["name"] = "The Problem with Containing a Death Loa", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Me know Mueh'zala still be hidin' someting. Ol' Bwonsamdi gonna find out what dat be. But dis old loa's presence be drawin' all da undead in Nazmir ta me doorstep! Me be needin' some time ta get Mueh'zala talkin'. Dere be a troll, Zel'han, leadin' da undead. Kill him and show Mueh'zala him broken armor. Dat should end any hope he be havin' of escapin'.", ["objectivesText"] = "Kill Zel'han the Betrayer and recover his armor. Progress: Zel'han be marchin' in here wit ya head. Me gonna enjoy seein' ya soul tortured in da Maw.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 180787 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 166018, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59740] = { ["id"] = 59740, ["name"] = "Repair and Restore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 59740 }, ["description"] = "You've already attuned several mirrors without incident. I do believe it's time you try your hand at repairing them instead. It's quite easy once you've found the fragments, but there are a few things of note to keep in mind. Repaired mirrors are fragile and unpredictable. They often break with a single use, and it's never a guarantee that using one will translocate you somewhere safe. Here's a few shards to get you started. Restore the mirror to working order and see where it leads.", ["objectivesText"] = "Repair the Broken Mirror and reap the rewards. Progress: I have complete faith in your abilities.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 181363, 182112 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[59741] = { ["id"] = 59741, ["name"] = "Dark Mojo for a Dark Loa", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "How many times must de Necropolis come under attack? I suppose no one ever said worshipping Bwonsamdi would be easy... Bwonsamdi seeks to force Mueh'zala into revealing his secrets, and I must do my part to help. De undead swarming de Necropolis are animated by Mueh'zala's dark mojo . Bwonsamdi needs some of dat mojo to finish his ritual. Strike down de undead and claim it.", ["objectivesText"] = "Recover 100 Dark Mojo from undead attacking the Necropolis. Progress: You got me dat mojo? I be usin' it ta control Mueh'zala durin' me ritual.", ["rewardGold"] = 289300, ["rewardXP"] = 8165, ["rewardItems"] = { 177818 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 165968, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59742] = { ["id"] = 59742, ["name"] = "Delaying the Other Side", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Many of Bwonsamdi 's worshippers did not make it inside when de undead began swarming de Necropolis. We need a few more of dem to complete Bwonsamdi 's ritual to uncover Mueh'zala's plans. Take dis powder and throw it on de worshippers who are stuck outside. It should dispel de dark magic dat afflicts dem. As for de ones who are already dead... dey will serve Bwonsamdi beyond de grave. Dat is all we could ever ask for.", ["objectivesText"] = "Use Strange Powder on 6 Injured Bwonsamdi Worshippers .", ["rewardGold"] = 286500, ["rewardXP"] = 8165, ["rewardItems"] = { 1607, 122363, 177817 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 165968, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59743] = { ["id"] = 59743, ["name"] = "The Spider on the Wall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59743 }, ["objectivesText"] = "Speak with Khaliiq", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 177693, 177710, 177712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Speak with Khaliiq", ["amount"] = 1, ["type"] = 3, ["objectID"] = 165966, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59747] = { ["id"] = 59747, ["name"] = "A Lost Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59747 }, ["description"] = "Many of us struggled to free ourselves when Gharmal imprisoned our souls here, but none more than Bacilia. She was a great champion, but the confinement drove her mad and darkness consumed her soul. Though we tried to reason with her over the course of eons, it is clear that there is no coming back for her. Please end her misery.", ["objectivesText"] = "Bacilia the Lost slain. Progress: Have you completed this task?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59748] = { ["id"] = 59748, ["name"] = "No Peace In Death", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "<name>. I have a favor to ask, if I may. This realm... The sense of honor and purpose that guides its denizens calls to me. My life was defined by such values. Maldraxxus , for a time, shared them with me... But I returned from the Maw to a land rife with treachery. I'd like to speak with the Paragon about Bastion.", ["objectivesText"] = "Talk to the Paragon of Courage with Alexandros.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165795, ["x"] = 0.448667, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59749] = { ["id"] = 59749, ["name"] = "One Little Whisper", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Here be da deal, <name>. To get Mueh'zala talkin', we gotta feed him a teeny bit a da life essence of everybody in dis room. Why ya be lookin' at me like dat? When has ol' Bwonsamdi ever let ya down? Me gonna use da mojo ya got to pull da truth outta him while he be feedin'. Oh, uh, just two more tings. First, I need ya to be ringin' an invitation to a special... friend. Den I be giving ya more of me mojo powder. Use it during da ritual if any o' me followers be gettin' too weak.", ["objectivesText"] = "Ring the gong to summon the special guest, then use mojo powder in the ritual to fuel Mueh'zala. Progress: I be eager to hear what ol' Mueh'zala be have ta say...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 177817, 179620, 179623, 179773, 181877 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59750] = { ["id"] = 59750, ["name"] = "How to Get a Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "An eager rookie who wants to be champion of the arena? People love a story like yours, but the first step is to get you noticed. Here's the plan. Marcel Mullby needs bloodtusk skulls , but it takes a real fighter to get those! You go kill some bloodtusks, use my knife to collect their heads, and deliver them to Mullby. That should get you recognition.", ["objectivesText"] = "Collect 12 Bloodtusk Skulls and deliver them to Marcel Mullby . Progress: You deliver those skulls?", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59751] = { ["id"] = 59751, ["name"] = "Through the Shattered Sky", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "When Sylvanas shattered the Helm of Domination, she was touched by the power it released. I can sense the echoes of that power, and I know where she has gone. If you wish to rescue your leaders, the shattered helm can open a path. It cannot bring you back, however. That you must do on your own. The risk is great, <name>, but there is no other way. We will begin the ritual at once.", ["objectivesText"] = "Complete the ritual at the Frozen Throne to open the rift into the Maw.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59752] = { ["id"] = 59752, ["name"] = "A Fractured Blade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "The chaotic energies of this place have scattered the Ebon Blade. I don't think Azeroth's blessings will reach you here, <class>. We will need allies if we are to survive this place. We should find them quickly, before they are overcome.", ["objectivesText"] = "Rally 10 Knights of the Ebon Blade in the Crucible of the Damned. Progress: We have no time for chatter. Let's find those knights!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59753] = { ["id"] = 59753, ["name"] = "Ruiner's End", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "One of the... larger fiends... has several of our knights engaged... Hurry to their aid... lest we lose more of our dwindling forces. Go... it is too late for me...", ["objectivesText"] = "Defeat Ruiner Maroth in the Crucible of the Damned. Progress: Our allies fall as you stand idle.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59754] = { ["id"] = 59754, ["name"] = "On Blackened Wings", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "It's a relief to see friendly faces again. But we have little time for pleasantries. Thrall is wounded, and we are being hunted by the denizens of this realm. We must seek shelter at once. Come, I believe I know of a place.", ["objectivesText"] = "Assist Jaina in escaping the Mawsworn in Calcis. Progress: What are you doing? This is no time for talk!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59755] = { ["id"] = 59755, ["name"] = "A Flight from Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "There's a cave not far from here. If we hurry, we can seek refuge. Those fiends will give chase if they spot us. Be prepared for a fight!", ["objectivesText"] = "Escort the assembled forces from Calcis to Forlorn Respite. Progress: This way!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59756] = { ["id"] = 59756, ["name"] = "A Moment's Respite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "Anduin insisted that our allies would come for us. I confess I had begun to doubt him. I'm sure you have many questions. I'll do what I can to provide answers, but I'm afraid even after... What has it been... weeks? Longer? Time loses all meaning in a place of such darkness. Forgive me. Let me tell you what little I can.", ["objectivesText"] = "Speak with Jaina in Forlorn Respite to learn what she knows about the Maw. Progress: I will tell you what I can.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59757] = { ["id"] = 59757, ["name"] = "Field Seance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "If these souls have information we need, we will take it from them. Even after being shattered by the Banshee, the helm fragment given to you by Bolvar holds the power of Domination. With it, we should be able to take control of the spirits long enough to find out what they know. They will need to be sufficiently weakened before we can break them. I'm confident you're more than capable of that task.", ["objectivesText"] = "Use the Shattered Helm of Domination to command 5 Malice Shadows in the Planes of Torment. Progress: Do you wish to speak to me, or to the dead?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 137663, 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59758] = { ["id"] = 59758, ["name"] = "Speaking to the Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "Look over to the ridge. There lies our quarry! No telling how many souls are writhing together within that amalgam. With any luck, one of them might be coherent enough to give us answers.", ["objectivesText"] = "Use the Shattered Helm of Domination to command the Tormented Amalgamation in the Planes of Torment. Progress: What are you waiting for?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59759] = { ["id"] = 59759, ["name"] = "The Lion's Cage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "Anduin is being kept in a place the shades call the Tremaculum. It's not far, but the way is perilous. I have tried more than once to free him from his captors, but the forces holding him are too great for me to handle alone. I'm counting on your presence to tip the scales.", ["objectivesText"] = "Find King Anduin Wrynn in the Tremaculum.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 11, ["flags"] = 0 } } },
[59760] = { ["id"] = 59760, ["name"] = "The Afflictor's Key", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "Sylvanas thinks us broken. She believes she has already won. We will show her how mistaken she is. First, I will need your help. The bonds that hold me are impossibly strong. We will need the key to free me of them. My... imprisonment here has been overseen by a creature they call the Afflictor. The key is likely in its possession.", ["objectivesText"] = "Collect the Afflictor's Key from Phael the Afflictor in the Tremaculum and unlock the Mawforged Shackles. Progress: Did you find the key?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 12, ["flags"] = 0 } } },
[59761] = { ["id"] = 59761, ["name"] = "An Undeserved Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "I have seen many souls brought here during my detention. The Jailer seems to want to break them, to twist them into his service... or worse. No soul deserves such a fate, <name>. The Mawsworn here hold the keys to their chains. Free as many as you can and we'll get them away from here.", ["objectivesText"] = "Collect Mawsworn Keys from Mawsworn forces in the Tremaculum and use them to free 15 Shackled Souls . Progress: Free those souls, <name>. They should not be bound here.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 13, ["flags"] = 0 } } },
[59762] = { ["id"] = 59762, ["name"] = "By and Down the River", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "Our next step is clear. We must travel to Zovaal's Cauldron--a frightful place I've heard spoken of in fanatical whispers. It's a forge of sorts that lies across the River of Souls. I have only been there a handful of times, but I have seen Baine held captive by the soldiers there. If fortune favors us, he'll still be nearby. Once he's safe, we can see about finding this waystone the shade spoke of.", ["objectivesText"] = "Cross the bridge over Gorgoa, the River of Souls. Progress: We must hurry!", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 159827, 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 14, ["flags"] = 0 } } },
[59765] = { ["id"] = 59765, ["name"] = "Wounds Beyond Flesh", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "Even as Baine's flesh mends, his spirit draws closer to death. I have seen dark magic like this before... among the Shadowmoon clan. The Jailer's minions must have inflicted a similar malady upon Baine. The only cure for the Shadowmoon's curse was to find the object they used to poison the spirit and shatter it. The sorcerers of this realm wield ornamental daggers. That might be what we're looking for. We must find the one that they used on Baine--quickly!", ["objectivesText"] = "Collect a Wither Blade from a Mawsworn Soulrender in Detrithos. Progress: We can only hope Baine's curse was inflicted by one of the sorcerers here.", ["rewardGold"] = 221280, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 15, ["flags"] = 0 } } },
[59766] = { ["id"] = 59766, ["name"] = "A Good Axe", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "I was a damned fool for throwing my axe at that sea hag. We can't afford to lose focus. The battle ahead won't be easy. I'll need another weapon to help us fight to the waystone. Looks like these soldiers have plenty of armaments. Let's keep an eye out for one I can use.", ["objectivesText"] = "Find a suitable weapon for Thrall amongst the Mawsworn Armaments in Detrithos. Progress: There should be something I can use around here...", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59767] = { ["id"] = 59767, ["name"] = "The Path to Salvation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "We must move quickly if we wish to find the waystone. The soul mentioned it overlooks the Cauldron, which would put it somewhere upon the ridge on the other side. Unfortunately, this area is swarming with enemy forces. We'd best avoid engaging them, lest we draw the Jailer's attention. I can shield us from sight, but we all have to stay together.", ["objectivesText"] = "Lead your allies past Zovaal's Cauldron. Progress: Stay close. We cannot risk being seen by the Jailer's forces.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59770] = { ["id"] = 59770, ["name"] = "Stand as One", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "<Anduin examines the obelisk intently.> I've never seen markings like these before. I've studied titan artifacts, but this appears to be made by a different hand. Hmm. It doesn't respond to me. I think Jaina's right. The waystone is reacting to your presence. Perhaps you'll have better luck activating it. Stay on your guard. The Jailer's forces paid this no mind when it was dormant, but there's no telling what they'll do if that changes.", ["objectivesText"] = "Activate the Eroded Waystone in Cocyrus.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 16, ["flags"] = 0 } } },
[59771] = { ["id"] = 59771, ["name"] = "History of Corruption", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59771 }, ["objectivesText"] = "Vesper of History rung", ["rewardXP"] = 8165, ["rewardItems"] = { 177836 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Vesper of History rung", ["amount"] = 1, ["type"] = 0, ["objectID"] = 158159, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59772] = { ["id"] = 59772, ["name"] = "Research Ruination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59772 }, ["description"] = "The Cult of the Damned continue their work within the halls of Aldur'thar. Infiltrate their chambers and destroy their research. It may not stop them, but it will buy us valuable time.", ["objectivesText"] = "Destroy 5 Research Notes at Aldur'thar. Progress: Making progress?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59773] = { ["id"] = 59773, ["name"] = "Seek the Ascended", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["description"] = "When you arrive in Bastion , seek out one of the kyrian. Explain that you require an audience with the Archon. Like the Arbiter, she is one of the Eternal Ones who rule over the Shadowlands. If anyone can guide you to the truth, it is the Archon. Perhaps she will even know a way to end this anima drought. Once you find the answers you seek, you are welcome to return to Oribos. Purpose guide your path, mortal.", ["objectivesText"] = "Journey to Bastion to inquire about the Maw kyrian.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166227, ["x"] = 0.392, ["y"] = 0.7708 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.7708 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59774] = { ["id"] = 59774, ["name"] = "Welcome to Eternity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57102 }, ["description"] = "Forgive my reaction. You see, the way from Oribos has been closed for quite some time. We did not know if it would ever open again. I welcome you, noble soul, to Bastion . Your deeds in life have earned you a most glorious fate! You are to become a kyrian, a winged bearer of the dead. My name is Kleia . It would be an honor to introduce you to our beautiful realm. There is much you must learn before your journey can begin. Gather yourself. When you are ready, we will venture on.", ["objectivesText"] = "Speak with Kleia .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166227, ["x"] = 0.392, ["y"] = 0.7708 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.7708 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59776] = { ["id"] = 59776, ["name"] = "From the Mouths of Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "I cannot express my gratitude enough for your help, champion. We mustn't linger, however. The Jailer's forces will soon be alerted to the disturbance here. Let us leave this place at once!", ["objectivesText"] = "Return to Lord Darion Mograine in Forlorn Respite and see what he has learned. Progress: The fiend is ready to talk. Let's get on with it.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59781] = { ["id"] = 59781, ["name"] = "The Last Guy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["series"] = { 62785 }, ["description"] = "You're not the first newcomer wanting to become famous. There've been a lot like you around! The last few wanted to prove themselves by killing a giant bloodtusk... none of them ever returned! You want to get recognition? Go find all those missing newcomers and kill the bloodtusk yourself.", ["objectivesText"] = "Find 5 Newcomer Corpses and slay Deadeye . Progress: Did you prove yourself?", ["rewardGold"] = 730080, ["rewardXP"] = 1770, ["rewardItems"] = { 174324, 175413, 175725, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59782] = { ["id"] = 59782, ["name"] = "The Deathspeaker's Devout", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59782 }, ["description"] = "Though Deathspeaker Kharos has long since been slain, the cultists in the nearby mountains continue his nefarious work. Clearly emboldened by the Scourge's resurgence and the rift in the sky, they once again kidnap our crusaders and perform their abhorrent alchemical experiments. Go forth and purge those fanatics from their camp.", ["objectivesText"] = "Kill 6 Dark Ritualists and 6 Dark Zealots at Deathspeaker's Watch.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59783] = { ["id"] = 59783, ["name"] = "Cultist Captors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59783 }, ["description"] = "Those damned cultists are relentless! They caught us off guard and managed to drag a few of our crusaders back to their camp. Light only knows what they're doing to them up there... Word is you're quite capable of holding your own. Our numbers are stretched thin enough as it is... if you could rescue the captives, we'd be in your debt. You can find the cultists lurking up in their mountain camp.", ["objectivesText"] = "Retrieve the Interrogator's Key from Interrogator Grell. Rescue 8 Captive Aspirants at Deathspeaker's Watch. Progress: What news have you?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 181497 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59789] = { ["id"] = 59789, ["name"] = "Tithe and Taxes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59789 }, ["objectivesText"] = "Anima Collector obtained HIDDEN: ANIMA CONTAINERS", ["rewardXP"] = 8165, ["rewardItems"] = { 177839, 180947 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Anima Collector obtained", ["amount"] = 1, ["type"] = 0, ["objectID"] = 166228, ["orderIndex"] = 0 }, { ["text"] = "HIDDEN: ANIMA CONTAINERS", ["amount"] = 1, ["type"] = 0, ["objectID"] = 166228, ["orderIndex"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59800] = { ["id"] = 59800, ["name"] = "Team Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Even if we're competing against each other, we're all Maldraxxi. That means we cheer on everyone, regardless of which side they're on. Enter the arena and douse the challengers with the contents of this flask. It may give them the edge they need to survive combat!", ["objectivesText"] = "Douse 15 Arena Challengers with the Flask of Team Spirit .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59801] = { ["id"] = 59801, ["name"] = "Take the Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "Wait! Before you enter, I would ask something of you. While we have not had a wildseed in some time, we did keep stores of anima. It served us well in staving off the gorm. Whatever has happened to my village, I do not want this power to remain in their hands. It will better serve Ardenweald in other groves. Keep an eye out for any anima within the village. We will put it to better use elsewhere.", ["objectivesText"] = "Collect 8 Animacones . Progress: Were you able to find any anima?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59802] = { ["id"] = 59802, ["name"] = "The Crumbling Village", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "This journal belonged to Lewor, the leader of our grove. It says he found something to use against the gorm, but what if it caused all this? There is only one way to be sure. Come with me to the village. Or what remains of it.", ["objectivesText"] = "Follow Partik .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 4, ["flags"] = 0 } } },
