[59805] = { ["id"] = 59805, ["name"] = "Maw Manifested", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Ya heard it from Mueh'zala himself... tanks to ol' Bwonsamdi . Dere be an ancient spirit trapped in da Maw. Me bettin' da Winter Queen gonna want it back. Good ting ya been goin' down dere yaself, hm? Should be nice an' easy for ya. Me gonna clean up da rest of da undead here. Meet ol' Bwonsamdi in Ardenweald when ya get back.", ["objectivesText"] = "Travel to the Maw to find the lost wild god of Ardenweald .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 177817 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 171655, ["x"] = 0.448, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863, 1543 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 6, ["flags"] = 0 } } },
