[59809] = { ["id"] = 59809, ["name"] = "On De Other Side", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13309, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["series"] = { 59811 }, ["description"] = "Ay dere, <name>... It be your ol' friend, Bwonsamdi ! I hear ya be workin' for da Winter Queen. Seems ya be makin' quite a name for yaself! Ardenweald be in grave danger, but da Queen... well, she be too proud to deal with ol' Bwonsamdi . Ya wanna save da forest, mon? Come visit me on da Other Side. I gonna be waitin' for ya...", ["objectivesText"] = "Use the deathstone to travel to the Other Side.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 1804, 1805, 1806, 1807, 177904, 184374, 184519 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13309 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59811] = { ["id"] = 59811, ["name"] = "Taking Inventory", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13309, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["series"] = { 59809 }, ["description"] = "Dark forces be at work, <class>. Ardenweald be where loa go ta be reborn after dey die on Azeroth. But some of da loa who be sleepin' in Ardenweald have gone missin'! Gotta be someone powerful behind it, takin' dem from right under da Winter Queen... Ol' Bwonsamdi can't be havin' loa vanishin' from Ardenweald. Dat could be me someday! No, no... we gonna put a stop to dis! Go back ta Ardenweald and search for da missin' loa.", ["objectivesText"] = "Search the Tranquil Pools for missing loa pods. Progress: Dark forces be at work in Ardenweald...", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13309 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59812] = { ["id"] = 59812, ["name"] = "Following the Trail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "I got a bad feelin' about dis, mon. Wildseeds don't just go missing... especially da kind wit' powerful loa in dem! Even da bad eggs like Hakkar and Dambala be protected by da Winter Queen. Someone... or someting... must be stealin' dem! But why? Dey weren't even ready ta be reborn... Search da area and see if ya can pick up da trail. Missing loa be bad for business... and Bwonsamdi be in enough trouble wit' da boss already!", ["objectivesText"] = "Search for clues leading to the missing loa. Progress: Hakkar and Dambala both gone missin' at da same time? Oh, I got a bad feelin' about dis...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180167 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59813] = { ["id"] = 59813, ["name"] = "Minions of Mueh'zala", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "Dese all be followers of Mueh'zala! Me shoulda known he be da one behind it all. Mueh'zala be da loa of death from long ago. It be him who raised up Ol' Bwonsamdi, him who made me a loa. Dat be before his worshippers started turnin' away from him. He always been a greedy one... but dis... Mueh'zala be goin' too far dis time! We gotta stop him, or he gonna take all da loa in Ardenweald!", ["objectivesText"] = "Defeat High Priest Rakazodu and 8 Mueh'zala forces. Progress: Mueh'zala be goin' too far dis time!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59815] = { ["id"] = 59815, ["name"] = "Stolen Loa", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "Hakkar and Dambala be somewhere in da grove. We need ta hurry and find out what Mueh'zala be up to. Dem two loa been mighty powerful on Azeroth... powerful and evil. Who knows what Mueh'zala be plannin' for dem! Search da Spirit Glen. Find da missing loa and see what Mueh'zala be meanin' ta do!", ["objectivesText"] = "Locate Hakkar the Soulflayer and Dambala. Progress: We gotta know what be happenin' ta da missin' loa!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59817] = { ["id"] = 59817, ["name"] = "Winter Be Comin'", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "Da boss be puttin' together an army of terrible loa. Hakkar and Dambala may only be da beginnin'. How da boss get so strong? I not be seein' him use power like dis before... Da Winter Queen not be fond of ol' Bwonsamdi, but we gonna need her help to stop Mueh'zala. Ya be friendly wit' da Queen, no? If she be willin' to rally her forces, we might be able to stop Mueh'zala before it be too late. Head to da Heart of da Forest and speak wit' da Queen. She be our only hope now.", ["objectivesText"] = "Gain an audience with the Winter Queen . Progress: We gotta convince da Winter Queen to join forces against Mueh'zala...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175586, 179767, 179890, 181911 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59818] = { ["id"] = 59818, ["name"] = "Gathering The Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "Loath as I am to aid Bwonsamdi, Mueh'zala must be made to answer for his crimes. We will eradicate his worshippers and drive them from the forest before they cause more harm. Rally the groves and muster the Wild Hunt. Ardenweald has need of its protectors. Make haste, <huntsman/huntress>.", ["objectivesText"] = "Gather the Wild Hunt to Tirna Noch in Ardenweald.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 167823, ["x"] = 0.672, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59819] = { ["id"] = 59819, ["name"] = "Cleansing the Forest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "The Winter Queen has commanded us to drive Mueh'zala's forces out of Ardenweald. This won't be an easy battle. The death loa's army is strong, and several of our hunters have been gravely injured. Can we count on you to turn the tide in our favor, <name>? Aid our fallen allies and vanquish Mueh'zala's minions!", ["objectivesText"] = "Aid the Wild Hunt in their fight against the forces of Mueh'zala. Progress: The fight is far from over.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 167823, ["x"] = 0.672, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 167823, ["x"] = 0.672, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59821] = { ["id"] = 59821, ["name"] = "Report to the Queen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59809, 59811, 59812, 59813, 59815, 59817, 59818, 59819, 59821 }, ["description"] = "Mueh'zala's forces are routed, and it's only a matter of time before the Wild Hunt completely purges them from Ardenweald. But something tells me that the struggle between Bwonsamdi and Mueh'zala is far from over. That creepy little mask has gone silent... You should hurry back to the Heart of the Forest and report to the Winter Queen . She will decide what we do next.", ["objectivesText"] = "Speak with the Winter Queen .", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 167823, ["x"] = 0.672, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1101, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1101, ["name"] = "Da Boss", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59822] = { ["id"] = 59822, ["name"] = "Tracking a Wild God", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Dis be a dark place, <name>. We gotta track down da spirit who be trapped here. Me tink me can pick up its trail... but dat be all dis ol' shadow hunter can do. If me be tryin' ta fight wit' ya, da threads dat be tyin' me ta Azeroth might break. Den I gonna be stuck here, too. C'mon. We best be moving.", ["objectivesText"] = "Track down the missing spirits of Ardenweald .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 177817 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 171655, ["x"] = 0.448, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 171806, ["x"] = 0.408, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59824] = { ["id"] = 59824, ["name"] = "Loa Rescue", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "We be here for Ashamane, but me sensin' loa bein' tortured up ahead. Three of dem, if me be right. Me don't know who dey be, but dey don't belong in da Maw. We need ta be bringin' dem back ta Ardenweald , too!", ["objectivesText"] = "Find and rescue the three loa trapped within the Maw.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 177817 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 171806, ["x"] = 0.408, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 166461, ["x"] = 0.462, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59825] = { ["id"] = 59825, ["name"] = "Seed Hunting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 59825 }, ["objectivesText"] = "Return Animacones to Alascene and Kill Players Animacones Returned", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2Objectives"] = { { ["text"] = "Return Animacones to Alascene and Kill Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Animacones Returned", ["amount"] = 5, ["type"] = 0, ["objectID"] = 166329, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[59826] = { ["id"] = 59826, ["name"] = "Bet On Yourself", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. The entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it. I've brought in a special challenger just to prove the point. Face Mistress Dyrax in the Theater of Pain and prove us wrong... or prove us right. We will be betting, so don't disappoint.", ["objectivesText"] = "Defeat Mistress Dyrax in the Theater of Pain, when she appears. Progress: What did you prove?", ["rewardGold"] = 386100, ["rewardXP"] = 8165, ["rewardItems"] = { 181645, 181647, 181649, 184062, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group", ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 15, ["flags"] = 0 } } },
