[59836] = { ["id"] = 59836, ["name"] = "Battles Won Long Ago", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59836 }, ["objectivesText"] = "Iron Trench enemies killed Plant Banner at the Iron Trench", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Iron Trench enemies killed", ["amount"] = 15, ["type"] = 0, ["objectID"] = 166494, ["orderIndex"] = 0 }, { ["text"] = "Plant Banner at the Iron Trench", ["amount"] = 1, ["type"] = 0, ["objectID"] = 166379, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[59837] = { ["id"] = 59837, ["name"] = "Working for the Living", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "I see you are wondering where we acquire all of the challengers we supply to this arena. We scour countless realms in search of opponents to provide the Maldraxxi with firsthand combat experience. Currently, I am in the process of procuring a new combatant--and with it, a lucrative betting opportunity. Would you make use of our portal and assist Zo'umlo in capturing Khogov the Expunger ? You will be appropriately compensated, of course.", ["objectivesText"] = "Shattered Grove secured and Khogov the Expunger captured. Progress: Have you successfully captured Khogov the Expunger ?", ["rewardGold"] = 393150, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59838] = { ["id"] = 59838, ["name"] = "Scourge War Machines", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59838 }, ["description"] = "The Scourge's war machines make it exceedingly difficult for us to gain ground. They must be our top priority. Though they are well protected, we must destroy them if we are to clear a path for our ground forces and grant them an opportunity to strike. Plant these charges underneath the war machines and then clear the area.", ["objectivesText"] = "Destroy 5 Scourge War Machines in The Conflagration.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 182313 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59839] = { ["id"] = 59839, ["name"] = "WARNING: This is Only a Test!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59839 }, ["description"] = "Where some see a problem, I see an opportunity. What this Scourge fiasco calls for is a creative solution! Behold--my \"secret weapon\"! Controlled by none other than my Carefully Constructed Control Device, or C.C.C.D. for short! Hmm, that name might need a little work. You're the first to see it, so that means you'll be the first to test it. But don't worry, I'm pretty sure it's safe. Good luck!", ["objectivesText"] = "Successfully complete the testing of Fizzix Blastbolt 's \"Secret Weapon\" at Deathspeaker's Watch. Progress: So, how's it goin'?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 172905, ["x"] = 0.67, ["y"] = 0.262667 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 172905, ["x"] = 0.67, ["y"] = 0.262667 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.262667 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59840] = { ["id"] = 59840, ["name"] = "Divine Gratitude", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59840 }, ["description"] = "Many thanks for restoring my power and vigor. My path will now lead me back to my people, but it is only right that you are rewarded for your efforts.", ["objectivesText"] = "Accept the boon offered by the deity.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59846] = { ["id"] = 59846, ["name"] = "Finders-Keepers, Sinners-Weepers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "Oh hello, mortal. You have a real knack for arriving at the most opportune times. I wonder what Taskmaster Matyas wants with you. Curious. As for me, again Matyas has used my sinstone against me. I was already enraged that he caged me and I assure you that this latest attack will not go unanswered. Yet, while he has my sinstone I am unable to act against him directly. So we must remedy that. You question the laborers and I will read this journal while I regain my strength.", ["objectivesText"] = "Discover the secrets of Taskmaster Matyas's efforts in Feeder's Thicket. Progress: Have you discovered anything useful?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 177713, 177714, 177765, 177881, 178065, 178066, 178067, 178068, 178069, 178070, 178071, 178072, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59847] = { ["id"] = 59847, ["name"] = "Defending the Rampart", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59847 }, ["description"] = "The Scourge are assaulting our outpost! We must defend it at all costs! Slay as many of the fiends as you can!", ["objectivesText"] = "Defend against the Scourge attack atop the Ironwall Rampart.", ["rewardGold"] = 248040, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
