[59851] = { ["id"] = 59851, ["name"] = "Frozen Solid", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59851 }, ["description"] = "The breath of a frost wyrm can freeze even its largest foes in an instant. Our forces, unfortunately, have experienced this firsthand. Their advance toward the citadel has come to a halt. I fear we may lose our foothold unless we act quickly. Take this potion and use it to free our forces from their frigid bonds. Light be with you.", ["objectivesText"] = "Rescue 12 Frozen Allies at the Court of Bones. Progress: Always keep an eye to the sky.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 182199 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
