[59856] = { ["id"] = 59856, ["name"] = "Rezan, Loa of Kings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Rezan be a powerful loa, one of great importance ta da Zandalari. We need ta rescue him... but dis creature be projectin' a barrier of death. Notin' be gettin' in. Unless... I be usin' me own anima ta shield ya from its magic. Ya gotta act fast and kill da monster dat be drainin' Rezan. Me anima not gonna last forever. Say da word when ya ready ta go.", ["objectivesText"] = "Accept some of Vol'jin's anima to protect yourself, then slay Exhaurbius to save Rezan. Progress: We need ta save Rezan!", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 177817 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 166461, ["x"] = 0.462, ["y"] = 0.855 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 166461, ["x"] = 0.462, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.855 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59862] = { ["id"] = 59862, ["name"] = "A Savior for Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["description"] = "The forest sighs in greeting, Maw Walker. Your arrival was written in the stars, and awaited by the boughs. Now our work begins. Let us proceed. Follow this path into the grove. These are but the first steps on our journey together.", ["objectivesText"] = "Walk with the Warden to the grove. Progress: Our paths converge. Together we walk.", ["rewardGold"] = 122850, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2363, ["db2PoiUiMapID"] = 1662, ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59863] = { ["id"] = 59863, ["name"] = "Combat Nullifier 07-X", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59863 }, ["description"] = "While everyone is busy fending off our enemies with swords and magic, how about we try something different. Behold, my latest invention--the Combat Nullifier 07-X! With this device, no enemy is truly your enemy any longer! Now, I haven't quite worked out the exact energy modulator calculations, but I am certain it works. Mostly. For now, we'll need to \"borrow\" some energy from our enemies in order to operate it. Go ahead. Charge it up and give it a whirl!", ["objectivesText"] = "Charge the Power Containment Module to Blast 5 enemies with the Combat Nullifier 07-X at Sindragosa's Fall. Progress: How's it going?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 173124, ["x"] = 0.676, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 173124, ["x"] = 0.676, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59865] = { ["id"] = 59865, ["name"] = "Glimmerflight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59865 }, ["series"] = { 59262, 59263, 59311, 59348, 59351, 60660 }, ["description"] = "This so exciting! Come, another test is in order. I can hardly wait!", ["objectivesText"] = "Observe Kowalskos ' test flight.", ["rewardGold"] = 365040, ["rewardXP"] = 8165, ["rewardItems"] = { 175791, 175792, 175967, 175968, 176812, 177951 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59866] = { ["id"] = 59866, ["name"] = "Parting Ways", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59731, 59732, 59739, 59741, 59742, 59749, 59805, 59822, 59824, 59856, 59866 }, ["description"] = "Me don't know what fate be comin' for ol' Vol'jin... but it be waitin' for me in Ardenweald . Ashamane, Hir'eek, Shadra... dey belong dere, too. We best be gettin' outta here. Me had enough of da Maw for an eternity.", ["objectivesText"] = "Return the lost loa and Vol'jin to the Winter Queen in Ardenweald .", ["rewardGold"] = 947700, ["rewardXP"] = 12250, ["rewardItems"] = { 175588, 177817, 179768, 179887, 181912 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 166461, ["x"] = 0.462, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.855 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1102, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1102, ["name"] = "Deal for a Loa", ["orderIndex"] = 10, ["flags"] = 0 } } },
[59867] = { ["id"] = 59867, ["name"] = "WANTED: Appraiser Vix", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59867 }, ["description"] = "For failure to pay debts upon lost wagers, theft of arena property, and for the slaughter of an authorized debt collector. All necessary violence is hereby sanctioned when confronting Vix. Special warning to be on the lookout for numerous associates who have demonstrated a violent attitude toward outsiders. Elimination of this felon is of the highest priority.", ["objectivesText"] = "Eliminate Appraiser Vix Progress: Eliminate Appraiser Vix .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181645, 181647, 181649, 184305, 184772, 184773, 184774, 184775, 184776 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group", ["questLines"] = { { ["id"] = 1171, ["name"] = "WANTED: Appraiser Vix", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59868] = { ["id"] = 59868, ["name"] = "Offer of Freedom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "Just as I was, some of the Briarbane venthyr you encounter will have been compelled to serve Matyas. They likely will not want to fight you, but will have no choice. Once they are injured, they may be willing to pause to see if one of the sinstones you recovered earlier is theirs. Free those you can. The use of a sinstone to compel others isn't fair.", ["objectivesText"] = "Weaken Briarbane venthyr and then offer them a sinstone. Progress: Have you released the compelled venthyr?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 177713, 177714, 177765, 177881, 178077, 179359, 179979, 179980, 179981, 180177, 184488 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 166616, ["x"] = 0.601, ["y"] = 0.791 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 9, ["flags"] = 0 } } },
[59871] = { ["id"] = 59871, ["name"] = "Catalyze This", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["series"] = { 59870, 59872, 59873 }, ["description"] = "The grove grows in power, and so shall the spirits it shelters. You have nurtured a spirit to rebirth on your own. Now you must learn to make use of catalysts. When planted near a wildseed, catalysts grant the slumbering spirit strength beyond what it knew in life. Strength that it retains when reborn. Catalysts are special and rare, though I have one here for you to use. Others can be found across the Shadowlands. For now, plant the catalyst and witness the potential it holds.", ["objectivesText"] = "Use the catalyst on the catalyst plot.", ["rewardGold"] = 122850, ["rewardXP"] = 4085, ["rewardItems"] = { 184779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2363, ["db2PoiUiMapID"] = 1662, ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59872] = { ["id"] = 59872, ["name"] = "How to Save a God", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["series"] = { 59870, 59871, 59873 }, ["description"] = "Many mortal souls suffer within the Maw. But so too do many spirits of Nature. Anima alone cannot heal wounds inflicted by the Jailer. Spirits plucked from his grasp must be planted anew and tended with care. These wildseeds are unlike any other. This grove, unlike any other. Within them lies dormant hope, a chance for even the weakest spirit to be reborn. One such as this. Lay this spirit to rest within a wildseed. Let its rebirth begin.", ["objectivesText"] = "Place the Soul Seed into the wildseed. Progress: Let fate and compassion guide your hand.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 177953 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2363, ["db2PoiUiMapID"] = 1662, ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59873] = { ["id"] = 59873, ["name"] = "Greeting a God", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["series"] = { 59870, 59871, 59872 }, ["description"] = "Soon, the moment of the spirit's rebirth will be nigh. A fate all but extinguished by the Maw, rekindled by grove and caretaker. Time will be the spirit's salve. Once enough of it has passed, lay your hands upon the wildseed and awaken them.", ["objectivesText"] = "Wait for the spirit to finish incubating, then open the wildseed. Progress: Patience is the way of the forest.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2363, ["db2PoiUiMapID"] = 1662, ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59874] = { ["id"] = 59874, ["name"] = "The Maw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "$p, your arrival has set Maldraxxus ablaze. If you have any honor, you will do as I ask. I believe I know where our answers may lie. The baron preceding Draka was lost to the Maw. It is said you have entered that dark abyss... and returned. If the baron survived, he may know our next course of action. You came here from Oribos. Return there, and see if you can find a way back to the Maw.", ["objectivesText"] = "Speak with Bolvar in Oribos.", ["rewardGold"] = 1230, ["rewardXP"] = 175, ["rewardItems"] = { 55049, 55050, 136350, 140618, 140619, 140620, 140621, 175511, 175524, 175525, 175526, 178018, 181174, 181476, 181557, 181733, 181741, 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466, 211279, 237812, 246936, 249400, 251821, 254267, 254579 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164843, ["x"] = 0.389333, ["y"] = 0.650667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.389333, ["y"] = 0.650667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 1, ["flags"] = 0 } } },
[59876] = { ["id"] = 59876, ["name"] = "Field Reports", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 60113, 60116, 60117, 60669, 60670, 60725, 60759, 60761 }, ["description"] = "The Scourge can strike anytime, anywhere. To counter their unpredictability, the Argent Crusade has secured key locations along the southern road heading east. However, I have yet to receive any reports from our scouts in the field. With the erratic nature of these attacks, I fear the worst. Travel the road and take stock of our outposts. I'll be expecting a full report when you return. Light be with you, <name>.", ["objectivesText"] = "Gather reports from officers in Elwynn Forest, Redridge Mountains and Duskwood. Progress: Gregor sent you?", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["rewardItems"] = { 177958, 177959, 177960 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 166383, ["x"] = 0.655, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 166184, ["x"] = 0.735, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 47, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59877] = { ["id"] = 59877, ["name"] = "A Message from Icecrown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 60169, 60727 }, ["description"] = "We received word from our forces in Northrend. Justicar Trueheart requests our immediate assistance. As you are an experienced <class>, I ask that you answer the call. The urgency of this summons cannot be ignored, even if it means braving the terrors of Icecrown itself. I know you fear for the safety of everyone here. I will continue to coordinate our efforts and call in additional reinforcements. Light be with you, <name>.", ["objectivesText"] = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 166383, ["x"] = 0.655, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 84, 118 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59878] = { ["id"] = 59878, ["name"] = "Too Many Whelps", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59878 }, ["description"] = "We cannot hope to hold this ground if frostwyrms strafe the skies above us. Cultists have been raising whelps from the dead nearby. The more of them we eliminate, the fewer monstrosities to breath deadly ice upon our forces. Put an end to their efforts.", ["objectivesText"] = "Kill 4 Wyrm Reanimators and 12 Frostbrood Whelps at Sindragosa's Fall.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59879] = { ["id"] = 59879, ["name"] = "This Thing of Ours", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Au'narim is the top broker here. She keeps this place supplied with exotic creatures for us to fight in the arena. She's noticed your efforts and wants to meet you! This is important. A broker's backing could lead to an invitation to compete!", ["objectivesText"] = "Meet with Au'narim .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59882] = { ["id"] = 59882, ["name"] = "Sure Bet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "You appear to have great profit potential. There are many interested parties willing to bet upon your performance in the Theater of Pain. Go now, Louison will arrange your appearance.", ["objectivesText"] = "Meet with Louison", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 11, ["flags"] = 0 } } },
[59894] = { ["id"] = 59894, ["name"] = "The Golden Dawn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1536, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["series"] = { 61586 }, ["description"] = "The machinations of war commence. Gharmal's crimes are now evident to all of the Shadowlands. Bastion demands vengeance, and we shall share it with them. Only our combined forces will defeat the Constructs once and for all. Meet Draka at the overlook. Your presence there will help solidify an agreement.", ["objectivesText"] = "Teleport to the Overlook to meet with Draka.", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 181803 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166535, ["x"] = 0.504, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 13, ["flags"] = 0 } } },
[59897] = { ["id"] = 59897, ["name"] = "Seeking the Baron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59959, 59960, 59962, 59966, 59973, 59974, 60972 }, ["description"] = "Take this amulet. One like it is carried by each of the Four Horsemen. The amulets are imbued with a power that links them to one another. That connection should help you locate Darion Mograine. No doubt Darion has witnessed countless horrors in the Maw. Perhaps he has caught sight of the missing baron. Let us hope he can lead you to our Azerothian allies as well.", ["objectivesText"] = "Enter the Maw.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 2, ["flags"] = 0 } } },
