[59907] = { ["id"] = 59907, ["name"] = "Mawsworn Menace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "Our knights are strong, but they don't stand much chance scattered against such an opponent. We need to thin the ranks of our foe. The Ebon Blade won't do us any good if they are cut down.", ["objectivesText"] = "Defeat 8 Mawsworn enemies in the Crucible of the Damned. Progress: Let your blade do the talking!", ["rewardGold"] = 221280, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 17, ["flags"] = 0 } } },
[59910] = { ["id"] = 59910, ["name"] = "Fight and Flight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "Mograine and Emeni will lead the assault on the western gate. You and Xandria will advance from the east. Secure the area and slay all who oppose you. Once we have them surrounded, we can strike the final blow against Gharmal.", ["objectivesText"] = "Fly with Xandria to the House of Constructs.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 209888 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171483, ["x"] = 0.362, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59914] = { ["id"] = 59914, ["name"] = "Fear to Tread", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "It appears we've escaped our enemies' notice for the moment. We should take the opportunity to scout the nearby area for signs of our allies. We will draw less attention alone. The Ebon Blade will hold back, awaiting my signal. Come, let us see what awaits us in this hellscape.", ["objectivesText"] = "Scout Calcis for any signs of your allies. Progress: Champion? Tell me this is not an illusion.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 18, ["flags"] = 0 } } },
[59915] = { ["id"] = 59915, ["name"] = "Soul in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent. It will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care. Let's bring our prize to the Lord Admiral.", ["objectivesText"] = "Return to Lady Jaina Proudmoore in Forlorn Respite.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 19, ["flags"] = 0 } } },
[59916] = { ["id"] = 59916, ["name"] = "The Butchers of Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 60043, 60050, 60510, 61770, 61771, 61773 }, ["description"] = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these monstrosities?! No! The butchers of Bastion made clear their hearts that day! They deserve only the eternal darkness that awaits them. Ensure that they meet it!", ["objectivesText"] = "Kill 10 House of Constructs forces in the Separation Chamber.", ["rewardGold"] = 303800, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59917] = { ["id"] = 59917, ["name"] = "Kill Them, Of Course", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "These mindless monstrosities hail from the farthest reaches of the Shadowlands. The anima drought has fueled their relentless hunger, driving them to seek new sources. Their presence here is inconvenient, to put it mildly. They tear at the land searching for any anima they can find. We must thin their numbers and buy time to safeguard the knowledge locked within the Sepulcher. Exactly the sort of work you're accustomed to, yes?", ["objectivesText"] = "Slay 8 Enraged Gluttons . Progress: How did the hunting go?", ["rewardGold"] = 438150, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 2, ["flags"] = 0 } } },
[59919] = { ["id"] = 59919, ["name"] = "An Earned Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58846, 58847, 58854 }, ["description"] = "There is one more thing you should do, Maw Walker. In rebuilding the Crest of Ascension you have earned more than just the trust of your fellow kyrian. It would seem our Forgelite Prime, Mikanikos, has rather enjoyed your time together and would like to soulbind with you. Given his predilection towards, well, himself, I am as surprised as you are. You must have truly impressed him.", ["objectivesText"] = "Soulbind with Mikanikos. Progress: This is a moment to remember.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59920] = { ["id"] = 59920, ["name"] = "Light the Forge, Forgelite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57713, 57908 }, ["description"] = "I think we have the materials I will need to light the forge, at long last. I am afraid the place is in a state of disrepair. Between failed attempts at working without anima and simple neglect, I cannot hope to work the forge as it currently stands. I would very much appreciate your help to get the place in order while I coax the forge to life once more.", ["objectivesText"] = "Help Forgelite Sophone .", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59921] = { ["id"] = 59921, ["name"] = "All I Ever Will Be", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "This is the site of an ancient battle won by the previous Paragon of Courage. She sacrificed herself to serve the Shadowlands. I only hope my own end will prove as exemplary. Many of my disciples meditate upon the scrolls here. With them, we remember the foundation of our courage. Accompany Alexandros as he reflects on his shrines. Aid him in understanding where the source of his courage lies. He will learn that this afterlife is not the one suited for him.", ["objectivesText"] = "Reflect on the Scrolls of Remembrance with Alexandros Mograine. Progress: What have you learned?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.4448, ["y"] = 0.5836 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 11, ["flags"] = 0 } } },
[59922] = { ["id"] = 59922, ["name"] = "Do Not Forget", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "The Arbiter's judgment was, as always, infallible. Though Alexandros's devotion to the Light is undeniable, it is the memory of his loved ones that truly fuels his strength. He was meant for Maldraxxus , not Bastion. Nonetheless, our reclamation of the temple stands. My vengeance is not yet complete, but now I know that some of the Maldraxxi can still be trusted. Go now. Return to your leader with news of our victory today. And tomorrow, we shall purge our foes once and for all.", ["objectivesText"] = "Return to Draka in the Seat of the Primus.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 44362, 44363, 44364, 44365, 44785, 44788, 46723, 46800, 46824, 116404, 258990 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.4448, ["y"] = 0.5836 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 12, ["flags"] = 0 } } },
[59959] = { ["id"] = 59959, ["name"] = "The Brand Holds the Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59960, 59962, 59966, 59973, 59974, 60972 }, ["description"] = "<Darion is unresponsive. The cage is locked, and doesn't appear easily broken. Perhaps the holder of the key is this \"Brand\" he mentioned.>", ["objectivesText"] = "Find the key to free Darion. Progress: Are you willing to listen to my proposition?", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 5, ["flags"] = 0 } } },
[59960] = { ["id"] = 59960, ["name"] = "A Cooling Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1960, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59962, 59966, 59973, 59974, 60972 }, ["description"] = "<The amulet burns hot in your hand. The magic that runs through it tugs slightly at your grip. Perhaps the enchantment spoken of by Bolvar can now be used to find Mograine.>", ["objectivesText"] = "Use the Amulet of the Horsemen to find Darion Mograine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 4, ["flags"] = 0 } } },
[59962] = { ["id"] = 59962, ["name"] = "Hope Never Dies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59966, 59973, 59974, 60972 }, ["description"] = "So, mortal, you are here looking for someone. Well it just so happens that, clever as I am, it's quite possible I know where they are. Allow me to propose a trade. That amulet you carry... it holds an interesting power. You give me the amulet, and I will help you find this Maldraxxi baron. And then you will leave. I don't mean to be rude, but I really prefer to keep a low profile. Allow me to speed things along.", ["objectivesText"] = "Follow Ve'nari .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 6, ["flags"] = 0 } } },
[59966] = { ["id"] = 59966, ["name"] = "Delving Deeper", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59973, 59974, 60972 }, ["description"] = "It's quite a thrill to have a mortal for a business partner! The amulet really is intriguing. What's that? Oh yes, that baron you're searching for... Well it so happens that I learned of a Maldraxxi warlord being held in the lower courtyard of Perdition Hold. As you might guess by the name, it's not the most charming of places. I would prefer to avoid the attention of the Jailer's forces. Fortunately, I have just the thing. Give the word, and I will conceal us from the Mawsworn.", ["objectivesText"] = "Follow Ve'nari to Perdition Hold.", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 7, ["flags"] = 0 } } },
[59973] = { ["id"] = 59973, ["name"] = "A Bond Beyond Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59966, 59974, 60972 }, ["description"] = "Since crossing into the Shadowlands, I've been so focused on our mission that I never even considered the souls of my family being here somewhere. Whatever this realm called Maldraxxus is, I hope it is worthy of my father's service! We must free him, <name>. There is... much I need to say to him.", ["objectivesText"] = "Protect Darion while he frees Alexandros. Progress: Every moment spent here tears at one's soul.", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 8, ["flags"] = 0 } } },
[59974] = { ["id"] = 59974, ["name"] = "A Soul Saved", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1536, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59966, 59973, 60972 }, ["description"] = "Vyraz... all this time... This cannot stand, <name>. We must avenge Krexus and cut him down! He must have sent you to the Maw expecting that you would never return. He underestimated you. A fatal mistake. Go with Mograine and claim Vyraz's head. I will warn our forces at the Seat of the Primus.", ["objectivesText"] = "Meet Alexandros Mograine at the House of the Chosen in Maldraxxus .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 178018, 181174 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162801, ["x"] = 0.412, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 11, ["flags"] = 0 } } },
[59986] = { ["id"] = 59986, ["name"] = "Wide Worlds of Catalysts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59986 }, ["description"] = "Catalysts come in different forms, for now we shall introduce you to two of them. Speed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover. Quality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. Return to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.", ["objectivesText"] = "Identify the different types of Catalysts", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59994] = { ["id"] = 59994, ["name"] = "Trust Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "Let us ponder the meaning of the Archivist's last words: \"Victory only belongs to those brave enough to fall.\" Hmm. It could be reference to the Volume of Victory. That is the most well-known of all the writings said to be kept in this tower. That book is priceless, <name>. I mean that almost literally. We must do whatever is necessary to find it! But, uh... What do you suppose \"brave enough to fall\" refers to?", ["objectivesText"] = "Jump from the tower. Progress: You have it?", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 175516, 175517, 175518, 175519, 178020, 182732 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166806, ["x"] = 0.452, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 6, ["flags"] = 0 } } },
[60003] = { ["id"] = 60003, ["name"] = "A Valiant Effort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60169, 60827, 60828, 60843, 60861, 60867, 60871, 60932, 62157, 62185, 62225 }, ["description"] = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale. While we managed to escort many to safety, there are some who were wounded in the chaos. Search the training grounds for any survivors from the onslaught. We need all the help we can get.", ["objectivesText"] = "Rescue 6 Wounded Valiants from the training grounds. Progress: Any word on survivors?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183797 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60004] = { ["id"] = 60004, ["name"] = "A Valiant Effort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60932, 62157, 62185, 62225 }, ["description"] = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale. While we managed to escort many to safety, there are some who were wounded in the chaos. Search the training grounds for any survivors from the onslaught. We need all the help we can get.", ["objectivesText"] = "Rescue 6 Wounded Valiants from the training grounds. Progress: Any word on survivors?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183689 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60005] = { ["id"] = 60005, ["name"] = "Imminent Danger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["series"] = { 59197, 59198, 59199, 59200, 59426, 60006 }, ["description"] = "The Temple of Courage must not fall! All kyrian learn to fight in its hallowed halls. Not only to protect Bastion , but to ensure their own safety when retrieving souls from across the veil. Travel there at once. Seek out Thanikos , the Paragon of Courage's loyal hand.", ["objectivesText"] = "Seek out Thanikos at Xandria's Vigil.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167873, ["x"] = 0.412, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60006] = { ["id"] = 60006, ["name"] = "Now or Never", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["series"] = { 59197, 59198, 59199, 59200, 59426, 60005 }, ["description"] = "In a fair fight our warriors could stand against countless swarms of these Maldraxxi. This was no fair fight, outsider. They came without warning. Without cause. We were caught unprepared. They must not be allowed to encroach any further. This stops here.", ["objectivesText"] = "Reclaim Xandria's Vigil. Progress: We will not go down without a fight.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167873, ["x"] = 0.412, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167873, ["x"] = 0.412, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60007] = { ["id"] = 60007, ["name"] = "Stay Scrappy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "I can rebuild this colossus's core systems, but a few things are beyond repair. Thankfully there were enough centurions present here that I believe we can improvise. Replacements are in order! I require an Anima Conflux to charge its systems, some Eternity Plating to protect its core, and an Archonic Resonator to make it go boom! I'll take care of the rest. Quickly, now!", ["objectivesText"] = "Recover the Anima Conflux , Eternity Plating , and Archonic Resonator . Progress: Do you have the parts?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167135, ["x"] = 0.408, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167135, ["x"] = 0.408, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60008] = { ["id"] = 60008, ["name"] = "Rip and Tear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "We will show these Maldraxxi insurgents the price for their betrayal. The northern grounds have been taken by the House of Constructs, home to Maldraxxus' most resilient warriors. They have earned no mercy this day, and we will give them none. We will carve through them side by side until this sacred ground is cleansed.", ["objectivesText"] = "Slay House of Constructs forces. Progress: This is what must be done.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167134, ["x"] = 0.405, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60009] = { ["id"] = 60009, ["name"] = "Fight Another Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "Some of our brethren are still alive in there! While many were lost in the initial assault, they seem keen on taking any survivors prisoner. I know not what they intend, but given their mastery of corpses we must assume the worst. Some have already been taken to their necropolis above, but others remain in cages on the ground. Free all you can.", ["objectivesText"] = "Save 6 captured kyrian. Progress: The kyrian leave none behind on the field of battle.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175718, 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167269, ["x"] = 0.412, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167269, ["x"] = 0.412, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60013] = { ["id"] = 60013, ["name"] = "Leave it to Mnemis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58843, 58980, 59196, 60180 }, ["description"] = "I have deduced by the urgency in your collective voices that you wish to leave. I will expedite your exit. There is a transport pad in the antechamber. I will ensure that the chamber is sealed once again on your exit. Please accompany me.", ["objectivesText"] = "Use the Transport Pad in the Vault of the Archon.", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167504, ["x"] = 0.563333, ["y"] = 0.673333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.673333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 10, ["flags"] = 0 } } },
[60020] = { ["id"] = 60020, ["name"] = "An Opportunistic Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "I'm impressed you made it this far. But don't get too full of yourself. Most of the fodder you plowed your way through were amateurs at best. Only one combatant will leave this arena a champion. Each of the five... uh, three houses has fighters in the field. Most merely seek to test their own limits or earn a bit of favor. Only a few have a real chance at claiming victory. Seek out those challengers if you wish to claim true glory this day.", ["objectivesText"] = "Slay 10 elite contenders. Progress: Are they finished?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60021] = { ["id"] = 60021, ["name"] = "Champion the Cause", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "Now you're starting to show potential! I'm guessing your name was well known on whatever mortal world you hail from. But don't rest on your laurels. The harder you fight, the harder others will strive to strike you down. That's the Maldraxxi way! Nothing wins the favor of the crowd like taking down a former champion. Two are in attendance today, attempting to recapture their past glories. Slaughter them!", ["objectivesText"] = "Slay Champion Rin'mar and Champion Gutrend . Progress: Is it done?", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 147905, 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 5, ["flags"] = 0 } } },
