[60041] = { ["id"] = 60041, ["name"] = "Build-A-Bomination", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "We need to get to work, every soul here needs a body. We have the parts to build a body for Chordy. Chordy is a great scavenger, rebuilding him could allow us to find more construct parts easier. Would you help me to rebuild him?", ["objectivesText"] = "Help Rathan to create a new construct body for Chordy. Progress: It will be nice to have Chordy back to his old self!", ["rewardGold"] = 144600, ["rewardXP"] = 4085, ["rewardItems"] = { 178061, 182074, 183743 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 10, ["flags"] = 0 } } },
[60042] = { ["id"] = 60042, ["name"] = "May I Take Your Order?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "Chordy is just the first success, there will be many more! As free souls show up here, speak with them and take their requests for new construct bodies. We'll soon have lots of new constructs to work on!", ["objectivesText"] = "Take the construct requests from the souls present.", ["rewardGold"] = 120510, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 11, ["flags"] = 0 } } },
[60043] = { ["id"] = 60043, ["name"] = "Justice from Above", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 59916, 60050, 60510, 61770, 61771, 61773 }, ["description"] = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts. The Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once. I shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", ["objectivesText"] = "Destroy 5 Maldracite Cores .", ["rewardGold"] = 303800, ["rewardXP"] = 8165, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60044] = { ["id"] = 60044, ["name"] = "Charging The Blade", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest one, but conventional weapons do nothing against their imbued hides. Thankfully, I have an idea. Your runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", ["objectivesText"] = "Charge your runeblade by killing enemy constructs in the Stitchyard.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 10, ["flags"] = 0 } } },
[60048] = { ["id"] = 60048, ["name"] = "Stitching Time", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "With the proper resources we can build a force of construct warriors greater than anything ever seen in the Shadowlands. Visit Arkadia Moa and see if you can secure the resources we need.", ["objectivesText"] = "Upgrade Abominaton Factory to Tier 1", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 9, ["flags"] = 0 } } },
[60049] = { ["id"] = 60049, ["name"] = "At Your Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60049 }, ["description"] = "I suppose I should commend you. You certainly exceeded my expectations. Rathan can be sentimental, but he is right. This place can be our new home, and here we can construct new bodies for the souls you freed. Inform Baroness Draka that she has earned the allegiance of Princess Emeni and the constructs of Butchers Block! We stand ready for whenever she has need of our strength.", ["objectivesText"] = "Check in with Baroness Draka back in the Seat of The Primus.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167044, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60050] = { ["id"] = 60050, ["name"] = "Trouble on the Western Front", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 59916, 60043, 60510, 61770, 61771, 61773 }, ["description"] = "The Ashbringer and your fellow Maldraxxi need reinforcements at the western gate. They are barely holding on! Xandria and my kin will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks, we cannot hope to achieve victory.", ["objectivesText"] = "Fly with Kynthia to report to Alexandros at the Stitchyard.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168860, ["x"] = 0.332, ["y"] = 0.302667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.302667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 9, ["flags"] = 0 } } },
[60051] = { ["id"] = 60051, ["name"] = "A Master of Their Craft", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60051 }, ["series"] = { 57531, 63056 }, ["description"] = "If we wish to get a travel network up and running, we'll need a master mirror maker in our employ. I've heard rumors that one such tradesman has landed himself in the Ember Ward. I am sure it won't take much cajoling to convince him to join our ranks. Head back into the Ember Ward and find this master mirror maker.", ["objectivesText"] = "Find Laurent in the Ember Ward.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 191784 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[60052] = { ["id"] = 60052, ["name"] = "Double Tap", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "The House of Rituals occupies the southern half of the temple. Unlike the constructs, their key advantage in battle is their endless army of risen fighters. Thankfully, the Archonic Resonator we recovered will take care of it. As we carve our way through their forces, blast their corpses with the resonator. Its energy will sunder their souls, preventing them from being raised to fight again.", ["objectivesText"] = "Use the Archonic Resonator to sunder 12 House of Rituals soldiers' corpses. Progress: We must ensure our foe stays dead, or our efforts will be futile.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167423, ["x"] = 0.395, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60053] = { ["id"] = 60053, ["name"] = "Clear as Crystal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "This Anima Conflux is completely drained of anima! Just a heavy hunk of metal! Not your fault, of course. Not at all. But we need to charge it! The Maldraxxi have extractors. Big green crystals, can't miss them. They're using it to drain anima from fallen kyrian. Very bad! We can use them to charge the conflux, then our colossus here will be functional again!", ["objectivesText"] = "Drain Necrotic Extractors to empower the Anima Conflux.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140, 237812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167135, ["x"] = 0.408, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167428, ["x"] = 0.398, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 6, ["flags"] = 0 } } },
[60054] = { ["id"] = 60054, ["name"] = "The Final Countdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "If the necromancer's brood descends upon us fully before the colossus is charged, we will perish. There is no question. We must keep his attention until Mikanikos's work is complete. He believes that the day is already won -- that we are pawns to be toyed with. We can use his hubris to our advantage to buy precious seconds. May it be enough.", ["objectivesText"] = "Delay Amarth the Harvester until the Colossus is fully charged.", ["rewardGold"] = 482040, ["rewardXP"] = 1770, ["rewardItems"] = { 173336, 173337, 173338, 173339, 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167423, ["x"] = 0.395, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167460, ["x"] = 0.39, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 7, ["flags"] = 0 } } },
[60055] = { ["id"] = 60055, ["name"] = "A Time for Courage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["series"] = { 60056, 61096 }, ["description"] = "I know not what awaits us across the chasm, outsider. By the Archon's grace I hope that my Paragon yet lives, but I fear the worst. We will face this great unknown together, as we have the rest of Maldraxxus's horrors. To be kyrian is to follow the path, no matter how dire the circumstances. Whatever happens, know that you have earned my undying respect this day.", ["objectivesText"] = "Confront Amarth the Harvester with Thanikos .", ["rewardGold"] = 482040, ["rewardXP"] = 1770, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167460, ["x"] = 0.39, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167583, ["x"] = 0.408, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 8, ["flags"] = 0 } } },
[60056] = { ["id"] = 60056, ["name"] = "Follow the Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60056, 61096, 61107 }, ["series"] = { 60055, 61096 }, ["description"] = "Maldraxxus must answer for their crimes against Bastion . There shall be justice! Let us go to Oribos and speak with the Tal-Inara , the Honored Voice. We will tell her what has transpired this day. Tell her that the kyrian will not stand idle against this aggression. Artemede will inform the Archon. My brothers and sisters will surely prepare for war. That must not come to pass.", ["objectivesText"] = "Inform Tal-Inara in Oribos of Maldraxxus's attack on Bastion . Progress: You looked troubled, outsider. What ails your mortal frame?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167583, ["x"] = 0.408, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1133, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1133, ["name"] = "Tidings of War", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60057] = { ["id"] = 60057, ["name"] = "Necrotic Wake: A Paragon's Plight", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60057 }, ["description"] = "Xandria, the mighty Paragon of Courage, is the finest warrior among all the ascended. But even she may be overwhelmed by the strongest of Maldraxxus' forces. Your fate is intertwined with hers, now. You must gather your allies and plunge into the Necrotic Wake to ensure both Amarth and Nalthor do not make it back to the safety of their realm. May the Archon guide your blade into their hearts.", ["objectivesText"] = "Defeat Amarth the Harvester and Nalthor the Rimebinder in the Necrotic Wake.", ["rewardGold"] = 1029600, ["rewardXP"] = 13630, ["rewardItems"] = { 184712, 184713, 184714, 184715 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167584, ["x"] = 0.408, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1187, ["name"] = "Necrotic Wake: A Paragon's Plight", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60060] = { ["id"] = 60060, ["name"] = "Mirror Attunement: Pridefall Hamlet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60060, 60147, 60159, 60160, 60164, 60165 }, ["description"] = "Work has been completed on a mirror that will allow travel between Sinfall and Pridefall Hamlet. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", ["objectivesText"] = "Enter the mirror in Pridefall Hamlet.", ["rewardGold"] = 31500, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1040, ["name"] = "The Mirror Network", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60061] = { ["id"] = 60061, ["name"] = "Tough as Silk", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60061 }, ["series"] = { 57661 }, ["description"] = "We are the heart of silk production in Ardenweald , but we can't do our work! Our grove has been completely taken over by spriggans and these strange shapeshifting... things. The silkstriders who spin the silk are very delicate creatures. They need peace and calm, and a little music to keep them happy! But with all these monsters all over the place, they're super stressed out. Please, can you get in there and eliminate these hooligans, and see if you can help get us up and running again?", ["objectivesText"] = "Slay attackers, save caretakers, and hatch silkstrider larvae in the Gossamer Cliffs. Progress: We need to get silk production running again, for Ardenweald !", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178138, 178143, 178144 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159270, ["x"] = 0.39, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159270, ["x"] = 0.39, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60062] = { ["id"] = 60062, ["name"] = "The Shattered Harp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60062 }, ["description"] = "<The harp lies broken, with pieces missing. Perhaps you can find more pieces, and get someone to repair it.>", ["objectivesText"] = "Find pieces of the broken harp . Progress: I lost my harp! It was taken and broken by those terrible creatures.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178138, 178143, 178144 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 167047, ["x"] = 0.38, ["y"] = 0.297 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.297 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60063] = { ["id"] = 60063, ["name"] = "A Song for Silkstriders", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60063 }, ["description"] = "There, the harp is fixed. I am too injured to take it to the silkstriders, but you are strong. You can help them. Our precious silkstriders are all across the cliffs. When you find one, play the harp for them, and they will give you fresh silk. Make sure that there is nothing nearby to stress them out first though! If you find yourself in need of a way to move about swiftly, just take a Silk Shooter there, next to me. Aim it where you want to go, and it will shoot silk to pull you there!", ["objectivesText"] = "Collect silk from the silkstriders by playing the harp for them. Progress: Were you able to help the poor silkstriders calm down, and get their silk?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 178138, 178143, 178144 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 167047, ["x"] = 0.38, ["y"] = 0.297 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 167047, ["x"] = 0.38, ["y"] = 0.297 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.297 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60064] = { ["id"] = 60064, ["name"] = "Save Ol' Gertie", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60064 }, ["series"] = { 60065 }, ["description"] = "We have to find Ol' Gertie! She is the broodmother of the silkstriders, and is our most reliable producer. We cannot lose her. But I cannot get to her and see if she is all right. She is usually at the top of the cliffs, at the highest point. Can you get up there, and make sure that she is safe? If she is not... then may justice fall swift and hard on the perpetrator.", ["objectivesText"] = "Slay Noisul of Many Faces Progress: Have you found Ol' Gertie? Is she safe?", ["rewardGold"] = 241020, ["rewardXP"] = 8165, ["rewardItems"] = { 178138, 178143, 178144 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 167047, ["x"] = 0.38, ["y"] = 0.297 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159388, ["x"] = 0.372, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.297 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60065] = { ["id"] = 60065, ["name"] = "Thread of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60065 }, ["series"] = { 60064 }, ["description"] = "<Gertie Jr. looks up at you with hope. Perhaps you can help get her to safety.>", ["objectivesText"] = "Deliver Gertie Jr. to Lillythistle.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175740, 178138, 178143, 178144, 179532, 179562, 181402, 181407, 181408, 181409, 181410, 181429, 181458, 181477, 181479, 181541, 183486, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159388, ["x"] = 0.372, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159270, ["x"] = 0.39, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60066] = { ["id"] = 60066, ["name"] = "Silk for Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60066 }, ["description"] = "It's clear that we may not be able to consistently supply Ardenweald with silk. But there is something that will help. Take Gertie Jr. and the silk you collected from the other silkstriders back to the Heart of the Forest. There, she will be safe, and perhaps grow up into a silkstrider as grand and beautiful as her mother!", ["objectivesText"] = "Bring Gertie Jr. to the Heart of the Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 178138, 178143, 178144 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159270, ["x"] = 0.39, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158556, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60067] = { ["id"] = 60067, ["name"] = "Pursuit of Justice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 60098, 61781 }, ["description"] = "Draka stands ready to unleash the power of the necropolis upon Gharmal. We need only buy her time to focus its weaponry. What we do now, we do for all of us. Bastion and Maldraxxus have both lost much to these fiends. Gharmal will not be defeated easily... but united, our forces will finally bring them to justice!", ["objectivesText"] = "Defeat Margrave Gharmal .", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 174294, 177055, 178158, 179945 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172002, ["x"] = 0.318, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173193, ["x"] = 0.31, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 15, ["flags"] = 0 } } },
[60092] = { ["id"] = 60092, ["name"] = "Skoldus Hall", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13400, ["storyline"] = { 60092 }, ["description"] = "<The object before you is emblazoned with runes, written in the language of domination. One of these runes reacts to your presence, lighting up with a bluish-gray light.> <It beckons you to touch it.>", ["objectivesText"] = "Enter Skoldus Hall and defeat its warden.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 161 },
[60096] = { ["id"] = 60096, ["name"] = "Wrath of the Lich King: To Northrend!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 84, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["description"] = "The Lich King stirs in the north. An undead army follows his command, marching across Northrend and spreading blight wherever they tread. We need you to stop them, <name>.", ["objectivesText"] = "Take a ship to Northrend. You can board the ship to Borean Tundra in Stormwind Harbor, or the ship to Howling Fjord in Wetlands.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60097] = { ["id"] = 60097, ["name"] = "Wrath of the Lich King: To Northrend!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 85, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["description"] = "The Lich King stirs in the north. An undead army follows his command, marching across Northrend and spreading blight wherever they tread. We need you to stop them, <name>.", ["objectivesText"] = "Take a zeppelin to Northrend. You can board the Howling Fjord zeppelin in Tirisfal Glades, or the Borean Tundra zeppelin in Orgrimmar.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60098] = { ["id"] = 60098, ["name"] = "The End is Now", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 60067, 61781 }, ["description"] = "Our forces have control of the House of Constructs, thanks to your intervention. Now, all that remains is to vanquish their treacherous leader--Margrave Gharmal. This battle has been long in the making, $p. I am at your side without hesitation. Let us confront this monster. We will join Xandria to see Gharmal slain.", ["objectivesText"] = "Meet with Xandria near the central chamber of the House of Constructs.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172002, ["x"] = 0.318, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 14, ["flags"] = 0 } } },
