[60139] = { ["id"] = 60139, ["name"] = "Torment Chamber: Jaina", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["description"] = "<Bolvar studies the objects you acquired from the brokers in Torghast.> I sense Lady Proudmoore's magic upon this debris. And these notes describe methods to contain her power. <The Highlord focuses on the items, peering into the darkness.> By the Light! They are tormenting her with white-hot fires. Though her will is strong, there is only so much any mortal can endure. I will modify Ve'nari's Attuned Shard using the items you returned. You must find her, $p. Before it is too late.", ["objectivesText"] = "Rescue Jaina Proudmoore from Torghast. Progress: You must find Jaina Proudmoore in Torghast.", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 184550 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60145] = { ["id"] = 60145, ["name"] = "Third Talon Vartox", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "This \"win the spirit of the people\" operation is noble and good. However, we must set our sights on cutting down our foe's tools. Third Talon Vartox , the leader of this incursion, also serves as the top stoneborn at the Tithelord's estate. If we strike her down here, the Tithelord will be left exposed for our attack.", ["objectivesText"] = "Kill Third Talon Vartox . Progress: Is Vartox dealt with?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60146] = { ["id"] = 60146, ["name"] = "Torment Chamber: Thrall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["series"] = { 62969 }, ["description"] = "Using the totem you recovered, I will alter the Attuned Shard to guide you to Thrall 's location. <Bolvar hands you the crystalline object.> Take care. You know the torments Baine and Lady Proudmoore endured in that accursed place. Thrall 's confinement will be no less harrowing. Beware. The deeper you journey into the Tower of the Damned, the closer you get to the Jailer himself. Free Thrall , <name>... before all hope is lost.", ["objectivesText"] = "Rescue Thrall from Torghast, Tower of the Damned. Progress: All our allies must be saved, <name>.", ["rewardGold"] = 1239200, ["rewardXP"] = 16330, ["rewardItems"] = { 184551 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 6, ["flags"] = 0 } } },
[60147] = { ["id"] = 60147, ["name"] = "Mirror Attunement: The Eternal Terrace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60060, 60147, 60159, 60160, 60164, 60165 }, ["description"] = "Work has been completed on a mirror that will allow travel between Sinfall and The Eternal Terrace. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", ["objectivesText"] = "Enter the mirror in The Eternal Terrace.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1040, ["name"] = "The Mirror Network", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60148] = { ["id"] = 60148, ["name"] = "No Place for the Living", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "A living mortal ... incredible! Forgive my astonishment. I am Kah-Delen, an overseer of the Arbiter's attendants here in the Eternal City of Oribos . You stand within the heart of the Shadowlands. While we are accustomed to receiving souls from all manner of worlds within the mortal realm, never before has one arrived that is quite so ... corporeal. Answer honestly, mortal. Did you truly escape the Maw?", ["objectivesText"] = "The Overseers want to know more about how you escaped the Maw. Progress: So where did you come from stranger?", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60149] = { ["id"] = 60149, ["name"] = "Audience with the Arbiter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "I am Tal-Inara , Honored Voice of the Arbiter. I speak for she who is ever silent. The Arbiter watches over Oribos . She blesses us with her wisdom. Every mortal soul that enters the Shadowlands passes before her for judgment. In the merest fraction of a moment, she sees every glory, every folly, every joy, every regret. With this knowledge, she chooses an ideal afterlife for that soul. At least, she did. Not long ago, catastrophe struck, and ... Come. Some things are better seen than explained.", ["objectivesText"] = "The Voice of the Arbiter wishes you to join them in the Arbiter's chamber. Progress: The Purpose guides us always.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60150] = { ["id"] = 60150, ["name"] = "Tether to Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "It is disappointing that you were unable to stir the Arbiter, but we must not give up hope. Your continued presence in the Shadowlands may help our cause. Perhaps your efforts would benefit from creating a tether to the mortal plane. The map table in this chamber was put in place long ago by the First Ones, the wise architects of all you see. If you have a memento from your homeworld, place it there. The table's magic can establish a connection.", ["objectivesText"] = "Affix the Helm of Domination fragment to the console.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60151] = { ["id"] = 60151, ["name"] = "A Doorway Through the Veil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "The Helm fragment connected us while you were in the Maw. As if through a darkened pane of glass, I saw glimpses of what you endured. The terrors you faced. At least the heroes of Azeroth yet live. They must be saved. By affixing the Helm here, you gave us a tether to Azeroth that served to bring a few of us across the veil. But you, and other heroes who join us, require a stronger connection. Our acolytes can open portals back. No doubt these attendants will be particular about their placement.", ["objectivesText"] = "Establish portals back to Azeroth. Progress: Have you helped the acolytes open the portals yet?", ["rewardGold"] = 170800, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60152] = { ["id"] = 60152, ["name"] = "The Eternal City", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "You should become familiar with the Eternal City and how best to navigate it. We, the attendants, serve Oribos as its caretakers. Everything you see here is done in service to the Purpose. In this time of chaos and drought, we must adapt our perspective. It seems we are to serve the Purpose in a new way. You mortals are not the only visitors here. Others have come as well. Like you, the brokers are not of Oribos . They are congenial and willing to aid you. Usually for a price.", ["objectivesText"] = "Tour the Eternal City of Oribos . Progress: Have you concluded your tour yet?", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60153] = { ["id"] = 60153, ["name"] = "Into the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 60153 }, ["description"] = "Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181430, 181457, 181458, 181459, 181477, 181479, 181541, 182469, 182605, 183132, 183167, 183466, 183473, 183479, 183482, 183485, 183487, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60154] = { ["id"] = 60154, ["name"] = "Understanding the Shadowlands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1671, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "As I sat upon the Frozen Throne all those years, <name>, I could peer into the Shadowlands. Brief glimpses, clouded and uncertain. Sights both wondrous and terrible. We must work together to make sense of what has happened. To prevent the Maw from consuming all of reality. Whatever Sylvanas and the Jailer want, we must stop them. But we cannot do so alone. Perhaps Tal-Inara can put us on the path to find answers.", ["objectivesText"] = "Speak to Tal-Inara . Progress: Let us align your path to the Purpose.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump