[60165] = { ["id"] = 60165, ["name"] = "Mirror Attunement: Feeders' Thicket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60060, 60147, 60159, 60160, 60164, 60165 }, ["description"] = "Work has been completed on a mirror that will allow travel between Sinfall and Feeders' Thicket. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", ["objectivesText"] = "Enter the mirror in Feeders' Thicket.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1040, ["name"] = "The Mirror Network", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60168] = { ["id"] = 60168, ["name"] = "The Art of Taming", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 59355, 59356, 60168, 85678 }, ["description"] = "I'm quite surprised to find this beast still alive and kicking. It appears to like you. Before we finish, you had better learn how to wrangle multiple pets. I'll give you one last lesson.", ["objectivesText"] = "Learn how to dismiss, tame, and stable pets from Austin Huxworth . Progress: Make sure to dismiss your pet before we get started. Oh, and if it's injured, use Revive Pet to bring it back.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 67, ["flags"] = 0 }, { ["id"] = 1076, ["name"] = "Classical Learning", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 23, ["flags"] = 0 } } },
[60169] = { ["id"] = 60169, ["name"] = "Securing the Area", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 59877, 60727 }, ["description"] = "The Scourge's attack was as sudden as it was unexpected. Truth be told, they caught us unawares. Through swift action, we were able to rally our defenses... though not before the tournament grounds were overrun. We must secure the area before we can mount a counteroffensive. Vanquish these monsters in the name of the Light!", ["objectivesText"] = "Remove 12 Scourge from the Argent Tournament Grounds.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60172] = { ["id"] = 60172, ["name"] = "This Quest is Temporary", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 60172 }, ["description"] = "Dropping out of the sky is a key part of this playtest, so enjoy the ride.", ["objectivesText"] = "Speak with Draedan to enter the Maw.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[60175] = { ["id"] = 60175, ["name"] = "A Taste of Tirna Noch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60175 }, ["description"] = "I'm a simple mushroom with simple pleasures, <name>. And what's simpler than a nice, hearty meal? Don't look so surprised. I need to eat just like anyone else! How else do you think I grew so big? Nice, tasty compost, that's how! Back in my day, I had the pick of Ardenweald for where to feed. Now, not so much. I've had a hankering for some of the loam that used to be around Tirna Noch. I haven't had shoots out there in a long time. Could you bring me some?", ["objectivesText"] = "Collect 6 Leafy Loam in Tirna Noch. Progress: Tirna Noch is a beautiful tree located east of Hibernal Hollow. You can't miss it.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 178215, 179513, 179517, 179532, 179562, 181405, 181406, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181477, 181479, 181511, 181541, 182335, 182466, 182621, 183467, 183473, 183478, 183490, 183505, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60176] = { ["id"] = 60176, ["name"] = "Bring Out Your Tithe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60176, 60177, 60178 }, ["description"] = "Unfortunately the Lord Chamberlain's gift isn't sufficient to cover the entire tithe we're expected to provide the Tithelord, but it will make a good start. The loss of the tithe convoy is a terrible blow to our village. Our little community is already suffering greatly from the drought and the need to meet the Tithelord's demands. Still we must all do our part. We have little time to accomplish this task. Can you help? Get the tithe from villagers and scour the area for every forgotten drop.", ["objectivesText"] = "Collect anima from the village for the tithe.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178565 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1145, ["name"] = "Tithes of Darkhaven", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60177] = { ["id"] = 60177, ["name"] = "Reason for the Treason", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60176, 60177, 60178 }, ["description"] = "If you ask me, the attack on our convoy is suspicious. I told Mistress Mihaela that there must be a traitor in the village, but she isn't concerned. It's understandable. She's got to worry about gathering a new tithe. I've taken it upon myself to figure this out and I could use your help. I'm making discreet inquiries but I can't be seen speaking with the help. That's where you come in. You can be my assistant sleuth.", ["objectivesText"] = "Speak with the \"help\" in the village to find clues leading to the identity of the traitor. Progress: Have you identified the traitor yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 178565 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167489, ["x"] = 0.617, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167489, ["x"] = 0.617, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1145, ["name"] = "Tithes of Darkhaven", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60178] = { ["id"] = 60178, ["name"] = "And Then There Were None", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60176, 60177, 60178 }, ["description"] = "Ilka and Samu argued, you say? And you found a coded message indicating that the tithe was going to be sent out soon. Those are helpful clues that will allow me to put the puzzle together. It's clear to me now who betrayed the village and what we need to do about it! You deliver invitations to a meeting to our suspects and I'll prepare to reveal the traitor.", ["objectivesText"] = "Gather the suspects and meet Lajos in the large crypt. Progress: The Master knows what's best for us. We must do our part.", ["rewardXP"] = 710, ["rewardItems"] = { 175737, 175766, 178565 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167489, ["x"] = 0.617, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168448, ["x"] = 0.612, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1145, ["name"] = "Tithes of Darkhaven", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60179] = { ["id"] = 60179, ["name"] = "Memory of Honor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "<A tablet sits embedded in the ground near a broken armor display. The runes on the epitaph conjure images of an ancient warrior in your mind. Clearly Maldraxxus honors the history of those who claimed great victories here. Similar memorials seem to be spread throughout the trench. Perhaps they can offer more insight into the denizens of this realm.>", ["objectivesText"] = "Read 3 Faded Epitaphs . Progress: Yes?", ["rewardGold"] = 295000, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 9, ["flags"] = 0 } } },
[60180] = { ["id"] = 60180, ["name"] = "A Paragon's Reflection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58843, 58980, 59196, 60013 }, ["description"] = "<The Vault-Keeper examines you.> You appear to carry a signature unique to one of the Paragons. If you know which Paragon, simply peer into their Soul Mirror to examine the memory of your choice. If you require anything else, you need only speak.", ["objectivesText"] = "Reveal the final memory. Progress: Did you find the memory you seek?", ["rewardGold"] = 477360, ["rewardXP"] = 1770, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167504, ["x"] = 0.563333, ["y"] = 0.673333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167504, ["x"] = 0.563333, ["y"] = 0.673333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.673333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 9, ["flags"] = 0 } } },
[60181] = { ["id"] = 60181, ["name"] = "Trench Warfare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "These would-be recruits seek a way to prove themselves. Let us give them the chance. The specter known as Malifis has grown in strength by consuming our anima reserves. In this time of drought, we cannot afford to lose any of our most precious resource. This threat needs to be dealt with immediately. Use this horn to signal the scavengers we've recruited. Let us see how well they fight under our banner!", ["objectivesText"] = "Use the Baron's Warhorn to defeat Malifis . Progress: Take care, our quarry is formidable.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 175739, 178496, 180827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 10, ["flags"] = 0 } } },
[60183] = { ["id"] = 60183, ["name"] = "After Them!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "We must move quickly! That anima will be key in fueling these citizens for the fight ahead. Deathfang is ready to ride.", ["objectivesText"] = "Board Deathfang and ride with Baroness Draka to stop the carriage.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167620, ["x"] = 0.615333, ["y"] = 0.695333 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60184] = { ["id"] = 60184, ["name"] = "Dude, Where's My Necropolis?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 60184 }, ["description"] = "Maintaining the portal between our sanctum and the Zerekriss is a difficult task. With enough resources, we could make it permanent and become the unstoppable force my baroness wishes us to be. She has asked much of you, as have I. But this work will make your name a legend among the Maldraxxi, as my baroness's has become. Help to empower us, and you will be empowered in turn.", ["objectivesText"] = "Upgrade your Sanctum's portal system to Rank 2.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard" },
[60188] = { ["id"] = 60188, ["name"] = "Go Beyond!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 60188 }, ["description"] = "Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 178464, 178465, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181420, 181421, 181422, 181423, 181424, 181425, 181427, 181428, 181429, 181430, 181457, 181459, 181461, 181477, 181479, 181541, 184381, 184382, 184383, 184384, 194371, 194372, 194376, 194393, 194416, 199461, 200960, 204076, 204586, 204594, 204602, 204610, 210024, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60189] = { ["id"] = 60189, ["name"] = "We Strike Now", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60108, 60189, 60190, 60191, 60192, 60193, 60194 }, ["description"] = "The time has come. The Wild Hunt has driven the Drust back to their stronghold at the edge of Ardenweald . Their scouts report that Gorak Zhar herself is among them. This may be our only opportunity to fully purge the minions of Thros from this realm. Lord Herne awaits your arrival at the battlefront. Go with haste, <name>.", ["objectivesText"] = "Meet Lord Herne outside of Darkreach.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 167686, ["x"] = 0.39, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1103, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1103, ["name"] = "Drust and Ashes", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60190] = { ["id"] = 60190, ["name"] = "Assault on Darkreach", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60108, 60189, 60190, 60191, 60192, 60193, 60194 }, ["series"] = { 60191, 60193 }, ["description"] = "The Drust have inflicted enormous loss on this forest and its denizens, <name>. It is time we put an end to their atrocities. We will drive the Drust from their enclave and close their gateway into Ardenweald . With you as our vanguard, victory is assured. I will make my way into the heart of their camp. Find me once you have routed their forces.", ["objectivesText"] = "Assault the Drust forces within Darkreach.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 167686, ["x"] = 0.39, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171838, ["x"] = 0.355, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1103, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1103, ["name"] = "Drust and Ashes", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60191] = { ["id"] = 60191, ["name"] = "Ingra Drif", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60108, 60189, 60190, 60191, 60192, 60193, 60194 }, ["series"] = { 60190, 60193 }, ["description"] = "Ingra Drif , the Drust captain, has been spotted inside Darkreach. This is our chance to destroy him for good. I know him and his cruelty all too well, <name>. Whatever you do to him, it's better than what he deserves.", ["objectivesText"] = "Slay Ingra Drif .", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172010, ["x"] = 0.37, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172010, ["x"] = 0.37, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1103, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1103, ["name"] = "Drust and Ashes", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60192] = { ["id"] = 60192, ["name"] = "Their Last Line of Defense", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60108, 60189, 60190, 60191, 60192, 60193, 60194 }, ["description"] = "Those sneaky Drust are protecting Gorak Zhar with their evil magic! I can sense several foul runes that are scattered across Darkreach. If you destroy them, we can easily shatter the barrier around that nasty Gorak Zhar. Hurry! I will meet you inside the enemy camp.", ["objectivesText"] = "Destroy Gorak Zhar's shielding runes .", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 167688, ["x"] = 0.37, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 167688, ["x"] = 0.37, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1103, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1103, ["name"] = "Drust and Ashes", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60193] = { ["id"] = 60193, ["name"] = "Unmasked", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60108, 60189, 60190, 60191, 60192, 60193, 60194 }, ["series"] = { 60190, 60191 }, ["description"] = "Thanks to your efforts, the shield that protects our prey has been made brittle as a dried leaf. Our hunt is all but complete. Come, let us put an end to the vile Gorak Zhar .", ["objectivesText"] = "Slay Gorak Zhar .", ["rewardGold"] = 514800, ["rewardXP"] = 8520, ["rewardItems"] = { 182251, 182260, 182269, 182278 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171838, ["x"] = 0.355, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171992, ["x"] = 0.362, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1103, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1103, ["name"] = "Drust and Ashes", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60194] = { ["id"] = 60194, ["name"] = "The Call of the Hunt", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60108, 60189, 60190, 60191, 60192, 60193, 60194 }, ["description"] = "I fear Lord Herne will have further need of our aid before this night is over. Come, I'll put some wings on you. We'll have to fly if we want to keep up with him.", ["objectivesText"] = "Speak to Lord Herne in Ardenweald .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171992, ["x"] = 0.362, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172091, ["x"] = 0.39, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1103, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1103, ["name"] = "Drust and Ashes", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60195] = { ["id"] = 60195, ["name"] = "Build One More", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60195 }, ["description"] = "All these souls deserve a new construct, and when rebuilt any of them will make a valuable addition to our forces. We must start somewhere. You should be able to find Malleable Flesh through out the Shadowlands. A few of the other parts may be harder to locate. Collect parts and use the Abominable Stitching Table to build another construct.", ["objectivesText"] = "Build one new construct. Progress: Remember, you can find parts from almost anything in Maldraxxus.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 183830 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
