[60268] = { ["id"] = 60268, ["name"] = "Deep Within", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1912, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["description"] = "Who... who are you? Have you come to extract more of my memories? I'm afraid there aren't any useful ones left, save for the memories of my imprisonment. Or perhaps you're here for something else?", ["objectivesText"] = "Speak with the prisoner and learn of his situation. Progress: What do you want of me?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 153, ["title"] = "9.0 Covenant Campaigns Ch 2 - Torghast", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 