[60270] = { ["id"] = 60270, ["name"] = "A Damned Pact", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 60271, 60272 }, ["description"] = "Yes... I begin to remember. Power. Power with a purpose. That is what I can offer. Runes. Runes are the key. I've recalled some of them, but to infuse them into your equipment, I require my hands. Well, one hand would suffice. Both would be better. Find a way to free me from my bonds, mortal. Then I can offer the power you seek. After that, freedom... and perhaps the downfall of the one who bound me.", ["objectivesText"] = "Discover a way to break the Runecarver free from his chains.", ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 149, ["title"] = "Int