[60272] = { ["id"] = 60272, ["name"] = "The Weak Link", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 60270, 60271 }, ["description"] = "This ought to be enough to break the bonds that hold your newfound ally. < Ve'nari pauses for a moment.> Before you do so, I offer a word of warning. No creature imprisoned in that place should be trusted. Tread carefully, mortal. After all, it would be a shame to lose so valuable a business partner.", ["objectivesText"] = "Break the Runecarver free. Progress: It's good to remember something new again.", ["rewardGold"] = 28090, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1210, [