] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1123, ["name"] = "Return to the Maw", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1238, ["name"] = "The Maw", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60288] = { ["id"] = 60288, ["name"] = "Supplies from the Necrolords", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "emissary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60288 }, ["description"] = "<name>, thanks to your efforts, our forces have been able to secure additional resources in our battles. The more you continue to dominate the battlefield the more resources our forces can spare.", ["objectivesText"] = "Speak with Oyne Soulborn at the Bleak Redoubt in Maldraxxus for your reward.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60289] = { ["id"] = 60289, ["name"] = "Rule 3: Trust is Earned", ["level"] = 55, ["requiredLevel"] = 55, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 58160, 60287, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Before you leave this cursed realm, there is one final task you must complete for me. The Mawsworn regularly transfer souls to various blocks of Torghast from many different areas in the Maw . I happen to know of one such area. Place this beacon there so I may be informed when the next transfer happens. And if you are seen by the enemy... well, you are known for your prowess in combat, yes?", ["objectivesText"] = "Place a Signaling Beacon in Cocyrus. Progress: I will have opportunities for trade in the future, Maw Walker. I am certain our paths will cross again.", ["rewardGold"] = 514800, ["rewardXP"] = 9365, ["rewardItems"] = { 184284 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id