[60575] = { ["id"] = 60575, ["name"] = "Belly Full of Fae", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "The local flora have gone somewhat wild during this anima drought. It seems they swallowed most of the young fae who were tending to the wildseeds here. At least now we know where they've been. Oh, don't worry. This isn't the first time this has happened. We can last quite a while inside those plants. Take my dagger. Use it to cut through the shrubbery and free the other wildseed tenders .", ["objectivesText"] = "Free 16 Wildseed Tenders from inside Devouring Hydra. Progress: How goes the gardening?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 175671, 175672, 175673, 175674, 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169202, ["x"] = 0.614, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169217, ["x"] = 0.622, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60577] = { ["id"] = 60577, ["name"] = "Hungry for Animacones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "I have to apologize for the state of the Tranquil Pools. Normally, it's quite peaceful here. The wildseed tenders tell me that the plants you see walking around have eaten all the animacones intended for use in Tirna Vaal. Could you rip the animacones out of those plants? We have wildseeds that are in need of that anima.", ["objectivesText"] = "Recover 25 Animacones from Gobbling Blossoms. Progress: Have you found the animacones ? They're still useful, even if they're a little slimy. Trust me, the spirits don't mind as long as they get their anima.", ["rewardGold"] = 331700, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169202, ["x"] = 0.614, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169217, ["x"] = 0.622, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60578] = { ["id"] = 60578, ["name"] = "Visions of the Dreamer: The Betrayal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58590, 58593 }, ["description"] = "I sense that in the spirit's vision, she struggles with the memory of a betrayal that is truly profound. Someone as close to her as a brother, turned to an enemy. Go to the second Dreamshrine in the Basin, and help vanquish the pain of this nightmare.", ["objectivesText"] = "Grapple with the Dreamer's vision of a great betrayal. If you leave the Vision, interact with a Dreamer's vision portal in Dreamshrine Basin to enter again. Progress: Have you seen what dreams have come?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 5, ["flags"] = 0 } } },
