[60594] = { ["id"] = 60594, ["name"] = "One Special Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "You've been a huge help to Tirna Vaal. I need to bring this anima to one of our newest wildseeds. I'd love for you to come with me. It's only fair, since you're the one who recovered the animacones. I'm quite excited for you! Let's go.", ["objectivesText"] = "Go with Dreamweaver to feed anima to the wildseed in Tirna Vaal. Progress: The howling wind becomes a gentle breeze. All is well once again.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 176445, 179921, 179922, 179978, 179983 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169217, ["x"] = 0.622, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 6, ["flags"] = 0 } } },
