[60600] = { ["id"] = 60600, ["name"] = "Preparing for the Winter Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Tirna Vaal is ready for the Winter Queen's arrival! And it's all thanks to you. You have more than upheld your end of our bargain... and yet I was not able to do the same. That is absolutely unacceptable for a faerie like me! What would the others think if they knew I had failed to honor our agreement? Please, allow me to make it up to you. I may not have been able to deliver your message to the Queen, but I have a special surprise that I hope you'll accept instead!", ["objectivesText"] = "Receive Ardenweald 's essence from Lady Moonberry . Progress: Joy follows Lady Moonberry , a scent that lingers as a flower blooms.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169031, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 0, ["flags"] = 0 } } },
