[60605] = { ["id"] = 60605, ["name"] = "Glimmerfin Scale", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 114, ["storyline"] = { 60605 }, ["series"] = { 60606, 60614, 60615, 60616, 60617, 60619, 60620 }, ["description"] = "<A brightly-colored scale fell to the ground as the murloc ran off. It was unlike any other murloc you've seen in Northrend. Perhaps King Mrgl-Mrgl would know more about this new species?>", ["objectivesText"] = "Show the scale to King Mrgl-Mrgl in Borean Tundra.", ["rewardGold"] = 236900, ["rewardXP"] = 150, ["rewardItems"] = { 5512, 5996, 97919, 158149, 180026, 180034 }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 25197, ["x"] = 0.435, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60606] = { ["id"] = 60606, ["name"] = "Glimmerfin Welcome", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 114, ["storyline"] = { 60606 }, ["series"] = { 60605, 60614, 60615, 60616, 60617, 60619, 60620 }, ["description"] = "First thing's first, they're probably hungry. Life up here in the cold isn't quite as easy as it is elsewhere, and even the most acclimated murlocs sometimes have trouble finding food. We're going to need to feed them, but also help them find food for themselves. They're already watching you, so search the area around where you found the murlocs for food sources and show them what to hunt. Then bring the meat to their leader--just look for the biggest one.", ["objectivesText"] = "Collect 10 Meaty Crab Chunks and deliver them to Glimmergut in Venture Bay. Progress: Mrgg?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 5996, 133755, 180010, 180026, 180034 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 25197, ["x"] = 0.435, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169414, ["x"] = 0.178, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 114, 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60609] = { ["id"] = 60609, ["name"] = "Who Devours the Devourers?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60609 }, ["objectivesText"] = "Devourer Rifts closed Resonating Anima Core created from motes", ["rewardXP"] = 8165, ["rewardItems"] = { 180008, 180009 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Devourer Rifts closed", ["amount"] = 5, ["type"] = 0, ["objectID"] = 169444, ["orderIndex"] = 0 }, { ["text"] = "Resonating Anima Core created from motes", ["amount"] = 1, ["type"] = 0, ["objectID"] = 175539, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[60614] = { ["id"] = 60614, ["name"] = "A Big Horkin' Task", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 60614 }, ["series"] = { 60605, 60606, 60615, 60616, 60617, 60619, 60620 }, ["description"] = "< Glimmergut begins to draw in the sand. The murloc traces the outline of what appears to be a large seal. He points at the picture, then upwards, indicating that the creature must be somewhere on the surface of the water. The murloc then digs a small, shallow hole in the sand, and points at it several times.> Mrg! Mrg! Grml. <He cocks his head expectantly.>", ["objectivesText"] = "Collect one Pile of Blubberfat and deliver it to Glimmergut in Venture Bay. Progress: Grmgr?", ["rewardGold"] = 315900, ["rewardXP"] = 200, ["rewardItems"] = { 5996, 180025, 180026, 180034 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 169414, ["x"] = 0.178, ["y"] = 0.932 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169414, ["x"] = 0.178, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.178, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60615] = { ["id"] = 60615, ["name"] = "Seer of the Waves", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 60615 }, ["series"] = { 60605, 60606, 60614, 60616, 60617, 60619, 60620 }, ["description"] = "< Glimmergut points across the ship. He wants you to take the blubber to someone.> Mrg m'grrl.", ["objectivesText"] = "Deliver the Blubberfat to the Glimmerfin Oracle .", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 5996, 180026, 180034 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 169414, ["x"] = 0.178, ["y"] = 0.932 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.178, ["y"] = 0.932 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60616] = { ["id"] = 60616, ["name"] = "Pearl in the Deeps", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 60616 }, ["series"] = { 60605, 60606, 60614, 60615, 60617, 60619, 60620 }, ["description"] = "<The oracle draws a circle in the sand, then points down into the deeps. There is something round down there that she is after, perhaps a pearl or stone? The oracle motions for you to wait a moment before you leave. She waves her hands around frantically, then places them under her mouth, mimicking two large fangs. You take this as a warning that there may be something waiting for you in the icy darkness.>", ["objectivesText"] = "Collect the Giant Pearl and deliver it to the Glimmerfin Oracle . Progress: <The oracle looks at you.>", ["rewardGold"] = 236900, ["rewardXP"] = 150, ["rewardItems"] = { 5996, 180026, 180034 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.17, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60617] = { ["id"] = 60617, ["name"] = "Trainer's Test", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 60617 }, ["series"] = { 60605, 60606, 60614, 60615, 60616, 60619, 60620 }, ["description"] = "<The oracle finishes peering into the pearl and turns to face you. She appears to be deep in thought, staring directly at you and blinking a few times. Finally, she nods. The oracle points at you, then points upwards. She places a hand a small distance above the ground, indicating something pet-sized. Your surmise that there may be test of your connection with your battle pets ahead.>", ["objectivesText"] = "Defeat Trainer Grrglin in a pet battle. Progress: <The oracle looks very excited.>", ["rewardGold"] = 315900, ["rewardXP"] = 200, ["rewardItems"] = { 5996, 136920, 180026, 180034 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.17, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60619] = { ["id"] = 60619, ["name"] = "Wrap it Up", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 60619 }, ["series"] = { 60605, 60606, 60614, 60615, 60616, 60617, 60620 }, ["description"] = "<The seems quite excited about the presence of the new egg. You get the sense that this is an important occasion for these murlocs--there may be few eggs left. The oracle waves a small piece of seaweed in front of you, showing you the young buds of the immature plant. She warps the seaweed around a small part of the egg, then points at you, then back at the wrapped seaweed. It appears that the egg needs to be wrapped in more immature seaweed stalks.>", ["objectivesText"] = "Collect a Warm Seaweed Stalk , a Young Seaweed Stalk , and a Bulbous Seaweed Stalk and deliver them to the Glimmerfin Oracle . Progress: <The oracle blinks at you.>", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 5996, 21191, 21310, 40585, 63206, 65274, 180026, 180031, 180032, 180033, 180034 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.17, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[60620] = { ["id"] = 60620, ["name"] = "Guardian of the Smallest", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 60620 }, ["series"] = { 60605, 60606, 60614, 60615, 60616, 60617, 60619 }, ["description"] = "<The oracle pats you on the shoulder, and seems quite pleased with all that you've done. She holds up one finger, then spreads her hands wide and emits a terrible roar-like murgle. She points outside, then at you, then your weapon, then nods seriously. There must be one more trial to await you. It would appear to be a test of strength.>", ["objectivesText"] = "Slay Great Mua'kin and return to the Glimmerfin Oracle . Progress: <The oracle claps excitedly.>", ["rewardGold"] = 631800, ["rewardXP"] = 250, ["rewardItems"] = { 5996, 180026, 180034 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 169415, ["x"] = 0.17, ["y"] = 0.938 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.17, ["y"] = 0.938 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "group", ["db2QuestSortName"] = "Battle Pets" },
[60621] = { ["id"] = 60621, ["name"] = "Enemies at the Gates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58719, 58720, 58869 }, ["description"] = "Lorkron is here. I tracked him all the way from the Glittering Falls. Then I saw the Drust try to flank our forces. I'd say they were rather surprised that we turned the tables against them. <Korayn's smile is fierce. She lifts her weapon and her voice to address all present.> Huntsmen and huntresses, with me! We ride to defend the grove! Take no prisoners and leave none standing!", ["objectivesText"] = "Reach Droman Aliothe in Hibernal Hollow.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162541, ["x"] = 0.570667, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169541, ["x"] = 0.598, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.570667, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60622] = { ["id"] = 60622, ["name"] = "Eye of the Scryer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60622 }, ["description"] = "Evading the Mawsworn's scryers requires powerful magical countermeasures. The prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance. The scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye. Restraint is advised in its procurement.", ["objectivesText"] = "Obtain the Eye of the Scryer from Leerok the Scryer in The Maw . Progress: Well? Do you have it, undamaged?", ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883, 180035, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60623] = { ["id"] = 60623, ["name"] = "AHHH! Real Monsters!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60623 }, ["objectivesText"] = "Repel the Devourer threat", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the Devourer threat", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60624] = { ["id"] = 60624, ["name"] = "Ride to Heartwood Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "A storm of strife and fear rains down upon Heartwood Grove. Sylvar flee from the flood. Brave the torrent astride a stag. Becalm the deluge and be the salvation of those who would drown. Make haste. Time wanes.", ["objectivesText"] = "Ride a stag to Heartwood Grove.", ["rewardGold"] = 34475, ["rewardXP"] = 710, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169686, ["x"] = 0.669, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60628] = { ["id"] = 60628, ["name"] = "The Missing Hunters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["description"] = "Strange creatures have been seen lurking just outside the grove. Terrible, ugly things. Whatever they might be, they are not native to Ardenweald . It does not matter how they breached our borders, though. Every one of them must be eliminated. I sent my best huntsmen and huntresses to slay them, but not one has returned. See if you can determine what has delayed them.", ["objectivesText"] = "Find Jynkla , Serinkai , Rondar , and Ara'lon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 180061 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60629] = { ["id"] = 60629, ["name"] = "Extreme Recycling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["description"] = "The Wild Hunt serves the Winter Queen under the leadership of Lord Herne. We are elite fighters, hunters, and trackers. But we cannot fight without weapons and supplies. The droman here informs me that there are severe obstacles to their delivery. I do not have time to wait. We need equipment, and we need it now. See what you can scavenge from the field. A broken weapon can always be mended and put to use again.", ["objectivesText"] = "Slay the Blighted and take their weapons. Progress: Did you find anything of use out there?", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 180061 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60630] = { ["id"] = 60630, ["name"] = "Totem Eclipse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["series"] = { 60519, 60520, 60521, 60522, 60631, 60632 }, ["description"] = "I can smell our foes' dark magic, twisting the air and muddling my mind. They are up to something. Bringing awful powers into Ardenweald . If you see any of their totems, destroy them immediately. I always feel better after smashing something to pieces, don't you?", ["objectivesText"] = "Destroy Foul Totems . Progress: What terrible magic has been brought into Ardenweald ?", ["rewardGold"] = 248040, ["rewardXP"] = 1415, ["rewardItems"] = { 180061 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60631] = { ["id"] = 60631, ["name"] = "Big Problem, Little Vorkai", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["series"] = { 60519, 60520, 60521, 60522, 60630, 60632 }, ["description"] = "Ara'lon's report matches what I have seen. Too many enemies, and too few of the Wild Hunt to dispose of them on our own. Fortunately, I feel strongly inclined to take matters into my own hands. And avenge my fallen hunters. Let us depart. We will show those monsters the fury of nature.", ["objectivesText"] = "Slay Blighted with Korayn. Progress: Ardenweald will endure.", ["rewardGold"] = 248040, ["rewardXP"] = 1415, ["rewardItems"] = { 180061 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60632] = { ["id"] = 60632, ["name"] = "I Know Your Face", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["series"] = { 60519, 60520, 60521, 60522, 60630, 60631 }, ["description"] = "This voice... I have heard it before. Though it is distorted and vengeful now. He hunts us. But I am not prey. And I will not let him gloat over his slain quarry. That is not the way of the Wild Hunt. Though he may draw us to ground of his choosing, we will fight him. And we will win. Are you with me?", ["objectivesText"] = "Defeat Lorkron the Hunter .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 175667, 175668, 175669, 175670, 180061 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169935, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60637] = { ["id"] = 60637, ["name"] = "The End of Former Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Heartwood Grove was to give up its anima so that other groves could survive. But then... I started seeing these masks on many of the other fae. Soon, everyone was wearing them. I don't know what has come over them, but it's clear they mean us harm. Please... you have to... They aren't the friends I once knew. Not anymore.", ["objectivesText"] = "Slay 8 possessed creatures in Heartwood Grove.", ["rewardGold"] = 248040, ["rewardXP"] = 1415, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169686, ["x"] = 0.669, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169748, ["x"] = 0.684, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60638] = { ["id"] = 60638, ["name"] = "Recovering Wildseeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "One of my tasks in Heartwood Grove was to tend to the wildseeds. Some were chosen to be brought back to Tirna Vaal. But now the masked fae are draining the anima from them! We need to save the ones that remain. I beg of you, recover any surviving wildseeds you can find. The spirits within them were chosen to be reborn. I won't let them wither away!", ["objectivesText"] = "Recover 6 Drained wildseeds in the Heartwood Grove. Progress: We need to split up and rescue as many wildseeds as we can.", ["rewardGold"] = 221280, ["rewardXP"] = 1415, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169686, ["x"] = 0.669, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169748, ["x"] = 0.684, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60639] = { ["id"] = 60639, ["name"] = "Heart of the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "We were supposed to take the heart of the grove to Tirna Vaal when we left this place to wither. The masked fae struck before that could happen. They must be after the heart of the grove! The heart contains all of the anima that was meant to save the other groves. We can't afford to lose it. Can you secure it? I need to find Korenth , one of our healers. His skills will help any survivors we find.", ["objectivesText"] = "Bring the Heart of the Grove to Tirna Vaal. Progress: Do you have the heart of the grove?", ["rewardGold"] = 124020, ["rewardXP"] = 710, ["rewardItems"] = { 175713, 175740, 179500, 179508, 179517, 179537, 179547, 179562, 179584, 179604, 180126, 180172, 181407, 181409, 181410, 181418, 181422, 181423, 181424, 181425, 181430, 181457, 181458, 181459, 181477, 181479, 181506, 181541, 182480, 182649, 183167, 183468, 183469, 183473, 183486, 183489, 184381, 184382, 184383, 184384, 184587 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169686, ["x"] = 0.669, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169748, ["x"] = 0.684, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60640] = { ["id"] = 60640, ["name"] = "Regrowth of the Grove", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["description"] = "The grove thrives, my mortal friend, but there is yet room for it to grow. With enough anima, it can nourish even more wildseeds at once. Each one is a spirit that might otherwise be lost forever. Speak with Zayhad once again, and see to the regrowth of the conservatory.", ["objectivesText"] = "Upgrade the Queen's Conservatory to Tier Three.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 6, ["flags"] = 0 } } },
[60641] = { ["id"] = 60641, ["name"] = "Blossoming of the Grove", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["description"] = "The conservatory grows hearty and hale. Now, it must blossom anew. Though it requires much in the way of anima, every additional spirit that the conservatory rebirths returns your generosity tenfold. Confer with Zayhad, so that this conservatory may grow ever larger.", ["objectivesText"] = "Upgrade the Queen's Conservatory to Tier Four", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 7, ["flags"] = 0 } } },
[60642] = { ["id"] = 60642, ["name"] = "The Grove Resplendent", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["description"] = "You have done much to return the conservatory to its former splendor. In ages past, this grove was a place of convalescence for spirits who were wounded upon their demise, and needed special care before being reborn. It was a place rarely used... but now, it is critical to the continuation of the cycle. Tell Zayhad that the time has come. The Queen's Conservatory must thrive for the good of Ardenweald.", ["objectivesText"] = "Upgrade the Queen's Conservatory to Tier Five", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 8, ["flags"] = 0 } } },
[60644] = { ["id"] = 60644, ["name"] = "Draw Out the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59751, 59752, 59753, 59757, 59758, 59765, 59766, 59907, 60644, 61874 }, ["description"] = "Now that we have the dagger, it will take the combined will of all of us to sever the weapon's link to the High Chieftain. Jaina, Anduin, and I must do our part to keep Baine's spirit grounded, so it will be up to you to deal with whatever force is unleashed when the blade is broken. Are you up to the task?", ["objectivesText"] = "Draw out and defeat the Withering Presence in Detrithos.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 168162, ["x"] = 0.313, ["y"] = 0.441 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.313, ["y"] = 0.441 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 21, ["flags"] = 0 } } },
[60645] = { ["id"] = 60645, ["name"] = "Gargantuan Seeker", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60645 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 4210, ["db2VignetteName"] = "Gargantuan Seeker" },
[60646] = { ["id"] = 60646, ["name"] = "Misery Business", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60646 }, ["description"] = "The Mawsworn have begun harvesting the misery of the souls flowing through Gorgoa, the river of souls. Why? I do not know yet. But it behooves us to stop them. Destroy the conduits that they deposit the misery into and bring me some samples of their work. Perhaps with some research, I can discern their intentions.", ["objectivesText"] = "Collect 10 Essences of Misery and destroy the Misery Conduits. Progress: Have you halted their misery?", ["rewardItems"] = { 177698, 178874, 178881, 178882, 180129, 184614, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60647] = { ["id"] = 60647, ["name"] = "Recovering the Animacones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "The grove's droman is wearing one of the masks. I fear he's going to drain all of the anima from the grove's heart! That anima is meant for the forest's other groves. If we lose it... then Heartwood Grove would have been lost for nothing... We'll carve a path to the Shrouded Mire to find the droman before it's too late. Many of these masked fae have stolen Heartwood Grove's animacones . We must recover them along the way. In this drought, every bit of anima is precious.", ["objectivesText"] = "Recover 25 animacones from the Possessed. Progress: We can't let the possessed take anything else from us.", ["rewardGold"] = 248040, ["rewardXP"] = 1415, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169748, ["x"] = 0.684, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60648] = { ["id"] = 60648, ["name"] = "Survivors of Heartwood Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Korenth... I can't believe he's... We have to save whomever we can. Droman Krelnor is too strong for us to face alone. I saw a few other survivors scattered around the grove. Hurry, we have no time to waste!", ["objectivesText"] = "Rescue Casad, Wagonmaster Derawyn , and Te'zan from the possessed. Progress: We must rescue my friends!", ["rewardGold"] = 248040, ["rewardXP"] = 1415, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169748, ["x"] = 0.684, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 6, ["flags"] = 0 } } },
