[60660] = { ["id"] = 60660, ["name"] = "Flight Test", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60660 }, ["series"] = { 59262, 59263, 59311, 59348, 59351, 59865 }, ["description"] = "I fix these to my arms... then they become wings, yes? Then I jump off cliff. And fly! You watch?", ["objectivesText"] = "Observe Kowalskos ' test flight. Progress: Did you watch me?", ["rewardGold"] = 289575, ["rewardXP"] = 6125, ["rewardItems"] = { 175791, 175792, 175967, 175968, 176812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[60661] = { ["id"] = 60661, ["name"] = "Dying Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58721 }, ["description"] = "We have lost so much... and this one is special. <Moonberry looks at you, resolute. Her voice is strangely formal, her manner commanding.> Come, <name>. We will carry her on the Path of Rebirth and entreat the Queen to save her. Hurry and make preparations. We have little time.", ["objectivesText"] = "Take Ysera's wildseed to the Heart of the Forest.", ["rewardGold"] = 126360, ["rewardXP"] = 710, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161847, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169869, ["x"] = 0.466, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60669] = { ["id"] = 60669, ["name"] = "Cause for Distraction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60670, 60725, 60759, 60761 }, ["description"] = "The Horde has come under siege, $p. The undead Scourge rises like a grim tide, in numbers not seen since Arthas Menethil sat upon the frozen throne. And as if that were not concerning enough... something terrible has occurred. What I am about to tell you, I share in the strictest confidence. This information will be known by all soon enough, but I needed to speak with you directly first. Allow me to explain.", ["objectivesText"] = "Speak with Lor'themar Theron atop Grommash Hold in Orgrimmar. Progress: There is much to discuss.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488667, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60670] = { ["id"] = 60670, ["name"] = "Return of the Crusade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60725, 60759, 60761 }, ["description"] = "I have witnessed the relentless advance of the Scourge firsthand. It is only a matter of time before they swarm our gates. The fate that befell Silvermoon must never be repeated. Death knights from the Ebon Blade have stepped forward to combat the threat, but even they will need reinforcements. The Argent Crusade has answered the call once more. I ask that you aid them in keeping our people safe, <name>. Their commander awaits your arrival.", ["objectivesText"] = "Speak with Commander Throgg in the Valley of Strength in Orgrimmar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 33447 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488667, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 2, ["flags"] = 0 } } },
[60671] = { ["id"] = 60671, ["name"] = "The Sacrifices We Must Make", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Hurry! We can use the animacones we gathered to save Derawyn. I know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.", ["objectivesText"] = "Use the recovered animacones to save Wagonmaster Derawyn .", ["rewardGold"] = 124020, ["rewardXP"] = 710, ["rewardItems"] = { 180126, 180172 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169985, ["x"] = 0.662, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 7, ["flags"] = 0 } } },
[60673] = { ["id"] = 60673, ["name"] = "The Traitor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Right, looks like I should let you in now. Can't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that. Wonder what happened to her. Denathrius seemed awfully upset when they last spoke. Anyways, let me just get that door open for ya.", ["objectivesText"] = "Kill Sinkeeper Mateo and collect his mirror shard. Progress: Do you have Mateo's mirror shard ?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 22980, 22982, 22984, 22995, 44358, 44359, 44360, 44361, 59171, 59172, 59173, 63912, 63913, 63914, 63915, 63916, 113232, 113233, 113234, 113235, 131466, 155462, 155471, 155479, 155487, 156941, 158599, 158600, 158601, 158602, 174092, 180900, 180913, 180914, 180915, 182251, 182260, 182269, 182278, 237812, 248065, 248069, 250355, 251330, 251548 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161298, ["x"] = 0.775, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 9, ["flags"] = 0 } } },
[60709] = { ["id"] = 60709, ["name"] = "Recovering the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Darkness grasps the heart of Droman Krelnor, as he grasps the heart of the grove. Anima drains from the heart, nectar taken from ripened fruit. It must be stopped. Foul magic bars the way. Anima in peril, anima the salvation. Beseech Te'zan . An old soul, brimming with anima, the spark to ignite our hope.", ["objectivesText"] = "Speak with Te'zan to break down the droman's barrier, then confront Droman Krelnor.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169956, ["x"] = 0.662, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170012, ["x"] = 0.654, ["y"] = 0.266 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 8, ["flags"] = 0 } } },
[60721] = { ["id"] = 60721, ["name"] = "The Anima Must Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 60721 }, ["series"] = { 63066 }, ["description"] = "This device you see here can be used to send anima to the thirsting wards, aiding our people. As each ward regains its flow of anima, it will begin to flourish. You may find those that live there ready to aid you in your journeys, or you may even find new challenges that await you. Once you have brought some anima to our sanctum, use the device to direct it to a ward, and see the results for yourself.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Revendreth.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[60722] = { ["id"] = 60722, ["name"] = "Tower Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 60722 }, ["series"] = { 63057 }, ["description"] = "This device is used to channel anima to our towers across Maldraxxus, empowering our forces stationed at them. Though you may find the support they offer useful, bear in mind that the anima will likely attract the attention of our foes. Use the device to direct our stores of anima toward one of our towers. You will soon see what true power can accomplish.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Maldraxxus. Progress: The anima must flow!", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 142342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard" },
[60723] = { ["id"] = 60723, ["name"] = "The Roots Thirst", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 60723 }, ["series"] = { 63067 }, ["description"] = "This device can soak the roots of our great canopy in anima. The branches thirst for it. As each of the great trunks is filled with anima, it will begin to bloom once more. You may find those under its boughs ready to aid you, or you may find new challenges that await you in the shade. Now, bring anima to the sanctum, and use the device to direct it out into the weald. Let the blooms flourish once more.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Ardenweald. Progress: The leaves shake in anticipation.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[60724] = { ["id"] = 60724, ["name"] = "Heartless", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "So many of my friends have returned to the cycle... all because of those strange masks. Why did they take my friends? What was the point of destroying the heart of my grove? You have to return to Tirna Vaal and tell Droman Tashmur what happened here. I'll make my way there eventually. I just... need some time to say goodbye.", ["objectivesText"] = "Return to Droman Tashmur in Tirna Vaal.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 175648, 175649, 175650, 175651, 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170012, ["x"] = 0.654, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 9, ["flags"] = 0 } } },
[60725] = { ["id"] = 60725, ["name"] = "Field Reports", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60670, 60759, 60761 }, ["description"] = "We cannot anticipate where and when the Scourge will strike. In order to mount a defense, the Argent Crusade has set up outposts at several key locations. But we have yet to receive word from them. Seek out my field officers along the southern road. I expect a full report when you return.", ["objectivesText"] = "Gather reports from officers in Durotar and the Barrens. Progress: Reinforcements? Thank the Light!", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["rewardItems"] = { 180231, 180232, 180233 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 10, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60727] = { ["id"] = 60727, ["name"] = "A Message from Icecrown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59877, 60169 }, ["description"] = "Our forces in Northrend have sent word. Justicar Trueheart requests our immediate assistance. We must respond to this summons at once, no matter what terrors await us in Icecrown. A <class> like you would do much to bolster our chances on the battlefield. You have my word that Orgrimmar will be protected in your absence. Battle calls, <name>. I trust you are ready.", ["objectivesText"] = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 46874 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 85, 118 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 6, ["flags"] = 0 } } },
[60732] = { ["id"] = 60732, ["name"] = "Disrupting the Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60732 }, ["description"] = "<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served. The complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done. Send the inhabitants of Zovaal's Cauldron a message.>", ["objectivesText"] = "Disrupt the Mawsworn's efforts in Zovaal's Cauldron.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176164, ["x"] = 0.394, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60733] = { ["id"] = 60733, ["name"] = "Front and Center", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The runes on that blade... they are the same as the ones etched on the door to the Seat of the Primus. And one of them just began to glow... Is this what I think it is, $p? Do you have the means to unseal the Seat? If so, then perhaps Vyraz's gambit was not for nothing. This could turn the tide of the entire war!", ["objectivesText"] = "Empower the Rune of Might at the Seat of the Primus. Progress: Come! Victory awaits!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 170094, ["x"] = 0.376, ["y"] = 0.29 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 14, ["flags"] = 0 } } },
[60735] = { ["id"] = 60735, ["name"] = "Trouble in Paradise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57261, 57584 }, ["description"] = "I have given your presence here some thought, <name>. It is clear to me that you are no ordinary arrival from Oribos. I do not know why you are here, nor what you hope to achieve. That alone is simply unprecedented. You must understand... individuals do not merely come to Bastion on a whim. This fate is earned, and those that are chosen for it are uniquely suited to this existence. So... I ask you... why are you here, truly?", ["objectivesText"] = "Answer Kleia 's question. Progress: < Kalisthene peers down at you.> What is it, mortal?", ["rewardGold"] = 118170, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166306, ["x"] = 0.422, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60736] = { ["id"] = 60736, ["name"] = "Quest 02", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60736 }, ["objectivesText"] = "Open the door to the Seat of the Primus.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 6797, 6798, 61487, 61488, 61489, 81787, 81788, 81789, 81790, 81791, 81792, 81793, 81794, 81795, 94219, 94220, 95622, 95623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60737] = { ["id"] = 60737, ["name"] = "The Door to the Unknown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["description"] = "You empowered the final rune? Then we might yet turn the tide of battle! Open the door, <name>! We'll hold the enemy back as long as we can!", ["objectivesText"] = "Open the door to the Seat of the Primus.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 170309, ["x"] = 0.504, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60738] = { ["id"] = 60738, ["name"] = "The Way to Hibernal Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "I've never seen a wildseed quite like this one. Even the ones that bonded with their caretakers in the past never manifested nightmares like this. Then again, we've also never had a living mortal in our midst. We need to bring this wildseed to Hibernal Hollow. There it can receive the care and attention it needs. I'll place it into the spirit cradle. Can you ask Niya if she would accompany you? The poor sylvar has been directionless since the fall of her grove. This would be good for her.", ["objectivesText"] = "Recruit Niya to help you bring the wildseed to Hibernal Hollow.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170171, ["x"] = 0.645, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 0, ["flags"] = 0 } } },
