[60759] = { ["id"] = 60759, ["name"] = "Damned Intruders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60670, 60725, 60761 }, ["description"] = "It is imperative that these reports reach Commander Throgg, but we are hard-pressed to defend the Crossroads. Before you depart, I ask that you aid us in thinning the Scourge's numbers. It may grant us the reprieve we need.", ["objectivesText"] = "Kill 6 Cultists and 4 Bloodthirsty Ghouls at the Crossroads. Progress: In troubled times, the Light guides our path.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 4, ["flags"] = 0 } } },
[60761] = { ["id"] = 60761, ["name"] = "Return of the Scourge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60670, 60725, 60759 }, ["description"] = "Deliver these reports to Commander Throgg . He must be told of the full extent of the threat we face. If we fail to hold the line against the Scourge... then Light help us all.", ["objectivesText"] = "Bring Lieutenant Althera 's report to Commander Throgg in the Valley of Strength in Orgrimmar. Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 180269 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 10, 85 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60762] = { ["id"] = 60762, ["name"] = "Death Motes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60762 }, ["description"] = "I have a task for you, Maw Walker. Souls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will. It is a tragic end. I wish to better understand this process--what is it about a soul that causes this transformation? Fragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.", ["objectivesText"] = "Collect 10 Death Motes from Ruin's Cradle in The Maw .", ["rewardItems"] = { 177698, 178874, 178880, 178881, 178882, 178883, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60763] = { ["id"] = 60763, ["name"] = "I Moustache You to Lend a Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60338, 60341, 60778 }, ["description"] = "A message from the Primus of Maldraxxus, you say? We haven't heard from him in... Well, it's been a long time. This isn't a prank, is it? The Queen doesn't have time for pranks. But I do! <Moonberry leans in close and whispers to you.> And for this one, I think we need one more lily. <Moonberry winks.> Let me take a look at this message. You bring that last night lily to Featherlight, and then we'll talk.", ["objectivesText"] = "Assist Moonberry and Featherlight.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178747 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 168341, ["x"] = 0.682, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157788, ["x"] = 0.65, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60764] = { ["id"] = 60764, ["name"] = "Soothing Song", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "I will fly ahead to Hibernal Hollow and convince the Droman Aliothe to help us. Hopefully she will have agreed by the time you and Niya arrive. This wildseed seems to take comfort in your presence, so you'll need to stick close to it. Niya will also need to sing to the wildseed to keep it calm... or else the nightmares may return. Spriggans love to interrupt our songs, so be on the lookout for them. Let me know when you're ready to head off.", ["objectivesText"] = "Travel with Niya to take the wildseed to Hibernal Hollow. Progress: How strange that such a small wildseed could cause so much trouble...", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170172, ["x"] = 0.645, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170290, ["x"] = 0.624, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60765] = { ["id"] = 60765, ["name"] = "Cure For All Ills", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60765 }, ["description"] = "Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness. Maw Walker, I'd do anything to help them. Even saving a few is better than saving none. Please, help me cure them!", ["objectivesText"] = "Use Roseboil 's Regenerative Molt to cure 15 Plague-ridden Survivors .", ["rewardXP"] = 8165, ["rewardItems"] = { 178680, 182487, 182496, 182505, 182514, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 159241, ["x"] = 0.55, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60766] = { ["id"] = 60766, ["name"] = "Damned Intruders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 60767 }, ["description"] = "Before you depart... we are in desperate need of reinforcements. These reports must reach Commander Gregor. But if you would help us thin the Scourge's numbers first, it would grant us a much needed reprieve.", ["objectivesText"] = "Kill 12 Scourge in the area. Progress: In troubled times, the Light guides our path.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 166184, ["x"] = 0.735, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 166184, ["x"] = 0.735, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 4, ["flags"] = 0 } } },
