[60775] = { ["id"] = 60775, ["name"] = "A Suitable Demise", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60775 }, ["description"] = "Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy. The soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain. This of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.", ["objectivesText"] = "Throw 5 Soulforged Cores into Soulforges in Zovaal's Cauldron in the Maw .", ["rewardItems"] = { 177698, 177699, 178874, 178880, 178881, 178882, 180280, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60778] = { ["id"] = 60778, ["name"] = "Wildseed Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60338, 60341, 60763 }, ["description"] = "< Featherlight checks his notes.> Let's see... There was a request for help regarding an imperiled wildseed and... something about an egg? The original note wasn't entirely clear, but the fae who sent it was... Ah! It was Korenth . Again. Well, I suppose we'll find out what his trouble is soon enough! I'll fly ahead and look for him. Stick to the path.", ["objectivesText"] = "Help Korenth recover the wildseed. Progress: You survived!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170175, ["x"] = 0.660667, ["y"] = 0.191333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170324, ["x"] = 0.676, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.191333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 3, ["flags"] = 0 } } },
