[60841] = { ["id"] = 60841, ["name"] = "Evacuation Effort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60841 }, ["description"] = "Our forces are in danger, and the fault is my own. Believing that the surrounding area was safe, I sent a small team to secure the abandoned camp in the valley to the southwest. But our field reports were outdated or mistaken. The camp is a lost cause. We must now focus on rescuing those whom I assigned to it. Head for the camp. Do what you can to save our allies.", ["objectivesText"] = "Rescue 6 allies in the Valley of Lost Hope. Kill 6 Scourge in the area.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
