[60843] = { ["id"] = 60843, ["name"] = "Cult Couture", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60861, 60867, 60932, 62185, 62225 }, ["description"] = "Though our scouts have been able to infiltrate the cultist forces at Aldur'thar, sneaking into Mord'rethar has proven all but impossible. Perhaps it is time to explore other methods of ingress. Start by investigating the cult's nearby ritual chambers. You may find something of use.", ["objectivesText"] = "Collect a Collaborator's Hood and a Collaborator's Robe from the cultists at Aldur'thar. Progress: Find something?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 181253, 181254 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 6, ["flags"] = 0 } } },
