[60856] = { ["id"] = 60856, ["name"] = "Toppling the Brute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "A nearby monstrosity has been thwarting our efforts to clear the meadow. Together, we can bring it down. You and I will face off against the beast. When the time is right, I will call for the hunt to charge. The Wild Hunt has suffered too many losses. Today we will claim victory against these monsters!", ["objectivesText"] = "Defeat the Blighted Beast .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 175983, 175984, 175985, 175986, 175987, 175988, 175989, 175990, 175992, 178029 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170485, ["x"] = 0.642, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170485, ["x"] = 0.642, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60857] = { ["id"] = 60857, ["name"] = "We Can't Save Them All", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["description"] = "I am surprised--but pleased--that you weren't torn to pieces! Well done. But now... I fear we have a far more serious task to complete. The Winter Queen has decreed that Heartwood Grove's anima is to be reclaimed, and its denizens must leave it to wither. Not all of their wildseeds will go with them. In fact, only a few have been chosen to be saved. We are to bring the final list to Droman Krelnor .", ["objectivesText"] = "Bring the list of saved wildseeds to Droman Krelnor at the Heartwood Grove. Progress: Move along, stranger.", ["rewardGold"] = 24570, ["rewardXP"] = 175, ["rewardItems"] = { 180436 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170324, ["x"] = 0.676, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168528, ["x"] = 0.678, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 4, ["flags"] = 0 } } },
