[60859] = { ["id"] = 60859, ["name"] = "Souls of the Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 57787 }, ["description"] = "If you're standing in for Lady Moonberry, then maybe you can help! Wagonmaster Derawyn was escorting a bunch of us to a new grove when we were attacked by a pack of hungry predators! The wolf be a fast soulshape, so I got away... but some of the little ones weren't so lucky. They're being hunted like prey! Come on! They're just down the road!", ["objectivesText"] = "Rescue souls in peril. Progress: Well, that was exciting.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 175652, 175653, 175654, 175655 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170537, ["x"] = 0.667333, ["y"] = 0.261333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170533, ["x"] = 0.667, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.667333, ["y"] = 0.261333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 5, ["flags"] = 0 } } },
[60861] = { ["id"] = 60861, ["name"] = "Secrets in Shadows", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60843, 60867, 60932, 62185, 62225 }, ["description"] = "Though we have been monitoring the cultist presence at Mord'rethar, we have not yet discovered what mysteries lie within its chambers. Take these robes. Make your way into the inner sanctum and see what you can discover. This may be our only chance to learn their intentions, <name>.", ["objectivesText"] = "Use the Collaborator's Robes in Mord'rethar to discover what secrets lie within. Progress: Find something?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 8, ["flags"] = 0 } } },
[60867] = { ["id"] = 60867, ["name"] = "A Message from Above", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60843, 60861, 60932, 62185, 62225 }, ["description"] = "This is troubling news, $p. Whoever this \"Banished One\" may be, it is clear he is behind the Scourge's return. That the undead are amassing in great numbers outside Icecrown Citadel cannot be a coincidence. Lead our hippogryph riders in surveying the area from above. Determine if the dark herald you saw is among them, and then clear a path for reinforcements. Let us hope she possesses the answers we seek.", ["objectivesText"] = "Discover the location of Herald Dalora. Destroy the Scourge forces surrounding Icecrown Citadel. Progress: The skies over the citadel may be dangerous, but we need to know what we're up against.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 10, ["flags"] = 0 } } },
[60869] = { ["id"] = 60869, ["name"] = "With Hope in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60932, 62157, 62185, 62225 }, ["description"] = "You must bring word of what we have uncovered back to Orgrimmar. One of our mages can open a portal for you at the tournament grounds. As for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use. May the Light protect you, <name>.", ["objectivesText"] = "Establish a portal to Orgrimmar at the Argent Tournament Grounds. Deliver the news to Lor'themar Theron atop Grommash Hold in Orgrimmar.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 85, 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 13, ["flags"] = 0 } } },
[60871] = { ["id"] = 60871, ["name"] = "With Hope in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60169, 60827, 60828, 60843, 60861, 60867, 60871, 60932, 62157, 62185, 62225 }, ["description"] = "You must bring word of what we have uncovered back to Stormwind. One of our mages can open a portal for you at the tournament grounds. As for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use. May the Light protect you, <name>.", ["objectivesText"] = "Establish a portal to Stormwind at the Argent Tournament Grounds. Deliver the news to Genn Greymane at Lion's Rest in Stormwind City.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 84, 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 14, ["flags"] = 0 } } },
