[60898] = { ["id"] = 60898, ["name"] = "The Fate of Ara'lon", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "<name>, I have an urgent request to make of you. Recently, the Wild Hunt has been encountering the masked fae in greater numbers... particularly in the area surrounding Blackthorn Grove. I sent a hunting party to investigate, but they have yet to return. Ara'lon was leading the hunt. You have offered him aid before, yes? I ask that you do so again. Search the area for signs of the missing hunters and report back to me.", ["objectivesText"] = "Search near Blackthorn Grove for Ara'lon and the lost hunting party.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 0, ["flags"] = 0 } } },
