[60904] = { ["id"] = 60904, ["name"] = "Medallion of Desire", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["series"] = { 57880 }, ["description"] = "The Medallion of Desire rests upon the neck of the Countess. It is a source of power for her, but not her only source of power. Claiming it by force would merit us only a short victory. For this we must be much more subtle. Lucky for us, Theotar has come to me with a plan but he will need your help. Speak with him and see what the two of you can do. He was closer to the Countess than any of us for a long time and I would consider him our resident expert on her.", ["objectivesText"] = "Speak with Theotar .", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60905] = { ["id"] = 60905, ["name"] = "Infusing the Wildseed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "Dreamweaver tells me of a ritual to quell the wildseed's nightmares... but it will require anima. A soul named Proglo lives beneath this tree, gathering anima for the grove's caretakers to use. His mortal life came to a violent end, and his soul has been skittish ever since. He will not respond well to your current form. I will grant you the ability to assume the soulshape of a fox. Approach Proglo in your new form to gain his trust and ask for his anima.", ["objectivesText"] = "Use Soulshape to collect anima from Proglo , then infuse the wildseed with the collected anima. Progress: I hope we can aid this wildseed.", ["rewardGold"] = 125190, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160963, ["x"] = 0.6, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 6, ["flags"] = 0 } } },
[60906] = { ["id"] = 60906, ["name"] = "Rightful Resting Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60906 }, ["description"] = "You have truly proven yourself a hero in the eyes of those who are its absolute judge. I thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place. Let us meet at Hero's Rest where you can do the honors.", ["objectivesText"] = "Enshrine the Spear of Kalliope in its rightful place at Hero's Rest. Progress: <The resting place of the spear lies before you.>", ["rewardGold"] = 116100, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[60907] = { ["id"] = 60907, ["name"] = "Ascension Calling: Kleia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60907 }, ["description"] = "<This scroll details an invitation for Kleia to join you and Pelagos on the Path of Ascension. It would be wise to deliver this to her at once.>", ["objectivesText"] = "Inform Kleia she is now able to participate in the Path of Ascension.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160390, ["x"] = 0.642, ["y"] = 0.166 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.166 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 182095 } },
[60910] = { ["id"] = 60910, ["name"] = "Masks of Deception", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "My hunting party was ambushed not far from here. I narrowly escaped capture, but the others were taken deeper into Blackthorn Grove. We must find and rescue them, but we are vastly outnumbered. We'll need to disguise ourselves while we search the grove. See if you can find something we can use to do so. I need just a little longer to recover from my wounds.", ["objectivesText"] = "Find two Masks of Possession . Progress: What have you found?", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 180462 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4296, ["y"] = 0.4572 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 1, ["flags"] = 0 } } },
