[60993] = { ["id"] = 60993, ["name"] = "Citadel of Loyalty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "The medallions, the source of magic the crown focuses, are still bent to the will of Denathrius. Forge cannot solve this. Citadel of Loyalty can. Taken over by the Forsworn in recent times. If we can get the crown to the temple, we can break the loyalty to the medallion's former master.", ["objectivesText"] = "Meet Mikanikos at the Citadel of Loyalty.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 10, ["flags"] = 0 } } },
[60994] = { ["id"] = 60994, ["name"] = "Lowering Their Defenses", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "We can alter the crown to expunge Denathrius's corruption in the medallions. Problem, Forsworn have set large barrier protecting the temple. Only there can Denathrius's influence be truly broken. Drain the anima from the barrier's sources that power it. Barrier will disappear.", ["objectivesText"] = "Drain the anima from the Forsworn Barrier Sources.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.227, ["y"] = 0.263 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 11, ["flags"] = 0 } } },
[60995] = { ["id"] = 60995, ["name"] = "Disloyalty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "There are many enemies of Bastion here. If we thin their numbers, it will further mend the tension between our realms. Show no remorse. I will take to the skies to support from above. I will be able to provide ground support when needed.", ["objectivesText"] = "Kill 15 Forsworn in the Citadel of Loyalty.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 170999, ["x"] = 0.244, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 12, ["flags"] = 0 } } },
[60996] = { ["id"] = 60996, ["name"] = "Face Your Fears", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "The temple is now accessible. We must go now to aid Mikanikos in breaking the Sire's influence on the crown. Prepare yourself. Denathrius's magic has always been potent and destructive. This won't be easy.", ["objectivesText"] = "Speak to General Draven to go to the Temple of Loyalty. Then, aid Mikanikos in purifying the Crown of the Harvesters .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 180605 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171147, ["x"] = 0.230444, ["y"] = 0.252222 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171175, ["x"] = 0.232, ["y"] = 0.256333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.230444, ["y"] = 0.252222 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 13, ["flags"] = 0 } } },
[61050] = { ["id"] = 61050, ["name"] = "How to Wear Seven Medallions", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["series"] = { 58530 }, ["description"] = "One venthyr cannot wear seven medallions and command the power they bestow, nor command respect from anyone looking at them. What I propose is the crafting of an artifact that can contain the power of the medallions. Focusing that power to one wielder. Unfortunately, Revendreth lacks the craftsmanship needed to channel such powers. Not without turning the wearer into a puppet of Denathrius. No, for this, we must employ the aid of a realm that specializes in service. Draven has the details.", ["objectivesText"] = "Speak with General Draven .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 0, ["flags"] = 0 } } },
[61051] = { ["id"] = 61051, ["name"] = "The Absent-Minded Artisan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["series"] = { 57818, 57824, 57825, 57952 }, ["description"] = "Of all the foolhardy, misguided, exasperating... < Guardian Kota snorts and stomps a hoof.> But standing here does Sha'lor no good. We must find him and bring him back safely. Come, meet me at the Autumnal Rise. We can survey the burrows below and see if there is any sign that he lives.", ["objectivesText"] = "Search for Master Sha'lor on the Autumnal Rise.", ["rewardGold"] = 24805, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171099, ["x"] = 0.628, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 0, ["flags"] = 0 } } },
[61057] = { ["id"] = 61057, ["name"] = "By Trials Forged", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 61057 }, ["description"] = "You have shown strength, cunning and compassion since your arrival in Ardenweald. These are the values the greatest hunters possess. It has been a privilege to fight by your side, <name>. It would be my honor to continue, as your Soulbind.", ["objectivesText"] = "Complete the soulbinding ritual with Korayn. Progress: Together we are stronger!", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[61058] = { ["id"] = 61058, ["name"] = "Bound in Dreams", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 61058 }, ["description"] = "I knew you were something special when Ysera's wildseed reacted to you. Without you, she would have been lost! It would have been a tragedy not just for Ardenweald, but your world as well! Since then, I have seen you take on many more tasks to help others in need. With your help, Ardenweald grows stronger. I would be honored to help you continue the good work you have been doing, and to become your soulbind.", ["objectivesText"] = "Complete the soulbinding ritual with Dreamweaver . Progress: I am humbled by the care you have shown for others.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[61059] = { ["id"] = 61059, ["name"] = "RSVP: Rendle and Cudgelface", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 61059 }, ["description"] = "I heard about the prince wanting Rendle and me at 'is court. I aim to please 'im an all, but Rendle says 'e haven't got proper ah-tire. Says 'e needs a sootible hat, maybe somethin' posh that hints at 'is inner depths. He says the only good hats are: Red Noggin Candle, or one a them Fae Revel Masques. Or mebbe a Pink Party Hat, or a fancy Crown o' the Righteous.", ["objectivesText"] = "\"Sootible\" hats may be crafted by players who have the recipe and appropriate tradeskill.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 10290, 171286, 171287, 171829, 173058, 173059, 173108, 173109, 173110, 173202, 176118, 177061, 177062, 180751, 180752, 180755, 180760, 183950, 183953, 183954 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700 },
[61060] = { ["id"] = 61060, ["name"] = "Spore Losers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61060 }, ["objectivesText"] = "Fungret Mushroom eaten Revenge for Fungrets Rally Fungret", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Fungret Mushroom eaten", ["amount"] = 1, ["type"] = 0, ["objectID"] = 171115, ["orderIndex"] = 0 }, { ["text"] = "Revenge for Fungrets", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Rally Fungret", ["amount"] = 50, ["type"] = 0, ["objectID"] = 171140, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61061] = { ["id"] = 61061, ["name"] = "Ulfar's Guidance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["series"] = { 61076, 61102 }, ["description"] = "There is one who may know how to dispel the curse from Gweyir. In the mountains of Drustvar lives Ulfar , an ancient Thornspeaker who sided with the humans of Kul Tiras against his fellow Drust. Journey to his den and ask for his wisdom. He may hold the answers you seek. Lord Herne and I will tend to Gweyir once she arrives with Ara'lon.", ["objectivesText"] = "Speak with Ulfar at Ulfar 's Den in Drustvar.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171138, ["x"] = 0.46, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 896, 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 4, ["flags"] = 0 } } },
