[61075] = { ["id"] = 61075, ["name"] = "A Spark of Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 61075 }, ["description"] = "Gorgoa is a protean force fueled by souls that trickle in from many worlds. They wash in from the head of the river, a place they have named the Crucible of the Damned. The Jailer's unblinking eyes patrol the river and watch for souls who attempt escape. Blind the eyes that find them. Close them for good. Take this and do what must be done.", ["objectivesText"] = "Defeat 4 Eyes of Damnation. Progress: Have you closed the Jailer's eyes?", ["rewardItems"] = { 180607, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[61076] = { ["id"] = 61076, ["name"] = "Into the Flame", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["series"] = { 61061, 61102 }, ["description"] = "I know the curse of which you speak. Dark magic that possesses the mind of the afflicted. Long ago, the Drust were ruled by a sorcerer king named Gorak Tul. It was he who twisted our rituals and set us on the path of death and domination. You will need to claim a portion of his power to break the curse. Take this fetish to Gol Inath and temper it in the Flame of Oblivion. But beware... it is a vile place, and danger lurks among its shadows.", ["objectivesText"] = "Imbue the Drust Fetish with the power of Gorak Tul. Progress: Gorak Tul's magic empowers the curse, and only his magic can break it.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 180625 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 5, ["flags"] = 0 } } },
[61077] = { ["id"] = 61077, ["name"] = "Confronting Sin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["series"] = { 58382 }, ["description"] = "Thanks to the raid launched against Castle Nathria, we have obtained an opportunity. A soul, powerful and fused with dark purpose at the hands of the Master's experiments. Given this soul is from Azeroth, the Accuser has asked for your assistance in untwining the corruption done to his sinstone. the Accuser awaits you in the lower levels of Sinfall.", ["objectivesText"] = "Speak with the Accuser in Sinfall.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 174211 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 0, ["flags"] = 0 } } },
[61079] = { ["id"] = 61079, ["name"] = "The Jailer's Share", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 61079 }, ["description"] = "The Mawsworn's torturers have a talent for misery. The suffering they inflict often produces more stygia than they can collect. The excess floats loosely in the air, left to drift into the abyss. I have fashioned a conduit specifically for capturing the leftover stygia . You can borrow it if you wish. There are a handful of prime gathering locations throughout Calcis. As you'll be using my conduits, we can split what you find upon your return.", ["objectivesText"] = "Place 4 Stygia Conduits at marked locations within Calcis in The Maw . Progress: Were the conduits effective? How much stygia did they collect?", ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[61092] = { ["id"] = 61092, ["name"] = "RSVP: Grandmaster Vole", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61092 }, ["description"] = "I'm busy, so I'll get right to the point. The only way I'm going is if you pay me enough coin to make it worth my while or you amuse me. As interesting and enjoyable as the Ember Court may be, I lose money every time I am away from here. That said, I do love a good slaughter. So, coin or deaths. Take your pick.", ["objectivesText"] = "Convince Grandmaster Vole by bribing him or slaying players of the opposite faction. Progress: You need to cough up the coin or get killing.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176122 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 163019, ["x"] = 0.528, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 163019, ["x"] = 0.528, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
