[61096] = { ["id"] = 61096, ["name"] = "The Arbiter's Will", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1671, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 60055, 60056 }, ["description"] = "We will all suffer if Bastion and Maldraxxus fall into war. For some time, the Necrolords have been isolated. You must travel to their realm and seek the truth of their incursion. Though our anima reserves remain low, they will be enough to open the way for you.", ["objectivesText"] = "Meet Kah-Sher in the Ring of Transference in Oribos.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 }, { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1133, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1133, ["name"] = "Tidings of War", ["orderIndex"] = 1, ["flags"] = 0 } } },
[61097] = { ["id"] = 61097, ["name"] = "Supplies from The Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61097 }, ["description"] = "The Ascended would like to thank you for your efforts in aiding Bastion . Please accept a gift in recognition of your service to our cause and our people.", ["objectivesText"] = "Speak with Adjutant Nikos in Hero's Rest in Bastion .", ["rewardItems"] = { 180647 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160470, ["x"] = 0.522, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2441, ["threshold"] = 10000 } } } },
[61098] = { ["id"] = 61098, ["name"] = "Supplies from The Wild Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61098 }, ["description"] = "The Wild Hunt thanks you for your efforts in aiding Ardenweald . Take these gifts as recognition for your aid. May they help you in whatever trials may come.", ["objectivesText"] = "Speak with Aithlyn at the Heart of the Forest in Ardenweald .", ["rewardItems"] = { 180649 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158556, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2444, ["threshold"] = 10000 } } } },
[61099] = { ["id"] = 61099, ["name"] = "The Search for Baine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "I dare not step inside that accursed tower myself, of course. While I cannot tell you exactly where your comrade is being held, I offer a gift to assist you. Use it inside Torghast. It should take you somewhere near your missing ally. Baine Bloodhoof was his name, yes? Either that, or you'll end up trapped within the tower's ever-shifting halls for all eternity. But those are the risks one must take, I suppose. Best of luck!", ["objectivesText"] = "Enter Torghast and search for Baine. Progress: You've found him!", ["rewardGold"] = 1239200, ["rewardXP"] = 16330, ["rewardItems"] = { 184544, 184757 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 153, ["title"] = "9.0 Covenant Campaigns Ch 2 - Torghast", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1242, ["questLineOrder"] = 1 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1243, ["questLineOrder"] = 1 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1244, ["questLineOrder"] = 1 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1245, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 } } },
[61100] = { ["id"] = 61100, ["name"] = "Supplies from the Court of Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61100 }, ["description"] = "Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. As a result, we have collection of resources you may find useful, plundered from Sire Denathrius' most devoted followers. They are waiting for you with me in Darkhaven.", ["objectivesText"] = "Speak with Mistress Mihaela for your reward.", ["rewardItems"] = { 180648 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2442, ["threshold"] = 10000 } } } },
[61102] = { ["id"] = 61102, ["name"] = "Kivarr the Thornspeaker", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["series"] = { 61061, 61076 }, ["description"] = "In my youth, I was mentored by a wise and powerful Thornspeaker named Kivarr. She passed from this world long ago, but her soul may yet rest within the Shadowlands. Kivarr's knowledge is ancient and vast, far eclipsing my own. She may be able to offer you the guidance that I cannot. Seek her out. Deliver the fetish to her. She will know what to do. May the wind be your guide.", ["objectivesText"] = "Speak with Lord Herne at Heart of the Forest in Ardenweald.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170848, ["x"] = 0.462, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 896, 1565 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 6, ["flags"] = 0 } } },
[61103] = { ["id"] = 61103, ["name"] = "Disrupting the Cycle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 61103 }, ["description"] = "The shacklers in the Tremaculum are an awful sort. Souls are tortured there until they turn malevolent. They are then outfitted as guards so the cycle can continue. If you wish to slow the rate at which the Jailer raises his armies, start at the source. Disrupt the cycle at the Tremaculum.", ["objectivesText"] = "Defeat 4 Mawsworn Shacklers and 6 Deadeyes at the Tremaculum in The Maw .", ["rewardItems"] = { 184613, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[61104] = { ["id"] = 61104, ["name"] = "Grathalax, the Extractor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 61104 }, ["description"] = "There are many powerful lieutenants among the Mawsworn, but there is one who is particularly important to the Jailer. Far beneath the Tremaculum lives the Jailer's prime interrogator, Grathalax . Power is fed to him via conduits throughout the area. His role is to make the process of anima extraction more efficient. His methods are... unkind. I believe we would both benefit from the end of his existence.", ["objectivesText"] = "Defeat Grathalax underneath the Tremaculum in The Maw .", ["rewardItems"] = { 177698, 177699, 178874, 178880, 178881, 178882, 178883, 183060, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[61105] = { ["id"] = 61105, ["name"] = "RSVP: Plague Deviser Marileth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61105 }, ["description"] = "Oh! This sounds like a wonderful opportunity to do field research in Revendreth, apprentice. I look forward to collaborating with new colleagues. We must bring a gift to thank them for their invitation. What could be more appropriate than some lovely slimes? Please pick some of the best slimes for me to present to our host. Just bring them to Kevin so they can make friends and travel together.", ["objectivesText"] = "Herd Bubbling Oozes to Kevin so Plague Deviser Marileth has a present to bring to the Ember Court. Progress: Have you finished choosing our gift slimes yet, apprentice?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176124 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61107] = { ["id"] = 61107, ["name"] = "A Land of Strife", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1671, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 57386 }, ["description"] = "It is imperative that you identify the cause of the attack on Bastion . We will require your aid to open the gateway. Once the focus is sufficiently powered, we will call upon the gate to Maldraxxus and direct it into position. From there, the fate of this war must rest upon your shoulders.", ["objectivesText"] = "Activate the gateway to Maldraxxus. Progress: Time is precious, now more than ever.", ["rewardGold"] = 120510, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 }, { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1133, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1133, ["name"] = "Tidings of War", ["orderIndex"] = 2, ["flags"] = 0 } } },
[61109] = { ["id"] = 61109, ["name"] = "RSVP: Hunt-Captain Korayn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61109 }, ["description"] = "I am a Captain of the Wild Hunt, a defender of the sacred groves. As much as I would enjoy the diversion, my place is here fighting back the forces of the enemy, not venturing outside of Ardenweald. Eggs are hatching again at Gormhive and we shall soon be overrun by gormling larva. Until that threat is neutralized I cannot leave my post.", ["objectivesText"] = "Remove the threat of Gormhive by smashing eggs, eliminating egg tenders, and slaying gorm so Hunt-Captain Korayn can attend the Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176116 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171319, ["x"] = 0.508, ["y"] = 0.704 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171319, ["x"] = 0.508, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61112] = { ["id"] = 61112, ["name"] = "A Hunger for Flesh", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 61112 }, ["description"] = "<The bile-soaked cloth bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable. Commander Gregor will want to know of this at once.>", ["objectivesText"] = "Bring the Partially Digested Cloth to Commander Gregor in the Trade District of Stormwind City. Provided item:", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 180712, 180719 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 166383, ["x"] = 0.655, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 180712 } },
[61113] = { ["id"] = 61113, ["name"] = "Kivarr's Den", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "Kivarr... I have not heard that name in many an age. She used to make her home near Eventide Grove to the south. Ara'lon knows the area well. I suggest you take him with you. I fear that the situation with Gweyir weighs heavily upon him. Perhaps joining you on the hunt will do him some good.", ["objectivesText"] = "Travel to Kivarr's Den at Eventide Grove in Ardenweald. Progress: Kivarr has made her home in Ardenweald for many an age, but she has always kept to herself.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170848, ["x"] = 0.462, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 7, ["flags"] = 0 } } },
[61114] = { ["id"] = 61114, ["name"] = "A Hunger for Flesh", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 61114 }, ["description"] = "<The bile-soaked leather bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable. Commander Throgg will want to know of this at once.>", ["objectivesText"] = "Bring the Partially Digested Leather to Commander Throgg in the Valley of Strength in Orgrimmar. Provided item:", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 180712, 180719 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["startItems"] = { 180719 } },
[61123] = { ["id"] = 61123, ["name"] = "RSVP: Polemarch Adrestes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61123 }, ["description"] = "I must politely decline your Prince's offer. My skills are needed here, and I am not particularly well-suited to the social demands of attending court. Perhaps the Paragon of Humility would be a better representative for Bastion. You may find him at the Temple of Humility, east of here. Please express my sincere regrets that I am unable to attend.", ["objectivesText"] = "Seek the assistance of the Paragon of Humility. Progress: My answer has not changed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176117 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171385, ["x"] = 0.604, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171385, ["x"] = 0.604, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
