[61190] = { ["id"] = 61190, ["name"] = "Wake of Ashes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "It feels as if the Maw itself is sentient... and taking notice of our presence. We must leave at once. Bolvar must be informed of what is happening here. I will bring my father with us. Lead the way out of here, <name>. With haste.", ["objectivesText"] = "Escape from the Maw and report to Bolvar in Oribos.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 178018, 181174, 204584, 204592, 204600, 204608, 205989 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 9, ["flags"] = 0 } } },
[61193] = { ["id"] = 61193, ["name"] = "A Light Touch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61193 }, ["description"] = "Need Firstborne's Light ! You know? Named after Archon! Always in water. Kofi 's favorite! Shine big light when grown. And go to shore! Easy to see!", ["objectivesText"] = "Collect 15 Firstborne's Light in water sources. Progress: Only grown flowers! Little ones won't work.", ["rewardGold"] = 30900, ["rewardXP"] = 8165, ["rewardItems"] = { 180897, 181368, 181377, 181612, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61196] = { ["id"] = 61196, ["name"] = "The Secret Ingredient", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61196 }, ["description"] = "At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common. There is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions. Will you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.", ["objectivesText"] = "Collect 10 Ephemeral Draught . Progress: Were you able to find the draught?", ["rewardGold"] = 549600, ["rewardXP"] = 8165, ["rewardItems"] = { 180898, 181368, 181377, 181583, 181601, 181610, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 184841, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61199] = { ["id"] = 61199, ["name"] = "Arms Day", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61199 }, ["description"] = "Many battles here. Especially lately! Now weapons all over. Too many. We can use! Go to big battle places and grab them. We will use better!", ["objectivesText"] = "Collect 20 Blessed Armaments from battlefields. Progress: Careful with the pointy end!", ["rewardXP"] = 8165, ["rewardItems"] = { 180946, 181368, 181377, 181599, 181609, 181610, 181629, 181632, 181636, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61209] = { ["id"] = 61209, ["name"] = "A Somber Melody", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61209 }, ["description"] = "Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters. These memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like. Take my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.", ["objectivesText"] = "Dissipate 15 Kyrian memories along the roads of Bastion.", ["rewardXP"] = 8165, ["rewardItems"] = { 180990, 181368, 181377, 181570, 181578, 181581, 181589, 181594, 181599, 181606, 181609, 181614, 181635, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61220] = { ["id"] = 61220, ["name"] = "AHHH! Real Monsters!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61220 }, ["objectivesText"] = "Assist Aspirant Thetes Repel the Devourer threat Helpless Aspirant rescued", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Assist Aspirant Thetes", ["amount"] = 1, ["type"] = 0, ["objectID"] = 171834, ["orderIndex"] = 0 }, { ["text"] = "Repel the Devourer threat", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Helpless Aspirant rescued", ["amount"] = 40, ["type"] = 0, ["objectID"] = 162685, ["orderIndex"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61226] = { ["id"] = 61226, ["name"] = "Extra Limbs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "We cannot carry out the baroness's plans alone. What she proposes will require a well-coordinated unit. Three individuals maintained Nurakkir alongside me. When the necropolis fell, two of my soulbinds fell with it. There remains a single soul paired with mine. My sister, Xennir, survived the wreckage--though grief besets her. Meet with Xennir. Guide her through her trauma, and return when she is ready to rejoin the fight.", ["objectivesText"] = "Locate and assist Navigator Xennir .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158529, ["x"] = 0.498, ["y"] = 0.178 }, { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 158604, ["x"] = 0.509333, ["y"] = 0.166667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 7, ["flags"] = 0 } } },
[61227] = { ["id"] = 61227, ["name"] = "The Other Foot", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "It is a fool's errand to command a necropolis without someone to repair it and keep it airborne. Nurrakir's mechanic was slain in the crash. But opportunity arises in dire times. Vyn has told me of an... altercation among the constructs. One of their own resisted the reckless scavenging of Nurakkir, and was promptly detained for his objections. Find this individual. An enemy deserter could make for a potential ally.", ["objectivesText"] = "Locate Mechanic Ansid.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164646, ["x"] = 0.498, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159814, ["x"] = 0.493, ["y"] = 0.177 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 6, ["flags"] = 0 } } },
[61230] = { ["id"] = 61230, ["name"] = "Outside Influence", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["series"] = { 61252 }, ["description"] = "It takes a particular kind of magic to pilot a necropolis. The Eyes' helmsman perished with Nurakkir. But Baroness Vashj has informed me of a means to acquire a new helmsman. Follow me to our house's communications beacon. My baroness has taught me a way to summon just the individual we require. I suspect she will not be pleased at the prospect of serving us. I trust you will encourage her compliance.", ["objectivesText"] = "Meet with Khaliiq at the House of Eyes' communications pillar.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 173312, 175796 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171875, ["x"] = 0.502, ["y"] = 0.169 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 174343, ["x"] = 0.542, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.169 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 5, ["flags"] = 0 } } },
[61246] = { ["id"] = 61246, ["name"] = "Power of the Chosen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "The necropolis is nearly in position. Now is the time to strike! We must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts. The Margrave will be unable to ignore their deaths. Once they leave their blighted tower, we can finish them once and for all.", ["objectivesText"] = "Destroy the Bilebloat Juggernauts . Progress: Every moment the juggernauts remain standing, our position is in jeopardy!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 13, ["flags"] = 0 } } },
[61252] = { ["id"] = 61252, ["name"] = "Call In a Favor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["series"] = { 61230 }, ["description"] = "We will do just as my baroness commands. Let us conjure a helmsman before us... however displeased it might make her. Activate the beacon and prepare yourself for a fight. The liches regard all Eyes as their enemies, and I am certain your reputation among them does you no favors.", ["objectivesText"] = "Summon Helmsman Caliroux and defeat her.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181162 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 174343, ["x"] = 0.542, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 171875, ["x"] = 0.502, ["y"] = 0.169 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 10, ["flags"] = 0 } } },
[61255] = { ["id"] = 61255, ["name"] = "RSVP: Alexandros Mograine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61255 }, ["description"] = "It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. But before I leave my post, I must ensure my comrades will be safe while I am away. Fight your way into the Ossein Foundry and retrieve weapons from our rivals there. I will have them distributed among the troops while I make ready to depart.", ["objectivesText"] = "Collect 9 Ossein Staves and 3 Ossein Battleaxes from the Ossein Foundry. Progress: Have you gotten the weapons yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176115, 181160, 181161 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171933, ["x"] = 0.504, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 171933, ["x"] = 0.504, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61256] = { ["id"] = 61256, ["name"] = "RSVP: Kleia and Pelagos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61256 }, ["description"] = "Oh, how wonderful! Thank you for the invitation to the Ember Court. We were just going to go cleanse ourselves with a meditation. That will be even more necessary if we are to travel soon. Care to join us?", ["objectivesText"] = "Join Kleia and Pelagos in the Meditation chamber and face the memories of your past. Progress: Have you completed your meditation yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176123, 180062 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 174916, ["x"] = 0.558, ["y"] = 0.864 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171951, ["x"] = 0.581, ["y"] = 0.868 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.864 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
