[61304] = { ["id"] = 61304, ["name"] = "Blueprint: Kyrian Smith's Kit", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61304 }, ["description"] = "<You have discovered plans for a kit that lets you repair a piece of armor while out adventuring. Dactylis should be able to help you with crafting this kit.>", ["objectivesText"] = "Bring the Blueprint: Kyrian Smith's Kit to Dactylis . Provided item:", ["rewardItems"] = { 181165 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 181165 } },
[61314] = { ["id"] = 61314, ["name"] = "REUSE ME - SCS", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 61314 }, ["description"] = "You'll need a vessel to hold the anima you need to collect, but one that will also allow you to channel said anima. There was once such a device ages ago, but as of late they've become much more rare. In my travels through the Maw , I have seen one once. It is in the (AREA NAME), held by (CREATURE). You'll need luck on your side in order to retrieve it.", ["objectivesText"] = "Obtain the Anima Focuser.", ["rewardItems"] = { 178562 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61323] = { ["id"] = 61323, ["name"] = "See What You've Done", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "We have gathered what forces we can. I hope it is enough. Within the ruins of our necropolis awaits one final challenge. The one leading the salvage effort calls herself Gorgantus. To preserve all that remains to us, we must end her. Lead the attack, and the Eyes will join you. We will reclaim our home.", ["objectivesText"] = "Slay Gorgantus the Gutter .", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 181162, 182256, 182265, 182274, 182283 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158529, ["x"] = 0.498, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 11, ["flags"] = 0 } } },
[61331] = { ["id"] = 61331, ["name"] = "Return Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["description"] = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible! The Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans. Return to the Maw and rescue those that you can.", ["objectivesText"] = "Rescue Souls in the Maw.", ["rewardGold"] = 561800, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 32, ["flags"] = 1 } } },
[61332] = { ["id"] = 61332, ["name"] = "Return Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["description"] = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands. The Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right. Return to the Maw and save all that you can.", ["objectivesText"] = "Rescue 5 Souls from the Maw.", ["rewardGold"] = 561800, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 29, ["flags"] = 1 } } },
[61333] = { ["id"] = 61333, ["name"] = "Return Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59609, 60287, 60289, 61333, 61355, 61359, 61388, 61397, 61983, 62833, 62834, 62835, 62837, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 62864, 62865, 62866, 62882, 63003, 63212, 65157, 65165 }, ["description"] = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. We must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords. I shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus. Return to the Maw and rescue those that you can.", ["objectivesText"] = "Rescue Souls in the Maw.", ["rewardGold"] = 561800, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 29, ["flags"] = 1 } } },
[61334] = { ["id"] = 61334, ["name"] = "Return Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59314, 59315, 59321, 59323, 60287, 60289, 61334, 61355, 61981, 62695, 62837, 62856, 62857, 62867, 62868, 62869, 62870, 62882, 62902, 62903, 62904, 62905, 62914, 62915, 62918, 62919, 62920, 62921, 63215 }, ["description"] = "Souls continue to pour into the Maw. Their anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. Bring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", ["objectivesText"] = "Rescue Souls in the Maw.", ["rewardGold"] = 561800, ["rewardItems"] = { 174992, 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 26, ["flags"] = 1 } } },
[61335] = { ["id"] = 61335, ["name"] = "Rage Against the Cage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "You're looking for a mechanic, are you? Look no further! I've been toiling on a new necropolis for ages. When Nurakkir collapsed, we saw a golden opportunity! We came to salvage parts from the wreckage, but these brutes locked me up when I criticized their methods. But now you need help, right? I'm your construct! You get me out of here, and you've got yourself a new mechanic!", ["objectivesText"] = "Free Ansid the Mechanic from his cage using Toc's key . Progress: Got a way to free me?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173312 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159814, ["x"] = 0.493, ["y"] = 0.177 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159814, ["x"] = 0.493, ["y"] = 0.177 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.493, ["y"] = 0.177 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 9, ["flags"] = 0 } } },
