[61353] = { ["id"] = 61353, ["name"] = "All Will Be Consumed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61353 }, ["objectivesText"] = "Devourer Invasion stopped Rift closed", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Devourer Invasion stopped", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Rift closed", ["amount"] = 20, ["type"] = 0, ["objectID"] = 172068, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61354] = { ["id"] = 61354, ["name"] = "RSVP: Lady Moonberry", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61354 }, ["description"] = "Of course I will attend, <name>, the Ember Court sounds like a lot of fun! But I cannot go without a gift! Hospitality gifts are an important tradition on many worlds and I feel obliged to provide something suitable for my host and fellow guests. < Lady Moonberry suppresses a smirk.> Now for reasons that I'm suuuure won't interest you, I'll need a stout but pretty vine, some dangerous but beautiful blossoms, and of course some gorm pheromones. Easy enough for someone of your prowess.", ["objectivesText"] = "Collect 3 Silverheart Vine Leaves , 9 Blooming Lasher Spurs , and a Gorm Pheromone Gland . Progress: Have you found all of the components for my gift?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176112, 181250, 181251, 181252 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172098, ["x"] = 0.49, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172098, ["x"] = 0.49, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61355] = { ["id"] = 61355, ["name"] = "Rule 2: Keep a Low Profile", ["level"] = 55, ["requiredLevel"] = 55, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 58160, 60287, 60289, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Though you may wish to depart with your precious souls in tow, we now have additional matters to settle first. The Eye of the Jailer is upon you. And that does not bode well for either of us. Take this device. You will reinforce my wards to ensure he does not take notice of me as well. The last thing I need is a loud, inelegant mortal bringing more attention my way. I can't have the Jailer capturing me, after all. I'm far too valuable.", ["objectivesText"] = "Reinforce 4 Soul Wards . Progress: Our business is not yet complete. Attend to my wards.", ["rewardXP"] = 3745, ["rewardItems"] = { 184314 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1238, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1238, ["questLineOrder"] = 1 }, { ["id"] = 168, ["title"] = "J