[61433] = { ["id"] = 61433, ["name"] = "Giant Lungcap", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 61433 }, ["objectivesText"] = "Progress: Is that... a lungcap? How did you possibly find one of those here in Revendreth ? No matter. Throw it on a platter! Perhaps they will not notice how terrible it tastes.", ["rewardItems"] = { 181369 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165500, ["x"] = 0.358923, ["y"] = 0.590615 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165500, ["x"] = 0.358923, ["y"] = 0.590615 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.358923, ["y"] = 0.590615 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
