[61436] = { ["id"] = 61436, ["name"] = "Field Trip", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61436 }, ["series"] = { 61364 }, ["description"] = "Now that you have the catalyst, you need only bring it to Mortimer in Maldraxxus. Our last correspondence indicates that his laboratory is still in-tact within the former House of Plagues. Exercise caution in your journey--what remains of the house is fraught with danger, and Mortimer himself has earned a less than pristine reputation among his peers.", ["objectivesText"] = "Bring the Catalyst of Creation to Mad Mortimer in the House of Plagues in Maldraxxus. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 181470 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172141, ["x"] = 0.592, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
