[61524] = { ["id"] = 61524, ["name"] = "The Ember Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61524 }, ["description"] = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!", ["objectivesText"] = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 176126, 176127, 176128, 176130, 176131, 176132, 176134, 176135, 176136, 176138, 176139, 176140, 176850, 179958, 181521, 181524, 181536, 182342, 182343 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
