[61548] = { ["id"] = 61548, ["name"] = "Set Me Free", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 61551 }, ["description"] = "Ansid has been captured and imprisoned by the foundry's guards. It seems they were expecting us, completely shattering the element of surprise. My baroness would be disappointed in my lack of foresight. This plan cannot succeed without Ansid. One of these soldiers is bound to possess the key to his cage. Should you find it, we may yet carry out my baroness's will.", ["objectivesText"] = "Find the Ossein Key on one of the Ossein Strongarms and use it to free Ansid. Progress: Take caution.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 128952, 133312, 181785 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.2876, ["y"] = 0.4564 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 5, ["flags"] = 0 } } },
