[61550] = { ["id"] = 61550, ["name"] = "Strengthening the Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "I know how you feel... and what you have endured for the sake of your world. You now know of my own triumphs and tragedies as well. Our bond will grow stronger over time. But for now, let us see what it has granted us. Ardenweald has needs of us. We must do everything in our power to save it.", ["objectivesText"] = "Activate a Soulbind Power using the Forge of Bonds. Progress: We are stronger together.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 180847, 181373, 181467, 181469, 181512, 181539, 181639, 181707, 181774, 181775, 181840, 181962, 182106, 182108, 182113, 182129, 182130, 182133, 182288, 182317, 182324, 182331, 182335, 182336, 182347, 182348, 182448, 182460, 182463, 182466, 182469, 182584, 182651, 182685, 182767, 182777, 182962, 182964, 183199, 183463, 183466, 183467, 183473, 183474, 183494, 183495, 183496, 183500, 199456, 199459, 199460 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 28, ["flags"] = 0 } } },
[61551] = { ["id"] = 61551, ["name"] = "Crush 'Em All", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 61548 }, ["description"] = "The mooring platform will be our best launching point to access the necropolis above. But one more fight remains before us. Enforcer Borgulla oversees all of the work efforts that take place here. We'll need to eliminate her if we are to proceed unhindered. She is a formidable foe. It appears Ansid has kept some of his explosives on his person. Let us utilize this advantage.", ["objectivesText"] = "Use Ansid's Explosive to kill Enforcer Borgulla .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 31537, 31538, 31539, 31540, 43858, 43911, 43927, 43928, 43929, 49927, 57357, 57358, 57359, 59050, 59051, 59052, 63821, 63822, 63823, 131516, 182250, 182259, 182268, 182277 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.2876, ["y"] = 0.4564 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 6, ["flags"] = 0 } } },
[61552] = { ["id"] = 61552, ["name"] = "The Hunt Watches", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61552 }, ["series"] = { 61553 }, ["description"] = "The Wild Hunt protects. Many eyes watch for danger. Many ears listen for secrets. Watcher Vesperbloom directs the eyes and ears of the forest. Seek out our new growth, then turn to her for guidance.", ["objectivesText"] = "Activate Adventures then seek out Watcher Vesperbloom . Progress: Ah. You're here. Good.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164023, ["x"] = 0.446, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61553] = { ["id"] = 61553, ["name"] = "Know Where to Strike", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61553 }, ["series"] = { 61552 }, ["description"] = "It is the Wild Hunt's duty to hunt down those who would harm our charges and to ensure the security of our borders. But as the crisis has grown, so have our duties to Queen and Grove. This is where I come in. It is my duty to be aware of all that goes on within the endless forest. It is my charge to help deploy our resources, so that we may aid our queen. Allow me to demonstrate...", ["objectivesText"] = "Use the Command Table to send your forces on an adventure. Progress: Every victory furthers our cause.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 164023, ["x"] = 0.446, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164023, ["x"] = 0.446, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61554] = { ["id"] = 61554, ["name"] = "The Play's The Thing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 61554 }, ["series"] = { 58104, 58157, 58158, 58159 }, ["description"] = "You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt. <Vesperbloom could be smirking... Or it could be a trick of the light.> Before our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold. Lady Moonberry awaits you in the Sanctum Hall with more information. Break a leg.", ["objectivesText"] = "Seek out Lady Moonberry in the Heart of the Forest central hall.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61556] = { ["id"] = 61556, ["name"] = "Party Crashers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61556 }, ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54302, 54303 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2QuestInfoID"] = 272, ["db2QuestInfoName"] = "VenthyrPartyQuest" },
[61557] = { ["id"] = 61557, ["name"] = "An Echo in the Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61557, 61558, 61559, 62569 }, ["description"] = "$p, I... I am beset by dark visions. A power emanating from within Torghast. A familiar sensation. One I have not felt since... Come to Oribos . Do not delay.", ["objectivesText"] = "Meet Bolvar Fordragon in Oribos .", ["rewardGold"] = 154900, ["rewardXP"] = 1020, ["rewardItems"] = { 179358, 184315 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1140, ["name"] = "A Fateful Vision", ["orderIndex"] = 0, ["flags"] = 0 } } },
[61558] = { ["id"] = 61558, ["name"] = "The Highlord's Vision", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61557, 61558 }, ["description"] = "< Thrall 's brow is furrowed.> We were speaking with the Highlord when he was struck by a jolt of agony. He said he could see something stirring in the Maw. Inside the Jailer's tower. The pain seems to be getting worse. We need to find out what he's sensing.", ["objectivesText"] = "Find out what Bolvar senses inside Torghast. Progress: We must know the truth.", ["rewardItems"] = { 184315 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 155, ["title"] = "9.0 Covenant Campaigns Ch 3 - Peering Into Darkness", ["questLineID"] = 1138, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1138, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1138, ["name"] = "Peering into Darkness", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1140, ["name"] = "A Fateful Vision", ["orderIndex"] = 1, ["flags"] = 0 } } },
[61559] = { ["id"] = 61559, ["name"] = "A Mourneblade Born", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61557, 61559, 62569 }, ["description"] = "While his father was missing, I cared for Anduin like a son. To see him like that, at the mercy of Sylvanas... <Bolvar's eyes flare with fire.> Something must be done. Take a moment. Let me know when you are ready to discuss what comes next.", ["objectivesText"] = "Discuss the vision with Bolvar and the others.", ["rewardItems"] = { 184315 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 155, ["title"] = "9.0 Covenant Campaigns Ch 3 - Peering Into Darkness", ["questLineID"] = 1138, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1138, ["qu