[61567] = { ["id"] = 61567, ["name"] = "Grave Intent", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "My spies have identified several astral projectors that Margrave Gharmal uses to rally their troops in the Stitchyard. I do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor. See to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", ["objectivesText"] = "Destroy the Southwestern, Northwestern, and Notheastern Astral Projectors .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167173, ["x"] = 0.286, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167173, ["x"] = 0.286, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 12, ["flags"] = 0 } } },
[61569] = { ["id"] = 61569, ["name"] = "Keys to the Ruin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["description"] = "At last, our target is within reach. The necropolis rests above us, moored to this platform by a necrotic restraining bolt. Twigin can fly you to the apex of the necropolis. It will be ours to command once you insert this keystone. We will prepare for our departure. Rejoin us when you are done. Victory will soon be ours.", ["objectivesText"] = "Fly with Twigin to the necropolis's apex and plug in the Runic Keystone. Progress: Our mission is nearly complete.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172805, ["x"] = 0.3, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 7, ["flags"] = 0 } } },
[61586] = { ["id"] = 61586, ["name"] = "Machinations of War", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 59894 }, ["description"] = "With Bastion as our ally, we have the strength to crush Gharmal and the House of Constructs. We'll gather the supplies for the attack, but our soldiers need a great champion to follow into battle. Prove to them that you are the champion they seek.", ["objectivesText"] = "Increase your Renown.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166535, ["x"] = 0.504, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 0, ["flags"] = 0 } } },
