[61697] = { ["id"] = 61697, ["name"] = "A New Age", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "With the final empowerment in place, our renewed Crest of Ascension stands bolstered by the might of not just Bastion , but all covenants. Soon new Ascended will grace these halls once more as aspirants finish their long-awaited trials. None of this would be possible without your aid, Maw Walker. The honor of activating the Crest at last is yours.", ["objectivesText"] = "Activate the Crest of Ascension. Progress: This is a glorious moment for all kyrian.", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 12, ["flags"] = 0 } } },
