[61785] = { ["id"] = 61785, ["name"] = "An Expected Visitor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61767, 61768, 61769 }, ["description"] = "One Alexandros Mograine of Maldraxxus is meeting with the Paragon of Courage in Archon's Rise. Xandria has requested you join them. The two worked together recently to repel a nascent secondary assault on the Temple of Courage. Xandria seems to trust him well enough, so we have granted him access to the hold...for now. I suspect they will not stay here long. You should make haste.", ["objectivesText"] = "Speak with Xandria in Archon's Rise.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 0, ["flags"] = 0 } } },
