[61839] = { ["id"] = 61839, ["name"] = "Nipping at the Undergrowth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61839 }, ["description"] = "<The small gorger nips at your heels hungry and seeking your protection. Maybe it will like some of the plants here?>", ["objectivesText"] = "Collect Endmire Vineroot . Progress: Collect Endmire Vineroot for your small gorger.", ["rewardXP"] = 4085, ["rewardItems"] = { 182314, 182590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
