[61871] = { ["id"] = 61871, ["name"] = "To Current Matters", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 862, ["storyline"] = { 61871 }, ["description"] = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next. Ye best get back te matters at hand, and do what ye can te empower that necklace o' yours. I've got ways te reach ye once MOTHER and I have fixed things up here.", ["objectivesText"] = "Return to Nathanos Blightcaller on the Banshee's Wail in Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 158075 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
