[61874] = { ["id"] = 61874, ["name"] = "Shadowlands: A Chilling Summons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 59751, 59752, 59753, 59757, 59758, 59765, 59766, 59907, 60644, 61874 }, ["description"] = "The time has come, <class>. Highlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Orgrimmar, and I will take you to him. I would not keep him waiting.", ["objectivesText"] = "Meet Darion Mograine outside Grommash Hold in Orgrimmar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 140192 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 176554, ["x"] = 0.765, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2147, ["db2PoiUiMapID"] = 1360, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 22, ["flags"] = 0 } } },
[61875] = { ["id"] = 61875, ["name"] = "Doing the Dew", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61875 }, ["description"] = "The Thistledrop is magnificent creature. The roots go deep into the earth where they drink of waters most ancient. With these waters they collect the very essence of the land into a drop of dew that enables our artisans to craft powerful armaments. Help us gather the dew and you will be well rewarded. Hurry, before it evaporates!", ["objectivesText"] = "Collect 30 Thistledrop Dew in Ardenweald's Forests. Progress: The dew evaporates quickly, hurry now!", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175728, 175740, 179532, 179584, 181399, 181400, 181401, 181402, 181407, 181409, 181410, 181411, 181412, 181413, 181417, 181418, 181429, 181430, 181457, 181459, 181477, 181479, 181541, 182333, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61876] = { ["id"] = 61876, ["name"] = "Take Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61877, 61878 }, ["description"] = "Mograine and I spoke at length when he visited Bastion. He suggested that should we manage to kill Gharmal, his heart could be used to empower the Crest of Ascension. The Margrave bears the power to shape form in ways few beings can. Though his results are grim, if we could harness that power our Ascended would be stronger than ever before. It is not our way, but our way is changing, I think. Perhaps this is a step on our new path.", ["objectivesText"] = "Collect the Fleshshaper's Heart . Progress: It must be done.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173193, ["x"] = 0.31, ["y"] = 0.29 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173193, ["x"] = 0.31, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 17, ["flags"] = 0 } } },
[61877] = { ["id"] = 61877, ["name"] = "Return to the Hold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61876, 61878 }, ["description"] = "Let us ferry the heart to Elysian Hold swiftly. There are many in the Shadowlands who would strike at us to take its power for their own. Keep your eyes open, Maw Walker. We return to our kin victorious this day.", ["objectivesText"] = "Meet Xandria at the Crest of Ascension in Elysian Hold in Bastion.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173193, ["x"] = 0.31, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 18, ["flags"] = 0 } } },
[61878] = { ["id"] = 61878, ["name"] = "Crest of Greatness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61876, 61877 }, ["description"] = "Once you are ready, all you must do is place the heart within the sphere here on the Crest of Ascension. Mikanikos's handiwork will ensure that its energy is channeled properly to aid in our ascension rituals, and its power should help protect the Crest against any further attack. May the House of Constructs never set foot in our realm again.", ["objectivesText"] = "Place the Fleshshaper's Heart in the Crest of Ascension. Progress: <This looks to be the orb Xandria directed you to place the heart in.>", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 19, ["flags"] = 0 } } },
