[62046] = { ["id"] = 62046, ["name"] = "A New Pack", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 62046 }, ["description"] = "<The gorger is more than fully grown, rivaling most of the other devourers in the area. It clearly wants to stay with you, but it appears to be uneasy straying too far from the world eaters. Maybe if you take one down together it will not hold as much sway over the gorger.>", ["objectivesText"] = "Defeat an Unbidden Worldeater . Progress: <The gorger gestures in the direction of a worldeater, seemingly feeling up to the challenge with you by its side.>", ["rewardXP"] = 4085, ["rewardItems"] = { 182589 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
