[62062] = { ["id"] = 62062, ["name"] = "Restock: Stolen Rugs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62062 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, those thieves steal more than memories. They steal rugs too! New rugs be so heavy thieves can't carry! Bring me things to make heavy rugs. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171840, 173202 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62064] = { ["id"] = 62064, ["name"] = "Restock: Broken Mirrors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62064 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, those prisoners break all the mirrors when they escape! Laurent help me fix, but need pieces. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173109 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62065] = { ["id"] = 62065, ["name"] = "Restock: My Favorite Table", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62065 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, one of them big bad dredgers sit on my favorite table, break in half! Need wood to fix table. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 177061 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62066] = { ["id"] = 62066, ["name"] = "Restock: Dredger Pool", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62066 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, that big slimeball leaked slimeball slime into our muckpool. Every new dredger all slimy! Need way to get rid of all bad stuff... You know thing does that? Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171263 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62067] = { ["id"] = 62067, ["name"] = "Restock: Statues", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62067 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, dredgers see big new statue made. All want statues now! Bring me stone and I carve tiny statues to hold. Make all dredgers happy. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171840 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62068] = { ["id"] = 62068, ["name"] = "Gormling Piper: Crumbled Ridge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62068 }, ["objectivesText"] = "Fae Flute acquired Burrowing Gormlings coaxed and bagged", ["rewardXP"] = 8165, ["rewardItems"] = { 182611 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Fae Flute acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 158969, ["orderIndex"] = 0 }, { ["text"] = "Burrowing Gormlings coaxed and bagged", ["amount"] = 8, ["type"] = 0, ["objectID"] = 173561, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[62069] = { ["id"] = 62069, ["name"] = "Restock: Sinstones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62069 }, ["objectivesText"] = "Progress: We got a problem, <name>. Last Ember Court, the Accuser's rituals were a little TOO convincing. A bunch of my dredgers want their own sinstones now, so they can list things they think they've done wrong. I'm going to need some resources to soothe their guilty consciences. Then we can pick our entertainment for the next Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62070] = { ["id"] = 62070, ["name"] = "Restock: Fragrant Flowers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62070 }, ["objectivesText"] = "Progress: We got a problem, <name>. Last Ember Court, some of the animals had... issues. I can't get the stains out and everything reeks! I'm going to need some very fragrant flowers to cover up this smell. Then we can pick our entertainment for the next Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170554 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62073] = { ["id"] = 62073, ["name"] = "Restock: Band Shirts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62073 }, ["objectivesText"] = "Progress: We got an opportunity, <name>. The Lost Chalice Band is the hottest entertainment in Revendreth after that killer performance at the last Ember Court. It's all anyone's talking about. We should make some band shirts, give 'em out for free to keep the hype rolling. Bring me the materials and I'll take care of the rest. Then we can pick our entertainment for the next Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172230, 173202 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62074] = { ["id"] = 62074, ["name"] = "Professions - Reuse", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62074 }, ["description"] = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.", ["objectivesText"] = "Bring the memory back to the Runecarver .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62075] = { ["id"] = 62075, ["name"] = "Restock: Soul Cages", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62075 }, ["objectivesText"] = "Progress: We got a problem, <name>. Last Ember Court, we were able to save quite of a few of those abused souls the Master's minions attacked us with. That's great, but we need more chains and cages if we're going to keep that many souls here until the Accuser can take them. Then we can pick our entertainment for the next Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171832, 172089 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62076] = { ["id"] = 62076, ["name"] = "Restock: Free Press", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62076 }, ["objectivesText"] = "Progress: We got a problem, <name>. Last Ember Court, that provocateur's gossip spread further than we thought. I've gotten all sorts of uncomfortable questions from socialites and nobles unsure of what to believe. We've got to write some pamphlets to set the record straight and dispel that scoundrel's lies! Then we can pick our entertainment for the next Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173059, 175886 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62078] = { ["id"] = 62078, ["name"] = "Restock: Fashion Accessories", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62078 }, ["objectivesText"] = "Progress: We got a problem, <name>. Last Ember Court, the Countess's clothier showed everyone the future of fashion and we're all way behind. Medallions are all the rage, thanks to the Prince's growing collection. I can't get a medallion, but I at least need a necklace so I don't get laughed out of courts. Then we can pick our entertainment for the next Ember Court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173141 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62080] = { ["id"] = 62080, ["name"] = "Restock: Herbal Tea", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62080 }, ["objectivesText"] = "Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, our guests drank more tea than Theotar himself! Our entire supply is depleted. I simply must acquire new tea ingredients, and I only accept the highest quality! After that, I shall happily discuss refreshment options for our next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 168583, 168589 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62081] = { ["id"] = 62081, ["name"] = "Return Those Animacones!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62081 }, ["description"] = "Reports say that once again the spriggan are proving to be a nuisance, <name>. Word is that a bunch of them broke into the stores at the Heart of the Forest and made off with a huge store of animacones. Needless to say, we need those animacones back. The report says the spriggan group split up as they were making their escape, so any one you see is as likely to be carrying the animacones as the next. Good luck.", ["objectivesText"] = "Collect 44 Looted Animacones from spriggan within Ardenweald. Progress: Were you able to find the animacones?", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175728, 179517, 179532, 181403, 181404, 181405, 181406, 181407, 181409, 181410, 181418, 181420, 181421, 181430, 181457, 181459, 181477, 181479, 181541, 182619, 183202, 183396, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62082] = { ["id"] = 62082, ["name"] = "Restock: Personal Stash", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62082 }, ["objectivesText"] = "Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, while your guests were so flippantly flinging food around court, several stray pies flew directly into my personal food supplies. Everything was ruined! You know I do not like to make a fuss, but I simply must insist that you replace the delicacies ruined by that unwelcome food fight. After that, I shall happily discuss refreshment options for our next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172051, 172069 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62083] = { ["id"] = 62083, ["name"] = "Restock: Medical Supplies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62083 }, ["objectivesText"] = "Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, those wild mushrooms you brought poisoned me and half of the socialites! Thankfully, it does not appear to be a lethal poison, but it has been most uncomfortable for all involved. We are in desperate need of anti-venom. After that, I shall happily discuss refreshment options for our next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171301 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62084] = { ["id"] = 62084, ["name"] = "Restock: Fine Cutlery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62084 }, ["objectivesText"] = "Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, the venthyr invaders did not just assault our guests--they stole our cutlery! My old friend Forgy can craft replacement cutlery for us, but we will need to provide the supplies. After that, I shall happily discuss refreshment options for our next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171828 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62085] = { ["id"] = 62085, ["name"] = "...Why Me?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62085 }, ["description"] = "<The dense, chunky liquid inside the vessel emits a horrendous odor. The initials O.K. are etched into the side. It seems someone stole Overseer Kalvaros ' canteen.>", ["objectivesText"] = "Deliver the Reclaimed Vessel to Overseer Kalvaros at the Challenger's Promenade. Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 182618 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["startItems"] = { 182618 } },
[62086] = { ["id"] = 62086, ["name"] = "Professions - Reuse", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62086 }, ["description"] = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver 's stolen memories.", ["objectivesText"] = "Bring the memory back to the Runecarver .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62087] = { ["id"] = 62087, ["name"] = "Restock: Imported Dinnerware", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62087 }, ["objectivesText"] = "Progress: I suffer yet another crisis in the kitchen, Maw Walker! Last Ember Court, the stone fiends dropped more than Theotar's tea set. They broke the dinnerware I had imported directly from Ardenweald, in order to help our Night Fae guests feel at home! I believe I can repair them, but I will need resources. After that, I shall happily discuss refreshment options for our next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171831, 177061 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
