[62155] = { ["id"] = 62155, ["name"] = "Runestone Roundup", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62155 }, ["description"] = "Stone is a rare material in Ardenweald. Yet, I've heard tales that those who were masked by the Drust have small stones upon them. I'd like you to retrieve some of these stones for the Wild Hunt , so that we may better understand their link to our enemy. Face the masked and collect the stones from their deceased forms and I'll compensate you for your efforts. It's a gruesome task, but one that must be done.", ["objectivesText"] = "Collect 18 Runestone Spikes from drust possessed fae within Ardenweald. Progress: How goes your investigation?", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175740, 179517, 179532, 179547, 179562, 179584, 181401, 181411, 181412, 181413, 181415, 181416, 181417, 181418, 181421, 181426, 181428, 181429, 181430, 181457, 181459, 181477, 181479, 181541, 182647, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62157] = { ["id"] = 62157, ["name"] = "Scouting from a Safe Distance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60827 }, ["description"] = "The resurgence of the Scourge is troubling enough, but there are also reports that the Cult of the Damned has risen anew as well. If true, then that bodes ill for us all. We cannot allow the cultists' machinations to continue unchecked. I suggest we engage in some reconnaissance.", ["objectivesText"] = "Survey the Cult of the Damned's presence at Aldur'thar and Mord'rethar. Progress: Notice anything unusual?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 3, ["flags"] = 0 } } },
[62159] = { ["id"] = 62159, ["name"] = "Aiding the Shadowlands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62000, 62159, 62704, 62716 }, ["description"] = "There is much to do within the Shadowlands. Many areas are suffering from the anima drought. The choice of who to help first is yours. Where will you go?", ["objectivesText"] = "Choose where to go in the Shadowlands.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1175, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1175, ["name"] = "Aiding the Shadowlands", ["orderIndex"] = 3, ["flags"] = 0 } } },
[62160] = { ["id"] = 62160, ["name"] = "A Bundle of Lilies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62160 }, ["description"] = "This grove needs something special, something to make it really stand out. I have a plan, but first I need flowers. Not just any flowers, but Night Lillies . They have a sweet scent that evokes starlit nights spent standing on a hilltop overlooking the majesty of the land. As you go exploring Ardenweald, look to the waterways for Night Lillies growing in the waterways and collect them. I will pay you for your efforts, of course.", ["objectivesText"] = "Collect 10 Night Lillies . Progress: Were you able to find any of the lillies?", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175740, 181401, 181404, 181405, 181406, 181407, 181412, 181416, 181417, 181423, 181424, 181425, 181429, 181430, 181457, 181477, 181479, 181541, 182659, 182686, 184378, 184381, 184382, 184383, 184384, 184487, 184519, 184665 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62161] = { ["id"] = 62161, ["name"] = "Blood from a Bone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["description"] = "I want nothing more than to make for Revendreth immediately... but it seems they have their own challenges to face. All know of the mark we left on Bastion. The venthyr are sure to be wary of allowing us into their realm. Once again, we must turn to you. Your renown across the Shadowlands has earned you the trust of many. Now, we need the trust of Revendreth.", ["objectivesText"] = "Increase your Renown.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 0, ["flags"] = 0 } } },
