[62244] = { ["id"] = 62244, ["name"] = "Digging Around", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62244 }, ["description"] = "The thin pale ones of Revendreth have been hoarding anima. I've heard they've been hiding it away, digging holes in the woods and just leaving it there. Anyone could come along and take it. I say that should be us! Let's go get some anima.", ["objectivesText"] = "Collect 15 Lost Anima Caches .", ["rewardXP"] = 8165, ["rewardItems"] = { 182488, 182497, 182506, 182515, 183043, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159212, ["x"] = 0.548, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62246] = { ["id"] = 62246, ["name"] = "A Fallen Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62246 }, ["description"] = "A bracelet delicately woven with living vines falls from Vivanna's wrist as she is slain. In the vines is written, \"Until Winter's end. - Flwngyrr \"", ["objectivesText"] = "Return this bracelet to Flwngyrr at the Heart of the Forest Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 178217, 183091 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168032, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183091 } },
[62250] = { ["id"] = 62250, ["name"] = "A New Adventure Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 62250 }, ["description"] = "<name>! You're needed in the present. Things have... well, you should just come back to see. I would finish what you're doing then head back. I can't keep you in the past for much longer!", ["objectivesText"] = "Return to Stormwind to embark on a new adventure. Chromie 's magic will run out soon, returning you to Stormwind.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 183185 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 }, { ["mapID"] = 84, ["npcID"] = 172334, ["x"] = 0.625333, ["y"] = 0.306 }, { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
