[62308] = { ["id"] = 62308, ["name"] = "Mantle of Mastery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62308 }, ["description"] = "You have done much to establish yourself as a promising acolyte. Your superiors have made it known that you are ready to be tested for your ritualist's mantle . When you are ready, begin the Ritual of Ancient Summoning to call forth an elder spirit of Maldraxxus . Conquer the spirit, and prove your mettle!", ["objectivesText"] = "Summon an elder spirit of Maldraxxus through the Prime Arcanum and defeat it. Summoning requires three players.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 183399, 183847, 187869 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172813, ["x"] = 0.679, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172813, ["x"] = 0.679, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.679, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group" },
[62317] = { ["id"] = 62317, ["name"] = "Casting Doubt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62317 }, ["description"] = "<A note has been left here for Kel'Thuzad. It does not appear that he has read it.> Baron, I do not trust your new favorite acolyte. Something has been off about them ever since they returned from their ritual with the Kyrian remains. Your work is too important to allow such discrepancies. The acolyte should be disposed of. Faithfully, Sorcerer Vutral", ["objectivesText"] = "Defeat Sorcerer Vutral in the Vault of Souls.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 183397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "group" },
[62320] = { ["id"] = 62320, ["name"] = "Regalia de Rigueur", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62320 }, ["description"] = "Ah, if it isn't Kel'Thuzad's favorite acolyte? I simply cannot understand how a baron like him would surround himself with such... homely company. When was the last time you even chanced at a looking glass? Those faded robes do your station no justice. I would take it upon myself to update your drab apparel, if I weren't sufferring such a shortage on the house's preferred amethystine tint. You could always fetch some yourself. The sorcerers usually have some stashed among their tomes and altars.", ["objectivesText"] = "Collect 10 Amethystine Powder from the House of Rituals. Progress: I will need large quantities of amethystine powder if I am to fix... <Moret gestures at you broadly.> ...this.", ["rewardGold"] = 309800, ["rewardXP"] = 10205, ["rewardItems"] = { 183400, 183401 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 174120, ["x"] = 0.715, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 174120, ["x"] = 0.715, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
