[62388] = { ["id"] = 62388, ["name"] = "House of Rituals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["series"] = { 58472, 58599, 58608, 58624 }, ["description"] = "The Ritualists are the ones behind this war. Every act of treason has been committed under their orders. We cannot defeat their sorcery with strength of arms alone. Victory will hinge on our knowledge of what they are plotting. Continue to bolster our forces. I will look for a way to infiltrate the House of Rituals.", ["objectivesText"] = "Increase your Renown.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 0, ["flags"] = 0 } } },
[62389] = { ["id"] = 62389, ["name"] = "Rebuild Our Trust", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62389 }, ["description"] = "So you have taken the first step to reclaiming our trust. Now you must prove that was not another false start in our relationship. This final task should prove your willingness to rejoin our ranks.", ["objectivesText"] = "Complete the task for the Venthyr.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62390] = { ["id"] = 62390, ["name"] = "Body Count", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62390 }, ["description"] = "I am acquainted with a few fleshcrafters who work outside of the House of Constructs. If we can find reagents for them, they can supply our war effort with constructs. The House of Constructs has plenty of excess body parts. Find them and bring them back here.", ["objectivesText"] = "Collect 30 abomination parts from around Maldraxxus . Progress: We'll take any quality of parts you can find.", ["rewardGold"] = 257400, ["rewardItems"] = { 180275, 181645, 181646, 181647, 181648, 181649, 181650, 181652, 181654, 181655, 181668, 181670, 181677, 181680, 181681, 181686, 183600, 184195, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62391] = { ["id"] = 62391, ["name"] = "Mobilize Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58833, 59020, 62391, 62406 }, ["series"] = { 58833, 61761 }, ["description"] = "It will be difficult to reach Kel'Thuzad while he is in his necropolis. Go now. It will take time for us to muster an army that can pierce his defenses.", ["objectivesText"] = "Increase your Renown.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1118, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1118, ["name"] = "Assault on the House of Rituals", ["orderIndex"] = 0, ["flags"] = 0 } } },
[62392] = { ["id"] = 62392, ["name"] = "Rebuild Our Trust", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62392 }, ["description"] = "You return as requested. Impressive, maybe you have indeed turned a new leaf. I wish to see you complete one more task for us. To prove your dedication to this transition. Not that we doubt you, but you must understand your previous behavior gives us reason to doubt that dedication.", ["objectivesText"] = "Complete the task for the Night Fae.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62393] = { ["id"] = 62393, ["name"] = "Rebuild Our Trust", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62393 }, ["description"] = "You still have the same strength you had before it seems. The question is - do you have any loyalty left within you? I have one more task so you can demonstrate that loyalty again.", ["objectivesText"] = "Complete the task for the Necrolords.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62400] = { ["id"] = 62400, ["name"] = "Go Beyond!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62400 }, ["description"] = "Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181420, 181421, 181422, 181423, 181424, 181425, 181427, 181428, 181429, 181430, 181457, 181459, 181461, 181477, 181479, 181541, 184381, 184382, 184383, 184384, 194371, 194372, 194376, 194393, 194416, 199461, 200960, 204076, 204586, 204594, 204602, 204610, 210024, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62401] = { ["id"] = 62401, ["name"] = "Strange Scourgestones", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62401 }, ["description"] = "The Lich King's minions once carried scourgestones given to them by their dark master. New ones have been found on the corpses of the undead. We do not know their purpose... but they have been touched by even more sinister magic. As you slay the Scourge across Icecrown, keep your eyes open for such stones. If you bring them back to me, I shall turn them over to the confessors for study.", ["objectivesText"] = "Collect Darkened Scourgestones and Pitch Black Scourgestones from undead forces in Icecrown. Progress: How goes your slaying of the undead?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 180720, 183200 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 169718, ["x"] = 0.71, ["y"] = 0.216 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 169718, ["x"] = 0.71, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[62403] = { ["id"] = 62403, ["name"] = "Boared to Death", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62403 }, ["description"] = "The boars around Maldraxxus have a peculiar trait. Their tusks absorb liquid. Depending on where it has been, these bones may contain a powerful compound of poisons or other alchemical rarities. It takes a trained eye to tell what the bone is made of, so just bring back a large amount of them. From there I will see if any of them are valuable.", ["objectivesText"] = "Collect 25 bloody tusks from the boars in Maldraxxus . Progress: Take care not to let any of the bones touch your skin for too long. They may cause irritation.", ["rewardGold"] = 257400, ["rewardItems"] = { 181503, 181507, 181638, 181645, 181647, 181649, 181650, 181654, 181656, 181657, 181658, 181670, 181671, 181672, 181673, 181674, 181676, 181677, 181678, 181689, 181690, 181695, 181697, 183620, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62406] = { ["id"] = 62406, ["name"] = "Staff of the Primus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58833, 59020, 62391, 62406 }, ["description"] = "The Staff of the Primus . The final piece of our leader's regalia. I can't deny the pride I feel in restoring this hall. You should feel the same sense of accomplishment. The statue awaits you, <name>. Bring glory to this realm.", ["objectivesText"] = "Place the Staff of the Primus upon the Statue of the Primus.", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 183888, 183889, 183890, 183891, 183892, 183893 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1118, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1118, ["name"] = "Assault on the House of Rituals", ["orderIndex"] = 3, ["flags"] = 0 } } },
[62407] = { ["id"] = 62407, ["name"] = "Herbicidal Tendencies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62407 }, ["description"] = "My gas is the most potent in all of Maldraxxus, but I've heard some of the others saying that it's not the strongest in the Shadowlands. They claim there are some plants in Ardenweald with a bloom that is far more pungent than my gas. Nonsense! Let's go and check these plants out. If their stench is as strong as the stories claim, I might even be able to mix them in with my own gas!", ["objectivesText"] = "Help Gas Bag collect Rotbloom Petals . Progress: Having fun picking flowers?", ["rewardXP"] = 8165, ["rewardItems"] = { 182481, 182490, 182499, 182508, 183133, 183719, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159240, ["x"] = 0.542, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62414] = { ["id"] = 62414, ["name"] = "Burying Suspicion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "It will do us no good to disguise yourself as Nelesis if word reaches Kel'Thuzad that she was slain. You must ensure that no one who sees you enter the cave survives.", ["objectivesText"] = "Kill 10 Lichsworn forces outside the House of Rituals.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 4, ["flags"] = 0 } } },
[62420] = { ["id"] = 62420, ["name"] = "Snapper Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62420 }, ["description"] = "<The Snapper Soul is determined. The shape of the dragon turtle will be yours to call upon.>", ["objectivesText"] = "Bring the Snapper Soul to Lady Muunn in the Heart of the Forest. Provided item:", ["rewardItems"] = { 181313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 181313 } },
[62421] = { ["id"] = 62421, ["name"] = "Gulper Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62421 }, ["description"] = "<The Gulper Soul is patient and calm. The shape of the Gulper will be yours to call upon.>", ["objectivesText"] = "Bring the Gulper Soul to Lady Muunn in the Heart of the Forest. Provided item:", ["rewardItems"] = { 181314 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 181314 } },
[62422] = { ["id"] = 62422, ["name"] = "Ardenmoth Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62422 }, ["description"] = "<The Ardenmoth is plentiful in Ardenweald . Delicate looking creatures, they have hidden strength. Their magic can soothe the most tortured soul... or send the unwary into an eternal sleep. The shape of the moth will be yours to call upon.>", ["objectivesText"] = "Bring the Ardenmoth Soul to Lady Muunn in the Heart of the Forest. Provided item:", ["rewardItems"] = { 182165 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 182165 } },
