[62441] = { ["id"] = 62441, ["name"] = "Fair Exchange for a Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62441 }, ["description"] = "While we work away here in the Conservatory, we must not forget to support the rest of the covenant. I am needed here, but you can range far, even though your legs are short. Please, help our covenant recover the anima we need. I can then dedicate my time to preparing another spirit for you to restore.", ["objectivesText"] = "Collect anima for your Sanctum. Progress: Go, find more anima. I shall tend to the spirits while you do.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 177699, 178877, 178880, 178883, 180974 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62442] = { ["id"] = 62442, ["name"] = "Aid the Covenant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62442 }, ["description"] = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger. You are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.", ["objectivesText"] = "Complete a World Quest in Ardenweald.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
