[62444] = { ["id"] = 62444, ["name"] = "Aid the Covenant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62444 }, ["description"] = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger. You are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!", ["objectivesText"] = "Complete a World Quest in Ardenweald. Progress: Head out into the Shadowlands. Return to me with stories of your exploits.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62445] = { ["id"] = 62445, ["name"] = "A Spirit's Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62445 }, ["description"] = "I seek to understand more about the prideful beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.", ["objectivesText"] = "Place a Prideful Spirit into a wildseed. Progress: Find a prideful spirit to restore. That is what I wish to see today.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62447] = { ["id"] = 62447, ["name"] = "A Rare and Unusual Spirit", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62447 }, ["description"] = "I have a mystery for you, <name>! Who doesn't savor a good mystery? We have found a spirit unlike any other, one who does not respond to being placed in a wildseed. Each of us who touched it experienced a dream in which we saw you battling a great beast. Only when you defeated it did the spirit begin on its path to rebirth. We think we know the beast. Are you up for discovering if these dreams were a portent?", ["objectivesText"] = "Defeat Tred'ova in Mists of Tirna Scithe.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 183704, 183805, 183806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62448] = { ["id"] = 62448, ["name"] = "Securing the House", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "Your journey into the Maw was impressive, but it will take even more phenomenal feats to earn the loyalty of the Maldraxxi. Increase your renown among our ranks, Maw Walker. The Maldraxxi are dedicated soldiers, but they will not follow just anyone into battle. Let your deeds prove your worth to them.", ["objectivesText"] = "Increase your Renown.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 0, ["flags"] = 0 } } },
[62449] = { ["id"] = 62449, ["name"] = "A Spirit's Duty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62449 }, ["description"] = "I seek to understand more about the Dutiful beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.", ["objectivesText"] = "Place a Dutiful Spirit into a wildseed. Progress: Find a Dutiful spirit to restore. That is what I wish to see today.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62450] = { ["id"] = 62450, ["name"] = "A Spirit's Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62450 }, ["description"] = "I seek to understand more about the Untamed beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.", ["objectivesText"] = "Place an Untamed Spirit into a wildseed. Progress: Find an Untamed spirit to restore. That is what I wish to see today.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
