[62653] = { ["id"] = 62653, ["name"] = "Stop the Inquisition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62653 }, ["description"] = "The Lord Chamberlain's inquisitors still torment the poor souls trapped under their care. You must put a stop to their wicked deeds! Speak with Archivist Fane, whom you worked with before to defeat an inquisitor, to acquire the sinstone of another inquisitor in the halls. With their sinstone, you will be able to shatter that inquisitor's defenses and lead the charge to defeat them. Bring friends, $p. Many of the inquisitors are far too dangerous to approach alone.", ["objectivesText"] = "Defeat any inquisitor in Halls of Atonement. Archivist Fane can provide Inquisitor Sinstones to help you in your hunt. Progress: Archivist Fane can help you acquire an inquisitor's sinstone.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172996, 173006, 179535, 180376 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173705, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1190, ["name"] = "Stop the Inquisition", ["orderIndex"] = 0, ["flags"] = 0 } } },
[62654] = { ["id"] = 62654, ["name"] = "Maw Walker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "I believe now it is time for you to leave. You are a Maw Walker, one who can activate the waystone between the Maw and the lands beyond. While your friends may not hold the same title, there is a way to send them through the gate. Souls can be connected. In theory, if you let someone attune themselves to your soul while you activate the waystone, you both should be able to leave. Even fleeting connections may produce some result. Go with your other two guests and see if my hypothesis is correct.", ["objectivesText"] = "Attune with Darion and Alexandros and assist them in leaving the Maw.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 175511, 175524, 175525, 175526, 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 10, ["flags"] = 0 } } },
[62691] = { ["id"] = 62691, ["name"] = "A Calling in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 62691 }, ["series"] = { 59323, 62695, 62856, 62857 }, ["description"] = "We got a lot of problems out there, boss. Big ones, little ones, really smelly ones, it's a lot. If we're gonna take on Denathrius, the first thing we gotta do is clean up right here in Revendreth. We get things cleaned up, yeah? Then we get some new allies, and we probably get our hands on some anima to boot. It's a call to action, it is. And it's important that we get started right away. Get on out there and get your boots muddy!", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: What do ya want?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62692] = { ["id"] = 62692, ["name"] = "A Calling in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 62692 }, ["series"] = { 57895, 57905, 62698, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "Our forces are weakened by doubt and our temples are under assault. If we are to aid the rest of the Shadowlands, we must begin here, in Bastion. Travel the golden fields and root out evil wherever you may find it. In time, we will rebuild our forces and our anima stores, and stand tall once more. Today, you walk the path of courage--it is your calling. Show our people that doubt will not fester here.", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Do the hills echo with the cries of your victories, Maw Walker?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62693] = { ["id"] = 62693, ["name"] = "A Calling in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 62693 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Ardenweald is fractured, its roots strangled. Before we can begin to regrow our glades, we must unearth the evils that have festered here. We call to you, today, to defend our forests. Take the weald paths through our lands, aiding our allies and defeating our enemies. With these actions, we will renew our forces, and rebuild our anima. In time, hope will blossom. Our trust is in you, our newest seedling.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you brought hope and faith to our people today?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62694] = { ["id"] = 62694, ["name"] = "A Calling in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 62694 }, ["series"] = { 62833, 62834, 62835 }, ["description"] = "Today marks the beginning of our path to victory. Enemies surround us on all sides. Aid our troops on the battlefield and return with the resources we need to wage our war. Once we have secured our home front, we can direct our efforts outwards. Such is your calling. Failure is unacceptable.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: How goes the battle?", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62695] = { ["id"] = 62695, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59323, 62691, 62856, 62857 }, ["description"] = "An opportunity has arisen that will be perfect for you to display your... prowess... to the denizens of Revendreth. Speak with Rendle . That dredger is disturbingly effective when it comes to hatching schemes. He says he has a plan for you.", ["objectivesText"] = "Speak with Rendle .", ["rewardGold"] = 33100, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } } },
[62697] = { ["id"] = 62697, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "< Laurel picks out a sad tune on her harp.> Our groves wilt and wither, and enemies wait at our gates! The forest calls out in sorrow, \"Please help us before it's too late!\" <The melody becomes a call to arms.> O <huntsman/huntress>, now answer our calling! Ardenweald is in need of your might! Envoy Blodwyn will give you a mission, to ride with the Wild Hunt tonight!", ["objectivesText"] = "Speak with Blodwyn .", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[62698] = { ["id"] = 62698, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57895, 57905, 62692, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "Elysian Hold requires anima to operate fully. We need as much as we can so it may serve our needs. Our temples are fraught with challenges. By heeding their call you will recover anima for use within the sanctum here. Speak with Hermestes first, who will guide you on the path of courage.", ["objectivesText"] = "Speak with Hermestes .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 9, ["flags"] = 0 } } },
[62700] = { ["id"] = 62700, ["name"] = "Ashes of the Tower", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62700 }, ["description"] = "Your first step towards obtaining the power is to retrieve... something. Yes, I believe it's coming back to me.", ["objectivesText"] = "Collect 1250 Soul Ash in Torghast. Progress: Have you recovered what is needed?", ["rewardItems"] = { 187077 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62704] = { ["id"] = 62704, ["name"] = "The Threads of Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62000, 62159, 62704, 62716 }, ["series"] = { 62000, 62716 }, ["description"] = "It is my duty to observe the strands of fate. The wondrous possibilities that the Purpose lays before us. Fate flows around you, mortal. It shifts. It changes. But I have stilled its movements to offer you... a choice. You may journey through the Shadowlands in the same manner as those who came before you have done. Or you may choose a different path. One that lets you forge a bond with a covenant now, and move freely through the realms of Death to forge your own destiny. What say you, mortal?", ["objectivesText"] = "Speak with Fatescribe Roh-Tahl and decide how you want to experience Shadowlands. Progress: Fate is not fickle. Should you accept its offer, there will be no turning back.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 188167, 190189 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1175, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1257, ["questLineOrder"] = 32 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1175, ["name"] = "Aiding the Shadowlands", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1257, ["name"] = "Time Skip", ["orderIndex"] = 3, ["flags"] = 0 } } },
[62705] = { ["id"] = 62705, ["name"] = "Scour the Temple", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62705 }, ["objectivesText"] = "Defend the temple Terrified Steward rescued Vesper of Purity cleansed Vesper of Harmony cleansed Forsworn Axiom destroyed", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defend the temple", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Terrified Steward rescued", ["amount"] = 13, ["type"] = 0, ["objectID"] = 174875, ["orderIndex"] = 5 }, { ["text"] = "Vesper of Purity cleansed", ["amount"] = 7, ["type"] = 0, ["objectID"] = 157622, ["orderIndex"] = 7 }, { ["text"] = "Vesper of Harmony cleansed", ["amount"] = 7, ["type"] = 0, ["objectID"] = 157625, ["orderIndex"] = 8 }, { ["text"] = "Forsworn Axiom destroyed", ["amount"] = 20, ["type"] = 0, ["objectID"] = 174876, ["orderIndex"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[62707] = { ["id"] = 62707, ["name"] = "The Elysian Fields", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1533, ["storyline"] = { 62707 }, ["series"] = { 62723, 62729, 63034 }, ["description"] = "You must travel to Bastion , eternal home of the winged kyrian. Do not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren. They will benefit greatly from your aid. Seek one known as Kalisthene in the crossroads called Hero's Rest. She will direct you further. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Kalisthene at Hero's Rest in Bastion .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62712] = { ["id"] = 62712, ["name"] = "War of Attrition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62712 }, ["objectivesText"] = "Wear down the enemy Forces", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Wear down the enemy Forces", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62714] = { ["id"] = 62714, ["name"] = "A Gift for an Acolyte", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60466, 62714, 62715 }, ["description"] = "The materials you supplied were more than sufficient for my purposes. For that, you have my gratitude. I think I know how to make the best use of the excess. A dear friend of mine recently achieved the role of Acolyte in service to the Temple of Purity. You are new here, so I will spare you the details, but it is an honor to serve a temple before one reaches ascension. I want to celebrate her success with a gift. Will you take this parcel to Acolyte Amalthina ?", ["objectivesText"] = "Deliver Klystere's Gift to Acolyte Amalthina in the Temple of Purity. Progress: Welcome to the Temple of Purity. How may I be of service?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 183966 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160598, ["x"] = 0.478, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 174900, ["x"] = 0.538, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1151, ["name"] = "An Act of Service", ["orderIndex"] = 1, ["flags"] = 0 } } },
[62715] = { ["id"] = 62715, ["name"] = "More Than A Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60466, 62714, 62715 }, ["description"] = "You have no idea what you just delivered, do you? <She opens the parcel to reveal a wreath of Larion plumage.> I will explain, but first... I wish to return the favor. Klystere and I frequent a resting place to the north of here, along the path to the Temple of Courage. We planted a flower for our enjoyment, as we spend so much of our free time there. Bring me this bloom, if you would be so kind. Then I will tell you about the significance of this gift.", ["objectivesText"] = "Acquire 1 Cultivated Windblossom . Progress: Did you find the place I mentioned? And the flower?", ["rewardGold"] = 316013, ["rewardXP"] = 1060, ["rewardItems"] = { 183967 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 174900, ["x"] = 0.538, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 174900, ["x"] = 0.538, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1151, ["name"] = "An Act of Service", ["orderIndex"] = 2, ["flags"] = 0 } } },
[62716] = { ["id"] = 62716, ["name"] = "Re-Introductions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62000, 62159, 62704, 62716 }, ["series"] = { 62000, 62704 }, ["description"] = "Though you have chosen your path, the fate of the Shadowlands has yet to be determined. The power of the Banished One grows. It falls to you, and others of your kind, to thwart him. The Arbiter's Honored Voice, Tal-Inara , will aid you in choosing a covenant. Bolstering their strength offers our best chance at victory. Let the Purpose guide you, <name>. Always.", ["objectivesText"] = "Speak with Tal-Inara within the Enclave in Oribos .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1175, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1175, ["name"] = "Aiding the Shadowlands", ["orderIndex"] = 1, ["flags"] = 0 } } },
[62718] = { ["id"] = 62718, ["name"] = "Hero's Rest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62718 }, ["description"] = "In light of the new arrivals to Bastion , Kalisthene has enabled the anima gateways to Hero's Rest once more! Those wishing to partake of breathtaking views, unparalleled steward service, and all manner of training and repair facilities should venture to this most remarkable of locations at their earliest convenience. Simply follow the path north and bear to the right at the crossroads. Kalisthene will personally greet all new arrivals for this most joyous of occasions!", ["objectivesText"] = "Speak to Kalisthene in Hero's Rest.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 }, { ["mapID"] = 1533, ["npcID"] = 165045, ["x"] = 0.528, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[62719] = { ["id"] = 62719, ["name"] = "The Final Pieces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62719 }, ["description"] = "The final components you'll need to acquire are... vessels... rune vessels! Armor to hold the might that will be imbued. And... powers? No... missives? Yes! Missives will allow your item to enhance your own personal strengths. But they cannot be the same. No, the two must offer different benefits. All of these can be obtained from souls with the correct crafting knowledge. And lastly, more of my memories. Memories of the runes, of the powers... of myself.", ["objectivesText"] = "Acquire a Runecarver Memory, an Armor Rune Vessel suitable to your class, and two different Missives. These items can be obtained through crafting, or can be found on the Auction House. Progress: Have you acquired the remaining items?", ["rewardItems"] = { 173160, 173161, 173162, 173163, 183243, 183244, 183249 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62720] = { ["id"] = 62720, ["name"] = "The Fallen Tree", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62720 }, ["objectivesText"] = "Tirna Noch reclaimed", ["rewardGold"] = 1029600, ["rewardXP"] = 13630, ["rewardItems"] = { 184015 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Tirna Noch reclaimed", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
