[62729] = { ["id"] = 62729, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62723, 62729 }, ["series"] = { 62707, 62723, 63034 }, ["description"] = "You have proven yourself a worthy ally of Bastion in your time here, <name>. Though I wish you could remain here, there are other realms in the Shadowlands that require aid more. Return to Oribos when you are able and seek out Tal-Inara . She will help you decide where to best next focus your efforts. Archon watch over you.", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1155, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1155, ["name"] = "Bolstering Bastion", ["orderIndex"] = 1, ["flags"] = 0 } } },
[62730] = { ["id"] = 62730, ["name"] = "Fruit of the Gods", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62730 }, ["series"] = { 62733 }, ["description"] = "You like sweet fruit? Stewards grow juiciest Purian. It special fruit! You find it many places in Bastion . It used for many things. Eat for nourishment. Give to bells for blessings. Give to stewards for treasure. You find, I show you how!", ["objectivesText"] = "Bring Elios 1 Ripe Purian fruit. Progress: You find sweet Purian?", ["rewardGold"] = 316013, ["rewardXP"] = 6125, ["rewardItems"] = { 178915, 180049 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 170284, ["x"] = 0.532, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 170284, ["x"] = 0.532, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
