[62738] = { ["id"] = 62738, ["name"] = "A Fresh Blade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1536, ["storyline"] = { 62738 }, ["series"] = { 62748, 62761, 63035 }, ["description"] = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other. Their armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus. Speak to Secutor Mevix at the Bleak Redoubt in Maldraxxus . His tactical skills will ensure you are sent where you are most needed. Pathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", ["objectivesText"] = "Speak to Secutor Mevix at the Bleak Redoubt in Maldraxxus .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62739] = { ["id"] = 62739, ["name"] = "Restoring Balance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1565, ["storyline"] = { 62739 }, ["series"] = { 62763, 62776, 63036 }, ["description"] = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm. Unfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle. Now foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. Lady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Lady Moonberry at the Heart of the Forest in Ardenweald .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 211279 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62740] = { ["id"] = 62740, ["name"] = "Dark Aspirations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1525, ["storyline"] = { 62740 }, ["series"] = { 62778, 62779, 63037 }, ["description"] = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth 's vast anima stores into the Maw. You must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Prince Renathal in the crypt beneath Darkhaven in Revendreth .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 175056, ["x"] = 0.614, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
