[62776] = { ["id"] = 62776, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 62763, 62776 }, ["series"] = { 62739, 62763, 63036 }, ["description"] = "I wish you could stay and relax here, maybe enjoy a play at the Star Lake Amphitheater, but there's simply no time! There are other realms out there that need your help, too. You will always be a friend of the Court, but I'm afraid you must return to Oribos. The Shadowlands needs you!", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1168, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1168, ["name"] = "Aiding Ardenweald", ["orderIndex"] = 1, ["flags"] = 0 } } },
[62778] = { ["id"] = 62778, ["name"] = "Reinforcing Revendreth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62778, 62779 }, ["series"] = { 62740, 62779, 63037 }, ["description"] = "Denathrius must be stopped at all costs. However, we've no hope of taking him out while his forces still control much of Revendreth . If you are here to aid us, then there is no shortage of work to be done. Disposing of my father's many allies being chief among that work, of course, but any aid you can provide will be of use. There is too much at stake for all the Shadowlands if we fail. I will see to it that you are handsomely rewarded for your efforts.", ["objectivesText"] = "Aid Revendreth by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Revendreth dungeons.", ["rewardGold"] = 4118400, ["rewardXP"] = 13630, ["rewardItems"] = { 181208, 181211, 181224, 181549 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 175056, ["x"] = 0.614, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 175056, ["x"] = 0.614, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1172, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1172, ["name"] = "Reinforcing Revendreth", ["orderIndex"] = 0, ["flags"] = 0 } } },
[62779] = { ["id"] = 62779, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62778, 62779 }, ["series"] = { 62740, 62778, 63037 }, ["description"] = "I truly wish you could remain here and aid our cause--it is truly the most pressing manner in all the Shadowlands--but Revendreth alone cannot stand against the growing darkness. You must return to Oribos and ensure the other realms do not falter in their commitments. Tal-Inara will be able to guide you appropriately. Thank you once again for your aid, mortal. May our paths cross again.", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 175056, ["x"] = 0.614, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1172, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1172, ["name"] = "Reinforcing Revendreth", ["orderIndex"] = 1, ["flags"] = 0 } } },
