[62793] = { ["id"] = 62793, ["name"] = "It's All Coming Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Our brothers and sisters are spread thin fighting the Forsworn, maintaining order among aspirants waiting to ascend, and countless other duties. The willing souls you recovered from the Maw will be a great boon to our capabilities in these dire times. Go to Haephus at once--he has long been searching for aid in activating some of our sanctum's most powerful features. It is time we saw Elysian Hold brought to its full potential.", ["objectivesText"] = "Speak to Haephus .", ["rewardGold"] = 16980, ["rewardXP"] = 1020, ["rewardItems"] = { 174292, 177053, 178156, 179942 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, 