[62839] = { ["id"] = 62839, ["name"] = "Anima is Strength", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 61397, 62840, 62843 }, ["description"] = "You are victorious, Maw Walker. And with your success, our forces grow stronger. Stay alert. Your strength will be called upon again soon enough. Bring the anima you recovered to Akradia Moa at once. She will ensure its proper storage.", ["objectivesText"] = "Speak to Arkadia Moa", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 14, ["flags"] = 0 } } },
[62840] = { ["id"] = 62840, ["name"] = "Into the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 61397, 62839, 62843 }, ["description"] = "With anima in short supply, Baroness Draka has tasked me with carefully managing our reserves as they are needed. You may deposit any anima you recover into the reservoir here. Be assured that the Necrolords will defend it at all costs.", ["objectivesText"] = "Deposit Anima into your sanctum's Reservoir.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 15, ["flags"] = 0 } } },
[62843] = { ["id"] = 62843, ["name"] = "The Soul Contact", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1543, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 61397, 62839, 62840 }, ["description"] = "Your reputation precedes you, Maw Walker... braving the Maw and bringing Baron Mograine back in one piece... That was most impressive! With our dire shortage of souls, we'll need you to do that again. Bring us more willing souls so we can restore this sanctum's power! Seek out the broker who aided you before and ask if she will do so again. You may need her.", ["objectivesText"] = "Speak to Ve'nari in the Maw.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 16, ["flags"] = 0 } } },
[62844] = { ["id"] = 62844, ["name"] = "Return to Draka", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["description"] = "Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will do what I can to prepare one. In the meantime, you received a summons from Baroness Draka asking that you return to the Seat of the Primus. The Necrolords are the key to saving the Shadowlands, <name>. I suggest you return to them as soon as you are able.", ["objectivesText"] = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 17, ["flags"] = 1 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 17, ["flags"] = 0 } } },
[62845] = { ["id"] = 62845, ["name"] = "Bringing It All Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "With all of the houses against us, our forces are hard pressed to hold the line. The souls you rescued from the Maw will help strengthen our position and bolster our defenses. Bring them to Arkadia Moa . She will know how best to put them to use and empower our sanctum.", ["objectivesText"] = "Speak to Arkadia Moa .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 182254, 182263, 182272, 182281 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 18, ["flags"] = 0 } } },
[62846] = { ["id"] = 62846, ["name"] = "Sanctum Improvements", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Your will to succeed is strong, Maw Walker. With the anima and the souls you have recovered, we can now begin to unlock our sanctum's true potential. As we acquire more souls and more anima, we can gain even greater power from the Seat of the Primus. Remain relentless in your pursuit, and victory will be ours.", ["objectivesText"] = "Start a Sanctum Upgrade. Progress: This is only the beginning.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 19, ["flags"] = 0 } } },
[62848] = { ["id"] = 62848, ["name"] = "Conduits, What Are They For?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "While the benefits of soulbinding are substantial, you may strengthen them further through the use of conduits. Conduits act to channel the anima of our bond in a myriad of ways, vastly increasing both of our potential. Let us test out the ones I have given you. Fear not--many others like it can be found throughout the Shadowlands.", ["objectivesText"] = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Plague Deviser Marleth. Progress: This is an important lesson, my apprentice.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 20, ["flags"] = 0 } } },
[62849] = { ["id"] = 62849, ["name"] = "Paragon of the Court of Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62849 }, ["description"] = "Maw Walker. Your efforts have provided the Court of Harvesters a decisive edge in their ongoing conflict with the zealots and sycophants who cling to the lost cause of Sire Denathrius. If you will join me in Darkhaven we can express our gratitude to you in a more... physical... way. With treasure, of course.", ["objectivesText"] = "Speak with Mistress Mihaela in Darkhaven.", ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62850] = { ["id"] = 62850, ["name"] = "Paragon of the Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62850 }, ["objectivesText"] = "Speak with Adjutant Nikos in Hero's Rest in Bastion .", ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160470, ["x"] = 0.522, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[62851] = { ["id"] = 62851, ["name"] = "Paragon of the Undying Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62851 }, ["description"] = "Your continued advancement of the Undying Army objectives has earned you the continued respect of our forces. I have been authorized to provide you with a portion of recent spoils of war in gratitude. Please join me at the Seat of the Primus to collect these spoils at your earliest convenience.", ["objectivesText"] = "Speak with Nalcorn Talsen at the Theater of Pain.", ["rewardItems"] = { 172924 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173003, ["x"] = 0.506, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
