[62867] = { ["id"] = 62867, ["name"] = "Return Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59314, 59315, 59321, 59323, 60287, 60289, 61334, 61355, 61981, 62695, 62837, 62856, 62857, 62867, 62868, 62869, 62870, 62882, 62902, 62903, 62904, 62905, 62914, 62915, 62918, 62919, 62920, 62921, 63215 }, ["description"] = "Souls continue to pour into the Maw. Their anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. Bring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", ["objectivesText"] = "Rescue Souls in the Maw.", ["rewardGold"] = 561800, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 27, ["flags"] = 1 } } },
