[62884] = { ["id"] = 62884, ["name"] = "The Forest Will Sing Your Name", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "< Laurel picks out an intricate melody on deft fingers, and sings.> The keeper of word and deed, am I, the weaver of song and lore. Boons are granted as you grow in Renown, fulfilling the oaths we swore. Each deed that you do is a seed of strength, which will blossom in fabulous power. Speak with me now and see what awaits, our magic is yours to discover!", ["objectivesText"] = "Examine your Renown with the Night Fae Covenant. Progress: I cannot wait to compose a song for you!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[62886] = { ["id"] = 62886, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62886 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "The Heart of the Forest requires anima to be renewed and to grow. The Wild Hunt will need your help to recover what we need. Together we strand strong. Speak with Blodwyn. She has been guiding assistance to where it is most needed.", ["objectivesText"] = "Speak with Blodwyn.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62890] = { ["id"] = 62890, ["name"] = "Who Shapes the Forest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1702, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "You have fulfilled your calling, Maw Walker, and brought calm to our forest. Stay vigilant, for others will similarly call upon you in time. The anima you have recovered will be of great use to the Heart of the Forest. Bring it to Zayhad. They will ensure it is safe until it is needed. You will find them deep in the roots of the Heart of the Forest.", ["objectivesText"] = "Find Zayhad in the Roots of the Heart of the Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[62891] = { ["id"] = 62891, ["name"] = "Into the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1702, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Groves wither, and our Queen weeps on barren soil. Anima, precious as water, now rare as snow. Our Queen gives of her own, shelters all beneath her boughs... but one tree does not a forest make. Your gift will be treasured and protected. Anima nourishes our roots, as hope nourishes our hearts. Ardenweald may yet flourish once more.", ["objectivesText"] = "Deposit Anima into your sanctum's Reservoir. Progress: None to waste, and none shall be wasted. It will be safe until needed.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } } },
[62892] = { ["id"] = 62892, ["name"] = "Recover the Lost", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Anima and souls. Wind and rain. Ardenweald needs both to thrive. Souls meant for our boughs suffer in darkness. None escape the Maw... but you walk its shadows and return. You are their salvation. Flutterby shepherds the flock with care and compassion. Speak with her. Bring our lost souls home.", ["objectivesText"] = "Speak to Flutterby in the Heart of the Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } } },
[62893] = { ["id"] = 62893, ["name"] = "Do What We Cannot", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1543, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Rumor has it that you've been to the Maw and back... and that you even made friends with a broker in there! So many souls destined for Ardenweald are trapped in that dark realm. They need our help... and we need theirs! We can't cultivate the Heart of the Forest's magic without them. I know this is a lot to ask... but you may be our only hope of rescuing them. Please, venture into the Maw and do what we cannot. Ardenweald's future depends on it!", ["objectivesText"] = "Find Ve'nari in the Maw.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 6, ["flags"] = 0 } } },
[62894] = { ["id"] = 62894, ["name"] = "Flutterback", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one. In the meantime, I suggest you bring the souls you rescued back to Ardenweald. They deserve respite after their harrowing ordeal in the Maw, and they will surely prove vital to the Night Fae's efforts.", ["objectivesText"] = "Report to Flutterby in the Heart of the Forest in Ardenweald.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and 