[62969] = { ["id"] = 62969, ["name"] = "Lest the Trail Go Cold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["series"] = { 60146 }, ["description"] = "From what the captive dredger told you, it seems Thrall has been taken deep into Torghast. The torments he is enduring must be unimaginable. We need to learn where he is being held before the trail goes cold. The tower is vast and perilous. Search where you are able. Bring back any clues you find. Go carefully, <name>. The Jailer's eye is upon you.", ["objectivesText"] = "Enter Torghast and find something to help us locate Thrall. Progress: Have you found anything to help us locate Thrall?", ["rewardGold"] = 1239200, ["rewardXP"] = 16330, ["rewardItems"] = { 184242 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 5, ["flags"] = 0 } } },
