[63166] = { ["id"] = 63166, ["name"] = "A Shadowed Fate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63166 }, ["description"] = "The Mawsworn... torture and torment souls within Ruin's Cradle. I... barely escaped, but I'm afraid I won't last long. Their twisted rituals... breaking souls to serve as wretched shades. Spare them this fate!", ["objectivesText"] = "Free 6 Tormented Souls in Ruin's Cradle by stomping out the Circles of Agony binding them.", ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176029, ["x"] = 0.298, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 176029, ["x"] = 0.298, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
