[63179] = { ["id"] = 63179, ["name"] = "Drowned and Torn Asunder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63179 }, ["description"] = "Maw Walker! I am relieved to see you in this place. A dark sect of kyrian who have allied themselves with the Maw stole my brothers and sisters from their posts in Bastion. They turned us over to a foul sea witch, the likes of which I've never seen. This... Helya, I believe they called her... seems determined to break us so that we might also join her ranks. Please, if you can, save my brethren.", ["objectivesText"] = "Free 8 Drowning Kyrian in Gorgoa, the River of Souls.", ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176144, ["x"] = 0.388, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 176144, ["x"] = 0.388, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63181] = { ["id"] = 63181, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63181 }, ["description"] = "Are you prepared for a challenge, <name>? It seems Pelagos has been struggling with his trials. I believe, with your guidance, some extra training on the Path is just what he needs! Athanos has many lessons to teach. With your aid, Pelagos can achieve victory and new experience to meditate on.", ["objectivesText"] = "Defeat Athanos as Pelagos in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63182] = { ["id"] = 63182, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63182 }, ["description"] = "Are you prepared for a challenge, <name>? Pelagos's time spent in Ardenweald taught him many lessons. I would like to witness what he has learned. A trial against Nuuminuuru should allow him this chance. With your aid, Pelagos can achieve victory and new experience to meditate on.", ["objectivesText"] = "Defeat Nuuminuuru as Pelagos in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63184] = { ["id"] = 63184, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63184 }, ["description"] = "Are you prepared for a challenge, <name>? Mikanikos has requested an additional trial to train Bron. Splinterbark Nightmare's memory was captured with the help of his praetors, and should prove a worthy challenge for his goliath. With your guidance, Mikanikos and Bron can overcome another trial.", ["objectivesText"] = "Defeat Splinterbark Nightmare as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63185] = { ["id"] = 63185, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63185 }, ["description"] = "Are you prepared for a challenge, <name>? Kleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further. Echthra's memory shall provide her with new lessons. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", ["objectivesText"] = "Defeat Echthra as Kleia in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63186] = { ["id"] = 63186, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63186 }, ["description"] = "Are you prepared for a challenge, <name>? Kleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further. If she is to bear souls across the veil, she will need be prepared to contend against devourers like Azaruux. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", ["objectivesText"] = "Defeat Azaruux as Kleia in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63187] = { ["id"] = 63187, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63187 }, ["description"] = "Are you prepared for a challenge, <name>? Mikanikos has requested an additional trial to train Bron. Mad Mortimer's memory should prove a good challenge, as he and Mikanikos share a mind with a passion to further their research. With your guidance, Mikanikos and Bron can overcome another trial.", ["objectivesText"] = "Defeat Mad Mortimer as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63188] = { ["id"] = 63188, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63188 }, ["description"] = "Are you prepared for a challenge, <name>? Thenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities. A trial against Alderyn and Myn'ir shall suffice. Let us see you and your soulbinds can do.", ["objectivesText"] = "Defeat Alderyn and Myn'ir in a Trial of Wisdom in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63189] = { ["id"] = 63189, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63189 }, ["description"] = "Are you prepared for a challenge, <name>? Thenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities. A trial against Thran'tiok shall suffice. Let us see you and your soulbinds can do.", ["objectivesText"] = "Defeat Thran'tiok in a Trial of Wisdom in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63190] = { ["id"] = 63190, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63190 }, ["description"] = "Are you prepared for a challenge, <name>? Though most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed. Let us see how your soulbinds fare against the memory of Craven Corinth while utilizing the Ring of Warding.", ["objectivesText"] = "Defeat Craven Corinth with the Ring of Warding in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63191] = { ["id"] = 63191, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63191 }, ["description"] = "Are you prepared for a challenge, <name>? Though most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed. Let us see how your soulbinds fare against the memory of Kalisthene while utilizing the Spiritforged Aegis.", ["objectivesText"] = "Defeat Kalisthene with the Spiritforged Aegis in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63192] = { ["id"] = 63192, ["name"] = "Path of Ascension: Trial of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63192 }, ["description"] = "Are you prepared for a challenge, <name>? Many kyrian struggle with their trials of humility at some point along their path. It is important to remember that we can always be learning and improving, no matter how far we have come. But as we continue training, we can overcome more obstacles than before. It is time for your soulbinds to be reminded of this lesson. Let us witness you all succeed in a Trial of Humility.", ["objectivesText"] = "Overcome a Trial of Humility in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63206] = { ["id"] = 63206, ["name"] = "Soulless Husks", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63206 }, ["description"] = "Some of the Mawsworn begin as inanimate suits of armor, forged by the stygian smiths of Zovaal's Cauldron. Once fashioned, they await infusion of a decrepit shade to complete their genesis. It is at this time they are the most vulnerable, and so it is then you should strike. The hammers wielded by the Mawsworn runesmiths hold the power to break as well as they shape. Procure one of them and smash our foes to dust before they can rise against us.", ["objectivesText"] = "Obtain a Stygian Hammer from a Stygian Runesmith and destroy 10 Armored Husks in Zovaal's Cauldron. Progress: Have you satisfactorily dismantled our enemies?", ["rewardItems"] = { 184622, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63208] = { ["id"] = 63208, ["name"] = "The Next Step", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63208 }, ["description"] = "Your efforts have not gone unnoticed, but there are other realms that still require your aid. Consider the next step in your journey, mortal.", ["objectivesText"] = "Choose where to go in the Shadowlands.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63209] = { ["id"] = 63209, ["name"] = "Furthering the Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63209 }, ["description"] = "There are realms which still require your aid, mortal. You must journey to one of their realms and ensure they stand strong. Where will you go next?", ["objectivesText"] = "Choose where to go in the Shadowlands.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63210] = { ["id"] = 63210, ["name"] = "The Last Step", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63210 }, ["description"] = "Just one realm remains which requires your aid, mortal. Speak with me when you are ready, and I shall inform you further. Such is the Purpose.", ["objectivesText"] = "Choose where to go in the Shadowlands.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 106135, 106149, 106157, 107302, 210957, 245438 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63211] = { ["id"] = 63211, ["name"] = "Report to Adrestes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 60491, 60492 }, ["description"] = "You have chosen well. The Kyrian have long ferried souls across the veil into the Shadowlands, ensuring a steady supply of anima for all the realms. Their sacred purpose must be kept strong. Speak with Polemarch Adrestes and begin your future with your covenant.", ["objectivesText"] = "Report to Polemarch Adrestes .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 19, ["flags"] = 0 } } },
[63212] = { ["id"] = 63212, ["name"] = "Report to Mevix", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 58609 }, ["description"] = "You have chosen well. The Necrolords, eternal protectors of the Shadowlands, must remain strong to ensure we may continue to fulfill the Purpose. Aid them as best you can. Speak with Secutor Mevix and begin your future with your covenant.", ["objectivesText"] = "Report to Secutor Mevix .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 21, ["flags"] = 0 } } },
