[63214] = { ["id"] = 63214, ["name"] = "Report to Moonberry", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 61475 }, ["description"] = "You have chosen well. The Night Fae fill a critical role in the eternal cycle of nature spirits. The balance of many worlds depends on their work. Speak with Lady Moonberry and begin your future with your covenant.", ["objectivesText"] = "Report to Lady Moonberry .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 11, ["flags"] = 0 } } },
[63215] = { ["id"] = 63215, ["name"] = "Report to Draven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59314, 59315 }, ["description"] = "You have chosen well. The Venthyr must return to their duty helping souls atone for their sins, saving them from an eternity in the Maw. Denathrius's treachery must be righted. Speak with General Draven and begin your future with your covenant.", ["objectivesText"] = "Report to General Draven .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 20, ["flags"] = 0 } } },
[63340] = { ["id"] = 63340, ["name"] = "Sinfall Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 63340, 63341 }, ["description"] = "Sinfall's influence grows thanks to your triumphs, <name>! Your accomplishments have not gone unnoticed, even beyond the borders of Revendreth. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1211, ["name"] = "Sinfall Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63341] = { ["id"] = 63341, ["name"] = "Sinfall Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 63340, 63341 }, ["description"] = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, <name>. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1211, ["name"] = "Sinfall Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63342] = { ["id"] = 63342, ["name"] = "Necrolord Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 63342, 63343 }, ["description"] = "The might of the Necrolords grows thanks to you, <name>. Your accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1212, ["name"] = "Necrolord Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63343] = { ["id"] = 63343, ["name"] = "Necrolord Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 63342, 63343 }, ["description"] = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1212, ["name"] = "Necrolord Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63344] = { ["id"] = 63344, ["name"] = "Kyrian Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63344, 63345 }, ["description"] = "Bastion is healing thanks to you, <name>. The path is clear. Your accomplishments have not gone unnoticed, even beyond the borders of Bastion. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1213, ["name"] = "Kyrian Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63345] = { ["id"] = 63345, ["name"] = "Kyrian Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63344, 63345 }, ["description"] = "Look around you, <name>. Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1213, ["name"] = "Kyrian Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63346] = { ["id"] = 63346, ["name"] = "Night Fae Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 63346, 63347 }, ["description"] = "Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1214, ["name"] = "Night Fae Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63347] = { ["id"] = 63347, ["name"] = "Night Fae Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 63346, 63347 }, ["description"] = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1214, ["name"] = "Night Fae Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63418] = { ["id"] = 63418, ["name"] = "Exploited Explorers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63418 }, ["description"] = "Chuck explains that something weird is happening in the jungle, and that his group has been captured by wild fungarians. He asks you to rescue his friends to help find out what's going on with the jungle.", ["objectivesText"] = "Rescue Chuck's friends", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63419] = { ["id"] = 63419, ["name"] = "Spores Galore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63419 }, ["description"] = "Chuck goes over again how the jungle seems to be alive and all wrong. He asks you to recover the spores that are on the fungarians and the beasts they've infected. Chuck is worried whatever is happening isn't natural.", ["objectivesText"] = "Collect 12 strange", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63435] = { ["id"] = 63435, ["name"] = "Temple Throwdown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 63435 }, ["description"] = "My parents are busy defending the Shrine of the... Eight... Coconuts? I wasn't paying attention. That's probably why they left me here. They told me I could train with the big white cat! I'm going to be a ninja! < Anthea kicks several times in your direction.> Ya! Kya! You better watch out! ... I'm bored, do you want to pet battle? I brought all of my favorite pets with me.", ["objectivesText"] = "Defeat Anthea in a pet battle. Progress: I'm gonna get you! < Anthea punches the air several times.> Biff! Pow!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 184866 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 176655, ["x"] = 0.704, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 176655, ["x"] = 0.704, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[63447] = { ["id"] = 63447, ["name"] = "Fear No Evil", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 63447 }, ["description"] = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.", ["objectivesText"] = "Revive 4 Injured Stormwind Soldiers.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57256, 57257, 57258, 65733, 131874 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[63455] = { ["id"] = 63455, ["name"] = "Dead On Their Feet", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63455 }, ["description"] = "As the Jailer twists the souls here to his will, there are still some that continue to resist him. I shall give you the ability to aid them in their resistance. Through Necrotic Cohesion we shall bind the runes, armor, and bones that reside here to create bodies for these souls. Bodies that will allow them to fight for us and their freedom! Bind the Zealous souls and build us an army!", ["objectivesText"] = "Use the Cohesion Crystal to create bodies for 10 Defiant Souls .", ["rewardItems"] = { 181501, 181502, 181507, 181645, 181647, 181649, 181653, 181659, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 182610, 182753, 184305, 184772, 184773, 184774, 184775, 184776, 184876 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177076, ["x"] = 0.335, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63479] = { ["id"] = 63479, ["name"] = "Summons from the Matriarch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63480, 65652 }, ["description"] = "Greetings, <name>. Let us not mince words--you are urgently needed in Silvermoon. We're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line! Meet me in the Hall of Blood, and we will get you a full briefing.", ["objectivesText"] = "Meet Lady Liadrin in Silvermoon.", ["rewardGold"] = 28090, ["rewardItems"] = { 45585, 191565, 191566, 191604 }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63480] = { ["id"] = 63480, ["name"] = "Briefing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63479, 65652 }, ["description"] = "We haven't much time. The Scourge have attacked Tranquillien, and there's nothing to hold them back. We must take decisive action.", ["objectivesText"] = "Listen to the briefing. Progress: We will find a way.", ["rewardGold"] = 25740, ["rewardXP"] = 3440, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 2, ["flags"] = 0 } } },
[63481] = { ["id"] = 63481, ["name"] = "Tranquillien Besieged", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "Rommath has opened the way for us to quickly travel to Tranquillien. I warn you, it's already a bloody battlefield. Take the portal, and I will be along right after you. And <name>... keep an eye on Salandria. She may have excelled in her training thus far, but she has yet to be tested like this.", ["objectivesText"] = "Take the portal to Tranquillien.", ["rewardGold"] = 28090, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 3, ["flags"] = 0 } } },
[63482] = { ["id"] = 63482, ["name"] = "Death to the Scourge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "I haven't seen Scourge mustering in numbers like this since... <Liadrin shakes her head, steeling herself.> Never mind. There's no use dwelling in the past. Our first priority is thinning their numbers enough that we can find out what--or who--is really behind this attack. Slay as many of the undead as you can.", ["objectivesText"] = "Slay Scourge in Tranquillien. Progress: Once we've thinned out the numbers of the Scourge, we can strike at Vorath in his lair.", ["rewardGold"] = 280900, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 4, ["flags"] = 0 } } },
[63483] = { ["id"] = 63483, ["name"] = "Magus Installation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "This is no mindless strike... I have a strong suspicion that some powerful entity is manipulating the Scourge. Ever since the Helm of Domination was shattered, there has been a conceivable risk that someone else could exert their will and assume control over the undead--at least temporarily. Rommath and I can help defend Tranquillien, but we need to break those lines. Clear a spot for us. Let us see if we can draw out their leader.", ["objectivesText"] = "Help Aethas and Rommath set up defenses in Tranquillien. Progress: Rommath and I are ready to help set up the wards, once you clear out a spot for us.", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176829, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176829, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 5, ["flags"] = 0 } } },
[63484] = { ["id"] = 63484, ["name"] = "A Knight's Weapon", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "It's clear that this san'layn has decided to use the Scourge to empower himself somehow. We can keep taking him out, but he will just keep coming back. We need a weapon that can break him for good. I think I have a solution. Upstairs, you will find a newly forged ranseur . It has yet to be tempered with magic--we will need to unlock its full potential. It will be our instrument of the Light.", ["objectivesText"] = "Collect the Ranseur from upstairs in Tranquillien. Progress: Have you acquired the ranseur?", ["rewardGold"] = 28090, ["rewardItems"] = { 184895, 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 6, ["flags"] = 0 } } },
[63485] = { ["id"] = 63485, ["name"] = "An Honest Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "If we are to defeat Vorath, we need to amplify the power of the ranseur. But we will not cut corners or impose our will to do it. That lesson has been learned. However, the kyrian of Bastion are masters of ushering souls to their proper places. Perhaps they would lend a fragment of their power to our cause. Go to Bastion , and find a way to empower the ranseur.", ["objectivesText"] = "Travel to Agthia's Repose in Bastion .", ["rewardGold"] = 28090, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 176930, ["x"] = 0.45, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95, 1533 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 7, ["flags"] = 0 } } },
[63486] = { ["id"] = 63486, ["name"] = "An Unbreakable Will", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "We're clearly dealing with someone who is using terrible magic to suspend his own death. There's another force we know of that uses magic in this fashion. The Maldraxxi are intimately familiar with the trappings of death, and equally familiar with how to subvert it. Perhaps one of the Houses knows of a way to help us. Go there, and seek out power that can break this unnatural loop.", ["objectivesText"] = "Travel to the Theater of Pain in Maldraxxus .", ["rewardGold"] = 28090, ["rewardXP"] = 9515, ["rewardItems"] = { 191565, 191566, 191604, 204220 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 176914, ["x"] = 0.462, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95, 1536 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 8, ["flags"] = 0 } } },
[63487] = { ["id"] = 63487, ["name"] = "Return to the Ghostlands", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1536, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63488, 63489 }, ["description"] = "Such power! Surely not even Vorath can withstand the might of this weapon now. We have what we came to the Shadowlands for. The ranseur is ready. Let's get back to Lady Liadrin in Tranquillien. I hope we're not too late to make a difference!", ["objectivesText"] = "Return to Lady Liadrin in Tranquillien.", ["rewardGold"] = 28090, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 176914, ["x"] = 0.462, ["y"] = 0.454 }, { ["mapID"] = 1533, ["npcID"] = 176930, ["x"] = 0.45, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 95, 1533, 1536 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 11, ["flags"] = 0 } } },
[63488] = { ["id"] = 63488, ["name"] = "I Am the Blade of the Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63487, 63489 }, ["description"] = "It's time to put all that power and training into the field. Take the empowered ranseur, and cut a swath of destruction through the Scourge! We'll meet you at the doorstep of Deatholme.", ["objectivesText"] = "Use the empowered ranseur to slay Scourge in the Dead Scar.", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 12, ["flags"] = 0 } } },
[63489] = { ["id"] = 63489, ["name"] = "Justice Long Overdue", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63487, 63488 }, ["description"] = "You made short work of the Scourge in the Dead Scar, but we've a bigger target to face. It's time to test the mettle of your weapon against Vorath . Let us finish this, together.", ["objectivesText"] = "Slay Vorath . Progress: We will protect our homeland.", ["rewardGold"] = 514800, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.3472, ["y"] = 0.7552 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 13, ["flags"] = 0 } } },
[63490] = { ["id"] = 63490, ["name"] = "Blood Knight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you. Meet me back in Silvermoon. Your efforts and heroism today will not go unrecognized.", ["objectivesText"] = "Receive accolades from Lady Liadrin in Silvermoon City.", ["rewardGold"] = 28090, ["rewardXP"] = 11765, ["rewardItems"] = { 191565, 191566, 191604, 191957, 204379, 263465, 268489, 269701 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.3472, ["y"] = 0.7552 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 14, ["flags"] = 0 } } },
[63498] = { ["id"] = 63498, ["name"] = "Brawl or Brew", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 63498 }, ["description"] = "Ach, Thurgaden sent ye did he? Ye'd think the Anvil-Thane would be made o' tougher stuff than the rest of this drunken lot, but I guess I was mistaken! If ye want tae win back his designs, yer gonna have tae win 'em fair and square. I've only got one question left fer ye. Brawl? Or Brew?", ["objectivesText"] = "Defeat Strongarm Jarden in one of her competitions. Progress: Not a single dwarf in 'ere has beaten me. What makes ye different?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 38466, 184894, 184915, 184916, 184917, 184922, 190606, 191123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "standard" },
[63501] = { ["id"] = 63501, ["name"] = "It's Called Borrowing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 63501 }, ["series"] = { 63502, 65563, 65564 }, ["description"] = "<These complex blueprints detail Thurgaden's designs for his weaponry, but are hard to parse. Notes are scribbled in the margins in messy handwriting, listing modifications and notes Thurgaden left for himself. Two notes in particular stand out to you. One denotes that he lent his engraving tool to the core hound trainer Kasea Angerforge, and the other wonders how many elementals they employ at the Grim Guzzler brewing operation.>", ["objectivesText"] = "Find 5 Darkforged Ingot , a Boiling Flamecore , and the Flamepoint Engraver around Shadowforge City. Progress: <Thurgaden is mumbling and cursing under his breath about how he will defeat Jarden in their next competition.>", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 184894, 184915, 184916, 184917, 184922, 190606, 191123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "standard", ["startItems"] = { 184894 } },
[63502] = { ["id"] = 63502, ["name"] = "Weapons o' the Dark Iron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 63502 }, ["series"] = { 63501, 65563, 65564 }, ["description"] = "One step left, friend. Lend me a hand in my craftin', then you'll have yer hands on the most powerful weapons forged in the deepest fires of Blackrock Mountain!", ["objectivesText"] = "Aid Anvil-Thane Thurgaden in crafting your new weapons. Progress: These weapons shall rival even my own!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 184915, 184916, 184917, 184922, 190606, 191123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "standard" },
[63519] = { ["id"] = 63519, ["name"] = "Unfair Fight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "A cowardly pest that cheats his way out of the glory of death? Bah! I have something that'll cut him down where he stands. But such an enhancement requires one who is strong enough to wield it properly. Show me your mettle and fight! If you can prove yourself, I'll empower that ranseur of yours.", ["objectivesText"] = "Prove your strength to Fightlord San .", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 176915, ["x"] = 0.466, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 176915, ["x"] = 0.466, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 9, ["flags"] = 0 } } },
[63522] = { ["id"] = 63522, ["name"] = "A Fair Race", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "A soul that refuses to cross the veil is a problem we kyrian are familiar with. I can help you. But before I grant your weapon this power, I must know that you will not abuse it, and that your heart is true. Let us run a race. Along the course, ring the bells. If your heart is pure, they will aid your speed. You must have at least five bells recently rung in order to complete the race. Do not be distracted by shortcuts. And do not try to cheat to get ahead, it will not work. Are you ready?", ["objectivesText"] = "Run an honest race with Vandellor .", ["rewardGold"] = 309800, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176932, ["x"] = 0.45, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 176932, ["x"] = 0.45, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 10, ["flags"] = 0 } } },
[63543] = { ["id"] = 63543, ["name"] = "Necrolord Assault", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63543 }, ["description"] = "The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!", ["objectivesText"] = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", ["rewardItems"] = { 185720, 185992 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 29, ["db2Objectives"] = { { ["text"] = "Report to Draka at the gates of Perdition Hold", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177674, ["orderIndex"] = 0 }, { ["text"] = "Help Maldraxxi forces assault Perdition Hold", ["amount"] = 1, ["type"] = 14, ["objectID"] = 92362, ["orderIndex"] = 1 }, { ["text"] = "Use Draka's Battlehorn to signal the advance", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177290, ["orderIndex"] = 2 }, { ["text"] = "Advance to the Altar of Domination", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177532, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[63545] = { ["id"] = 63545, ["name"] = "Putting A Plan Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63545 }, ["description"] = "While Maldraxxus pushes the main gate, we can take the side gate with the help of our Centurions. The remains of many Corrupted Centurions taken by the Jailor litter this area. Their parts could be used to build new ones to help in the assault. See if you can locate the parts we need to build a new Centurion.", ["objectivesText"] = "Deliver 3 Centurion Parts and 15 Automaton Bolts to Mikanikos Progress: Have you found the parts I requested?", ["rewardItems"] = { 180935, 181377, 181572, 181573, 181581, 181599, 181609, 181610, 181703, 181843, 181866, 182127, 182385, 182470, 182667, 183132, 183480, 183506, 184294, 184362, 184363, 184513, 184766, 184767, 184768, 184839, 185685, 186573, 186603, 186604, 187508 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63576] = { ["id"] = 63576, ["name"] = "The First Move", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["description"] = "While the covenants labor to defend the Shadowlands, the Jailer has not sat idle within Torghast. It seems he intends to set the next phase of his scheme into motion. Polemarch Adrestes has brought us disturbing news from Elysian Hold. He will recount what he witnessed once you arrive. Make haste. I fear that time grows short.", ["objectivesText"] = "Speak with Polemarch Adrestes in Oribos . Progress: We will continue to fight.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 186017, 186094, 186599, 187439 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1219, ["name"] = "Battle of Ardenweald", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63578] = { ["id"] = 63578, ["name"] = "The Battle of Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1565, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["series"] = { 63638, 63639, 63856, 63857, 63904 }, ["description"] = "With the betrayal of Sire Denathrius, and the absence of the Primus of Maldraxxus, we must assume that the Winter Queen is the Jailer's next target. And we won't let anyone take her sigil! Ardenweald has endured much, but it is a realm of great and mysterious power. Things aren't always what they seem. We'll use this to our advantage, no matter who comes for the Queen!", ["objectivesText"] = "Protect the Winter Queen's sigil in the Battle of Ardenweald.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 179498, 179511, 179515, 179531, 179536, 179546, 179564, 179583, 182322, 182323 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 177148, ["x"] = 0.486, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["questLines"] = { { ["id"] = 1219, ["name"] = "Battle of Ardenweald", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63579] = { ["id"] = 63579, ["name"] = "A Paladin's Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Bolvar Fordragon has seen visions of a vault hidden deep within Torghast where the Jailer keeps souls he deems valuable. Uther was struck down by a mourneblade. When such a weapon is wielded with rage, it can shatter a soul into fragments. If the Jailer holds a part of Uther's soul, it cannot be fully mended until the lost piece is restored. Take this attuned shard to Torghast, $p. It should guide you to the vault's location. Find the lost fragment of Uther's soul so that he can be made whole.", ["objectivesText"] = "Reclaim the Remnant of Justice from the Ossuary of the Banished in Torghast. Progress: Greetings Maw Walker. Your arrival is fortuitous.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 42997, 185679, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179356, ["x"] = 0.628, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1533, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 30, ["flags"] = 0 } } },
[63580] = { ["id"] = 63580, ["name"] = "Wounded Memories", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "The arrival of Uther's wounded soul was the impetus for many events that led us to our current struggles. Devos's broken trust. Her involvement with Helya. The rise of the Forsworn. Bastion needs to change, but we struggle to find a solution. Perhaps this soul fragment will provide valuable insight.", ["objectivesText"] = "Help Uther forge a connection to the Remnant of Justice. Progress: I have never seen a soul torn as Uther's has been.", ["rewardGold"] = 140450, ["rewardXP"] = 4085, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 31, ["flags"] = 0 } } },
[63581] = { ["id"] = 63581, ["name"] = "Step Into the Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "It is as I feared. This fragment of Uther's soul was darkened by the mourneblade that slew him. His memories are shattered and twisted. For Uther to move past his pain, to move past his grief, he must experience his past once again. But he does not have to do this alone. Using my soul mirror, we can aid Uther in walking through these memories. He can then come to terms with the emotions they contain. We must help him see past the distortions and understand the truths they hold.", ["objectivesText"] = "Use the Soul Mirror to aid Uther in reliving his past. Progress: We can learn from this.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 32, ["flags"] = 0 } } },
[63582] = { ["id"] = 63582, ["name"] = "He Was My Student", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Uther's memories of this Prince Arthas haunt him deeply. He is the reason Uther's soul was fragmented, why Devos fell the way she did. The pain in these memories is palpable. We have to dig deeper. Uther must face the source of this darkness. Once again, you need to enter his past to protect his future.", ["objectivesText"] = "Aid Uther in reliving his second memory. Progress: Uther needs our support.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 62199, 62200, 62201, 107640, 109076, 131635, 185680, 185853, 211279 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177123, ["x"] = 0.284, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 33, ["flags"] = 0 } } },
[63583] = { ["id"] = 63583, ["name"] = "I Intend to Live Forever", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Please, <name>. I am not finished. There is one more memory that I must see. One more that must be faced. It... it will not be easy. I will need support from all of you. But it must be done.", ["objectivesText"] = "Aid Uther in reliving his final memory. Progress: <Adrestes is deep in thought.>", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 180733, ["x"] = 0.402, ["y"] = 0.202 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 34, ["flags"] = 0 } } },
[63584] = { ["id"] = 63584, ["name"] = "A Triumphant Return", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63590 }, ["description"] = "This temple represents a new dawn for Bastion, <name>. The Temple of Devotion will stand as a place of fellowship. We will work with the Forsworn, as well as aspirants and kyrian of all experience and backgrounds, to forge a future of which all can be proud. Let us return to Elysian Hold. I request that you join us for a momentous occasion--the ascension of a new Paragon and the creation of a new sigil.", ["objectivesText"] = "Meet Kalisthene at Elysian Hold. The Kyrian Courier can provide a flight.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 60726, 60727, 60730, 60734, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 35, ["flags"] = 0 } } },
[63585] = { ["id"] = 63585, ["name"] = "Blind Loyalty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63586, 63589 }, ["description"] = "The path forward for the kyrian is clear to me now. First we will speak with Nikolon. I urge you to stay and listen. Afterward, we must return to Elysian Hold. There I will request an audience with the Archon, and I need you all by my side as I do so.", ["objectivesText"] = "Join Polemarch Adrestes at Elysian Hold for an audience with the Archon. Progress: The kyrian must forge a new path.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 36, ["flags"] = 0 } } },
[63586] = { ["id"] = 63586, ["name"] = "Compassion in Devotion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63585, 63589 }, ["description"] = "Our first order of business is to rededicate the Temple of Loyalty. Pelagos has volunteered to stay here and help prepare for the ceremony. I requested that Nikolon bring his companions to meet us at Steward's Rest, to aid us in convincing some of the Forsworn of our new path. Meet us there when you are able.", ["objectivesText"] = "Meet Adrestes at Steward's Rest.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 37, ["flags"] = 0 } } },
[63587] = { ["id"] = 63587, ["name"] = "Reclaimable Anima", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Mikanikos has explained much about Forsworn centurions to me, <name>. I cannot say that I understood all of it, but it seems he has not yet found a reliable way to return them to their proper operating standards. Their anima can still be useful, though! Adrestes has focused on how to rededicate the temple, but not on his own safety. I worry the process will drain much of his anima. If you can reclaim cores from the Forsworn centurions, we can use them as anima stores for Adrestes.", ["objectivesText"] = "Collect 5 Tainted Centurion Cores from Forsworn centurions. Progress: I've been working with Mikanikos on methods to reuse anima from Forsworn centurions. I can handle this!", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177123, ["x"] = 0.284, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177123, ["x"] = 0.284, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 38, ["flags"] = 0 } } },
[63588] = { ["id"] = 63588, ["name"] = "Rebuilding Faith", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "The Forsworn are lost, <name>. They are like ghosts, haunting the Temple of Loyalty. Nowhere else to go. Leaderless, purposeless, abandoned. We must show them that there is a path forward. Let me accompany you into the temple. Allow me to talk to them, speak to their sensibilities. Perhaps we can convince them to give Adrestes's new path a chance.", ["objectivesText"] = "Convince 10 Forsworn to return to the Path. Progress: The Forsworn may have abandoned the Path, but we had good reason.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 137663, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177300, ["x"] = 0.282667, ["y"] = 0.243333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.282667, ["y"] = 0.243333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 39, ["flags"] = 0 } } },
[63589] = { ["id"] = 63589, ["name"] = "Directing Dedication", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63585, 63586 }, ["description"] = "The five temples of Bastion have stood strong since its very creation. The idea of rededicating one has never been broached before, and will no doubt require a significant amount of anima. Underneath this temple are stores of anima we rationed for the drought. Now that anima is returning, we can use these reserves for our purposes. You will need to use channelers and collectors throughout the grounds to redirect anima to the top. That should give me the power I need.", ["objectivesText"] = "Redirect anima from the Citadel of Loyalty to the temple. Progress: We endeavor to perform a monumental feat, one that has never been attempted before.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 40, ["flags"] = 0 } } },
[63590] = { ["id"] = 63590, ["name"] = "The Vesper Rings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63584 }, ["description"] = "Loyalty shall no longer be a demanded tenet of the Path, but rather a virtue that is earned. A choice. We must show devotion to those who struggle, whether they are recently arrived souls or peers who need our aid. It will take all the anima at hand to rededicate this temple. And in so doing, to ring in a new age for the kyrian. I fear the Mawsworn may attempt to thwart our plans. Protect me during this ritual, <name>. We must see this through.", ["objectivesText"] = "Protect Polemarch Adrestes as he rededicates the Temple of Loyalty. Progress: <Adrestes cannot be distracted as he uses every ounce of himself for the task at hand.>", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 41, ["flags"] = 0 } } },
[63591] = { ["id"] = 63591, ["name"] = "The Grand Reception", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 2017, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63592, 63593 }, ["description"] = "<name>, you have aided the kyrian in the most trying of times. Your devotion to our cause has helped usher in a new beginning for all of us. We would be honored if you would join us for a gathering prior to the ceremony. Many members of our covenant wish to express their appreciation for all you have done. This is a day of great joy. I am so pleased that you are here to witness it!", ["objectivesText"] = "Speak to Kalisthene to attend the gathering, then mingle with your soulbinds and the other kyrian.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2482, ["db2PoiUiMapID"] = 2017, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 42, ["flags"] = 0 } } },
[63592] = { ["id"] = 63592, ["name"] = "The New Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1695, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63591, 63593 }, ["description"] = "Today, a new paragon is anointed. And for the first time since the dawn of our realm, a temple is rededicated to represent our devotion to one another. A new paragon, a new sigil, and a new path for all kyrian. This ceremony shall be glorious indeed!", ["objectivesText"] = "Speak to Kalisthene to take part in the ceremony at the Seat of the Archon.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181743, 185680, 185853, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2285, ["db2PoiUiMapID"] = 1695, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 43, ["flags"] = 0 } } },
[63593] = { ["id"] = 63593, ["name"] = "New Sigil of the Kyrian", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1961, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63591, 63592 }, ["description"] = "With a future of kinship and devotion secured for Bastion, a new sigil is born to represent our path forward. Please report all that you have done to the Primus . When he is ready, we will deliver the sigil to him. Let us hope he can use it to thwart the Jailer's plan and save the Shadowlands.", ["objectivesText"] = "Report back to the Primus in Korthia .", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.250667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 44, ["flags"] = 0 } } },
[63594] = { ["id"] = 63594, ["name"] = "Clearing the Walls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63594 }, ["description"] = "<This scroll shows the locations of a series of pylons, that protect Perdition Hold from assault. Destroying these Pylons could aid in the success of our attack>", ["objectivesText"] = "Use the Overcharged Champion to destroy 6 Deadsoul Pylons along the walls of Perdition Hold. Progress: Have you cleared the walls?", ["rewardGold"] = 74100, ["rewardXP"] = 8165, ["rewardItems"] = { 186573, 186601 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["startItems"] = { 186573 } },
