[63612] = { ["id"] = 63612, ["name"] = "The Chains of Command", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "If we must hold a position so near to the Jailer's lands, we need to provide some assurances. Vyraz and Helya have retreated within the walls of Desmotaeron. They have grown lax in their expected safety, which provides us with an opportunity. We will take them by surprise. Strike swiftly and without mercy, and perhaps we can cut the heads off those snakes.", ["objectivesText"] = "Meet Draka near Desmotaeron.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177560, ["x"] = 0.628, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.250667 }, ["mapCandidates"] = { ["npc"] = { 1543, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 45, ["flags"] = 0 } } },
[63613] = { ["id"] = 63613, ["name"] = "Gates of the Damned", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "We need to prepare for the assault before we signal Zerekriss. Once it is in place, our allies will use death gates to assault the area. We will need to summon the death gates on this side. Find strategic locations for them.", ["objectivesText"] = "Summon 4 Death Gates. Progress: Once we have all of these death gates summoned, then the real fight can begin.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177560, ["x"] = 0.628, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 319, ["title"] = "Lorewalking: Thrall", ["questLineID"] = 6016, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 46, ["flags"] = 0 }, { ["id"] = 6016, ["name"] = "Lorewalking: Thrall", ["orderIndex"] 