[63614] = { ["id"] = 63614, ["name"] = "Weapon in Hand", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "A moment, <name>. I threw my axe Dra'gora at Helya during our first encounter in the Maw, and I haven't seen it since. If this is truly where she commands her forces, then perhaps it's held here. I crafted that weapon in Nagrand, and it reminds me of many good days spent beside my family there. I want to feel its weight in my hands once again.", ["objectivesText"] = "Find Thrall's axe, Dra'gora . Progress: I threw my axe in the heat of the moment...", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 319, ["title"] = "Lorewalking: Thrall", ["questLineID"] = 6016, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 47, ["flags"] = 0 }, { ["id"] = 6016, ["name"] = "Lorewalking: Thrall", ["orderIndex"] = 7, ["flags"] = 0 } } },
[63615] = { ["id"] = 63615, ["name"] = "Clip Their Wings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "The skies are dark with Helya's kyrian followers. If we do not thin their numbers, Zerekriss and our aerial allies may have difficulties pushing forward. I've noticed that the Mawsworn often use magical chains. We could turn their equipment against them and tear them down from the sky.", ["objectivesText"] = "Use Mawsworn Chains to kill 6 Helsworn Soulbreakers . Progress: We need to clear out the skies before we can begin the real assault.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 39804, 39854, 39855, 39867, 181648, 185742, 185772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 319, ["title"] = "Lorewalking: Thrall", ["questLineID"] = 6016, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 48, ["flags"] = 0 }, { ["id"] = 6016, ["name"] = "Lorewalking: Thrall", ["orderIndex"] = 6, ["flags"] = 0 } } },
[63616] = { ["id"] = 63616, ["name"] = "A Job Done Right", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "We should be clear to start the assault. Signal the Zerekriss. Let us show them the might of a Maldraxxian necropolis and the combined armies of the Shadowlands!", ["objectivesText"] = "Signal the Zerekriss and start the assault. Progress: Nothing can stand against the might of Maldraxxus!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 49, ["flags"] = 0 } } },
[63617] = { ["id"] = 63617, ["name"] = "Bending Bars", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "In all the chaos, the gates of the upper hold have been left open. If we slip through, they might not even notice us until it is too late. One of Helya's lieutenants stands between us and Helgarde Keep. End them.", ["objectivesText"] = "Slay Ironkeeper Salryx . Progress: We need to get through that gate.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 50, ["flags"] = 0 } } },
[63618] = { ["id"] = 63618, ["name"] = "What Maldraxxus Does Best", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "Every enemy we vanquish here is one our army does not have to contend with. We will make sure they will not soon forget the true purpose of Maldraxxus. Show them what happens to those we deem a threat towards the Shadowlands. Kill every Mawsworn in sight.", ["objectivesText"] = "Slay 10 Mawsworn in upper Desmotaeron. Progress: Each Mawsworn we defeat is one less that will bother our forces in Korthia .", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 51, ["flags"] = 0 } } },
[63619] = { ["id"] = 63619, ["name"] = "Forsworn and Forgotten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "Wait... I know you! The Maw Walker! My brothers and sisters have been twisted... tainted. Some took power willingly from Helya, but others resisted. Now all of us are forced to submit to her power. I escaped when the fighting started, but most of the remaining Forsworn are being subjected to horrific rituals. Please, I beg you to free them. Then we will return to Bastion and submit to the Archon's judgment.", ["objectivesText"] = "Free 5 Forsworn Prisoners .", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177288, ["x"] = 0.655, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 52, ["flags"] = 0 } } },
[63620] = { ["id"] = 63620, ["name"] = "A Traitor's Due", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "Vyraz has been a constant thorn in Maldraxxus's side since he betrayed us. As Baroness of the House of the Chosen, it is my duty to see this threat eliminated... and the murder of Margrave Krexus avenged. As the Primus said, we must remove the head from this snake. The time to strike is now!", ["objectivesText"] = "Kill Vyraz. Progress: Vyraz is a stain upon Maldraxxus as long as he still draws breath.", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 181648, 185742, 185772 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178103, ["x"] = 0.618, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 53, ["flags"] = 0 } } },
[63621] = { ["id"] = 63621, ["name"] = "Pulling His Chain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63621 }, ["description"] = "They call this one the Keeper of Chains . Do not underestimate his power. He has bound nearby souls in preparation for an attack against our position. I need you to eliminate this threat, Maw Walker, before it moves against our forces.", ["objectivesText"] = "Eliminate the Keeper of Chains . Progress: Have you eliminated this threat?", ["rewardItems"] = { 181368, 181571, 181572, 181573, 181576, 181580, 181581, 181589, 181599, 181601, 181603, 181604, 181609, 181610, 181614, 181704, 181745, 184294, 184362, 184363, 184513, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.537 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group" },
