[63646] = { ["id"] = 63646, ["name"] = "Convoy of the Covenants", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63644, 63645, 63647, 63648, 63650, 63652, 63653, 63654, 63659 }, ["description"] = "A new sigil for the Venthyr would require all seven medallions to forge. The Primus was correct. The person we need is the Stonewright . Her grievances against the Unseen could fill a library and she holds the last of the medallions we need. I believe you and I are long overdue in convincing her to join our cause. I will make the arrangements. We shall go properly this time, with gifts and diplomacy. You should warn Chelra, she will want to arrange an escort.", ["objectivesText"] = "Gather the Envoys and ride to Dominance Gate. Progress: What do you bring me, Maw Walker? Be advised I have no patience for deception and am not above feeding messengers to the gargons.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185734, 185762 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168898, ["x"] = 0.23, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165866, ["x"] = 0.342, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.23, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1220, ["questLineOrder"] = 5 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1220, ["name"] = "The Unseen Guests", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 59, ["flags"] = 0 } } },
[63647] = { ["id"] = 63647, ["name"] = "The Unseen Guests", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63644, 63645, 63646, 63648, 63650, 63652, 63653, 63654, 63659 }, ["description"] = "Dreadlords. Of course. Of course they would come back now of all times. I half suspected they returned during the drought. I was not entirely convinced you were not one, the first time I saw you. They have gotten more clever over the eons since they fled Revendreth. But not clever enough... I think. Come, Maw Walker. Follow me and do not make a fuss. Keep your weapon ready. The envoy you brought is not as well intentioned as you might have thought.", ["objectivesText"] = "Join the Stonewright as she investigates the Envoy.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 185734 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165866, ["x"] = 0.342, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["i