nation", ["questLineID"] = 1220, ["questLineOrder"] = 5 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1220, ["name"] = "The Unseen Guests", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 61, ["flags"] = 0 } } },
[63649] = { ["id"] = 63649, ["name"] = "Spy vs Spy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "Nathrezim. Dreadlords. The Unseen Guests. Call them what you will, they are a race that was crafted to be the greatest collection of spies and infiltrators in all of reality, once upon a time. Their intrusion has underestimated three things. Kael'thas Sunstrider, Baroness Vashj, and <name>! I have brought a tool Kael'thas and I used to detect nathrezim when we served under Illidan. And I am the matron of spies! Let us hunt these intruders down.", ["objectivesText"] = "Track down and defeat 5 Dreadlord Infiltrators . Progress: Who says death is without its little pleasures.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 23372, 23373, 23390, 23391, 23392, 23393, 24441, 25553, 57498, 57499, 57500, 63793, 63794, 63796, 63797, 133695, 137663, 185734, 190454, 191984, 191988, 191990, 191991, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192005, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 198490, 198529, 198532, 198695, 205423, 209837, 21