5917, 185918, 185944, 186155, 186156, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186770, 186976, 187506, 187507 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1220, ["questLineOrder"] = 5 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1220, ["name"] = "The Unseen Guests", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 64, ["flags"] = 0 } } },
[63652] = { ["id"] = 63652, ["name"] = "The \"Unwelcome\" Guests", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63644, 63645, 63646, 63647, 63648, 63650, 63653, 63654, 63659 }, ["description"] = "Chelra, I mean Nal'ragas, would not have been working alone. We must assume the worst, that not all of our friends and allies are who they seem to be. It will take time for the Court of Harvesters to render our detection ritual. While we do so we will be exposed. I ask that you use the techniques you employed at Dominance Gate within Sinfall to root out any nathrezim within our ranks. Good hunting.", ["objectivesText"] = "Eliminate 3 nathrezim inside Sinfall.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185734 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1220, ["questLineOrder"] = 5 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLi