[63662] = { ["id"] = 63662, ["name"] = "Mysteries of the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["series"] = { 63660, 63661 }, ["description"] = "The Maw is changing, mortal. And with change comes opportunity. The Jailer has pulled a realm that was hidden deep within the Shadowlands into the Maw. It is a location of some interest to me, but I do not wish to approach it alone. The Mawsworn are swarming the area, you see. There must be something of value that they seek. I have a safe enclave nearby. Accompany me there and I may be able to help you find that waystone you're looking for. Do we have a deal?", ["objectivesText"] = "Travel with Ve'nari to the site of the new landmass within the Maw", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177202, ["x"] = 0.584667, ["y"] = 0.146667 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543, 1961 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["ques