[63663] = { ["id"] = 63663, ["name"] = "Korthia, the City of Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["description"] = "We are on the threshold of attaining our desires, Maw Walker. Your grand waystone cannot be far off. Of course, my needs are much more modest. A bit of useful information here, a priceless relic there... I will survey the area to see if there is anything useful--or hazardous--nearby. Then we can proceed.", ["objectivesText"] = "Have Ve'nari scan the area, then investigate whatever is found.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177202, ["x"] = 0.584667, ["y"] = 0.146667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177227, ["x"] = 0.638, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.584667, ["y"] = 0.146667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["