[63669] = { ["id"] = 63669, ["name"] = "Somebody Feed Kevin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63669 }, ["description"] = "My family of slimes is always hungry for anima. Thankfully the bodies of the defeated here are a good source! The more the slimes consume the larger they grow. Then what remains of the fallen will become part of our wonderful, happy family. Take Kevin and let him consume fallen enemies till he is fully grown, then unleash him upon our foes!", ["objectivesText"] = "Consume 8 fallen enemies to grow Kevin to full size.", ["rewardGold"] = 58650, ["rewardXP"] = 8165, ["rewardItems"] = { 181503, 181645, 181647, 181649, 181651, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181686, 181689, 181734, 181864, 182470, 182667, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 163295, ["x"] = 0.328, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
