[63728] = { ["id"] = 63728, ["name"] = "Hunting Amid Houses", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63673, 63674, 63675, 63990 }, ["description"] = "I have dreamed that Tyrande Whisperwind is crucial to the survival of Ardenweald. The night fae have been searching for others like her who were once Night Warriors. We have recruited an ancient ally of Azeroth, Huln Highmountain , in order to look for them. Elune's power is too much for any mortal to contain--even Tyrande. I do not know how much longer she can hold on. Allow me to explain further, then you must hurry to meet Huln in Maldraxxus.", ["objectivesText"] = "Speak with Ysera to learn more, then find Huln Highmountain in the Sepulcher of Knowledge. Progress: Ardenweald appreciates your help.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185773 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 177434, ["x"] = 0.460667, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 177471, ["x"] = 0.424, ["y"] = 0.243 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 1536, 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 92, ["flags"] = 0 } } },
[63731] = { ["id"] = 63731, ["name"] = "Researching Korthian Relics", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63731 }, ["series"] = { 63732, 64567 }, ["description"] = "<You find a torn book regarding relics that were being kept within Korthia. A name written within its pages begins to glow: \"Roh-Suir.\" The book spins in your hand and points in a direction while Roh-Suir's name pulses. Perhaps this Roh-Suir could help you discover more about the relics you've found.>", ["objectivesText"] = "Find Scholar Roh-Suir to learn more about relics. Provided item:", ["rewardGold"] = 28090, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178694, ["x"] = 0.59, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187177 } },
[63732] = { ["id"] = 63732, ["name"] = "Interrupt the Interrogations", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["series"] = { 63731, 64567 }, ["description"] = "Shhh... quietly! The invaders will kill me if they find me here, just as they have killed so many others! <Roh-Suir points frantically in the direction of the Mawsworn.> They're torturing the Archivist! You must find a way to rescue her. We cannot allow the Mawsworn to learn all that she knows!", ["objectivesText"] = "Rescue Archivist Roh-Senara. Progress: There is no hope until and unless Archivist Roh-Senara is safe.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178694, ["x"] = 0.59, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178694, ["x"] = 0.59, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63733] = { ["id"] = 63733, ["name"] = "Carving Out a Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "While I abhor violence and prefer a reasoned response to conflict, there is no alternative here. In order for Roh-Suir and I to escape safely, you must deliver a decisive strike to the Mawsworn who have invaded Seeker's Quorum. Carve out a path so that we may escape.", ["objectivesText"] = "Defeat 15 Mawsworn invaders. Progress: Attacking the Mawsworn is risky, but necessary. I pray they did not follow us.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178713, ["x"] = 0.599, ["y"] = 0.553 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63734] = { ["id"] = 63734, ["name"] = "The Sundered Staff", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "I have no choice but to trust you with the secrets of the Lodestaff. In the right hands, such as those of a trained Archivist, the staff can locate influential relics from the afterlives of the Shadowlands. It was split into three segments to ensure that it would not fall into the wrong hands. The invaders have found the pieces, but they are yet not aware of their significance. Recover the pieces of the staff. Each segment is held by a different member of the Mawsworn.", ["objectivesText"] = "Recover the three segments of the Lodestaff. Progress: Were you able to recover all three segments of the Lodestaff?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178713, ["x"] = 0.599, ["y"] = 0.553 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 2, ["flags"] = 0 } } },
[63735] = { ["id"] = 63735, ["name"] = "Recover the Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63735 }, ["description"] = "Though the circumstances are grim, we cannot neglect the Purpose. On the bodies of the attendants in the Seeker's Quorum, you will find scrolls detailing our ongoing research. What is written on each of these scrolls represents efforts equal to many of your lifetimes. Retrieve them, before they are destroyed and lost forever.", ["objectivesText"] = "Recover 6 Scholars' Research Scrolls.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63736] = { ["id"] = 63736, ["name"] = "An Infusion of Anima", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "Normally we would infuse the Lodestaff with energy from the Netherstar, another relic of note. Regrettably, that is not an option. But, in a pinch, anima is an acceptable substitute. Take the Lodestaff . Brandish it near recently slain devourers in the estuary below us. The staff should draw in and absorb their anima.", ["objectivesText"] = "Infuse the Lodestaff with anima.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614, 198608 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 3, ["flags"] = 0 } } },
[63737] = { ["id"] = 63737, ["name"] = "Finding One's True Purpose", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "All our efforts have led us here. With the combined wisdom of the Archivists, and a little help from a <race> <class>, we will attune the Lodestaff to the relics that we seek. Should we succeed, we will have what we need to re-establish the Archive. Our sacred work can then continue.", ["objectivesText"] = "Participate in the ritual to attune the Lodestaff. Progress: Is it over? Was the attuning a success?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178991, ["x"] = 0.358, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178992, ["x"] = 0.36, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 6, ["flags"] = 0 } } },
[63738] = { ["id"] = 63738, ["name"] = "Establishing the Archive", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "I will head to Keeper's Respite, where there is some small semblance of safety. There, we will establish a new archive. Meet me there when you are able. I hope we can count on you again. We will have need of your assistance there in the future.", ["objectivesText"] = "Meet Scholar Roh-Suir at Keeper's Respite.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178992, ["x"] = 0.36, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178313, ["x"] = 0.615, ["y"] = 0.217 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 7, ["flags"] = 0 } } },
[63739] = { ["id"] = 63739, ["name"] = "Hope Ascending", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "There is one final thing we must do. Meet us atop the peak of Hope's Ascent.", ["objectivesText"] = "Meet Archivist Roh-Senara and Scholar Roh-Suir near the top of Hope's Ascent.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178991, ["x"] = 0.358, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 5, ["flags"] = 0 } } },
[63740] = { ["id"] = 63740, ["name"] = "Consulting the Experts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63732, 63733, 63734, 63736, 63737, 63738, 63739, 63740 }, ["description"] = "We can restore the functions of the Lodestaff, but it will require the wisdom of the Archivists. Not just me, but the Archivists who have come before. They were laid to rest near here. Given the scale of the destruction of Korthia and the likely possibility that this destruction will continue, this may be our last chance to visit their memorials before they are irrevocably ruined. Visit the Archivists' memorials. Take Roh-Suir with you, so that he may take note of their messages before they are lost.", ["objectivesText"] = "Commune with the Archivists' memorials. Progress: Do not fear the Archivists of old. They are here to help.", ["rewardGold"] = 193050, ["rewardXP"] = 6125, ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177928, ["x"] = 0.395, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1236, ["name"] = "Archivists of Korthia", ["orderIndex"] = 4, ["flags"] = 0 } } },
[63751] = { ["id"] = 63751, ["name"] = "A Terrible Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 63751 }, ["description"] = "This strange shard pulses in your hand. An aura of dread radiates forth from it like a chill wind, sending a shiver down your spine. Perhaps the Primus could tell you more about this... if you could find him.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185726 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63753] = { ["id"] = 63753, ["name"] = "Centurions March!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63753 }, ["description"] = "Three of our Centurions have broken through the side gate. They need additional anima to continue their assault. Several of my assistants tried to deliver anima to them, but failed. Please get recover the anima and assist the Centurions in the attack.", ["objectivesText"] = "Collect 5 Anima Motes to empower and assist the Centurion in combat. Progress: Have the Centurions succeeded?", ["rewardItems"] = { 181368, 181377, 181461, 181569, 181572, 181576, 181581, 181589, 181591, 181599, 181604, 181605, 181609, 181614, 181627, 181630, 181632, 181635, 181636, 181637, 181745, 182126, 182559, 182584, 182621, 183202, 183470, 183478, 183490, 183514, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 184841, 185733, 190641 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63754] = { ["id"] = 63754, ["name"] = "The Caged Bird", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "Remain quiet. We must not attract attention. Many of my sisters have already been lost. It will soon be my turn to perish in that witch's vile ritual. Release me from this cage and I can see us both to safety. Keeper Odyn must be warned of this foul betrayal! The Mawsworn called Kjellrun holds the seal that can free me. You can find her gloating in the nearby hall.", ["objectivesText"] = "Acquire the Helwrought Seal from Kjellrun and release Danica from her captivity. Progress: This is no fate for a Val'kyr!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177597, ["x"] = 0.672, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177597, ["x"] = 0.672, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 12, ["flags"] = 0 } } },
[63755] = { ["id"] = 63755, ["name"] = "A Matter of Urgency", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["description"] = "Maw Walker, there is a matter of urgency that has not been addressed. Our Fatescribe is missing. They have not found their way here. They would have been in Seeker's Quorum before... < Pathscribe Roh-Vess pauses.> Can you look for the Fatescribe? Many attendants used the caves near the ruins to hide from the mawsworn.", ["objectivesText"] = "Search for the Fatescribe of Korthia .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177155, ["x"] = 0.648667, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648667, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63756] = { ["id"] = 63756, ["name"] = "Rescued from Torment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["description"] = "The Mawsworn are not only killing those they find in the Seeker's Quorum. They are interrogating the survivors. We should help save those we can. It's possible one of them might have seen the Fatescribe.", ["objectivesText"] = "Rescue 6 Tortured Attendants in Seeker's Quorum.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63757] = { ["id"] = 63757, ["name"] = "Looting the Looters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["description"] = "<The Mawsworn was carrying a Korthian artifact. It's unclear what the enemy wants with such relics, but you suspect the attendants in Keeper's Respite would want to see them returned.>", ["objectivesText"] = "Retrieve 4 Korthian Artifacts from the Mawsworn.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 3, ["flags"] = 0 } }, ["startItems"] = { 185915 } },
[63758] = { ["id"] = 63758, ["name"] = "The Last Place You Look", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["description"] = "I came here hoping to locate the Fatescribe or something to help me find him. Evidence shows he was here and survived a Mawsworn attack. The only other place I haven't looked is a meditation chamber on the opposite side of the ruins. It's too dangerous for me to head back into the Seeker's Quorum alone. Could you help me? I must find the Fatescribe. It's a matter of great importance.", ["objectivesText"] = "Search the Seeker's Quorum for the missing Fatescribe.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 2, ["flags"] = 0 } } },
[63759] = { ["id"] = 63759, ["name"] = "Redirect the Search", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["series"] = { 63760, 63762 }, ["description"] = "I believe the Fatescribe was headed to the Sanctuary of Guidance. A holy place for the attendants of Korthia . Fortunately, because you seem to be in the habit of picking up every piece of trash you find, we have the Fatescribe's Implement! I'm sure that will prove useful in locating him. But first, on to the Sanctuary.", ["objectivesText"] = "Meet Caretaker Kah-Than at the entrance to the Sanctuary of Guidance in Korthia .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 4, ["flags"] = 0 } } },
[63760] = { ["id"] = 63760, ["name"] = "Echoes of Fate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["series"] = { 63759, 63762 }, ["description"] = "The devourers have swarmed this place, but our focus must remain on finding the Fatescribe. Attendants who worshipped here would leave offerings of anima at the shrines. The implement you found will resonate if the Fatescribe has been nearby. With any luck, it will give us insight into where he has gone.", ["objectivesText"] = "Resonate the Fatescribe's Implement at the shrines in the Sanctuary of Guidance.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185740, 185771, 185827, 185828, 185830, 185831, 185847, 185915 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 5, ["flags"] = 0 } } },
[63761] = { ["id"] = 63761, ["name"] = "Revenge Delayed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["description"] = "<The Korthian protector is gravely wounded and struggles to speak.> Devourers... swarmed the sanctuary. Too few of us... My duty... incomplete. The Purpose... I... <The protector's voice fades.>", ["objectivesText"] = "Kill 10 Devourers in the Sanctuary of Guidance.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177850, ["x"] = 0.555, ["y"] = 0.221 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177155, ["x"] = 0.648667, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.221 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 6, ["flags"] = 0 } } },
[63762] = { ["id"] = 63762, ["name"] = "Under the Illusion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["series"] = { 63759, 63760 }, ["description"] = "The Fatescribe has collected the necessary items to create an illusion in this chamber. Fortunately, we can use his own implement to dispel it and reveal him. He will be grateful to see a friendly face, I'm sure. I must say, you've proven to be incredibly helpful in this task. I truly couldn't have done it without you.", ["objectivesText"] = "Use the Fatescribe's Implement to dispel the illusion.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177610, ["x"] = 0.565, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 7, ["flags"] = 0 } } },
[63763] = { ["id"] = 63763, ["name"] = "They Could Be Anyone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63755, 63756, 63757, 63758, 63759, 63760, 63761, 63762, 63763 }, ["description"] = "<The still-warm head of the dreadlord Azodius grimaces at you. The attendants at Keeper's Respite should be told of the Fatescribe's abduction. No doubt Highlord Fordragon will want to hear of this unexpected threat.>", ["objectivesText"] = "Take the head of Azodius to Bolvar Fordragon in Keeper's Respite. Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 185740, 185771, 185827, 185830, 185831, 185847, 185915 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1228, ["name"] = "They Could Be Anyone", ["orderIndex"] = 8, ["flags"] = 0 } }, ["startItems"] = { 185740 } },
[63764] = { ["id"] = 63764, ["name"] = "Claim the Sky", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "I mourn the loss of my sisters and desire nothing more than to avenge them. Yet I know that I am no match for the witch's magics or her army of Mawsworn. We must let wisdom guide us and fly from here. Though I am weak from my captivity, I have the strength to bear you from this place. Let us go, friend.", ["objectivesText"] = "Fly with Danica to Odyn's halls in Skyhold.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177597, ["x"] = 0.672, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 