[63771] = { ["id"] = 63771, ["name"] = "Fate's Reminder", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63771 }, ["description"] = "Fatescribe Roh-Tahl awaits you within Oribos , should you ever wish to change the course of fate. You may speak with him at your leisure.", ["objectivesText"] = "Meet Fatescribe Roh-Tahl in Oribos if you wish to enter the Threads of Fate.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63772] = { ["id"] = 63772, ["name"] = "Waiting in the Wings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63772 }, ["description"] = "Kyrian forces have arrived to assist in the assault. They have secured our flank and will lay siege to the south gate of Perdition Hold. Report to Artemede and assist the Kyrians however you can!", ["objectivesText"] = "Assist Artemede and the Kyrian forces outside the southern gate of Perdition Hold.", ["rewardGold"] = 26210, ["rewardXP"] = 1020, ["rewardItems"] = { 184513 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63773] = { ["id"] = 63773, ["name"] = "You and What Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63773 }, ["description"] = "The Jailer has dispatched a force of elite troops to strike our rear lines. Their attack threatens our whole assault! I need you and one other soldier to eliminate these enemies. A volunteer from each of the five houses of Maldraxxus has requested to assist you, <name>. Pick one and give them the honor of serving alongside you.", ["objectivesText"] = "Select a champion and Eliminate 3 Mawchained Rampagers and 5 Mawchained Demolishers .", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 181501, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181651, 181652, 181653, 181654, 181655, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181667, 181668, 181669, 181670, 181671, 181673, 181676, 181679, 181680, 181681, 181682, 181686, 181864, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63774] = { ["id"] = 63774, ["name"] = "An Embarrassment of Corpses", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63774 }, ["description"] = "Look around us, $p. Everywhere you turn there are corpses piling up like mountains. These disembodied souls are desperate to return to battle. We will use their fervor to turn the tide. Rally the disembodied souls around the battlefield and bring them to my stitchers at the corpse piles to build them new bodies!", ["objectivesText"] = "Deliver 4 Disembodied Souls to Front-Line Stitchers who will craft them new bodies. Progress: Find the disembodied souls and bring them to my stitchers!", ["rewardItems"] = { 181498, 181626, 181645, 181647, 181649, 181651, 181656, 181658, 181659, 181661, 181664, 181665, 181666, 181667, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 181688, 181842, 182110, 182338, 182584, 183470, 184305, 184772, 184773, 184774, 184775, 184776, 187533 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177720, ["x"] = 0.335, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177720, ["x"] = 0.335, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63775] = { ["id"] = 63775, ["name"] = "Cryptograms and Keys", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63775 }, ["description"] = "The repositories of knowledge within Korthia have layers of security--for very good reasons. Each vault requires cryptographs in order to decode and disable the barriers. They are, for lack of a better term, the keys to every secret. Search outside the Vault for cryptographs stolen by the Mawsworn and return them to me. I will keep them, and the secrets they protect, safe.", ["objectivesText"] = "Retrieve 6 Stolen Cryptographs from outside the Vault and Seeker's Quorum. Progress: We cannot allow the Jailer to raid the Vaults of Korthia .", ["rewardItems"] = { 185746, 185855, 185857, 185859, 185860, 185861, 185863, 185864, 185865, 185866, 185867, 185868, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185888, 185893, 185894, 185895, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185944, 186155, 186156, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186770, 186976, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179082, ["x"] = 0.64, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179082, ["x"] = 0.64, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63776] = { ["id"] = 63776, ["name"] = "Observational Records", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63776 }, ["description"] = "Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Scholar's Den records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Be sure to check in the caverns below ground, as well! Bring those data to me, and I will reward you handsomely.", ["objectivesText"] = "Collect 5 Observational Records from the Scholar's Den. Progress: Have you retrieved the observational records from the Scholar's Den?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184374, 185758, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185887, 185888, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185941, 185944, 186017, 186155, 186156, 186170, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, [