[63794] = { ["id"] = 63794, ["name"] = "Broker's Bounty: Hungering Behemoth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63794 }, ["description"] = "New lands bring new opportunity. We will provide a quantity of valuables to any interested party in return for a substantial amount of devourer blood , preferably the goliath kind. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.", ["objectivesText"] = "Retrieve a Substantial Amount of Devourer Blood from a Hungering Behemoth. Progress: Have something to trade?", ["rewardItems"] = { 184374, 185855, 185857, 185858, 185859, 185860, 185863, 185864, 185865, 185866, 185868, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185879, 185880, 185881, 185882, 185884, 185885, 185886, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185944, 186017, 186155, 186156, 186201, 186205, 186206, 186245, 186663, 186665, 186666, 186667, 186668, 186670, 186734, 186735, 186737, 186738, 186739, 186740, 186741, 186742, 186744, 186745, 186746, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187506, 187507 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[63810] = { ["id"] = 63810, ["name"] = "Birds of a Feather", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["series"] = { 63848, 63849, 63855, 63895 }, ["description"] = "I have seen many ebon wings in the Maw, but never brilliant golden ones. Now that the aural sequencers are relaying information reliably, we should discover the source of these feathers. Follow the trail, Maw Walker. There is a mystery here... and very likely profit. Gold has value where you come from, does it not?", ["objectivesText"] = "Follow the trail of golden feathers to find what dropped them.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179078, ["x"] = 0.5685, ["y"] = 0.4675 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177597, ["x"] = 0.672, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.5685, ["y"] = 0.4675 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLin