[63853] = { ["id"] = 63853, ["name"] = "Kill the Flame", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63853 }, ["description"] = "Can you see it? Just out of the corner of my eye, it's always there... glowing so brightly! How is one supposed to relax and enjoy a cup of tea while that reminder of fire and ash is around. Please Maw Walker do me a favor... remove it so that we may all enjoy a cup of my favorite blend!", ["objectivesText"] = "Kill Infernus the Infinite for Theotar . Progress: Have you killed that dreadful creature?", ["rewardItems"] = { 180943, 181178, 181184, 181191, 181193, 181196, 181545, 181546, 181547, 181548, 181550, 181640, 181708, 181842, 182338, 182584, 183468, 183470, 184147, 184150, 184587, 185829, 185942 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63855] = { ["id"] = 63855, ["name"] = "Ease of Passage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["series"] = { 63810, 63848, 63849, 63895 }, ["description"] = "Korthia is ripe with opportunity. Look at all of these intriguing objects. In anticipation of such wonders, I have come prepared. Let us find a suitable location and establish a more permanent connection between this place and my refuge. Our work together is not yet finished.", ["objectivesText"] = "Establish a connection between Korthia and Ve'nari 's Refuge. Progress: I'll take my bag now, if you have it.", ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178470, ["x"] = 0.654, ["y"] = 0.233333 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.233333 }, ["mapCandidates"] = { ["npc"] = { 1543, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["