[63857] = { ["id"] = 63857, ["name"] = "Voices of the Eternal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["series"] = { 63578, 63638, 63639, 63856, 63904 }, ["description"] = "<Bolvar peers at the grand figures before him, at the numberless gateways stretching out into the ether.> This chamber is... truly wondrous. Yet there is no time to be awestruck. The Honored Voice must begin this meeting at once.", ["objectivesText"] = "Listen to the plan.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title