[63899] = { ["id"] = 63899, ["name"] = "Book of Binding: The Mad Witch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63899 }, ["description"] = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover crimson pages . Flipping through the volume, you note that many of its pages are missing. If the pages were retrieved, the book could be returned to the Archivist and reassembled.>", ["objectivesText"] = "Collect 12 Crimson Pages , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Is that book... speaking?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187206 } },
[63901] = { ["id"] = 63901, ["name"] = "Focusing the Eye", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "The combination of grief and rage you have harvested is sufficient for your needs. Most likely. If you insist on seeing this ill-advised endeavor through, use the horn at the Terminus Platform, where the River of Souls flows upward to Torghast. The energies there are most potent indeed. The presence of your golden allies should draw the Jailer's Eye. I only hope this does not prove to be the end of you. I hate to see an investment wasted.", ["objectivesText"] = "Go to the Terminus Platform and use the Ilskahorn to summon the Wrath of Odyn.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179078, ["x"] = 0.5685, ["y"] = 0.4675 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178950, ["x"] = 0.37, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.5685, ["y"] = 0.4675 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLin