[63902] = { ["id"] = 63902, ["name"] = "Good News, Everyone!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "Come, friend. Let us be rid of this foul place. No doubt your comrades will be eager to hear the news of the defeat of the Eye. I will bear you to them. Give the word when you are ready to depart, <name>.", ["objectivesText"] = "Fly with Danica to Korthia to give Bolvar the news. Progress: What has happened?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178950, ["x"] = 0.37, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 1543, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] =