[63963] = { ["id"] = 63963, ["name"] = "Broker's Bounty: Ripmaul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63963 }, ["description"] = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for a piece of heavily spiked hide from the beast known as Ripmaul. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.", ["objectivesText"] = "Retrieve a Heavy Spiked Hide from Ripmaul. Progress: Have something to trade?", ["rewardItems"] = { 184374, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185893, 185894, 185897, 185898, 185900, 185901, 185903, 185905, 185944, 186017, 186155, 186156, 186201, 186205, 186206, 186663, 186665, 186666, 186667, 186668, 186669, 186670, 186735, 186736, 186737, 186738, 186739, 186740, 186742, 186743, 186745, 186746, 186747, 186748, 186749, 186751, 186753, 186754, 186755, 186756, 186757, 186760, 186762, 186763, 186766, 186767, 186768, 186769, 186770, 186976, 187238, 187506, 187507 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[63964] = { ["id"] = 63964, ["name"] = "Broker's Bounty: Grimtalon", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63964 }, ["description"] = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for an intact boney beak from the beast known as Grimtalon. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.", ["objectivesText"] = "Retrieve a Mature Ossified Beak from Grimtalon. Progress: Have something to trade?", ["rewardItems"] = { 184374, 185856, 185857, 185858, 185860, 185861, 185862, 185863, 185864, 185866, 185867, 185869, 185870, 185871, 185873, 185874, 185875, 185876, 185878, 185881, 185882, 185883, 185885, 185886, 185894, 185903, 185905, 185941, 186017, 186155, 186156, 186201, 186205, 186206, 186663, 186665, 186666, 186667, 186668, 186669, 186670, 186735, 186736, 186737, 186738, 186739, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186760, 186761, 186762, 186763, 186764, 186765, 186767, 186769, 186770, 186976, 187239, 187506 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[63968] = { ["id"] = 63968, ["name"] = "Clean Out the Crucible", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63968 }, ["description"] = "The Winter Queen has called a hunt. We will ensure that the Crucible of the Damned is rid of the Jailer's forces today. Do your part and hunt down any enemies you find.", ["objectivesText"] = "Kill 30 enemies in the Crucible of the Damned and Calcis.", ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179537, 179562, 179584, 179604, 181402, 181403, 181411, 181412, 181414, 181415, 181416, 181417, 181419, 181426, 181427, 181428, 181429, 181430, 181457, 181459, 181477, 181479, 181541, 182110, 182338, 183470, 184378, 184381, 184382, 184383, 184384, 184519 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63969] = { ["id"] = 63969, ["name"] = "Looming Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63969 }, ["description"] = "The Winter Queen called for a hunt in this location due to reports of a massive, unnatural darkness swelling in its upper regions. The Wild Hunt is brave, but not foolish. We must learn what we can about this darkness before we charge into it. Search the bodies of our enemies nearby for clues.", ["objectivesText"] = "Collect 1 Mawsworn Ritual Book , 10 Mawsworn Missive Scraps , and 15 Dark Marrow . Progress: Have you learned anything regarding the darkness yet?", ["rewardItems"] = { 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184378, 184381, 184382, 184383, 184384, 184519, 186300, 186309, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63970] = { ["id"] = 63970, ["name"] = "No Soul Left Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63970 }, ["description"] = "Do you hear the cries of tormented souls trapped in Gorgoa? The twisted river of souls flows before us, swelling with cruelty and the torment of undeserving victims. Our brave regiment of druid spirits led the charge into the river to seek out those lost souls, but I fear many have instead joined in their suffering. Summon your courage and take my cradle with you into the river. Load the lost souls you find onto the cradle, then order the cradle to come back to me.", ["objectivesText"] = "Use Thiernax 's Rescue Cradle to rescue 12 Lost Druids in Gorgoa and send them back to Thiernax . Progress: I admire Thiernax 's dedication to even the least among us.", ["rewardItems"] = { 179508, 179513, 179517, 179532, 179537, 179547, 181405, 181426, 181427, 181428, 181429, 181455, 181477, 181479, 181541, 181735, 181736, 182136, 182657, 182769, 183487, 183488, 184378, 184381, 184382, 184383, 184384, 184519, 186300, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178884, ["x"] = 0.228, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178884, ["x"] = 0.228, ["y"] = 0.432 }, { ["mapID"] = 1543, ["npcID"] = 178892, ["x"] = 0.224, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63971] = { ["id"] = 63971, ["name"] = "Snail Stomping", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63971 }, ["description"] = "Careful where you step. You wouldn't want to accidentally squish a Mawsworn, would you? Of course you would! It's so fun! < Lady Moonberry giggles and points at the snails around her.> It's so much easier to squish Mawsworn after you've transformed them into stinky little snails. Here, take my wand and try it out on whatever you like. You may need to weaken them a bit first, but it'll work on almost anything!", ["objectivesText"] = "Use Lady Moonberry's Wand to transform 15 weakened enemies into snails, and then squish them! Progress: Lady Moonberry never ceases to surprise me.", ["rewardItems"] = { 137663, 175728, 181398, 181413, 181430, 181457, 181477, 181479, 181541, 184378, 184381, 184382, 184383, 184384, 184519, 186199 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178885, ["x"] = 0.226, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63972] = { ["id"] = 63972, ["name"] = "Just Don't Ask Me to Spell It", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63972 }, ["description"] = "It's getting dangerous out there for druid spirits! Thankfully, we always have room for another friend in our group, and this fine tirnenn has offered to help me and the gang get around the battlefield safely. <The tirnenn behind Choofa begins speaking slowly, but Choofa just talks louder.> Good ol' Kirriprkar- I mean, Karripkraker- I mean, Krackerkrisp... < Choofa laughs.> Let's just call her \"Big K\"! Hop on, everybody!", ["objectivesText"] = "Help Krrprripripkraak and her friends sow chaos in the Crucible of the Damned. Progress: Krrprripripkraak and Choofa are teaming up? This, I must see.", ["rewardItems"] = { 175740, 179508, 179513, 179517, 179532, 179547, 181398, 181399, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181421, 181458, 181459, 181477, 181479, 181541, 184378, 184381, 184382, 184383, 184384, 184519, 186654 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179066, ["x"] = 0.22, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63973] = { ["id"] = 63973, ["name"] = "Double Dromans", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63973 }, ["description"] = "Relax, $p. Breathe. < Dreamweaver inhales and exhales slowly.> Things are getting tense around here, but that doesn't mean YOU need to be tense. Everything is going to be okay. If you don't believe me, let the mighty deeds of Droman Aliothe and Droman Tashmur reassure you. They headed up the hill together to clear a path for the rest of us. They'll have everything taken care of in no time.", ["objectivesText"] = "Help Droman Aliothe defeat enemies along her path and kill Lord Dretnal . Progress: You can find the droman up the hill from here.", ["rewardItems"] = { 175713, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181413, 181477, 181479, 181541, 182456, 182686, 183484, 184378, 184381, 184382, 184383, 184384, 184519, 186300, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179067, ["x"] = 0.226, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63974] = { ["id"] = 63974, ["name"] = "That's Going to Sting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63974 }, ["description"] = "< Niya speaks loudly to be heard over the buzzing coming from the collection of needler nests behind her.> I've caught Moonberry trying to steal these nests for her pranks over ten times already! The other faeries said I was crazy to bring the needlers out here. Too wild! Too unpredictable! But that's exactly why we need them. Lord Herne 's scouts report powerful Heralds among our enemy's forces. Take one of these nests, and use it to surprise the Heralds!", ["objectivesText"] = "Use an Angry Needler Nest to weaken and kill Herald Gkeca , Herald Throgtu , and Herald Duarri . Progress: Niya is proving to be quite the clever tactician...", ["rewardItems"] = { 175713, 175728, 175740, 179562, 181398, 181411, 181412, 181413, 181457, 181458, 181459, 181477, 181479, 181541, 182559, 184378, 184381, 184382, 184383, 184384, 184519, 186569 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179065, ["x"] = 0.222, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63976] = { ["id"] = 63976, ["name"] = "The Al'ley Cat of Oribos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1672, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "Ah, Maw Walker. I have a message. An individual has a proposition for you, specifically. I know nothing of the details, only that they asked you meet them towards the back of the Idyllia.", ["objectivesText"] = "Meet with the mysterious contact in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 186182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1672, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 14, ["flags"] = 0 } } },
[63977] = { ["id"] = 63977, ["name"] = "Insider Trading", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13672, ["mapID"] = 1672, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "I am the foremost expert on broker culture. However, relationships between cartels are complicated and unstable. Cartel So holds a small presence here in Oribos, which means the other cartels may have knowledge that I do not. Ask around--with your renown, surely they'll have whatever information that we are missing.", ["objectivesText"] = "Speak with various broker cartels around Oribos. Progress: Have you had a chance to speak with the other cartels?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 186182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13672 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1672, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 15, ["flags"] = 0 } } },
[63979] = { ["id"] = 63979, ["name"] = "Things Best Kept Dark", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1672, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "The leader of Cartel So represents a grave danger to the Shadowlands, Maw Walker. Her name is So'leah. She seeks to assemble an artifact of the First Ones and use its power for selfish ends. Pieces of the relic are said to be hidden on your homeworld. Brokers have never before found our way there. But if So'leah does, then Azeroth too is imperiled. We must intercept her. There is cargo nearby marked for Cartel So. Perhaps the manifest will give us clues as to their leader's whereabouts.", ["objectivesText"] = "Find a shipping manifest belonging to Cartel So. Progress: Have you found anything?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 186182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1672, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 16, ["flags"] = 0 } } },
[63980] = { ["id"] = 63980, ["name"] = "Seeking Smugglers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13672, ["mapID"] = 1525, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "We brokers have found that it is in our best interests to remain mobile. And discreet. A number of our cities and outposts are tucked away in the In-Between, capable of moving from place to place. Much to my chagrin, it seems I have lost track of Tazavesh. I believe our best course of action is to ask Cartel Ta for access. They pride themselves on keeping track of such things. Let's try our luck with those at the Night Market in Revendreth. They may be more forthcoming than their Oribos kin.", ["objectivesText"] = "Speak with Ta'nla the Identifier at the Night Market.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 186182, 186637 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160090, ["x"] = 0.514, ["y"] = 0.828 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.828 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13672 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 17, ["flags"] = 0 } } },
[63982] = { ["id"] = 63982, ["name"] = "Above My Station", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "While I indeed know the location of the Veiled Market, I fear I can do little in terms of providing you with transportation to it. In return for your assistance with a task, I can send you to someone who can assist us both. There is a bounty hunter at Transfer Station Ta--a broker enclave in Bastion. He is better suited to help you... and he owes me a shipment. Meet with Ta'oku and tell him that Ta'nla sent you. For your convenience, I can offer use of a portal. After all, we are partners, yes?", ["objectivesText"] = "Take the portal at the Night Market and speak with Ta'oku.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 186182 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160090, ["x"] = 0.514, ["y"] = 0.828 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158890, ["x"] = 0.325, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.828 }, ["mapCandidates"] = { ["npc"] = { 1525, 1533 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 18, ["flags"] = 0 } } },
[63983] = { ["id"] = 63983, ["name"] = "Dead Drop", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "Ta'nla requested something very... specific... on behalf of a client. The kyrian have been working on a new type of centurion they call an aquilon. I sent some of our trade specialists to retrieve the prototype in question, but they have yet to return. Until I have the item, there is obviously no way I can ship it to Ta'nla. Perhaps we can help one another. If you can locate the aquilon and bring it here, I will help you reach Tazavesh.", ["objectivesText"] = "Retrieve the Prototype Aquilon . Progress: Have you acquired the... item?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 137663, 186182 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158890, ["x"] = 0.325, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158890, ["x"] = 0.325, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 19, ["flags"] = 0 } } },
[63984] = { ["id"] = 63984, ["name"] = "Coins for the Ferryman", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "Your side of the deal is done, Maw Walker. Now for your payment. My cartel runs a ferry that travels between Oribos and Tazavesh. Its purpose is to transport cargo, but as in all things, there are... exceptions. Take this coin to Ta'meri and you will be provided safe passage to the market. What happens after that is up to you. <Ta'oku bows, uttering a sound that seems almost like a chuckle.>", ["objectivesText"] = "Speak with Ta'meri in Oribos. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 186182, 186696 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158890, ["x"] = 0.325, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 20, ["flags"] = 0 } } },
[63985] = { ["id"] = 63985, ["name"] = "The Veiled Market", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 2016, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "Let me guess... Ta'oku sent you my way, yes? < Ta'meri looks at the coin you offer.> So, you seek travel to Tazavesh. Not something we'd typically offer an outsider, but since payment has been accounted for, it would be my pleasure to assist you. Step aboard, and do remember to keep any appendages inside the craft at all times. The currents of the In-Between can be fickle.", ["objectivesText"] = "Ride the barge to Tazavesh.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 186182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 2016, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 21, ["flags"] = 0 } } },
[63986] = { ["id"] = 63986, ["name"] = "Tazavesh: Raiders of the Lost Artifact", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13672, ["mapID"] = 2016, ["storyline"] = { 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 63986 }, ["description"] = "It looks like you may need to show a bit of force once more, my dear friend. Tazavesh security will not let us simply walk in. But So'leah needs to be stopped. If that requires a bit of physical... persuasion... then it is a necessary evil. Bring some friends. I have a feeling the security here has tricks up their sleeves.", ["objectivesText"] = "Enter Tazavesh and defeat So'leah .", ["rewardGold"] = 3098000, ["rewardXP"] = 16330, ["rewardItems"] = { 184315, 186182, 187171, 188808 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13672 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 2016, ["questLines"] = { { ["id"] = 1235, ["name"] = "Tazavesh: The Veiled Market", ["orderIndex"] = 9, ["flags"] = 0 } } },
[63989] = { ["id"] = 63989, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63989 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! Can you take Plaguey with you and test their ability to infect organic life forms?", ["objectivesText"] = "Help Plaguey test their infection ability in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 137663, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63990] = { ["id"] = 63990, ["name"] = "The Blade in the Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63673, 63674, 63675, 63728 }, ["description"] = "Though my hunt has been arduous, I have two promising leads on additional Night Warriors. The first is here in Maldraxxus. This tower contains records of those who arrived in Maldraxxus, including someone referred to as \"The Blade in the Night.\" I believe this to be our next Night Warrior. I encountered many traps on the way here. Doubtless we will find more within the tower. Someone is trying to stop us. We will not let them succeed.", ["objectivesText"] = "Search the Sepulcher of Knowledge for clues. Progress: Hmm.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185773 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 177471, ["x"] = 0.424, ["y"] = 0.243 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 177435, ["x"] = 0.474, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.243 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 }