[63994] = { ["id"] = 63994, ["name"] = "Who is the Maw Walker?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["description"] = "Korthian prophecies foretell the arrival of a Maw Walker who can save us from disaster. Perhaps this is that day. But perhaps not. I must test your anima to verify your claim. If you speak the truth, then I have a solemn duty to empower your anima before we proceed.", ["objectivesText"] = "Participate in Tal-Galan 's Maw Walker trial. Progress: Let us proceed, Maw Walker.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 175511, 175524, 175525, 175526, 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177227, ["x"] = 0.638, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177227, ["x"] = 0.638, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["quest