[64007] = { ["id"] = 64007, ["name"] = "Charge of the Covenants", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1961, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["description"] = "Thanks to the efforts of you and other heroes of Azeroth, the covenants have grown strong. But we can no longer afford to wait for the Jailer to make his next move. The way to the Maw is open. Our forces stand ready. The covenants await your signal, <name>.", ["objectivesText"] = "Rally the covenant forces to go into the Maw.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 109183, 118937, 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143