[64015] = { ["id"] = 64015, ["name"] = "Into the Meat Grinder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64015 }, ["description"] = "All these mawsworn have got me excited for some slaughter! I've got a plan that probably won't end in you dying. Are you in?", ["objectivesText"] = "Lay a trap for the Mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64016] = { ["id"] = 64016, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64016 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Ooz, I'd like to know if they are able to consume organic material and increase in size.", ["objectivesText"] = "Help Ooz test their growth ability on Shardhide in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 137663, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64017] = { ["id"] = 64017, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64017 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.", ["objectivesText"] = "Help Bloop test their propagation ability in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64018] = { ["id"] = 64018, ["name"] = "The Weight of Stone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64018 }, ["description"] = "The campaign continues, $p. The Stone Legion is here to turn the tide of battle. First, we must deliver supplies to our allies. The broken land of Korthia means we are the only ones who can keep our troops supplied. Second, we must deal with the mawsworn and the devourers. I have a very simple strategy. We are going to drop anima onto the mawsworn. That will attract the devourers to attack. Either they kill the mawsworn, or the mawsworn kills them. Regardless, we win.", ["objectivesText"] = "Assist the Stone Legion in delivering supplies and anima.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178794, ["x"] = 0.615, ["y"] = 0.251 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178794, ["x"] = 0.615, ["y"] = 0.251 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.251 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64042] = { ["id"] = 64042, ["name"] = "Rituals of Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63679, 63680, 63681, 63682, 63683, 64090, 64091, 64437 }, ["description"] = "Tyrande's time grows short, so we must act quickly. < Ysera frowns in concern.> We had hoped to gather more Night Warriors, but we will have to proceed with who we have and hope it is enough. < Ysera shakes her head, then looks more resolute.> Before we can begin, we must finish preparations for the ritual. Please bring these last few items with you and meet us at the grove.", ["objectivesText"] = "Assist with the preparations and ritual. Progress: Good, we may begin.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 22296, 185773 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 177434, ["x"] = 0.460667, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 177434, ["x"] = 0.460667, ["y"] = 0.614 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questTyp