[64080] = { ["id"] = 64080, ["name"] = "Down to Earth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64080 }, ["description"] = "I can hear the wings of the Mawsworn in the sky up above, taunting us. But a bird in the hand can be crushed. Take my spear and prove your aim. Pull a few down and smite them. Be sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point. I want to see you drag them out of the sky.", ["objectivesText"] = "Use Korayn's Javelin to spear 4 Mawsworn Harbingers.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 186474, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178841, ["x"] = 0.609, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178841, ["x"] = 0.609, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.609, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64083] = { ["id"] = 64083, ["name"] = "Sinfall Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 64083, 64325 }, ["description"] = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, <name>. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1256, ["name"] = "Sinfall Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64084] = { ["id"] = 64084, ["name"] = "Necrolord Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 64084, 64324 }, ["description"] = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1254, ["name"] = "Necrolord Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64085] = { ["id"] = 64085, ["name"] = "Night Fae Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 64085, 64322 }, ["description"] = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1255, ["name"] = "Night Fae Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64086] = { ["id"] = 64086, ["name"] = "Kyrian Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 64086, 64323 }, ["description"] = "Look around you, <name>. Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1253, ["name"] = "Kyrian Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64090] = { ["id"] = 64090, ["name"] = "The Big Squeeze", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63679, 63680, 63681, 63682, 63683, 64042, 64091, 64437 }, ["description"] = "So our missin' blue got 'imself dragged off to the big squeeze. Fortunately I am wise to the prise. We'll soft foot it in like we work there, find your moose, avoid eye contact with the fangs, and chisel out of 'ere like we're masons. Follow?", ["objectivesText"] = "Head to where Cudgelface thinks Huln was taken, and blend in. Progress: Well, this is exciting!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185773 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 177967, ["x"] = 0.356, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLin