[64092] = { ["id"] = 64092, ["name"] = "Hunting Huln", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "Huln is somewhere in the area, but the Stonewright isn't letting anyone in to her territory because of the recent, ah, troubles with Dreadlords. The guards won't let anyone in, and they're kicking out anyone who doesn't look like they belong. Luckily for Huln, Cudgelface and I came up with a foolproof plan! We just need to look like we belong and then we can ask around and find Huln. Easy!", ["objectivesText"] = "Don a disguise then search Dominance Keep for Huln Highmountain while avoiding the guards.", ["rewardGold"] = 241020, ["rewardXP"] = 8165, ["rewardItems"] = { 185773 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 177962, ["x"] = 0.297, ["y"] = 0.193 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 178254, ["x"] = 0.38, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.297, ["y"] = 0.193 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 97, ["flags"] = 0 } } },
[64103] = { ["id"] = 64103, ["name"] = "Old Tricks Work Best", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64103 }, ["description"] = "$p. Here we are again, fighting alongside each other to protect the Shadowlands. We're waging a losing war, but we might be able to turn the tide. I need you to seek out some very specific commanders of the Mawsworn forces. In every army, there's good commanders and bad ones. By taking out the good ones, only the bad ones advance, weakening the force as a whole. Our Eyes have brought us the names. Now I just need you to kill them.", ["objectivesText"] = "Kill Moros , Oizys , and Apate , commanders of the Mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178808, ["x"] = 0.606, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178808, ["x"] = 0.606, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64104] = { ["id"] = 64104, ["name"] = "Think of the Critters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64104 }, ["description"] = "The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat. I've saved some extra food that we can share with them. But I'm worried that they might be too shy to trust us, and I don't blame them! Here. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.", ["objectivesText"] = "Approach and feed Hungry Gromits in Korthia .", ["rewardItems"] = { 71076, 182180, 183395, 184396, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 186561, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178839, ["x"] = 0.614, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178839, ["x"] = 0.614, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64106] = { ["id"] = 64106, ["name"] = "A Unified Effort", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64106 }, ["description"] = "You have made strong allies within your covenant as well as the others within the Shadowlands. This bond is why they have decided to loan aid to our cause. They are ready to fight alongside us as we begin our advance into the Maw. Each covenant will strike at the Jailer from a different area. Help them scour this treacherous land for any who serve Zovaal so that we may put an end to his growing influence.", ["objectivesText"] = "Aid the covenants in assaulting the Jailer's forces in the Maw.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 186300, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64129] = { ["id"] = 64129, ["name"] = "Charge of the Wild Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64129 }, ["description"] = "Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. I admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh . Aldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?", ["objectivesText"] = "Mount Aldermeigh and slay Mawsworn in Korthia .", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64166] = { ["id"] = 64166, ["name"] = "Random Memory Access", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64166 }, ["description"] = "When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too. Those people had lives, hopes, memories. I have to think that they can't all be gone, and we might be able to save something of them that lingers. Here, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. No one should be forgotten.", ["objectivesText"] = "Collect Korthian Memories using the Ephemeral Wings .", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 186672, 187184, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64167] = { ["id"] = 64167, ["name"] = "Pets Detective", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7502, ["storyline"] = { 64167 }, ["description"] = "I'm so glad you're here, <name>! I've been expecting a delivery of pet supplies and some new pets. But my distribution manager, Zantini has not reported in. I suspect foul play. There's been some shady people eyeballing my store for a while now. But I haven't been able to leave the store and track them down. You can. Take my pet cat, Fiona, and find these well hidden spies.", ["objectivesText"] = "Investigate the city of Dalaran with Breanni 's special spy catching cat, Fiona. Progress: What have you learned, <name>?", ["rewardGold"] = 29500, ["rewardXP"] = 25, ["rewardItems"] = { 186553, 186695, 186772, 187128 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[64184] = { ["id"] = 64184, ["name"] = "Missing Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10472, ["storyline"] = { 64184 }, ["rewardXP"] = 2090, ["rewardItems"] = { 31666 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10472 } }, ["questType"] = "standard" },
[64194] = { ["id"] = 64194, ["name"] = "War Prototype", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64194 }, ["description"] = "As Forgelite Prime, I always work to make something better! But largest centurions, they are much too large to bring to Korthia . This, I fix. Here is Atleos , field colossus prototype. Vanguard of the Kyrian! It needs testing. More testing. Must be perfect against a powerful opponent. Go, take Atleos and defeat a great Maw beast! Press all the buttons!", ["objectivesText"] = "Use the Atleos prototype in the Windswept Aerie to defeat Kraxis . Progress: You have work still, yes?", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64196] = { ["id"] = 64196, ["name"] = "Pet Up", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7502, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "It sounds like some group of pet poachers are up to no good in the Eye of Azshara . My supply manager's flight path takes him right over that area! Zantini and his pets, Strigfellow and Speedy IV , were bringing back a rare murloc pet, along with some other pets and supplies. <name>, please find Zantini and his pets. Help them out. Then we can try to recover the pets and the supplies.", ["objectivesText"] = "Find and help Zantini and his pets along the coast of the Eye of Azshara .", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 79869, 87399, 89125, 91086, 116415, 143753, 151191, 163036, 165835, 169665, 174360, 184373, 184374, 186553, 186695, 186772, 187128, 198725, 198726, 237812, 263871 }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64202] = { ["id"] = 64202, ["name"] = "Gotta Hand It To Ya", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 64202 }, ["description"] = "Your power Maw Walker... it rivals even mine before Zovaal separated my body. This is but a small part of my whole, but more than enough... Allow me to aid you in your efforts against Zovaal. In doing so my vengeance will be fulfilled.", ["objectivesText"] = "Accept Nilganihmaht's help.", ["rewardItems"] = { 184513, 185972, 185973, 186653, 186654, 186713, 226506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64203] = { ["id"] = 64203, ["name"] = "The Coast is Clear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "I was on the last leg of a supply run when we were shot down! They took the pets, but the supplies are scattered over this stretch of beach. I don't know what they're planning, but I know we gotta get our supplies. You an' me, we ain't subtle.... But Speedy IV ... He won't cause all them pirates to go into hiding. He can get the supplies while Stringfellowe surveils the area from the air. Speedy's fond of you, so chat him up and let's try to recover the smoldering supplies before they all burn up.", ["objectivesText"] = "Gather pet supplies along the shores of Eye of Azshara with Speedy IV . Progress: Supplies are always in need.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 183395, 184396, 186553, 186695, 186730, 186772, 187005, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64210] = { ["id"] = 64210, ["name"] = "The Box of Many Things", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13575, ["mapID"] = 1912, ["storyline"] = { 64210, 64216, 64557 }, ["description"] = "Ah, Maw Walker, of course. Soon I shall be undone, claimed by this place forever. But you continue to walk its halls, unbroken! It was my great aspiration to prevail with the help of this box. Sadly, I overestimated my own capabilities. I trust I am not overestimating yours. Take the box. Prove yourself worthy of it.", ["objectivesText"] = "Bring the Box of Many Things to the Runecarver . Progress: Ah, you return.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 186732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13575 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 157, ["title"] = "Box of Many Things Intro", ["questLineID"] = 1259, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1912, ["questLines"] = { { ["id"] = 1259, ["name"] = "The Box of Many Things", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64213] = { ["id"] = 64213, ["name"] = "A Symbol of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64211, 64213, 64314 }, ["series"] = { 64211 }, ["description"] = "Before Anduin followed the Jailer through the gateway, he dropped something. I don't think this was part of the Jailer's plan. It must be a sign that Anduin's soul is still his own! <Jaina opens her hand to show you a golden compass.> This was very personal to Anduin. I feel his presence upon it. We need to know why he left it for us.", ["objectivesText"] = "Assist Jaina in examining Anduin's compass. Progress: If Anduin was able to leave this for us to find, then some part of him must still be free from the Jailer's domination...", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 180074, ["x"] = 0.631333, ["y"] = 0.248667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180074, ["x"] = 0.631333, ["y"] = 0.248667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.631333, ["y"] = 0.248667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64214] = { ["id"] = 64214, ["name"] = "A Symbol of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64212, 64214, 64314 }, ["series"] = { 64212 }, ["description"] = "Before Anduin followed the Jailer through the gateway, he dropped something. I'm not sure what it was, but Jaina picked it up. Perhaps this is a sign that Anduin is still fighting back against the Jailer! We need to find out what this object was, and why the young king left it for us.", ["objectivesText"] = "Assist in examining Anduin's compass. Progress: Why did Anduin leave this for us to find?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 180073, ["x"] = 0.62, ["y"] = 0.2596 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180073, ["x"] = 0.62, ["y"] = 0.2596 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.2596 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64215] = { ["id"] = 64215, ["name"] = "Paw Patrol", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "While Speedy IV was collecting supplies, Stringfellowe was scouting the rest of the Eye of Azshara . Turns out there is a whole mess of pirates to the west. That must be where the pets are at. Head over there and rescue the pets.", ["objectivesText"] = "Obtain keys from the Violetsail pirates along the west coast of the Eye of Azshara . Then set the captured pets free. Progress: Have you found them, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 55053, 77532, 82960, 130250, 159825, 159826, 171441, 186553, 186695, 186772, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64216] = { ["id"] = 64216, ["name"] = "Tower Knowledge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1911, ["storyline"] = { 64210, 64216, 64557 }, ["description"] = "The woven power of this box can only be unlocked by feeding it pride and memory. In its weave are incantations I have seen used in the other realms to siphon or condition a soul. This... abomination... has used these tools of redemption and honor to create a lock. As you challenge the floors of Torghast, your skill, speed, and efficiency will all contribute to Tower Knowledge which this box can feed upon. Feed it to retrieve the powers within.", ["objectivesText"] = "Place the Box of Many Things in Torghast. Progress: < The Box of Many Things thrums with power.>", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 186732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 157, ["title"] = "Box of Many Things Intro", ["questLineID"] = 1259, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1911, ["questLines"] = { { ["id"] = 1259, ["name"] = "The Box of Many Things", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64218] = { ["id"] = 64218, ["name"] = "Danger Near and Far", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["series"] = { 64219 }, ["description"] = "We have done all we can about the Jailer for now, my friend. Other matters require our attention. Like the devourer rifts I recently saw opening to the east! If we do not stop them, those beasts will wreak havoc on this place. Will you help me take care of them, <name>?", ["objectivesText"] = "Investigate the Genesis Fields.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 29, ["flags"] = 0 } } },
[64219] = { ["id"] = 64219, ["name"] = "A Mysterious Voice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["series"] = { 64218 }, ["description"] = "So much destruction. The devourers are insatiable. I hope the creature we heard is not badly hurt. This door is not going to open normally. Perhaps we can force our way through together! Whatever is on the other side needs our help.", ["objectivesText"] = "Enter the Cradle of Nascence. Progress: We must help whoever is trapped inside!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 30, ["flags"] = 0 } } },
[64223] = { ["id"] = 64223, ["name"] = "Core of the Matter", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "She has fallen, but appears to still be alive. There must be something we can do to help her. Let us see if the Enlightened know anything. I will find some way to transport her and meet you back in Haven.", ["objectivesText"] = "Speak with Elder Kreth in Haven. Progress: Let us hope we are not too late.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 31, ["flags"] = 0 } } },
[64224] = { ["id"] = 64224, ["name"] = "Seeking the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "If the Elders will not assist us, we must find someone who will. That other Enlightened, Firim... he was much more interested in the automa. He said he was estranged from his kin. Someone in Haven must know something about him. Look around the camp for clues about Firim's whereabouts. I will try again to convince the Elders to talk.", ["objectivesText"] = "Search Haven for information about Firim. Progress: Have you found anything?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["order