[64225] = { ["id"] = 64225, ["name"] = "Finding Firim", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "You found something? What luck! May I see the letter? So, an Enlightened named Xevveth heard that Firim was last seen west of the Forge of the Afterlives, and went to go seek him out. We should begin our search there.", ["objectivesText"] = "Find Firim .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 33, ["flags"] = 0 } } },
[64226] = { ["id"] = 64226, ["name"] = "Security Measures", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "It seems the hidden traps I placed around the grotto are not as effective as I would like, considering your presence in my home. However, they are still useful in preventing the majority of unwanted attention. Since you so kindly brought assassins to me, I cannot reset the traps myself. So you will need to do it for me. I will stay here to guard both myself and my precious research. Use this Sensory Synchronizer I placed nearby to show you which traps need to be reset.", ["objectivesText"] = "Use the Sensory Synchronizer, then reset 10 Triggered Traps near Exile's Hollow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 35, ["flags"] = 0 } } },
[64227] = { ["id"] = 64227, ["name"] = "Unseen Agents", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "Ever since you opened the way from Oribos, certain cartels have taken the opportunity to come after me and my work in a rather... lethal fashion. They know how important my research is to everything. More assassins are sure to follow, what with you blazing a clear path right to me! I cannot get them all. You need to fix this and help protect my secrets. Take care of them for me.", ["objectivesText"] = "Kill assassins near Exile's Hollow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 34, ["flags"] = 0 } } },
[64228] = { ["id"] = 64228, ["name"] = "Now You May Speak", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "You truly brought me an oracle! Intact even! I have never known these divine beings to speak to anyone but automa. There is so much we could learn from her about Zereth Mortis . You must tell me everything!", ["objectivesText"] = "Talk to Firim about the oracle. Progress: Let me hear what happened...", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 36, ["flags"] = 0 } } },
[64230] = { ["id"] = 64230, ["name"] = "Cyphers of the First Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "The way is not quite clear, but the first steps have been made. It seems the divine construct has taken more of a liking to you than to me. Now that it has given you the beginnings of understanding, see what else it wishes to show you. The results should be enlightening.", ["objectivesText"] = "Investigate the Cypher Console . Progress: You have been blessed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 189983, 190980, 190981, 190982, 190986, 190987, 190988, 190992, 190993, 190994, 190998, 190999, 191000 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 38, ["flags"] = 0 } } },
[64237] = { ["id"] = 64237, ["name"] = "Gurgl and the Bandit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "We've got all the pets back except Gurgl . <name>, we need to get that pet back for Breanni . Stringfellowe saw a nook where we think the leader of these pet poachers is hiding out. Let's get 'em!", ["objectivesText"] = "Find and battle the leader of the pet poachers.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 93040, 186553, 186695, 186772, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64240] = { ["id"] = 64240, ["name"] = "Flight of the Kyrian", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64240 }, ["description"] = "We've engaged in a heavy battle at the entrance to the Vault of Secrets! Our forces could use some reinforcement. Please, guide my fellow Ascended to give support to our fighters there. The fighters on the ground can handle the clean-up, but they need shields and healing. Good luck!", ["objectivesText"] = "Assist covenant forces from the air at the Vault of Secrets. Progress: Have you helped our forces at the Vault of Secrets?", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64255] = { ["id"] = 64255, ["name"] = "Party Time", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 64255 }, ["objectivesText"] = "Progress: Oh neat that looks like Temel's hat!", ["rewardItems"] = { 180752 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[64266] = { ["id"] = 64266, ["name"] = "Supplies from The Archivists' Codex", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64266 }, ["description"] = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact. Please. Allow me to share my gratitude.", ["objectivesText"] = "Speak with Archivist Roh-Suir in the Reliquary of Remembrance in Korthia.", ["rewardItems"] = { 187028 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2473, ["threshold"] = 10000 } } } },
[64267] = { ["id"] = 64267, ["name"] = "Mysterious Gifts from Ve'nari", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64267 }, ["description"] = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. Take this and continue your work... somewhere less conspicuous.", ["objectivesText"] = "Speak with Ve'nari at Ve'nari 's Refuge in the Maw.", ["rewardItems"] = { 187029 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2474, ["threshold"] = 10000 } } } },
[64271] = { ["id"] = 64271, ["name"] = "A More Civilized Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64271 }, ["description"] = "Ah, $p. I have a matter to discuss with you. But not here. <Nadjia eyes the other denizens of Keeper's Respite suspiciously.> Meet me where the road enters Korthia from the Maw and I will explain.", ["objectivesText"] = "Meet Nadjia near the road leading into Korthia .", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64282] = { ["id"] = 64282, ["name"] = "Full of Surprises", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64282 }, ["description"] = "You continue to surprise me Maw Walker, your presence here is most unexpected! Since we are both here, I believe we should work together. The Jailer has a vault full of valuables, somewhere in this rift. Locate it for me, or bring it here to be opened and we'll share the wealth together!", ["objectivesText"] = "Locate Zovaal's Vault. Progress: Have you found the vault?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 180817, 186731, 186969, 187113 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179904, ["x"] = 0.447, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 179904, ["x"] = 0.447, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[64286] = { ["id"] = 64286, ["name"] = "Paragon of Death's Advance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64286 }, ["description"] = "The call to action has been answered, yet again. Your efforts shall not go unnoticed. Let us see if we cannot find a fitting reward for your efforts.", ["objectivesText"] = "Speak with Duchess Mynx at Keeper's Respite in Korthia .", ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64287] = { ["id"] = 64287, ["name"] = "Paragon of The Archivists' Codex", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64287 }, ["description"] = "You have gone to great lengths to restore that which we cherish most dearly, Maw Walker. Meet me in my chamber when you are ready. We have one final matter to discuss.", ["objectivesText"] = "Speak with Archivist Roh-Suir at the Reliquary of Remembrance in Korthia.", ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64288] = { ["id"] = 64288, ["name"] = "Paragon of Ve'nari", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64288 }, ["description"] = "Come, Maw Walker. Meet me at my refuge. We have one final matter to discuss. ...and do make sure you are not followed.", ["objectivesText"] = "Speak with Ve'nari at Ve'nari 's Refuge in The Maw .", ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[64289] = { ["id"] = 64289, ["name"] = "Picking Up the Pieces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64289 }, ["description"] = "Much was lost when Korthia was pulled into the Maw. Priceless relics were torn asunder. I have seen creatures carrying the remnants of these items. They must be recovered. Confront the Jailer's forces and search what remains of Korthia for these fragments of our once glorious vault.", ["objectivesText"] = "Recover 50 Relic Fragments from rare creatures and treasures throughout Korthia.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64290] = { ["id"] = 64290, ["name"] = "Collecting Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64290 }, ["description"] = "You have done well to collect these fragments. They will go a long way to restoring our archives. I can use what you have found to gather more research about what was lost within Korthia. Afterwards, it will be up to you to find more fragments and relics within Korthia to boost our archives.", ["objectivesText"] = "Speak with Archivist Roh-Suir to turn in any Korthian Relics for Cataloged Research. Progress: We thank you for your aid so far, Maw Walker.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186664, 186665, 186716, 186734, 186735, 186741, 186742, 186750, 186751, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64292] = { ["id"] = 64292, ["name"] = "Maelie, The Wanderer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64292 }, ["description"] = "I can't thank you enough for finding Maelie! You know, I think she's just a little bit more than I can handle. Would you mind watching over her? I think she's really taken a liking to you!", ["objectivesText"] = "Accept responsibility for Maelie.", ["rewardItems"] = { 184513, 186643 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179930, ["x"] = 0.606, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179930, ["x"] = 0.606, ["y"] = 0.218 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64314] = { ["id"] = 64314, ["name"] = "Covenants Renewed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64211, 64212, 64213, 64214, 64314 }, ["description"] = "Our efforts were focused on preventing the Jailer from shattering the barrier around the Maw and invading the rest of the Shadowlands. Instead, he expanded the Maw itself to envelop Oribos and claim the Aribiter's sigil. I do not fully understand what we witnessed atop Torghast. But the Primus certainly does. It is time to enact his contingency plan. The covenants will arrive with their sigils shortly. Inform the Primus that we are ready to begin.", ["objectivesText"] = "Speak to the Primus , then claim the Sigils from each covenant.", ["rewardGold"] = 170800, ["rewardXP"] = 4085, ["rewardItems"] = { 187347 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64322] = { ["id"] = 64322, ["name"] = "Night Fae Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 64085, 64322 }, ["description"] = "Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1255, ["name"] = "Night Fae Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64323] = { ["id"] = 64323, ["name"] = "Kyrian Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 64086, 64323 }, ["description"] = "Bastion is healing thanks to you, <name>. The path is clear. Your accomplishments have not gone unnoticed, even beyond the borders of Bastion. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1253, ["name"] = "Kyrian Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64324] = { ["id"] = 64324, ["name"] = "Necrolord Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 64084, 64324 }, ["description"] = "The might of the Necrolords grows thanks to you, <name>. Your accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1254, ["name"] = "Necrolord Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64325] = { ["id"] = 64325, ["name"] = "Sinfall Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 64083, 64325 }, ["description"] = "Sinfall's influence grows thanks to your triumphs, <name>! Your accomplishments have not gone unnoticed, even beyond the borders of Revendreth. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1256, ["name"] = "Sinfall Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
