[64430] = { ["id"] = 64430, ["name"] = "Spill the Tea", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64430 }, ["description"] = "It seems Tubbins and Gubbins have gone off somewhere. I do worry about the two of them. Be a dear and check on them. One never knows what shenanigans they might be up to. I last saw them speaking with one of the faeries from Ardenweald. They were discussing the fine art of tea making.", ["objectivesText"] = "Find Tubbins and Gubbins.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187353, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179218, ["x"] = 0.616, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179218, ["x"] = 0.616, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64432] = { ["id"] = 64432, ["name"] = "Strength to Weakness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64432 }, ["description"] = "$p, the scrap metal we've been recovering has some interesting properties. I have come to believe the mawsworn are imbuing their armor and increasing its durability. Take this lightning rod. First, you will need to get struck by lightning. Don't make that face. You'll be fine. But, you need to also be grounded on mawsworn metal. The large chains embedded in Korthia , near the Windswept Aerie should work. Once you are... ah... energized, I will send a tauralus, Borrhas, to carry you into battle.", ["objectivesText"] = "Empower the lightning rod, then kill mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179214, ["x"] = 0.632, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179214, ["x"] = 0.632, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64437] = { ["id"] = 64437, ["name"] = "Inform the Primus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63728, 63990, 64042, 64090, 64091, 64092, 64437 }, ["series"] = { 63679, 63680, 63681, 63682, 63683, 64042, 64090, 64091 }, ["description"] = "<name>, return to Korthia and tell the Primus that the Winter Queen's sigil has been restored.", ["objectivesText"] = "Return to the Primus in Korthia .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185773 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 177434, ["x"] = 0.460667, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 1565, 1961 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 18, ["flags"] = 0 } } },
[64438] = { ["id"] = 64438, ["name"] = "Empowering Equipment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64438 }, ["description"] = "The research you find can unlock many possibilities. One such avenue is improving some equipment that you may find within Korthia. Speak with my assistant nearby. He can use our research to restore this equipment to its former power.", ["objectivesText"] = "Speak with Assistant Scholar Kah-Vez to upgrade one piece of equipment from Korthia. Progress: I will do what I can to aid you, Maw Walker.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
