[64506] = { ["id"] = 64506, ["name"] = "What Must Be Found", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64506 }, ["description"] = "There is much detailed in the codex. Items that are forever lost, and some that still exist. Some powerful relics may remain, hidden somewhere within Korthia. Browse the reliquary. You will find echoes of artifacts that are still whole here in Korthia. Commit them to memory. You must find them and return them to me.", ["objectivesText"] = "Examine what relics are missing within the Reliquary of Remembrance. Progress: Have you seen the missing relics?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64509] = { ["id"] = 64509, ["name"] = "Stylish Cover", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 64509 }, ["objectivesText"] = "Progress: Is that ta' same type of head topper Hips from the Sinstone Swingers wears?", ["rewardItems"] = { 187256 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[64511] = { ["id"] = 64511, ["name"] = "Missing Relics", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64511 }, ["description"] = "Thanks to your aid, I have been able to recover more research regarding the lost relics from the vault. I have gone over the codex and believe there are more relics within Korthia that can still be recovered. These were sealed within chests that I believe have been scattered in Korthia during the initial attack. I have set up the missing relics in here. Commit them to memory. They must be recovered.", ["objectivesText"] = "Examine the missing relics within the Reliquary of Remembrance. Progress: Have you seen the missing relics?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614, 187863 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64513] = { ["id"] = 64513, ["name"] = "Ve'rayn's Head", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64513 }, ["description"] = "<Ve'rayn has been hunting Ve'nari for some time. Ve'nari would be very interested in seeing proof that she has been dealt with permanently.>", ["objectivesText"] = "Deliver Ve'rayn's Head to Ve'nari in Ve'nari 's Refuge. Provided item:", ["rewardItems"] = { 187264 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["startItems"] = { 187264 } },
