[64592] = { ["id"] = 64592, ["name"] = "Historic Protection", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64592 }, ["description"] = "The outsiders have disrupted the sands. We cannot reach the terraforming records we need in order to collect necessary historical information. Will you assist us? Help Mai Obet collect historical records in the Endless Sands.", ["objectivesText"] = "Help Mai Obet examine 6 Terraforming Records in the Endless Sands.", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190341, 190342, 190343, 190344, 190347, 190348, 190349, 190350, 190351, 190354, 190355, 190357, 190358, 190359, 190362, 190363, 190365, 190366, 190367, 190370, 190371, 190605, 190633, 190634, 190635, 192423, 192424, 192425, 192427, 192429, 192430, 192440, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
