[64642] = { ["id"] = 64642, ["name"] = "Clearing the Ruins", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64641, 64642, 64643, 64644, 64645, 64646, 64647, 64648 }, ["description"] = "This place was abandoned for too long. The vegetation has overtaken the land. We must enter the Blooming Foundry to fix it. Until then: clear the area. Remove the deviants who have grown twisted over time.", ["objectivesText"] = "Kill 15 creatures within the Untamed Verdure.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187131, 187619 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179900, ["x"] = 0.605, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179900, ["x"] = 0.605, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1290, ["name"] = "Reap What You Sow", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64643] = { ["id"] = 64643, ["name"] = "Scavenging a Solution", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64641, 64642, 64643, 64644, 64645, 64646, 64647, 64648 }, ["description"] = "The Blooming Foundry created this area. It maintains the automa, the creatures, and the plants. The overgrowth is its fault. We need to enter the Foundry to fix this land. This constructor can break through when it is working. Many automa in this area stopped moving long ago. Find usable pieces inside them.", ["objectivesText"] = "Find 8 Automa Internals from Abandoned Automa in the Untamed Verdure. Progress: With your help, we will restore this place to its glory.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187131, 187619 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179923, ["x"] = 0.62, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179923, ["x"] = 0.62, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1290, ["name"] = "Reap What You Sow", ["orderIndex"] = 2, ["flags"] = 0 } } },
