[64706] = { ["id"] = 64706, ["name"] = "A Matter Of Motivation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Giants litter these sands, mortal. But I believe we can revitalize them. The smaller automa that are hiding in the desert can be utilized here. Use my Motivator to rally them to our cause. If we can gather enough, their energy can replenish these defeated behemoths to bolster our forces. Return as many as you can to me, and we will put them to work!", ["objectivesText"] = "Return 6 Motivated Automa to Firim . Progress: Have they been suitably motivated?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 188678, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64710] = { ["id"] = 64710, ["name"] = "Whispering Felflame Crystal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7502, ["storyline"] = { 64710 }, ["description"] = "The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran . Perhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.", ["objectivesText"] = "Bring the Whispering Felflame Crystal to Aridormi in Dalaran , floating above the Broken Isles.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 187611 } },
[64713] = { ["id"] = 64713, ["name"] = "Picking Up the Pieces... Literally", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Orbs help us develop terrain for the Forge. Magic within the orbs draws the devourers. They tear apart the metal to reach it. We must collect the remains. Look for the fragments around the orbs. Bring them to us.", ["objectivesText"] = "Collect 30 Orb Fragments . Progress: Did you find the fragments? We need many pieces.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187615 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180919, ["x"] = 0.366, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180919, ["x"] = 0.366, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64717] = { ["id"] = 64717, ["name"] = "Materials of Creation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64717 }, ["description"] = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. The spheres near the Forge of Afterlives contain trace amounts of materials unique to that location. I have modified my Forge-Tap to harvest those materials. Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges .", ["objectivesText"] = "Collect 10 Eidolic Fragments and 300 Minor Enigmet . Progress: Have you collected what we need?", ["rewardXP"] = 8165, ["rewardItems"] = { 187516, 187527, 187728, 187779, 187782, 187787, 187788, 187789, 187790, 187791, 187908, 188231, 189544, 190062, 190189, 190341, 190342, 190343, 190345, 190346, 190347, 190348, 190350, 190352, 190353, 190354, 190355, 190356, 190357, 190358, 190360, 190361, 190362, 190363, 190364, 190365, 190366, 190367, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192427 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64718] = { ["id"] = 64718, ["name"] = "Keys To Victory", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "The song... incomplete. Harmony is needed. Seek those who scry. Send them to serve the cycle. Mawsworn hold the keys that bind. Take the keys, set them free.", ["objectivesText"] = "Free 6 Automa Scryers from their cells.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64720] = { ["id"] = 64720, ["name"] = "Cleaving A Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Maw Walker! My scouts report that the Mawsworn have dominated two automa Oracles to aid them in battle. These Oracles will most certainly predict our strategy and our ultimate goal, if given the chance. We need to eliminate both Oracles before we enter the Crypts. With them out of the way, the Mawsworn troops won't know what we're doing until we're finished with it. Take Emeni with you. She's eager for battle.", ["objectivesText"] = "Slay Oracle Zoketh and Oracle Voraxxi .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187602, 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180928, ["x"] = 0.56, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180928, ["x"] = 0.56, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64722] = { ["id"] = 64722, ["name"] = "Knocking On Death's Door", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "This is it, mortal. The forces you have assembled should be enough to break through the Mawsworn and reach the Crypts. Getting inside, however, will require more effort. The Mawsworn have barricaded the entrance. Kbato will carry you into battle. Eliminate the Mawsworn, and destroy the devices that power the barrier.", ["objectivesText"] = "Riding Kbato, defeat the Mawsworn forces in the Endless Sands and open the way to the Crypts of the Eternal.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 188008, 188014, 188021, 188030, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64723] = { ["id"] = 64723, ["name"] = "Restoration Project", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 64733, 64879 }, ["description"] = "Without an Arbiter, the very purpose of the Shadowlands has been compromised. Souls flood the Maw with no direction. As Saezurah noted, Zereth Mortis would ordinarily craft a new being to take the Arbiter's place. I suspect the Jailer's forces have disrupted the land to the point where this is no longer possible. It is time to take action ourselves, and bring stability again to the Shadowlands! Speak to Saezurah, and see where we must begin.", ["objectivesText"] = "Speak with Saezurah. Progress: Have you spoken with them?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187602, 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64725] = { ["id"] = 64725, ["name"] = "Unforgivable Intrusion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Darkness spreads dissonance throughout these halls. Mawsworn drain life from the air, and give only suffering in return. This must not be. If the song is to be restored, silence is needed. The Mawsworn must be destroyed.", ["objectivesText"] = "Eliminate 6 Dominated Automa and 3 Darkseer Corrupters . Progress: When the halls are silent, we may proceed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64726] = { ["id"] = 64726, ["name"] = "The Order Of Things", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Essences of ancient souls, tampered with--they bleed from each room. The halls must be restored, the flow of souls redirected. The spheres hold the key. Seal the breaches, restore the flow, then the vessel may be filled.", ["objectivesText"] = "Use $13oa Containment Spheres to seal the breaches. Progress: Seal the breach, restore the flow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 8, ["flags"] = 0 } } },
[64727] = { ["id"] = 64727, ["name"] = "The Infinite Circle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Creation calls--can you hear it? Yet darkness lingers below, taints the ancient melody. To forge anew, peace must be restored. The Walker must walk, and protect. There is much to be done. Lead the way.", ["objectivesText"] = "Escort Saezurah to the center of the Crypts of the Eternal.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64728] = { ["id"] = 64728, ["name"] = "Acquaintances Forgotten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "It is time. The song shall bring life anew. Tell me when you are ready to begin.", ["objectivesText"] = "Complete the Ritual. Progress: The ritual must be completed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 10, ["flags"] = 0 } } },
[64729] = { ["id"] = 64729, ["name"] = "Lifetimes To Consider", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 65238, 65329 }, ["description"] = "This song has been completed, and harmony has been restored. Yet Zereth Mortis remains haunted by discord. Dissonance lingers still, outside these walls. We must leave before it finds us. Speak with the one you call Firim--he will open the way.", ["objectivesText"] = "Return to Exile's Hollow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475, 190980, 190981, 190982, 190986, 190987, 190988, 190992, 190993, 190994, 190998, 190999, 191000 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 13, ["flags"] = 0 } } },
[64730] = { ["id"] = 64730, ["name"] = "The Turning Point", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "A pause, devoid of breath. A melody lingers on. The cycle awaits a voice. <You are unsure of what Saezurah means. Perhaps you should try to set up the ritual again, starting with the Vessel and the scryers.>", ["objectivesText"] = "Examine the Vessel and the Automa Scryers. Progress: Have you tried everything?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 30372, 30373, 30374, 30375, 30859, 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180915, ["x"] = 0.565, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 11, ["flags"] = 0 } } },
[64731] = { ["id"] = 64731, ["name"] = "For Every Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Without the Arbiter to stem the flow of souls to the Maw, the Shadowlands will never be fully repaired. This cannot be the end. Surely you can think of something?", ["objectivesText"] = "Find a way to create a new Arbiter. Progress: This moment is of great importance.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180915, ["x"] = 0.565, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 12, ["flags"] = 0 } } },
[64733] = { ["id"] = 64733, ["name"] = "Help From Beyond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 64723, 64879 }, ["description"] = "If we stand any chance of breaking through the Mawsworn forces, we will need the help of all of the covenants. I will speak with the Kyrian. You and Pelagos can speak with the others. But before you go, ask Firim if there is any way we can gain the support of the Enlightened as well.", ["objectivesText"] = "Speak with representatives from the Enlightened, Venthyr, Necrolord, and Night Fae.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180914, ["x"] = 0.566, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.343, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64739] = { ["id"] = 64739, ["name"] = "Zovaal's Grasp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "I remember this metal. I saw it when I was touched by Maw magic. When I was severed... I will show you where this happened. Follow me. I will tell you my story.", ["objectivesText"] = "Follow Hanoa the Exile and listen to her story.", ["rewardGold"] = 64350, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184469, ["x"] = 0.4094, ["y"] = 0.3284 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180989, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.4094, ["y"] = 0.3284 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64745] = { ["id"] = 64745, ["name"] = "Selfless Preservation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The automa were once abundant here, singing, constructing various things, carrying out the purpose of the First Ones. Then, invaders from the Maw slaughtered them all. The last automa to fall were protecting something important in a nearby structure. I witnessed one of the cursed Mawsworn steal a device by the door. The Elders say we should not meddle with artifacts, but would it be a transgression to recover what was stolen?", ["objectivesText"] = "Recover the Stolen Artifact in the Arrangement Index and restore it to its rightful place.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64759] = { ["id"] = 64759, ["name"] = "Junk's Not Dead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "This automa has been hiding here! I suspect it will not be receptive to our help. I am hesitant to suggest this, but if the servitor were to associate you with this facility, it might be more amenable. If you have the means, copy the glyphs inscribed on similar automa outside. Those that the Maw have touched will be tainted, but I saw from my vantage point a few fallen automa in the sands with untarnished glyphs.", ["objectivesText"] = "Obtain glyphs from 6 Depleted Servitors around the Arrangement Index.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64761] = { ["id"] = 64761, ["name"] = "Core Competency", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The poor thing. The sacred should not be disturbed, but... will the elders judge us if we help it survive? This is preservation, not interference. ...I hope. We can power it back up. Use this depleted core as a conduit. Perhaps the larger wild animates in the nearby sands have enough energy to charge it.", ["objectivesText"] = "Charge a Depleted Automa Core by draining slain wild creatures in the Arrangement Index.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64762] = { ["id"] = 64762, ["name"] = "Revival of the Fittest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "This core is brimming with energy! Use the charged core to revive the automa. Hopefully, it will no longer see us as a threat. Do be careful. The power of the First Ones is not meant for us to control.", ["objectivesText"] = "Revive the Hidden Servitor in the Arrangement Index.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64763] = { ["id"] = 64763, ["name"] = "Maintenance Mode", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The architect set forth these tasks: Stay safe. Restore the Protoform Repository when danger passes. The mortal knows the cyphers. The mortal will help with the tasks. Attuning of the energy terminals is required. Each terminal requires a codex. Invaders pilfered the necessary codices. Go.", ["objectivesText"] = "Attune 4 Energy Terminals in the Arrangement Index.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.6624, ["y"] = 0.3236 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64766] = { ["id"] = 64766, ["name"] = "Access Request", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The architect alone possesses the Restoration Matrix required for the restoration. The architect will restore the Protoform Repository. The mortal will gain access to the Chamber of Shaping and inform the architect of recent progress. The architect will restore the repository. Fulfillment of the task is imminent.", ["objectivesText"] = "Find the Proto Architect in the Chamber of Shaping and retrieve a Restoration Matrix . Progress: The architect will assist us.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189460, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.6624, ["y"] = 0.3236 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64767] = { ["id"] = 64767, ["name"] = "The Final Song", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "Servitors do not possess the strength to restore the repositories. Nevertheless, the task must be completed. The mortal must stay close to protect the restoration process. Come.", ["objectivesText"] = "Stay near Kodah while keeping enemies away to capture the Protoform Repository.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.6624, ["y"] = 0.3236 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64772] = { ["id"] = 64772, ["name"] = "Broken Circle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["series"] = { 64775 }, ["description"] = "The jiro of Circle Olea work here. We make... <The jiro pauses for a moment.> They... make new lands and creatures for the Forge. Devourers attacked, but some jiro still survive. You must find them. Tell them to gather outside the cave to the north. I will clear the way. Do not tell them I sent you. They will not want to see me.", ["objectivesText"] = "Find any surviving jiro and convince them to meet outside the cave.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187804, 187824, 188793, 189980, 189986, 190333, 191039 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181091, ["x"] = 0.4, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180984, ["x"] = 0.395, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64773] = { ["id"] = 64773, ["name"] = "A Jiro Guide to Not Being Eaten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Devourers attacked. They overran the guardians. They still search for food. We are not safe. Reduce the devourers' numbers. This is how not to be eaten.", ["objectivesText"] = "Reduce the devourer presence at the Terrace of Formation. Progress: Is it safe? There are so many devourers...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181098, ["x"] = 0.38, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181098, ["x"] = 0.38, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64775] = { ["id"] = 64775, ["name"] = "Mawdified Behavior", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["series"] = { 64772 }, ["description"] = "There is a devourer in the cave. It creates a rift. This should not be possible in Zereth Mortis . Enter the cave and destroy the devourer. Search for clues. See how it can open a rift. Be careful. This one is different from others. It has absorbed the magic of the First Ones. This has never happened before. Be ready for anything. I will stay here and protect the jiro.", ["objectivesText"] = "Kill the Unraveller and search it for clues. Progress: Is the devourer destroyed? Did you find any clues?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 189493 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180984, ["x"] = 0.395, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184469, ["x"] = 0.4094, ["y"] = 0.3284 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64778] = { ["id"] = 64778, ["name"] = "Rift Recon", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Devourers are a problem. Rifts are a bigger problem. They will keep bringing devourers. We must close them. To do this, we need information. Take the crescendal. Use it to analyze the rifts. Bring the information back to us.", ["objectivesText"] = "Analyze 6 Warped Rifts. Progress: Do not break the crescendal. It can be... difficult to use.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181170, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181170, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64779] = { ["id"] = 64779, ["name"] = "Pound of Flesh", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Automa remove threats to us. But there are no more automa. We must help ourselves. We need magic. Devourers ate the orb magic. Now they are warped and twisted. But also full of magic. Bring us devourer flesh. We will extract the magic. We will need it to defeat the devourers.", ["objectivesText"] = "Collect 30 Warped Flesh from devourers at Zovaal's Grasp. Progress: Devourers were not meant to eat this magic.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187950 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181174, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181174, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64780] = { ["id"] = 64780, ["name"] = "Mawsteel, Maw Problems", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Zereth Mortis is sacred. Rifts should not form here. Something creates them. The metal you found has Maw magic. Devourers use it to make rifts. This is how they skirt our protections. Mawsteel shards are strewn across the area. Take these shards. Throw them off our cliffs. Make sure devourers do not use them to create rifts.", ["objectivesText"] = "Lift 4 Mawsteel Shards and throw them off the cliffs.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181177, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181177, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 8, ["flags"] = 0 } } },
[64783] = { ["id"] = 64783, ["name"] = "Dance Dance Darkmoon", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 8, ["zoneID"] = 5861, ["storyline"] = { 64783 }, ["description"] = "Simon says, \"Are you ready to dance?\" Step on in and show off your sweet moves, <class>. The rules are simple. Your opponent will perform a series of stylish moves, then you gotta match 'em. Earn enough accolades and then come back to ol' Simon. Just know that the more challenging the opponent, the more accolades you can earn. Simon says, \"Are you up for the challenge?\"", ["objectivesText"] = "Earn accolades by competing in the dance competition. Progress: Simon says, \"Show me what you got.\"", ["rewardItems"] = { 93724, 187689 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[64785] = { ["id"] = 64785, ["name"] = "Overgrown Story", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64785 }, ["description"] = "Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose. There could be valuable research data to be obtained from these creatures. Use a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.", ["objectivesText"] = "Gaiagantic and 12 Geomentals examined for research data. Progress: Have you completed the research?", ["rewardXP"] = 8165, ["rewardItems"] = { 187684, 187700, 187908, 187909, 189544, 190189, 190341, 190344, 190345, 190348, 190349, 190351, 190352, 190355, 190359, 190360, 190363, 190367, 190368, 190371, 190605, 190632, 190633, 190634, 190635, 192424 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64794] = { ["id"] = 64794, ["name"] = "Knowing is Half the Battle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "<name>, you should join Shandris and infiltrate the Mawsworn forces from the east. Whatever information you two uncover will inform us of your next course of action. Take care. We have no information on what you may find.", ["objectivesText"] = "Meet Shandris near the Provis Strata.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181180, ["x"] = 0.485, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 16, ["flags"] = 0 } } },
[64796] = { ["id"] = 64796, ["name"] = "Scour the Sands", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "The little I have seen so far has given me almost no information about our enemies. We will have to take a closer look. I can hide the both of us from sight on your command. But stay away from the dreadlords--their eyes are sharp enough to spy even a hidden huntress.", ["objectivesText"] = "Scout Provis Strata with Shandris Feathermoon . Progress: The less attention we draw, the better.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181180, ["x"] = 0.485, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 17, ["flags"] = 0 } } },
[64797] = { ["id"] = 64797, ["name"] = "Harmony and Discord", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "These obelisks must be key to Zovaal's plans. Even without full knowledge of their purpose, we should stop the Mawsworn from meddling with them. I will bring this information to Highlord Bolvar. Head to Darion Mograine and do the same. He will need to plan his defenses around this.", ["objectivesText"] = "Speak with Darion Mograine at Provis Terra.", ["rewardGold"] = 128700, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 188024, 188032, 188036, 188037, 190975 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 18, ["flags"] = 0 } } },
[64798] = { ["id"] = 64798, ["name"] = "What We Overcome", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64812, 64813, 65259 }, ["description"] = "I understand now. All of us that were touched by Domination were able to tap into something. Whether nobility or vengeance, it gave the strength to resist. With all that I have faced, I have to remember that I am still here. And if there are those willing to stand with Sylvanas, I have to believe they will stand with me as well. I'm ready to try again. This time, I will overcome whatever I face.", ["objectivesText"] = "Defeat the Mawbound Monstrosity and infuse the final shard. Progress: We will not fail. There is no other choice but oblivion.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187785, 188009, 188015, 188020, 188027, 190953 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181284, ["x"] = 0.592, ["y"] = 0.884 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 14, ["flags"] = 0 } } },
[64799] = { ["id"] = 64799, ["name"] = "The Broken Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64800 }, ["description"] = "Our friends have returned from the Sepulcher of the First Ones with a familiar face. Anduin... What terrible things he has endured. But as difficult and painful as it is, we must uncover what he knows. The Jailer has blocked our way within the Sepulcher, and we risk falling victim to Domination ourselves if we blindly follow. He is our best hope.", ["objectivesText"] = "Speak to Anduin Wrynn in the Geometric Cavern. Progress: We must defeat Zovaal, or all is lost.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64800] = { ["id"] = 64800, ["name"] = "Our Last Option", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64799 }, ["description"] = "Zovaal has blocked our pursuit. If we are to defeat him, we must find a way to withstand Domination. But to overcome it, we need to understand how it works. The Primus of Maldraxxus created Domination, he will be able to tell us more. I asked Taelia to bring a piece of the Helm of Domination to Zereth Mortis. I dread to think of what might happen were I to try to carry it again... Let us discuss the way forward.", ["objectivesText"] = "Listen to the plan. Progress: We can never turn things back to the time that was. We can only live with the choices made, and move forward.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64801] = { ["id"] = 64801, ["name"] = "Elder Eru", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "Since we have earned the trust of the Enlightened, I have learned more about their explorations into Zereth Mortis . They know more than they are willing to tell, but often do not act on that knowledge. Perhaps where they observe, we can be a catalyst for action. In a secluded corner called the Lexical Glade, there is an elder named Eru. She may be able to give us insight on how we might use the language of the First Ones. Seek her out, and see if she will help us.", ["objectivesText"] = "Find Elder Eru outside the Lexical Glade.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181266, ["x"] = 0.562, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64802] = { ["id"] = 64802, ["name"] = "Hello, Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "I created Domination as a tool to punish Zovaal. My anger informed that creation, and now we pay the price for my hubris. Even Eternal Ones err on occasion. But we are not without hope. Take the half of the broken Helm of Domination, and test it upon one of your own. If it retains enough power, it can then be used to test it elsewhere in Zereth Mortis .", ["objectivesText"] = "Test the broken Helm of Domination on Darion Mograine. Progress: We will not give up until we have stopped Zovaal.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181245, ["x"] = 0.332, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181245, ["x"] = 0.332, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64804] = { ["id"] = 64804, ["name"] = "Cryptic Catalogue", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64803, 64805, 64853 }, ["description"] = "This area is a repository of various texts. Hmmm? What do they say? I have no idea! I have dedicated myself to their catalogue and organization. This is more important than ever, with invaders destroying the balance in Zereth Mortis ! We must preserve what we have found so far. You can help. Go into the glade and memorize the phrases there, then meet me down in the grotto. There is something in it that might help you test that helm of yours further.", ["objectivesText"] = "Memorize Phrases in the Lexical Glade. Progress: Think how much we could learn if we understood the intentions of the First Ones.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181266, ["x"] = 0.562, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64805] = { ["id"] = 64805, ["name"] = "The Not-Scientific Method", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64803, 64804, 64853 }, ["description"] = "The language of the First Ones is not static like most others. It evolves. Creatures like the sentries are more advanced than your average poultrid, obviously. Their more complex thought processes give them an innate resistance to the invaders' overriding magic. But you should not take my word for it. We can actually test this! In the grotto there is a librarian. Take those phrases you memorized and infuse them into it. Then try out your helm.", ["objectivesText"] = "Test the Broken Helm on an activated Lexicon Librarian and observe the results.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64806] = { ["id"] = 64806, ["name"] = "Where the Memory Resides", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "I think I know what will be asked of us in Bastion . It will not be easy. With this half of the Helm, we have collected the first part of what is needed to resist Domination. But there are those of us who have also suffered from it. Lived through it. In a way, it has marked us. All of us. There must be something in those experiences that will help us break free from Zovaal's influence. Let us go to the Chamber of First Reflection in Bastion .", ["objectivesText"] = "Meet Highlord Bolvar inside the Chamber of First Reflection in Bastion .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 172924, 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1533, 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 11, ["flags"] = 0 } } },
[64807] = { ["id"] = 64807, ["name"] = "What We Wish to Forget", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "While the language of the Progenitors will aid us, there is another trait that will help break Domination's hold on us. An indomitable will. Those of us who have endured before, and survived, have that inherent resistance, which we will offer up to be infused into each of the shards. The Primus has assured me that this will work. With no other options, this is the only way. I trust that it will be worth the suffering.", ["objectivesText"] = "Assist with the ritual and infuse the Shards of Domination . Progress: We will do whatever it takes.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.881 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 12, ["flags"] = 0 } } },
[64808] = { ["id"] = 64808, ["name"] = "What Makes Us Strong", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "I wish that I knew of this place sooner. Where terrible darkness could be purged from oneself, memories examined and expunged... I am willing to do whatever it takes to help defeat Zovaal, no matter the cost. This is the only way.", ["objectivesText"] = "Assist with the ritual and infuse the Shards of Domination . Progress: It takes more than raw strength to do what must be done.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181284, ["x"] = 0.592, ["y"] = 0.884 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181284, ["x"] = 0.592, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 13, ["flags"] = 0 } } },
[64809] = { ["id"] = 64809, ["name"] = "One Half of the Equation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64810 }, ["description"] = "The Primus's theory about the language of the First Ones has borne out. Still, it may not be enough. While the Primus finalizes his plans, let us go deep into the Endless Sands to find pieces of this power to infuse the helm. Darion, Taelia, and I will meet you there to help with the Mawsworn.", ["objectivesText"] = "Travel to the Deserted Overlook.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 8, ["flags"] = 0 } } },
[64810] = { ["id"] = 64810, ["name"] = "Oppress and Destroy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64809 }, ["description"] = "What we seek is in the vaults of the Endless Sands. To reach them will require strength and numbers. Together we will destroy the Mawsworn. I look forward to taking the fight directly to them. Remember, they will be vulnerable to the broken shard from the Helm of Domination.", ["objectivesText"] = "Slay Mawsworn in the Endless Sands. Progress: Such magnificent desolation.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178061, 187785, 188957, 189161, 189459, 189704, 190197, 190198 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 9, ["flags"] = 0 } } },
[64811] = { ["id"] = 64811, ["name"] = "Aggressive Excavation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "Elder Eru said that we could find the most complex examples of the First Ones' language out here. We'll need to fight our way to the vaults, and then infuse the helm once we find those phrases. On a personal note, I never thought I'd have the chance to fight alongside my father. Though with the stakes this high, it somehow feels like exactly the place I'm supposed to be. I am ready when you are.", ["objectivesText"] = "Collect the Inscrutible Phrases.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187785, 190980, 190981, 190982, 190986, 190987, 190988, 190992, 190993, 190994, 190998, 190999, 191000 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181372, ["x"] = 0.572, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 10, ["flags"] = 0 } } },
[64812] = { ["id"] = 64812, ["name"] = "Forge of Domination", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64798, 64813, 65259 }, ["description"] = "We have all of the pieces we need. The broken half of the helm has been augmented with the complexity of the language of the First Ones, and the shards bear our memories. Our will to resist Domination. All that remains is for the Primus to reforge the Helm, then we will be able to draw upon that combined power for ourselves. I know that it is dangerous, but it is our only hope.", ["objectivesText"] = "Travel to The Runecarver's Oubliette in Torghast.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.881 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1912, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 15, ["flags"] = 0 } } },
[64813] = { ["id"] = 64813, ["name"] = "The Crown of Wills", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1912, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64798, 64812, 65259 }, ["description"] = "When I created Domination, I did not foresee how much pain it would cause the realms. Not only the Shadowlands, but yours as well. It is time we take this helm, this symbol of that magic, and reforge it anew. But, not for the same purpose it once had. Let it represent the strength of will that you and your kind possess, so that it may help us overcome and defeat Zovaal at last.", ["objectivesText"] = "Reforge the Helm of Domination. Progress: There is no going back.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 187785 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1912, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 16, ["flags"] = 0 } } },
[64814] = { ["id"] = 64814, ["name"] = "Battle for the Forge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "Our forces have been holding out so far, but we have not secured the area. We could use some assistance cutting down the enemy's numbers. This should be a simple task for you, Maw Walker.", ["objectivesText"] = "Kill 8 Mawsworn forces. Progress: Is it done?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 19, ["flags"] = 0 } } },
[64815] = { ["id"] = 64815, ["name"] = "Together, We Ride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "The four covenants are working together here along with the automa. Unfortunately, some of our soldiers have been separated or wounded and are unable to return back here. If you could aid them, that would help tremendously.", ["objectivesText"] = "Aid 5 covenant forces.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We 