[64816] = { ["id"] = 64816, ["name"] = "Reality's Doorstep", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64816 }, ["description"] = "The time has come to follow Zovaal into the very heart of the Shadowlands. We must return to Zereth Mortis and finish this.", ["objectivesText"] = "Return to Zereth Mortis .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[64817] = { ["id"] = 64817, ["name"] = "In Plain Sight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "That sound! It came from the direction of the obelisk at Provis Flora. Impossible. We've let no one through. Hurry, <name>. Follow me!", ["objectivesText"] = "Defend the obelisk at Provis Flora. Progress: We must hurry!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 114732, 114733, 114734, 114735, 187839, 190975, 237812 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183615, ["x"] = 0.4144, ["y"] = 0.5316 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onwa