[64825] = { ["id"] = 64825, ["name"] = "Seeking Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "I am at a loss. We have no way to follow Zovaal and Anduin. I'll open a portal back to Haven. We will discuss our next steps there.", ["objectivesText"] = "Return to Haven with Jaina and Baine.", ["rewardGold"] = 257400, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 190742, 190745, 190748, 190751, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183717, ["x"] = 0.573, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.573, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 28, ["flags"] = 0 } } },
[64829] = { ["id"] = 64829, ["name"] = "Finding Tahli", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "After eons of tranquility, the Maw's influence has brought sorrow to Zereth Mortis . One of our acolytes, Tahli , has found it particularly difficult to process recent events. She left some time ago and has not returned. Will you check on her? She was last seen heading toward the ruins that are buried under the sands.", ["objectivesText"] = "Find Tahli near the Arrangement Index.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64830] = { ["id"] = 64830, ["name"] = "Enlisting the Enlightened", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "The fate of Sylvanas is not my immediate priority. The Jailer has destroyed the Harmonic Channels, ensuring that we cannot follow him. Perhaps the studious Enlightened Brokers know something about these channels that will help us--but broker cooperation comes often with strings attached. Do whatever they demand. We must learn more.", ["objectivesText"] = "Persuade the Elders of Haven to offer their assistance.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184532, ["x"] = 0.348, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64831] = { ["id"] = 64831, ["name"] = "Remnants of the First Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "Some evidence of the Mawsworn's destruction may remain in Provis Esper. Recovering that evidence will provide some clue as to how to follow this Jailer. Let us hunt together. I will know the sign of the First Ones's magic when we are in its vicinity.", ["objectivesText"] = "Collect 3 Conduction Remnants . Progress: Have we found all of the remnants?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183139, ["x"] = 0.562, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183168, ["x"] = 0.534444, ["y"] = 0.548222 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64832] = { ["id"] = 64832, ["name"] = "Reclaiming Provis Esper", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "Provis Esper is overrun with devourers, buzzing around like hungry vespoids. They are destroying the local automa, which is not at all what the First Ones intended. A cleansing is in order. For our safety and to restore the natural order, clear some of them out.", ["objectivesText"] = "Kill 20 Insatiable Mites , 5 Soul-Parched Gorgers , and 2 Reality Breachers . Progress: Have you cleansed Provis Esper?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183139, ["x"] = 0.562, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183168, ["x"] = 0.534444, ["y"] = 0.548222 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64833] = { ["id"] = 64833, ["name"] = "Forging Unity from Diversity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "The other Elders follow a strict interpretation of how best to honor the works of the First Ones. I am not so inflexible. Our end goal is the same. Let us return to the area where you last saw the Jailer.", ["objectivesText"] = "Meet Elder Ara above Provis Esper.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184532, ["x"] = 0.348, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183139, ["x"] = 0.562, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64834] = { ["id"] = 64834, ["name"] = "Glow and Behold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "Look, <name>. The remnants are faintly glowing! They must be reacting to something in Pilgrim's Grace. Find out what is causing this reaction!", ["objectivesText"] = "Locate what is causing the Conduction Remnants to react. Progress: The remnants reacted to this translocator? Incredible!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183251, ["x"] = 0.612, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183252, ["x"] = 0.646, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64835] = { ["id"] = 64835, ["name"] = "Pluck from the Vines", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "I ran, scrambling through the thorny foliage, the lashers snapping at my heels. My fellow pilgrims were not so lucky. I could hear their screams of pain and horror as I fled. You must find a way inside. Rescue them, <name>!", ["objectivesText"] = "Rescue 5 missing pilgrims. Progress: Have you rescued the missing pilgrims?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181771, ["x"] = 0.48, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184323, ["x"] = 0.476, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 9, ["flags"] = 0 } } },
[64836] = { ["id"] = 64836, ["name"] = "Nip It in the Bud", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "The Catalyst Wards used to be peaceful. Pilgrims have been coming here for ages to observe the wonders of the First Ones. But this place is no longer safe. The Cultivator showed no mercy and no reason as it slew several of our brethren. You must destroy it. Other Elders would disagree with me. The other Elders are wrong.", ["objectivesText"] = "Kill the Cultivator . Progress: What could have caused the Cultivator to behave so irrationally... so violently?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183338, ["x"] = 0.48, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183338, ["x"] = 0.48, ["y"] = 0.75 }, { ["mapID"] = 1970, ["npcID"] = 183359, ["x"] = 0.476, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 10, ["flags"] = 0 } } },
[64837] = { ["id"] = 64837, ["name"] = "The Pilgrim's Journey", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "Pilgrim's Grace is a sacred site for the Enlightened. The Elders there have an intimate understanding of the creations of the First Ones. We will find answers there about these strange remnants we have found. Meet me at Pilgrim's Grace. It is not far.", ["objectivesText"] = "Meet Elder Ara at Pilgrim's Grace.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183168, ["x"] = 0.534444, ["y"] = 0.548222 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183251, ["x"] = 0.612, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.534444, ["y"] = 0.548222 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64838] = { ["id"] = 64838, ["name"] = "Where There's a Pilgrim, There's a Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "If the remnants can be restored, someone in Pilgrim's Grace may know how. Begin with Elder Nirav. I hope he is willing to help. He seems anxious and distracted today. Find me in town when you are done.", ["objectivesText"] = "Speak to the inhabitants of Pilgrim's Grace. Progress: Have you spoken to the Enlightened in Pilgrim's Grace?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183252, ["x"] = 0.646, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183530, ["x"] = 0.622, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64839] = { ["id"] = 64839, ["name"] = "Root of the Problem", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "I suspect we can harness the growth energy present in these plants for our own purposes, but I will need fresh samples. You can harvest energized plant matter from any of the lashers or vine-choked automa nearby, or those inside the Catalyst Wards.", ["objectivesText"] = "Collect energized plant matter. Progress: Have you recovered the energized plant matter?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 84075, 84076, 84077, 84078, 84079, 187730, 187731, 187732, 187835, 188276, 211279 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181771, ["x"] = 0.48, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181771, ["x"] = 0.48, ["y"] = 0.75 }, { ["mapID"] = 1970, ["npcID"] = 184323, ["x"] = 0.476, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 11, ["flags"] = 0 } } },
[64840] = { ["id"] = 64840, ["name"] = "Unchecked Growth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "This growth energy is highly unusual. I would like to know more about how it affects the local automa. Harvest replicating essence from deceased automa in the Catalyst Gardens. Bring it back to me for study.", ["objectivesText"] = "Collect 12 Replicating Essence . Progress: Do you have the replicating essence ?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184323, ["x"] = 0.476, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184323, ["x"] = 0.476, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 12, ["flags"] = 0 } } },
[64841] = { ["id"] = 64841, ["name"] = "Take Charge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "That floating structure looming overhead is the Creation Catalyst. I cannot get close to it. The tower is overloaded with an excess of Progenitor energy. To travel there now would be suicide. There are consoles in the gardens that can be used to discharge that energy. Do so.", ["objectivesText"] = "Discharge the excess energy of the Creation Catalyst. Progress: Is it safe to fly up to the Creation Catalyst?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181814, ["x"] = 0.475, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181814, ["x"] = 0.475, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 13, ["flags"] = 0 } } },
[64842] = { ["id"] = 64842, ["name"] = "Flora Frenzy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "Those guardian automa will shoot down anything that attempts to reach the Creation Catalyst. May I suggest fighting fire with fire? Or rather, fighting the creations of the First Ones with the creation energy of the First Ones? I have had little time to adequately test my theory, but this potion should provide the boost you need to destroy them... ideally without dying from exposure to the creation energy in the process.", ["objectivesText"] = "Drink Feroz 's solution and destroy the automa of the Catalyst Gardens. Progress: Your safety is probable, but not guaranteed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276, 189560, 189722, 189723, 189724, 189725, 189726, 189727, 189728, 189729, 189730, 189731, 189732, 189733, 189734, 189735, 189742, 189760, 189761, 189762, 189763, 189764, 190977, 190978, 190979, 190983, 190984, 190985, 190989, 190990, 190991, 190995, 190996, 190997 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184442, ["x"] = 0.476, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184442, ["x"] = 0.476, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["que