[64843] = { ["id"] = 64843, ["name"] = "Key Crafting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "With those agitated automa quelled, there is but one task ahead. We shall ferry you and your Enlightened companion up to the Creation Catalyst. The rest is up to you.", ["objectivesText"] = "Restore the Translocator Key at the Creation Catalyst. Progress: It is incredible to see the Creation Catalyst up close.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181814, ["x"] = 0.475, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184153, ["x"] = 0.474, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 16, ["flags"] = 0 } } },
[64844] = { ["id"] = 64844, ["name"] = "The Pilgrimage Ends", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "You have rescued many pilgrims, and I have restored your entrance to the Sepulcher. With that, our bargain is concluded--and so, too, is my pilgrimage. But your journey continues. Return to the overlook behind Pilgrim's Grace and open the translocator. My thanks, <name>. This adventure has been... enlightening.", ["objectivesText"] = "Return to the overlook behind Pilgrim's Grace. Progress: Let us listen to what they have to say.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188010, 188016, 188023, 188028, 188276 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184153, ["x"] = 0.474, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181948, ["x"] = 0.646, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 17, ["flags"] = 0 } } },
[64846] = { ["id"] = 64846, ["name"] = "Torghast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64846 }, ["description"] = "Countless souls are tortured in the halls of Torghast. They need your help!", ["objectivesText"] = "Speak with Tal-Inara .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 176 },
[64849] = { ["id"] = 64849, ["name"] = "Tower of the Damned", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64849 }, ["series"] = { 64850, 65035 }, ["description"] = "We know little of Torghast. However, Fatescribe Roh-Tahl claims there is work that must be done there. He believes there is a path for you to reach this place... and that someone there requires your aid. Do what you must to reach Torghast and aid anyone who is within.", ["objectivesText"] = "Travel to Torghast by jumping into the Ring of Transference, then find any entity there that needs your aid.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[64850] = { ["id"] = 64850, ["name"] = "Traversing Torghast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13400, ["mapID"] = 1911, ["storyline"] = { 64850 }, ["series"] = { 64849, 65035 }, ["description"] = "I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish . I am here to find great treasures within Torghast with the aid of my box. I can see you admiring it. Perhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead? I shall even reward you for anything you discover within.", ["objectivesText"] = "Aid Ve'nish 's exploration of Torghast by completing a wing within Torghast. Use the wayfinder within Torghast to access different wings. Progress: How goes exploring the darkness of Torghast?", ["rewardGold"] = 52350, ["rewardXP"] = 13630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1911 },
