[64853] = { ["id"] = 64853, ["name"] = "Two Paths to Tread", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64803, 64804, 64805 }, ["description"] = "Did that answer your question? Oh, you wanted a way to completely resist Domination magic? That I'm afraid I do not know. The First Ones' language will only delay the inevitable. What I can tell you is that if you want to find more deliciously complex phrases of the First Ones' language, you should go to the Endless Sands and search the vaults. I wish I could go myself, but it has been overrun by those nasty Mawsworn. Good luck with the rest of your studies!", ["objectivesText"] = "Report to the Primus in the Geometric Cavern.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181245, ["x"] = 0.332, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64854] = { ["id"] = 64854, ["name"] = "Trappings of Success", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64854 }, ["description"] = "The wildlife of Zereth Mortis are attracted to the frenetic creation energy that flows throughout the land. When the wildlife finds something charged with that energy... they eat it! The Mawsworn Cryptoseers have become aware of this and are attempting to find such wildlife to extract any remnants of that energy. Eliminate the Cryptoseers, and use the Containment Trap to subdue and examine the wildlife for our research.", ["objectivesText"] = "Slay 5 Mawsworn Cryptoseers and examine the wildlife listed. Progress: You have collected data before the Cryptoseers?", ["rewardXP"] = 8165, ["rewardItems"] = { 187684, 189544, 190189, 190341, 190345, 190346, 190347, 190348, 190349, 190351, 190352, 190353, 190354, 190355, 190359, 190360, 190361, 190362, 190363, 190368, 190369, 190370, 190371, 190605, 190634, 190635, 192422, 192423, 192424, 192425, 192428, 192429, 192430, 192440, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
