[64875] = { ["id"] = 64875, ["name"] = "Something Wonderful", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "<name>, I am so glad you are here! Firim sent me to find you. It's the oracle, it... well... it's hard to describe. You should come see it for yourself. Hurry!", ["objectivesText"] = "Travel to Exile's Hollow to witness for yourself what is happening to Saezurah. Progress: We must hurry, <name>. We do not know how long this will last.", ["rewardGold"] = 64350, ["rewardXP"] = 2040, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182556, ["x"] = 0.354, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64876] = { ["id"] = 64876, ["name"] = "Music of the Spheres", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "It started gradually, the energy emanating from the oracle in increasing amounts, until the grand design you see before you took shape. The terrible clamor ringing in our ears began shortly afterward. My attempts to approach the fractals have been... unsuccessful. But they appear to resonate with Pocopoc. You share a special bond with it; perhaps you shall have better luck than I.", ["objectivesText"] = "Examine the fractals that surround Saezurah's body.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64878] = { ["id"] = 64878, ["name"] = "What a Long Strange Trip", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "<The voice from the vision speaks through Pocopoc , albeit distant and distorted.> I... am Saezurah. Oracle. This automa... speaks with my voice. Acts with my will. For now. The pattern... is torn. Disrupted. Mending must be done. A great hunger swarms the sands. What it seeks must not be consumed. Journey with me. Follow my voice.", ["objectivesText"] = "Go with Pocopoc to make sense of your vision. Progress: Pocopoc has not reached the destination yet.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 190977, 190978, 190979, 190983, 190984, 190985, 190989, 190990, 190991, 190995, 190996, 190997 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.41025, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64879] = { ["id"] = 64879, ["name"] = "A Monumental Discovery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64879 }, ["series"] = { 64723, 64733 }, ["description"] = "Maw Walker--Pelagos stopped by earlier to give a report and said that the oracle's preparations were complete, and you were urgently needed. If this is something that can help our efforts, I want you involved. Head to Exile's Hollow and see what they need.", ["objectivesText"] = "Meet Firim in Exile's Hollow.", ["rewardGold"] = 64350, ["rewardXP"] = 2040, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[64888] = { ["id"] = 64888, ["name"] = "Borrowed Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "The land provides. The land thirsts. Invaders devour what we require. Reclaim what has been consumed. Absorb what remains abundant. Wings need wind to fly. We need power to ascend.", ["objectivesText"] = "Defeat volatile lured enemies or soak power from pools to reclaim Cosmic Energy to empower Pocopoc . Progress: More power to Pocopoc .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.41025, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64889] = { ["id"] = 64889, ["name"] = "Match Made in Zereth Mortis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "The cyphers are the key. Each one, a step along the path. You must find them all. Enter the inner chamber. The Prime Locus Arrangement awaits. The first step toward ascension. Toward the vessel.", ["objectivesText"] = "Study the Locus Arrangements and use the Locus Shift to reach the Ultimus Locus. Progress: Need to gather the cyphers to reach the door where the vessel waits.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 188044, 188045, 188053, 188054, 188055, 188106, 189704, 189863, 190374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64935] = { ["id"] = 64935, ["name"] = "Between a Rock & a Rock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "<Piles of rock are scattered around the area. The devourers have done enough damage to obscure the cypher you seek. Perhaps one of the nearby servitors could be made to clear the rubble.>", ["objectivesText"] = "Smash the rubble barring access to the secundus locus arrangement. Progress: Until we discover the cypher, we need to keep smashing rubble.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64936] = { ["id"] = 64936, ["name"] = "Searching High and Low", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "Three locks upon the door, three keys hidden atop the zenith. Find the phrases. Speak the words. Secure the vessel.", ["objectivesText"] = "Gather the Ingress Phrases on the Ultimus Locus that are needed to claim the Vessel. Progress: The vessel slumbers high above.", ["rewardGold"] = 128700, ["rewardXP"] = 8165, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184949, ["x"] = 0.478, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64937] = { ["id"] = 64937, ["name"] = "You Light Up My Life", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "Great power entices great hunger. The insatiable devourers scale the cliffs in search of sustenance. Soon they will swarm the plateau. They seek to consume all they encounter. The vessel. Its power. Us. This must not come to pass. Wield this automa. Silence their slavering howls.", ["objectivesText"] = "Use Pocopoc to defend the vessel against the devourers.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 188007, 188013, 188022, 188029 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184949, ["x"] = 0.478, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 8, ["flags"] = 0 } } },
[64941] = { ["id"] = 64941, ["name"] = "Chicken Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 64941 }, ["description"] = "<The Chicken Soul is perky and voracious. The shape of the chicken will be yours to call upon.>", ["objectivesText"] = "Bring the Chicken Soul to Choofa in the Heart of the Forest. Provided item:", ["rewardItems"] = { 187813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 187813 } },
[64942] = { ["id"] = 64942, ["name"] = "Call of the Primus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "Though we fought to stop the Jailer in the Sanctum of Domination, we failed. He enveloped Oribos in the Maw, struck down the Arbiter, and opened the way to Zereth Mortis . The time has come to follow him. Within the Arbiter's Chamber, we will forge our own path. Hurry, Maw Walker. The fate of the Shadowlands, and all the realms beyond, is at stake.", ["objectivesText"] = "Speak with Tal-Inara in Oribos to travel to the Arbiter's Chamber.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64945] = { ["id"] = 64945, ["name"] = "Strangers in a Strange Land", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64944, 64947, 65456 }, ["description"] = "Did we... did we reach Zereth Mortis ? And are we walking on water? What a wondrous place! At least, from what I can tell through this fog. I think I can make out a structure in the distance. Perhaps we will find answers there.", ["objectivesText"] = "Accompany Pelagos and explore your surroundings.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181931, ["x"] = 0.278667, ["y"] = 0.559333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.278667, ["y"] = 0.559333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64947] = { ["id"] = 64947, ["name"] = "Give Me A Hand", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64944, 64945, 65456 }, ["description"] = "To drive the Jailer from Zereth Mortis , we must direct all our resources against the enemy. An object of potential power lies in a nearby repository, but the chamber's defenses respond only to automa. I would never harm their kind, but I have encountered one that no longer functions. If you extract its hand, we could use the inert appendage to gain access to the repository. I find such use of the First Ones' creations unsavory, but we cannot abide the presence of Mawsworn in this realm.", ["objectivesText"] = "Assist Firim .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 187845, 187846, 188954, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.5475 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64949] = { ["id"] = 64949, ["name"] = "For Research Purposes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "I have taken pains not to disturb the automa during my time in Zereth Mortis , and so far they have paid little attention to me. It seems recent events have changed that. Again, let me be clear that I have no wish to harm the creations of the First Ones. But if, in the course of your efforts, conflict with the automa becomes inevitable, we must ensure that some good can come of it. If I can examine fragments of fallen automa, it may provide knowledge to use against the Mawsworn. Go carefully.", ["objectivesText"] = "Collect 12 Intact Automa Fragments from Alerted Automa within Genesis Vestibule Progress: Did you find any useful fragments?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64950] = { ["id"] = 64950, ["name"] = "A Mutual Exchange", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64951 }, ["description"] = "It seems the other automa did not appreciate our appropriation of their colleague's hand. They have become hostile. Unfortunate, but we cannot allow this to impede our progress. The automa's hand should activate a console within the Genesis Repository. I believe it holds an object of great potential. After you acquire it, I will guide you to a place that may provide a means to reach the allies you left behind. Do we have an accord?", ["objectivesText"] = "Use the Automa Hand to activate an Automa Console and obtain the Repository Treasure. Progress: Did you acquire the object from the console?", ["rewardGold"] = 257400, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64951] = { ["id"] = 64951, ["name"] = "The Road to Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64950 }, ["description"] = "I did not expect to encounter a living mortal and a kyrian this day, but your assistance has been valuable. Before I begin my studies of this automa core, I will guide you to Haven, the settlement founded by my expedition upon our arrival. Though my colleagues saw fit to exile me for challenging their \"Enlightened\" dogma, I have no wish to see Haven wiped from existence by the Jailer. Aid them and they may assist your efforts to return to your allies. We brokers are nothing if not transactional.", ["objectivesText"] = "Ride with Firim out of the Genesis Repository.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 7, ["flags"] = 0 } } },
[64952] = { ["id"] = 64952, ["name"] = "Destroying the Destructors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "The Mawsworn possess terrible weapons that gather dark magic and hurl it against our gates. The defensive barrier around Haven will not hold much longer. All that we are, all that we hold dear, will soon be erased from existence. If you are who you claim to be, then prove it to us. Destroy the enemy's armaments and help defend our home. I pray to the First Ones that you succeed.", ["objectivesText"] = "Destroy 4 Maw Destructors.", ["rewardGold"] = 128700, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.336667, ["y"] = 0.679333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 9, ["flags"] = 0 } } },
[64953] = { ["id"] = 64953, ["name"] = "Defending Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "The Mawsworn are gathering in force outside our very gates. It is clear they mean to overrun our home! The Enlightened wish only to honor the marvels of the First Ones in peace. Haven's defensive barrier was put in place to shield us from minor threats. We did not imagine the Jailer would send his forces against us. You claim to be our ally, mortal? Then help us defend this sacred land.", ["objectivesText"] = "Defeat 13 Mawsworn in the Great Veldt. Progress: Our pilgrims cannot continue like this.", ["rewardGold"] = 257400, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 10, ["flags"] = 0 } } },
[64957] = { ["id"] = 64957, ["name"] = "This Old Waystone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "The Jailer has withdrawn his forces. I should be relieved, but I fear this means he has found a way into the Sepulcher. < Elder Ara trembles.> Despite Elder Kreth's doubts, you have proven to be an ally. Something we need more of. When our expedition arrived in Zereth Mortis , we discovered a dormant waystone. If you are indeed a Maw Walker, then the prophecies tell us that you will be able to activate it. If your allies can save this sacred place, then the path to them must be opened. Come.", ["objectivesText"] = "Open the Waystone to Oribos.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.336667, ["y"] = 0.679333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 11, ["flags"] = 0 } } },
