[64962] = { ["id"] = 64962, ["name"] = "As Foretold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13753, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "The spheres are in place. A melody builds. Go--bring forth the chorus of Scryers, that the cycle of rebirth may begin.", ["objectivesText"] = "Bring Firim and the Scryers to the center. Progress: The song awaits its chorus.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 9, ["flags"] = 0 } } },
[64963] = { ["id"] = 64963, ["name"] = "A Defector's Request", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64963 }, ["description"] = "<Unrolling the scroll, you can make out that it's a coded arms requisition from the Maldraxxi of Death's End to their venthyr allies... all servants of the Jailer. Surely someone among the Death's Advance in Korthia will be able to help you fully break the code and learn exactly what they were planning.>", ["objectivesText"] = "Deliver the missive to Duchess Mynx in Keeper's Respite in Korthia. Provided item:", ["rewardItems"] = { 187822 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187822 } },
[64964] = { ["id"] = 64964, ["name"] = "Choose Your Fighter", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64964 }, ["description"] = "The presence of the Jailer's forces at Provis Strata have been causing untold damage to the region. If left unchecked, we will lose all knowledge in the area. One of our kin has prepared some automa to deal with the Mawsworn. Meet with them, and fight back against those who would disrespect Zereth Mortis in this manner.", ["objectivesText"] = "Pick an automa construct and use it against the Mawsworn. Progress: Is the task complete?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190342, 190343, 190344, 190345, 190347, 190348, 190350, 190351, 190352, 190353, 190354, 190355, 190356, 190357, 190358, 190360, 190362, 190363, 190364, 190365, 190366, 190368, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192422, 192423, 192424, 192425, 192427, 192428, 192430, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64969] = { ["id"] = 64969, ["name"] = "In the Weeds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "I understand now why Elder Nirav is filled with worry. Many of the pilgrims who have journeyed to the Catalyst Wards have not returned. This includes Feroz, who is most likely to have information we need to restore the remnants. Prepare yourself. The First Ones's newest creations are prevalent at the Catalyst. If something has gone wrong there, it could be tragically dangerous.", ["objectivesText"] = "Meet Elder Ara outside the Catalyst Wards.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 55899, 55900, 55901, 131343, 187730, 187731, 187732, 187835, 188276, 211279 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183530, ["x"] = 0.622, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183338, ["x"] = 0.48, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 8, ["flags"] = 0 } } },
[64970] = { ["id"] = 64970, ["name"] = "Timeworn Keystone: The Broken Isles", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64970 }, ["description"] = "I recently came into possession of a unique keystone. It may look old and worn, but I believe it still has a story to tell. Take it with you. Perhaps it will serve as a reminder of adventures long past. Adventures I hope you will tell me about, of course.", ["objectivesText"] = "Complete a Timeworn Keystone dungeon.", ["rewardItems"] = { 184315 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[64974] = { ["id"] = 64974, ["name"] = "Clean Up, Automa Aisle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64974 }, ["objectivesText"] = "Plain of Actualization cleared", ["rewardItems"] = { 187841 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13536 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Plain of Actualization cleared", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[64977] = { ["id"] = 64977, ["name"] = "Step Into the Ring", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64977 }, ["description"] = "One of the remarkable things we have found about these lands is that they seem to be adaptive and changing, even as ancient as they are. Things are not stationary. In the depths of the Nexus of Actualization there is a forge that appears made to test these various designs, and to learn. These creatures may one day be used to defend Zereth Mortis from threats, so you should test their effectiveness where possible. Go there, challenge what the forge creates and report back to me.", ["objectivesText"] = "Defeat Generated creations in the Nexus of Actualization.", ["rewardItems"] = { 189544, 190189, 190341, 190342, 190343, 190345, 190346, 190347, 190349, 190350, 190351, 190352, 190353, 190354, 190357, 190359, 190360, 190361, 190362, 190365, 190368, 190369, 190370, 190605, 190632, 190633, 190634, 190635, 192422, 192423, 192424, 192428, 192430, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
