[65031] = { ["id"] = 65031, ["name"] = "Battlegrounds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 65031 }, ["description"] = "Champions of the Horde and Alliance continue to fight across countless battlegrounds. The brokers of Cartel Zo are paying combatants in order to observe their tactics. Will you answer the call and join the fray?", ["objectivesText"] = "Speak with Tal-Inara .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardItems"] = { 254677, 268490 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 177 },
[65032] = { ["id"] = 65032, ["name"] = "Battleground Observers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 65032 }, ["series"] = { 65033, 65034 }, ["description"] = "Zo'sorg and the other brokers of Cartel Zo can be found just down the hall. They will certainly be eager to hear that large-scale battles are included in the Purpose.", ["objectivesText"] = "Speak with Strategist Zo'rak in Oribos .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[65033] = { ["id"] = 65033, ["name"] = "Observing Victory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 65033, 65034 }, ["series"] = { 65032, 65034 }, ["description"] = "The threads of fate have called you to the realm of conflict, $p. Will you rise to the challenge issued by your territorial rivals? Will you face them in combat and emerge victorious? If you allow me to observe your victory, I will pay you your worth.", ["objectivesText"] = "Win any Battleground.", ["rewardGold"] = 2059200, ["rewardXP"] = 13630, ["rewardItems"] = { 181417, 181638 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1268, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1268, ["name"] = "Observing Victory", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65034] = { ["id"] = 65034, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 65033, 65034 }, ["series"] = { 65032, 65033 }, ["description"] = "Return tomorrow for another observation. Until then, Tal-Inara will be able to help direct your efforts in a productive manner.", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1268, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1268, ["name"] = "Observing Victory", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65035] = { ["id"] = 65035, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13400, ["mapID"] = 1670, ["storyline"] = { 65035 }, ["series"] = { 64849, 64850 }, ["description"] = "You have been fantastic to work with, Maw Walker. You should bring this information back to whoever sent you here. Me? Oh, I'm staying here with my helpful box. Feel free to come back whenever you want. I may even have more tasks for you to do!", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1269, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1269, ["name"] = "Traversing Torghast", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65064] = { ["id"] = 65064, ["name"] = "Look Who I Found!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Behold this magnificent creature! Siloh says we have no resources for another of my \"abnormal pets.\" But we may be able to alter E'rnee so that I can keep him. Strange interactions occur between creatures and this environment. Perhaps we can make him smaller. I know a spot where we can conduct our research. There are flowers nearby called chromatic rosids that might trigger a reaction. Why don't you collect some on the way?", ["objectivesText"] = "Retrieve 6 Chromatic Rosids near Dimensional Falls. Progress: We must find a way to keep E'rnee.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184486, ["x"] = 0.346, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65066] = { ["id"] = 65066, ["name"] = "Flora Aroma", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Perhaps we should not experiment on E'rnee without first knowing the effects. Hang on to the rest of these rosids. We can run more tests. Some of the creatures here near the waterfall are more tame than others, and will be suitable for such experimentation. Let us discover whether different creatures have diverse responses to the rosid aroma.", ["objectivesText"] = "Experiment with Chromatic Rosids near Dimensional Falls. Progress: Those rosids have such an odd aroma... Perhaps creatures will respond to it in unique ways.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65067] = { ["id"] = 65067, ["name"] = "Broker Beaker", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "I was running some experiments of my own before you got here. Those tests... did not go too well. It turns out some environmental components can aggravate the creatures, turning even the most docile into predators. I dropped my component container and ran, and I cannot recall where I left it. The beaker must be somewhere among the herd of carnivorous cervids. If these flowers do not work, we will need that container for our next round of tests.", ["objectivesText"] = "Retrieve the Component Beaker from Carnivorous Cervids near Dimensional Falls. Progress: Be careful with those carnivorous cervids--they bite!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 2, ["flags"] = 0 } } },
[65068] = { ["id"] = 65068, ["name"] = "Cascades of Magnitude", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Many of the creatures here at Dimensional Falls are particularly affected by the environment. Hmm... let us experiment with the waterfalls themselves! We have seen unique effects from various natural components here in Zereth Mortis . Why not the water as well? Collect some water, then sprinkle it on a creature in the Falls to see what happens.", ["objectivesText"] = "Experiment with waterfall water in Dimensional Falls. Progress: These Falls must contain magic we cannot even comprehend.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 3, ["flags"] = 0 } } },
[65069] = { ["id"] = 65069, ["name"] = "Culling the Maelstrom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Those little E'rnee duplicates were unfriendly. Some effect of the Falls created them. They are not stable. Did you see where they went? They must be culled before they harm the rest of the wildlife. You take care of that while I collect another sample from the Falls.", ["objectivesText"] = "Kill 50 E'rnee Duplicates . Progress: Have you found the duplicates?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 4, ["flags"] = 0 } } },
[65070] = { ["id"] = 65070, ["name"] = "Can I Keep Him?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Oh, no. I have created havoc in this sacred place. Look. E'rnee has bonded with you. It pains me, but you would be a better caretaker for him than I have been. Once we resolve this, you should take him. Now we know, at least, that the Falls have the ability to change the size of creatures. Let us try it again.", ["objectivesText"] = "Throw Water on E'rnee . Progress: If this does not work, we can always try again!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 5, ["flags"] = 0 } } },
[65072] = { ["id"] = 65072, ["name"] = "Not Safe for Work", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65072 }, ["description"] = "Rana's discovery of Progenitor relics at the Ageless Shards has created quite a stir among the Enlightened. These relics predate our earlier discoveries, and through them we may gain a deeper understanding of the workings of Zereth Mortis . Rana is collecting the relics, but I fear she is in danger. Agents of Cartel Xy have been spotted in the area, and will likely attempt to steal the relics. Please travel to the Ageless Shards, and help Rana collect the relics.", ["objectivesText"] = "Assist Rana in her search and collect 8 Progenitor Relics . Progress: Have you collected the Progenitor Relics ?", ["rewardXP"] = 8165, ["rewardItems"] = { 187944, 189544, 190189, 190343, 190345, 190346, 190352, 190353, 190358, 190361, 190366, 190368, 190369, 190370, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192427, 192440, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65080] = { ["id"] = 65080, ["name"] = "Anima, Diverted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 65080 }, ["description"] = "Now, for the moment of truth. Deposit any anima on your person at the Field Anima Diverter behind me. With any luck, you will not experience any side effects - loss of anima, loss of consciousness, loss of memory. That sort of thing.", ["objectivesText"] = "Deposit anima at the Field Anima Diverter in the Reliquary of Remembrance. Progress: Were you able to deposit your anima at the Field Anima Diverter?", ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
