[65090] = { ["id"] = 65090, ["name"] = "Return More Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 65090 }, ["description"] = "Souls still continue to pour into the Maw. Can you venture out again to save more? We must thwart his plans. Return to the Maw and rescue any more that you can.", ["objectivesText"] = "Rescue 20 Souls in the Maw.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[65096] = { ["id"] = 65096, ["name"] = "Your Death Or Mine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65096 }, ["description"] = "We have obtained a wealth of information from relics discovered at the Ageless Shards. The Mawsworn are aware of our discoveries, and are trying to stop us. They have placed traps around the area to block access to the relics. We cannot allow the Jailer to cut off our access to those relics. Please eliminate this Mawsworn threat, and recover as many relics as possible.", ["objectivesText"] = "Slay Punisher Makaris and collect 6 Sacred Relics . Progress: Have you secured the relics at the Ageless Shards?", ["rewardXP"] = 8165, ["rewardItems"] = { 187996, 189544, 190189, 190343, 190346, 190348, 190351, 190353, 190355, 190356, 190358, 190363, 190366, 190368, 190371, 190605, 190632, 190633, 190634, 190635, 192422, 192423, 192424, 192425, 192429, 192430, 192440, 192450 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
