[65103] = { ["id"] = 65103, ["name"] = "Return More Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 65103 }, ["description"] = "Souls still continue to pour into the Maw, we must stay the course and find more worthy souls. Return to the Maw and save all that you can.", ["objectivesText"] = "Rescue 20 Souls from the Maw. Progress: There is no fate worse than the Maw, did you find more?", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[65104] = { ["id"] = 65104, ["name"] = "Return More Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 65104 }, ["description"] = "Maw Walker, we must do more to cut off the Jailer's power and deny him any more souls. Return to the Maw and rescue any more that you can.", ["objectivesText"] = "Rescue 20 Souls in the Maw. Progress: There is no fate worse than the Maw, did you find more?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard" },
