[65353] = { ["id"] = 65353, ["name"] = "An Automa-free Diet", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["description"] = "These devourers are relentless! They feed on any energy they can find. If left unchecked, they would surely devour the whole of Zereth Mortis . We cannot allow the creations of the First Ones to be sullied by these invaders! I am no fighter. But you... perhaps the First Ones delivered you to us after all. Will you help?", ["objectivesText"] = "Kill 10 Invading Gorgers and Reality Breachers .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184537, ["x"] = 0.554, ["y"] = 0.497 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182458, ["x"] = 0.618, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.497 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 2, ["flags"] = 0 } } },
