[65419] = { ["id"] = 65419, ["name"] = "Protoform Synthesis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["storyline"] = { 65419 }, ["description"] = "< Pocopoc jumps around anxiously. When you completed your research into the basics of Dealic, it got very excited and it is urging you to follow it somewhere else in this realm.>", ["objectivesText"] = "Escort Pocopoc to the Protoform Synthesis Forge . Progress: < Pocopoc looks between you and the console excitedly.>", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187633, 187634, 187636, 187638, 187713, 187795, 187803, 187833, 187928, 188957, 189145, 189146, 189147, 189148, 189149, 189151, 189152, 189153, 189154, 189155, 189156, 189157, 189158, 189159, 189160, 189161, 189162, 189163, 189164, 189165, 189166, 189167, 189168, 189169, 189170, 189364, 189367, 189369, 189371, 189375, 189377, 189380, 189381, 189382, 189383 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65420] = { ["id"] = 65420, ["name"] = "Judgment Call", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "Oh no... No no no... What have I done? The elders will never take me back. They shall cast me out as they did Firim. Please, outsider, speak to Elder Amir in Pilgrim's Grace. Give him my thanks for sending you, and tell him all that has happened here. He will understand why I must never return.", ["objectivesText"] = "Speak to Elder Amir in Pilgrim's Grace.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 8, ["flags"] = 0 } } },
[65426] = { ["id"] = 65426, ["name"] = "The Lost Component", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65426, 65427 }, ["description"] = "Maw Walker! Look. We have been studying this automa component for some time. Its cyphers are similar to those of the components near and within the Protoform Repository. Kodah's last effort should not be in vain. Please return this component to the repository that our friend restored.", ["objectivesText"] = "Pick up the Protoform Catalyst and return it to the Protoform Repository. Progress: The mortal seeks protoform synthesis.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1293, ["name"] = "A New Architect", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65427] = { ["id"] = 65427, ["name"] = "A New Architect", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1970, ["storyline"] = { 65426, 65427 }, ["description"] = "The architects prototype designs to fulfill the purposes of the First Ones. This archive contained many such designs. A number of design entries are lost or corrupted due to the Maw invasion. An untouched design lattice and tools are detected nearby. The mortal will retrieve them to begin the synthesis process.", ["objectivesText"] = "Collect 1 Cervid Lattice and 3 Protoform Tools and bring them to the Servitor Interface in the Protoform Repository. Progress: Have the necessary materials been located?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1293, ["name"] = "A New Architect", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65431] = { ["id"] = 65431, ["name"] = "Further Research: Aealic", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65431, 65432, 65433 }, ["description"] = "Maw Walker, you have made some wondrous discoveries, but there are still secrets to uncover. You have taken the first step, in unlocking the console and I believe that you are ready to take another. Please go investigate the console and see what new piece of the pattern unfolds itself to you.", ["objectivesText"] = "Investigate the Cypher Console in Exile's Hollow further. Progress: Go see what secrets await you!", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1288, ["name"] = "Cyphers of the First Ones", ["orderIndex"] = 0, ["flags"] = 0 } } },
