[65445] = { ["id"] = 65445, ["name"] = "Necessary Resourcing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65445 }, ["description"] = "Devourers are consuming neomotes. We need neomotes for necessary creation work. Without them, we are unable to complete our work. Eliminate the devourers and retrieve the neomotes.", ["objectivesText"] = "Obtain 30 Neomote Residue and 3 Solidified Neomotes from Devourers in Zereth Mortis . Progress: Have you collected the neomotes?", ["rewardXP"] = 8165, ["rewardItems"] = { 189535, 189536, 189544, 190189, 190341, 190342, 190343, 190344, 190348, 190349, 190350, 190351, 190354, 190355, 190356, 190357, 190358, 190359, 190363, 190364, 190365, 190366, 190367, 190370, 190371, 190372, 190605, 190632, 190633, 190635, 192422, 192423, 192424, 192428, 192429, 192430, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65448] = { ["id"] = 65448, ["name"] = "A Return to Grace", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13952, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["description"] = "<With the temple restored and its defenses back online, the Wellspring should be safe from the devourers. Conservator Olem will want to know what you've done here.>", ["objectivesText"] = "Speak to Conservator Olem and give him the good news. Progress: You return--and as I expected, you were successful.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 188012, 188018, 188026, 188034 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182146, ["x"] = 0.618, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13952 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 3, ["flags"] = 0 } } },
[65456] = { ["id"] = 65456, ["name"] = "Long Lost Firim", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64944, 64945, 64947 }, ["description"] = "I was gathering data here when your portal opened. The disruption activated these gate-locking mechanisms. It is only fair for you to gather the gate keys, yes? We shall speak while you search.", ["objectivesText"] = "Help Firim open the gate into Zereth Mortis . Progress: And now, onward.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.5475 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 3, ["flags"] = 0 } } },
[65460] = { ["id"] = 65460, ["name"] = "Your First Cantaric Protolock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65460 }, ["description"] = "Maw Walker, it appears that Pocopoc has learned the Cachial skill. This grants you access to the Caches of Creation. You will find several types of these caches all throughout Zereth Mortis . In order to aid me with my research, you will need to be able to decode various cyphers such as the Cantaric Protolock. Now, let me show you what you need to do to assist me.", ["objectivesText"] = "Complete the Cantaric Protolock. Progress: Good, now take your expanded knowledge out into the field.", ["rewardGold"] = 25740, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65461] = { ["id"] = 65461, ["name"] = "Your First Mezzonic Protolock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65461 }, ["description"] = "In order to aid me in my research, you will need to decode various Progenitor cyphers like the Mezzonic Protolock. Now, I will show you what you need to do.", ["objectivesText"] = "Complete the Mezzonic Protolock. Progress: Use this knowledge to collect more data from the field.", ["rewardGold"] = 25740, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65463] = { ["id"] = 65463, ["name"] = "The Wellspring of the First Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["series"] = { 65349 }, ["description"] = "A mortal, here? How unusual! Welcome to Pilgrim's Grace. Would that you had arrived under better circumstances. Pilgrims usually travel here to visit the sacred Wellspring of the First Ones. Unfortunately, the wellspring has gone dry. I do not understand it. The creations of the First Ones should be infallible! This situation is as unusual as your arrival--perhaps you can lend your aid? Travel to the wellspring and speak to Conservator Olem .", ["objectivesText"] = "Speak to Conservator Olem about the Wellspring's problem.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181084, ["x"] = 0.614, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182146, ["x"] = 0.618, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 4, ["flags"] = 0 } } },
[65466] = { ["id"] = 65466, ["name"] = "Your First Fugueal Protolock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65466 }, ["description"] = "In order to aid my research you will need to decode various Progenitor cyphers like the Fugueal Protolock. This is a most difficult cypher, I will show you what you need to do.", ["objectivesText"] = "Complete the Fugueal Protolock. Progress: Use this knowledge and collect more data from the field.", ["rewardGold"] = 25740, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
