[65563] = { ["id"] = 65563, ["name"] = "Delivery for Kasea", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 65563 }, ["series"] = { 63501, 63502, 65564 }, ["description"] = "Hope ye don't mind, but I used some of your materials to craft something Kasea has been asking me for. Would you mind bringin' it over to her?", ["objectivesText"] = "Deliver the Bladed Helmet to Kasea Angerforge .", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 184915, 184916, 184917, 184922, 190606, 191123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "standard" },
[65564] = { ["id"] = 65564, ["name"] = "Good Fiery Boy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 65564 }, ["series"] = { 63501, 63502, 65563 }, ["description"] = "I train hounds of all types, 'long as they're fiery. I've trained up Grimhowl here since he was a wee pup, but a life in Shadowforge City isn't what he's meant ta live! Grimhowl needs that special someone to bond with, someone who'll take him 'round all of Azeroth. Perhaps that could be you? Take some time to get to know him. I think Grimhowl will warm up to ye real quick!", ["objectivesText"] = "Bond with Grimhowl . Progress: If ye bond with this beastie, you'll have a loyal companion for life!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 184915, 184916, 184917, 184922, 190606, 191123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "standard" },
[65625] = { ["id"] = 65625, ["name"] = "The Jailer's Gauntlet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 65625 }, ["description"] = "Maw Walker! I have been looking for you. Word is there is a new gathering of the Jailer's forces in Torghast. I'm not sure what they are doing, but it can't be good. Perhaps you should put an end to their plans?", ["objectivesText"] = "Enter the new portal in the Torghast Lobby.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[65640] = { ["id"] = 65640, ["name"] = "Cervid Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 65640 }, ["description"] = "<The Cervid Soul is noble and wise. The shape of the cervid will be yours to call upon.>", ["objectivesText"] = "Bring the Cervid Soul to Lady Muunn in the Heart of the Forest. Provided item:", ["rewardItems"] = { 187780, 189971, 189972, 189973, 189975, 189976, 189977, 189980, 189982, 189983, 189986, 189987, 189988, 189989, 189990, 189991, 190337 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 190337 } },
[65652] = { ["id"] = 65652, ["name"] = "Summons from the Matriarch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63479, 63480 }, ["description"] = "Greetings, <name>. Let us not mince words--you are urgently needed in Silvermoon. We're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line! Meet me in the Hall of Blood, and we will get you a full briefing.", ["objectivesText"] = "Meet Lady Liadrin in Silvermoon.", ["rewardGold"] = 28090, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65653] = { ["id"] = 65653, ["name"] = "Victory for the Sin'dorei", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you. Meet me back in the Hall of Blood. Silvermoon is grateful for your bravery.", ["objectivesText"] = "Return to Lady Liadrin in Silvermoon City.", ["rewardGold"] = 28090, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.3472, ["y"] = 0.7552 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 15, ["flags"] = 0 } } },
[65655] = { ["id"] = 65655, ["name"] = "Eyes of the Wolf", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "An alarming rumor has reached me, thanks to our spies. The Forsaken are mustering in Tirisfal Glades. For what purpose, I do not know. Notably, Calia Menethil has gone there as well. We must know more of what they are up to, now that the accursed Banshee Queen no longer unites them. Go, don a disguise and see what you can discover. Observe everything. And if there is opportunity to gain their trust and learn more, do as they ask. I eagerly await your report.", ["objectivesText"] = "Meet Calia Menethil in Brill, Tirisfal Glades.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 136780, 136781, 191029, 191658 }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185512, ["x"] = 0.608, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65657] = { ["id"] = 65657, ["name"] = "Assemble the Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "It's heartening to see progress has been made in rebuilding Brill, but this is only a first step. The ruins of the capital remain inaccessible because of the blight. And here is where I hope you will aid the cause. Restoring as much of the land as possible will require a gathering of minds all working toward a singular purpose. A number of influential figures have risen to prominence among the Forsaken. Please help bring them together so we can meet and discuss the path forward.", ["objectivesText"] = "Assemble Dark Ranger Velonara , Lillian Voss, and Master Apothecary Faranell . Progress: Everyone is working hard to get back on their feet. Might not be the feet they started out with, but they work.", ["rewardGold"] = 170800, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185512, ["x"] = 0.608, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65658] = { ["id"] = 65658, ["name"] = "This Land is Ours", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The plague unleashed during the war has tainted the land and disturbed the dead. That is to say, more so than they already were. We have worked hard to rebuild, but our people cannot complete their efforts while under threat. My first duty is to ensure the safety of the Forsaken. I will meet with the others as Calia requests, but first you must help me eradicate some of these Blighted.", ["objectivesText"] = "Slay Blighted Soldiers in Tirisfal Glades . Progress: We need the pressure off of Brill so we can continue to rebuild.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185514, ["x"] = 0.62, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185792, ["x"] = 0.6148, ["y"] = 0.5192 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 2, ["flags"] = 0 } } },
[65659] = { ["id"] = 65659, ["name"] = "The Blight Congress", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "We, the Forsaken, have been through a lot since the destruction of Lordaeron. But we're determined to keep our home. Why should we give up what we've fought so hard to carve out for ourselves? Calia is still a relative newcomer in some ways, but obviously she's known to our people. How could she not be, as the sister of Arthas himself? I hope we can move forward, and that she can really help. Her voice could be a powerful one, if she is really truly committed to the people.", ["objectivesText"] = "Listen to the Forsaken.", ["rewardGold"] = 170800, ["rewardXP"] = 850, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185797, ["x"] = 0.62, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 3, ["flags"] = 0 } } },
[65660] = { ["id"] = 65660, ["name"] = "Walk of Faith", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "I promised that I would help, and I shall. We need that pure sample of the plague afflicting Lordaeron, but we cannot put anyone else at risk. Come with me. I will call forth a shield of Holy Light to safeguard us deep into the blighted area so that we can collect that sample. This spell will require my full focus. I'll trust you to protect us from anything that might try to stop us. Are you with me?", ["objectivesText"] = "Protect Calia inside her shield and collect the pure plague sample. Progress: I guess I should have faith.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185797, ["x"] = 0.62, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 4, ["flags"] = 0 } } },
[65661] = { ["id"] = 65661, ["name"] = "Consulting Our Allies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "I hope Calia is right about these lords of Maldraxxus. That they know how to deal with this sort of powerful plague. We've only got one plague eater left, too, but Faranell says he can replicate more of them as long as they're strong enough to survive. Let's get to the Shadowlands.", ["objectivesText"] = "Speak to Margrave Sin'dane in Maldraxxus.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 177782, ["x"] = 0.746, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1536, 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 5, ["flags"] = 0 } } },
[65662] = { ["id"] = 65662, ["name"] = "House of Plagues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The one with the knowledge you seek is a survivor of the House of Plagues. You already know him. Plague Deviser Marileth may not be the most lucid of conversationalists, but he will know what to do with your plague. Find him near the ruins of that fallen house. But be wary! Many things lurking there could end your existence without a hint of concern.", ["objectivesText"] = "Meet Plague Deviser Marileth in the House of Plagues.", ["rewardGold"] = 140450, ["rewardXP"] = 850, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 177782, ["x"] = 0.746, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185517, ["x"] = 0.71, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.746, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 6, ["flags"] = 0 } } },
[65663] = { ["id"] = 65663, ["name"] = "Feed the Eater", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The House of Plagues has suffered calamity, much like Lordaeron. I hope that our work and effort here will reverse some of that destruction. But first, we must reach farther into the House of Plagues so we can strengthen the capabilities of Faranell's plague eater. Any slime or creature you slay will surely help it gain fortitude.", ["objectivesText"] = "Slay Slimes and Plaguerocs in the House of Plagues. Progress: We all have something we can contribute.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185803, ["x"] = 0.71, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185826, ["x"] = 0.686, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 7, ["flags"] = 0 } } },
[65664] = { ["id"] = 65664, ["name"] = "Essence of Plague", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "Your little friend there looks hungry! Not to worry, I know just what to feed it. Soon it will grow big and strong and be able to eat all the plague it can. There are various concoctions nearby that will give it bolstering properties. And every color is a different flavor! I will take the plague sample you brought me deeper into the House of Plagues, to see what else we can learn. Meet me there, and let your plague eater dine in style!", ["objectivesText"] = "Absorb different Concoctions in the House of Plagues. Progress: Every color is a different flavor!", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185517, ["x"] = 0.71, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185825, ["x"] = 0.686, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 8, ["flags"] = 0 } } },
[65665] = { ["id"] = 65665, ["name"] = "Embodiment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "What a nasty little plague you've brought me, apprentice. Must've been concocted by a true sadist. To study the sample, I gave it form. But the ungrateful thing turned on me and attacked, completely unprovoked! It's shuffled a bit further on into the House. I hate to say it, but I believe this one must be put down before it is allowed to grow any stronger... or larger. Look on the bright side. If your plague eater manages to survive, it'll be attuned to your particularly terrible form of blight.", ["objectivesText"] = "Slay the Lordaeron Blight . Progress: Have you disposed of that manifestation?", ["rewardGold"] = 578600, ["rewardXP"] = 8520, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185825, ["x"] = 0.686, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185829, ["x"] = 0.685, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 9, ["flags"] = 0 } } },
[65666] = { ["id"] = 65666, ["name"] = "Return to Brill", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "We've strengthened our plague eater, and now it looks ready to take on a much, much bigger meal. Let's get it back to Faranell. He said he can replicate its properties and disperse plague eaters all across the ruins. Then maybe, just maybe, we can set foot in our home again. Here, take my hearthstone. It'll bring you back to Brill.", ["objectivesText"] = "Return to Master Apothecary Faranell outside of the Ruins of Lordaeron. Progress: What have you brought me?", ["rewardGold"] = 28900, ["rewardXP"] = 850, ["rewardItems"] = { 173523, 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185829, ["x"] = 0.685, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185831, ["x"] = 0.658, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 1536, 2070 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 10, ["flags"] = 0 } } },
[65667] = { ["id"] = 65667, ["name"] = "The Remedy of Lordaeron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The time has come. By the Light, I pray our plan works. Master Apothecary Faranell's wagons have reproduced the plague eater many times over, and the bats are ready to deploy them. If you see a place where our forces could spread even more of the remedy, you can signal them with a flare. Take to the skies, and let's put an end to this blight. For Lordaeron, and for the Forsaken.", ["objectivesText"] = "Mount a Shadowbat and deploy Plague Eaters in the Ruins of Lordaeron.", ["rewardGold"] = 1024800, ["rewardXP"] = 8520, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185839, ["x"] = 0.658, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185852, ["x"] = 0.618, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 11, ["flags"] = 0 } } },
[65668] = { ["id"] = 65668, ["name"] = "The Desolate Council", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "By combining our knowledge and expertise, we've restored the surface of the Undercity to the Forsaken. It was only possible by setting aside our distrust and acting for the good of our people. Now it's time to make this council official. We are no longer the same undead that followed and served Sylvanas Windrunner. From here on, we lead ourselves, with the same spirit of independence and pride we've had since we reclaimed our free will. It's time for a new future, with new leadership.", ["objectivesText"] = "Witness the formation of the new Desolate Council. Progress: Hope, and fresh air, have been restored.", ["rewardGold"] = 140450, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185852, ["x"] = 0.618, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185848, ["x"] = 0.618, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 12, ["flags"] = 0 } } },
[65669] = { ["id"] = 65669, ["name"] = "Report to Greymane", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "Thank you for all of your assistance, leading to this historic moment. I believe there may be others who are interested in what happened here. Please, carry this letter, and my well wishes, when you return to them.", ["objectivesText"] = "Deliver Calia's letter to Genn Greymane in Oribos . Progress: What happened with the Forsaken?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 136780, 136781, 191029, 191034, 191658 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185848, ["x"] = 0.618, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 14, ["flags"] = 0 } } },
[65674] = { ["id"] = 65674, ["name"] = "What Is This Thing?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65674 }, ["description"] = "<The ambiguous essence in your hands looks as if it could serve a variety of purposes. In fact, it almost seems to radiate possibility.> <Perhaps Firim may have some answers about this.>", ["objectivesText"] = "Bring the Unformed Essence to Firim in Exile's Hollow. Provided item:", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 190579 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["startItems"] = { 190579 } },
[65680] = { ["id"] = 65680, ["name"] = "Schematic Reassimilation: Heartbond Lupine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 65680 }, ["description"] = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", ["objectivesText"] = "Present the schematic to an appropriate protoform forge. Provided item:", ["rewardItems"] = { 188957, 189172, 190388, 190580, 190585 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 190585 } },
[65700] = { ["id"] = 65700, ["name"] = "Core Control", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65700 }, ["description"] = "Your timing is most excellent. It appears one of my traps captured a rather curious creature moments ago. I dare not investigate, but you... you can do this for me. Take Pocopoc along with you. Perhaps there are secrets yet to be discovered.", ["objectivesText"] = "Examine the curious creature outside of Exile's Hollow. Progress: Find something of interest?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
