[65717] = { ["id"] = 65717, ["name"] = "Leading Motives", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65717 }, ["description"] = "<A small object catches your eye. It glitters with Progenitor magic--ancient, yet... strangely more refined.> <Soft vibrations and tones are woven into the device in a repeating refrain that almost seems to be trying to... speak?> < Firim would be very interested in this.>", ["objectivesText"] = "Bring the Almanac's Echo to Firim in Exile's Hollow. Provided item:", ["rewardItems"] = { 190771, 190773 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["startItems"] = { 190773 } },
[65725] = { ["id"] = 65725, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65725 }, ["objectivesText"] = "Progress: The large bufonid beneath the mud remains still. There must be something it fancies. Have you some meats we can use to lure it out?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65726] = { ["id"] = 65726, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65726 }, ["objectivesText"] = "Progress: If meat and honey could not lure this creature from the waters, let us try another approach. Bring me some Shrouded Cloth . I will craft a net from it that may be more effective.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65727] = { ["id"] = 65727, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65727 }, ["description"] = "Have you stopped to watch the bufonids? A lovely one lurks underwater. Still, patient, unmoving. Wise Bud takes after him. They are much alike. I sense Bud desires to see this large bufonid up close. Perhaps the creature can be lured out with some honey from the vespoids here in Zereth Mortis . Would you please gather some?", ["objectivesText"] = "Collect 15 Vespoid Honey from Vespoid around Zereth Mortis . Progress: Have you found that honey?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 189470, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65728] = { ["id"] = 65728, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65728 }, ["objectivesText"] = "Progress: Since a trap did not work, let us try again to find a lure that interests this austere bufonid. Perhaps it desires some fish? Please bring us some.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65729] = { ["id"] = 65729, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65729 }, ["objectivesText"] = "Progress: I am running out of ideas. What else might entice our shy friend? Let us try more flesh from the creatures of Zereth Mortis . Something must grab its attention!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65730] = { ["id"] = 65730, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65730 }, ["objectivesText"] = "Progress: What else could we possibly try to persuade this bufonid to emerge? Maybe the jiro know the trick. I hear there is one with fruit pastries to offer. Bring us one, if you please.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65731] = { ["id"] = 65731, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65731 }, ["objectivesText"] = "Progress: Hmmmmm... My friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis ' supply of tempting flavors. I have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: Sweet organic melons . My dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65732] = { ["id"] = 65732, ["name"] = "The Patient Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65732 }, ["description"] = "Look, another magnificent creature of Zereth Mortis ! By the glint in its eye, I would say it was playing along the whole time. Patience delights. Bud is pleased. Excellent work, Maw Walker.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65735] = { ["id"] = 65735, ["name"] = "WANTED: Custos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65735 }, ["description"] = "A once-stable automa is showing signs of unusual dysfunction, attacking Enlightened along the road outside of Pilgrim's Grace. It is essential that the roads remain safe for our pilgrims. Rafiq has designated the elimination of this threat to be of the highest priority.", ["objectivesText"] = "Eliminate Custos .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 189865 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 185587, ["x"] = 0.605, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[65748] = { ["id"] = 65748, ["name"] = "You Supply the Effort", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65748 }, ["description"] = "The gear I provide is made available by the blessings of the First Ones and the... efforts of many other travelers. Each of us needs to provide for those that will follow later. Collect what provisions you come across in your exploration of Zereth Mortis . Keep a sharp eye out--they may be hidden in mysterious places. Return them here to me. I will in turn provide them to future travelers.", ["objectivesText"] = "Locate 10 Enlightened Provisions from chests, nests, relics and other containers about Zereth Mortis . Progress: What have you found for me?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 188170, 190927, 228741 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 185713, ["x"] = 0.35, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 185713, ["x"] = 0.35, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65749] = { ["id"] = 65749, ["name"] = "The Necessity Of Equipment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65749 }, ["description"] = "I have been sharing research for some time with an associate of mine, Rafiq . It is only through our shared efforts that he has been able to acquire useful items. Deliver my latest research notes to Rafiq and see if you can earn favor with him. In time, he should be able to aid you with better equipment.", ["objectivesText"] = "Collect Firim's Research Notes and deliver them to Rafiq . Progress: What is this you have brought me?", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 190189, 190940 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 185587, ["x"] = 0.605, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65762] = { ["id"] = 65762, ["name"] = "Sepulcher of the First Ones - Heavy is the Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13742, ["storyline"] = { 65762 }, ["description"] = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", ["objectivesText"] = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Mythic Difficulty. Progress: Four Sword Fragments should allow us to access his chamber.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 190959 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13742 } }, ["questType"] = "raid" },
[65763] = { ["id"] = 65763, ["name"] = "Sepulcher of the First Ones - Heavy is the Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13742, ["storyline"] = { 65763 }, ["description"] = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", ["objectivesText"] = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Heroic Difficulty. Progress: Four Sword Fragments should allow us to access his chamber.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 190966 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13742 } }, ["questType"] = "raid" },
