[65768] = { ["id"] = 65768, ["name"] = "Our Forward Scouts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "The Jailer's forces control much of Zereth Mortis , but there are other dangers out there as well. I have dispatched scouts to survey the surrounding area and pinpoint any potential threats. Speak with each scout. They should have a report of their surveys. Gather this information and then return to me.", ["objectivesText"] = "Speak with the forward scouts in Zereth Mortis . Progress: What have you discovered?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 188011, 188017, 188025, 188033, 190968, 190969, 190971, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 13, ["flags"] = 0 } } },
[65772] = { ["id"] = 65772, ["name"] = "Necessary Harvest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "Between the Mawsworn attacks and your presence here, our supplies are dwindling. It pains me to say it, but the most immediate solution for replenishing our resources is the local wildlife. It is unfortunate that it has come to this, but it is what must be done. Cull some of the local wildlife, and help us replenish our supplies.", ["objectivesText"] = "Collect 15 Latent Protein from raptora, cervids, and lupines in The Great Veldt and surrounding area. Progress: Have you brought us the necessary supplies?", ["rewardGold"] = 64350, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190743, 190746, 190750, 190752, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.336667, ["y"] = 0.679333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 15, ["flags"] = 0 } } },
[65774] = { ["id"] = 65774, ["name"] = "The Catalyst Awakens", ["level"] = 61, ["requiredLevel"] = 61, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65774 }, ["description"] = "Adventurer, can you feel it? High above the Catalyst Gardens, the Creation Catalyst hums with new power. This power will change the world itself. You must harness it at once.", ["objectivesText"] = "Travel to the Catalyst Gardens and use the Creation Catalyst. Progress: The very fabric of creation shudders.", ["rewardItems"] = { 32572, 188957 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182257, ["x"] = 0.348, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182257, ["x"] = 0.348, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65788] = { ["id"] = 65788, ["name"] = "A Walk with Ghosts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65656, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65788, 66091 }, ["description"] = "Reclaiming these ruins means a lot to the Forsaken. Especially since the war ended, our people have needed something to hold onto, to give us purpose in the wake of everything that's happened to us. I saw Calia walk toward the throne room. That place holds many memories for her. Many ghosts. We should check on her.", ["objectivesText"] = "Speak to Calia in the throne room of Lordaeron.", ["rewardGold"] = 31500, ["rewardXP"] = 850, ["rewardItems"] = { 136780, 136781, 140192, 191658, 208475 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185852, ["x"] = 0.618, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185893, ["x"] = 0.618, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070, ["questLines"] = { { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 14, ["flags"] = 0 } } },
[66042] = { ["id"] = 66042, ["name"] = "Patterns Within Patterns", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "We stand at the origin of the Shadowlands. We must not allow this place to become its undoing. Work with our new allies, <name>. Their assistance will be the difference between our success and the unmaking of all things.", ["objectivesText"] = "Assist your allies in Zereth Mortis by completing World Quests, Daily Quests, looting treasures, and slaying rare creatures. Progress: In this place, all fates are intertwined.", ["rewardItems"] = { 191139 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 11, ["flags"] = 1 } } },
