[66243] = { ["id"] = 66243, ["name"] = "A Gift of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1565, ["storyline"] = { 66243 }, ["description"] = "Greetings, Maw Walker. I bear a summons from the Winter Queen. She requests your presence in Ardenweald to witness a ceremony involving others from your world. Shandris Feathermoon will be among them. You can find her in the Grove of Awakening.", ["objectivesText"] = "Meet Shandris Feathermoon in the Grove of Awakening. Progress: The Winter Queen awaits us, <name>.", ["rewardGold"] = 128700, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 187733, ["x"] = 0.458, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
